import{c as e,i as t,l as n,n as r,r as i,t as a,u as o}from"./coursesHaccp3And4-Da-AAL9t.js";var s=[{id:`cdm-v-mod-1`,moduleNumber:1,title:`Scope of Practice, Leadership Role & Interdisciplinary Clinical Care Team`,estimatedMinutes:30,overview:`Master the executive scope of practice of a Certified Dietary Manager (CDM), understand clinical vs operational boundaries with Registered Dietitians and Physicians, and run daily interdisciplinary shift briefings.`,internationalClauses:[`ANFP Certified Dietary Manager (CDM, CFPP) Scope of Practice`,`JCI Hospital Patient-Centered Care & Nutrition Standards (COP.4)`],keyPrinciples:[`The Certified Dietary Manager leads hospital and institutional foodservice operations: menu execution, therapeutic diet accuracy, food safety/HACCP, procurement, budgeting, and team leadership.`,`Clinical Dietitians (RD/RDN) perform medical nutrition assessments and prescribe therapeutic diet modifications; the CDM ensures every prescribed meal is cooked, portioned, verified, and delivered safely on time.`],criticalControlParameters:[{parameter:`Ward Diet Census Synchronization`,standardLimit:`100% live reconciliation of Admissions, Discharges, Transfers & NPO orders ≥ 30 mins before every meal service`,correctiveProtocol:`Halt tray release for any unverified bed change; confirm verbally and digitally with the Ward Charge Nurse before dispatch.`}],practicalChecklist:[`Lead a structured 10-minute morning huddle reviewing ward census, therapeutic specials, allergens, and staffing assignments.`,`Reconcile new NPO (Nil Per Os) and Hold-Tray requests immediately with nursing stations before tray-line startup.`],quickCheck:{question:`How do the professional responsibilities of a Clinical Dietitian (RD) and a Certified Dietary Manager (CDM) complement each other in a hospital?`,options:[`The CDM prescribes intravenous TPN formulas while the Dietitian supervises kitchen dishwashing and store inventory`,`The Clinical Dietitian assesses nutrition risk and prescribes therapeutic diet targets, while the CDM manages kitchen operations, food safety, staff, budget, and accurate meal delivery`,`Both roles are identical and either person may independently change a physician’s NPO surgical order`,`The CDM only manages the staff cafeteria and has no responsibility for patient therapeutic tray accuracy`],correctIndex:1,explanation:`Clinical Dietitians handle clinical nutrition assessment and Medical Nutrition Therapy (MNT); Certified Dietary Managers lead foodservice production, HACCP, staffing, budgets, and accurate execution of every therapeutic tray.`},presentationSlides:[{slideNumber:1,title:`Course Architecture & Certified Dietary Manager Mastery Blueprint`,subtitle:`Interactive Professional CDM Curriculum — Food Science Portal`,calloutBanner:{label:`Hospital & Institutional Leadership Blueprint`,text:`Engineered for Certified Dietary Managers, Hospital Foodservice Directors, Clinical Kitchen Supervisors, Nutritionists, and Catering Managers — combining clinical therapeutic diet execution, IDDSI dysphagia controls, hospital SOPs, 12 controlled dietary documents, interactive drills, and financial KPI mastery.`,tone:`blue`},visualIllustration:`cdm-care-team`,bulletPoints:[`Structured across 15 progressive interactive modules covering Clinical Care Coordination, Therapeutic Diets, IDDSI Textures, Hospital HACCP, Tray-Line QA, Financial PPD Control, and Accreditation Readiness.`,`Includes 12 authentic Hospital Controlled Document Templates (CDM-DOC-01 to CDM-DOC-12), interactive SOP tabs, Germometer, Risk Matrix, and Classification Drills.`,`Assessment Goal: Study all 15 interactive modules and score ≥ 60% (≥ 75% Distinction) on the 40-MCQ Final Examination.`],keyTakeaway:`A Certified Dietary Manager bridges clinical medicine and culinary operations so the right diet reaches the right patient safely at every meal.`},{slideNumber:2,title:`Scope of Practice: CDM vs Clinical Dietitian vs Ward Nursing`,subtitle:`Preventing Clinical Errors Through Clear Role Boundaries`,twoColumns:{leftTitle:`Certified Dietary Manager (CDM) Mandate`,leftTone:`blue`,leftItems:[`Translate prescribed diet manuals into cycle menus and standardized recipes`,`Direct kitchen operations, tray assembly line, thermal transport & sanitation`,`Manage food purchasing, FIFO/FEFO inventory, PPD food cost & labor rosters`,`Screen routine food preferences, allergies & intake; escalate high nutrition risk to RD`],rightTitle:`Clinical Dietitian (RD) & Physician Mandate`,rightTone:`emerald`,rightItems:[`Physician writes legal medical diet order (Diabetic, Renal, IDDSI, NPO)`,`Clinical Dietitian performs comprehensive MNT assessment & calculates tube feeds`,`Dietitian approves hospital diet manual and complex clinical nutrient modifications`,`Ward Nurse verifies dual patient ID at bedside, assists feeding & records % eaten`]},documentTemplateBlock:{docCode:`CDM-DOC-01`,version:`Rev 2.0`,codexStepLabel:`Daily Clinical Operations Control`,docTitle:`Daily Dietary Shift Huddle & Ward Census Sign-Off Sheet`,purpose:`Synchronizes kitchen production with live nursing census, NPO surgical holds, and high-risk patient allergen alerts prior to breakfast, lunch, and dinner tray lines.`,fields:[{label:`Hospital / Unit`,value:`Tertiary Care Dietary Dept (250 Beds)`},{label:`Meal Service Period`,value:`Lunch Service (Tray Line Start: 11:30 AM)`},{label:`Total Active Patients`,value:`218 Active · 14 NPO · 6 Hold Trays`},{label:`Shift Lead / CDM`,value:`Certified Dietary Manager on Duty`}],tablePreview:{headers:[`Ward`,`Regular`,`Diabetic / Cardiac`,`Renal / Low-K`,`IDDSI L4–L6`,`NPO / Allergen Flags`],rows:[[`ICU / CCU`,`4`,`12`,`5`,`6 (Pureed/Soft)`,`4 NPO · Bed 104: Peanut Allergy`],[`Medical Ward A`,`26`,`28`,`9`,`11`,`3 NPO · Bed 212: Celiac (GF)`],[`Surgical Ward B`,`31`,`14`,`2`,`8 (Liquid/Soft)`,`7 NPO (Pre-Op) · 3 Hold Trays`]]},signOffLine:`CDM Signature & Time ________ | Charge Nurse Census Confirm ________`},bulletPoints:[`Never alter a therapeutic diet restriction independently without documented physician or Clinical Dietitian authorization.`,`When a patient reports chewing difficulty, weight loss, or <50% meal consumption for 3 consecutive days, submit an immediate Clinical Dietitian Referral.`],keyTakeaway:`Clear scope boundaries and pre-meal census reconciliation eliminate NPO breaches and therapeutic diet mix-ups.`}]},{id:`cdm-v-mod-2`,moduleNumber:2,title:`Hospital Kitchen Architecture, One-Way Flow & Ergonomic Zone Control`,estimatedMinutes:30,overview:`Design and audit a hygienic hospital dietary facility using strict Dirty-to-Clean one-way workflow, multi-stream therapeutic segregation, air-pressure zoning, and ergonomic equipment placement.`,internationalClauses:[`Codex CXC 1-1969 Hygienic Facility Design`,`ISO/TS 22002-2 Catering & Institutional Kitchen Zoning`],keyPrinciples:[`A compliant hospital kitchen enforces strict One-Way Forward Flow (Receiving → Storage → Pre-Prep → Hot/Diet Cooking → Tray Assembly → Ward Dispatch) with a physically isolated Scullery return route.`,`Positive air pressure in the clean tray-assembly zone, washable coved floor-to-wall junctions, shatterproof ≥500 lux lighting, and dedicated handwash basins prevent environmental contamination.`],criticalControlParameters:[{parameter:`Facility Zoning & Environmental Separation`,standardLimit:`Zero cross-traffic between raw preparation, clean tray plating, and soiled ward-cart scullery return`,correctiveProtocol:`Re-route carts immediately, sanitize affected clean-zone surfaces, and retrain floor stewards on directional signage.`}],practicalChecklist:[`Walk the kitchen floor weekly from Receiving Bay to Scullery verifying zero back-tracking of raw ingredients or dirty trays.`,`Check shatterproof light covers, insect-screen mesh integrity, floor drain traps, and handwash station supplies every shift.`],quickCheck:{question:`Why must returning soiled meal trolleys from hospital wards enter directly into an isolated Dishwashing (Scullery) zone rather than passing through the Tray Assembly area?`,options:[`To reduce the walking distance for kitchen chefs during lunch preparation`,`To prevent infectious ward pathogens, used utensils, and food waste from cross-contaminating clean plated patient meals`,`Because soiled trolleys are too heavy for standard kitchen floor tiles`,`To allow ward nurses to wash patient dishes before returning trolleys`],correctIndex:1,explanation:`Hospital trays returning from patient wards may carry clinical pathogens; an isolated soiled-return route preserves strict One-Way (Dirty-to-Clean) hygienic separation.`},presentationSlides:[{slideNumber:1,title:`The 6 Functional Zones of a Hospital Dietary Kitchen`,subtitle:`Engineering Cross-Contamination Out of Daily Operations`,visualIllustration:`cdm-kitchen-zones`,flowDiagramData:{title:`Hospital Multi-Stream Meal Workflow (Regular + Therapeutic Convergence)`,isMultiStream:!0,mainSteps:[{step:`Zone 1: Receiving Bay Gatekeeping`,note:`Verify COA, weight, pest-free truck, ≤5°C chilled / ≤-18°C frozen`},{step:`Zone 2: Segregated Dry, Chilled & Frozen Stores`,note:`FIFO/FEFO tagging · 15 cm off floor · raw bottom shelf`},{step:`Zone 3: Color-Coded Pre-Preparation`,note:`Dedicated raw meat, produce & allergen-free benches`},{step:`Zone 4: Hot Bulk & Therapeutic Cooking`,note:`Validated core lethality ≥75°C (probe verified)`,isCcp:!0},{step:`Zone 5: Clean Tray Assembly & Ticket Audit`,note:`Hot hold ≥63°C · Cold ≤5°C · Dual-ID & NPO check`,isCcp:!0},{step:`Ward Thermal Dispatch → Isolated Zone 6 Scullery`,note:`Deliver ≤30 min; soiled carts return via separate scullery door`}],secondarySteps:[{step:`Therapeutic & IDDSI Puree Station`,note:`Dedicated salt-free / allergen-free kettles & IDDSI flow check`,joinAtIndex:4},{step:`Cold Desserts, Oral Shakes & Salads`,note:`Chilled ≤5°C RTE plating line`,joinAtIndex:4}]},bulletPoints:[`Physical Barriers: Where full walls are unavailable, enforce color-coded floor zoning, dedicated equipment, and time-separated sanitization.`,`Dedicated Handwash Basins: Must be hands-free (elbow/knee/sensor), stocked with warm water, liquid antibacterial soap, paper towels, and pedal bin — never used for vegetable washing.`],keyTakeaway:`Facility flow design is your strongest silent supervisor — when clean and dirty paths never cross, outbreaks plummet.`},{slideNumber:2,title:`Structural Hygiene, Ventilation, Lighting & Equipment Audit`,subtitle:`Building & Utility Specifications Every CDM Inspects`,documentTemplateBlock:{docCode:`CDM-DOC-02`,version:`Rev 1.8`,codexStepLabel:`Facility & GMP Inspection`,docTitle:`Weekly Hospital Kitchen Structural & Equipment Hygiene Audit`,purpose:`Documents preventive facility checks across flooring, drainage, hood ventilation, lighting, water filtration, and cooking equipment prior to regulatory or JCI rounds.`,fields:[{label:`Lighting Standard`,value:`≥ 500 Lux Prep/Tray Line (Shatterproof Sleeves)`},{label:`Floor & Coving`,value:`Anti-slip epoxy/tile · Coved wall junctions`},{label:`Exhaust & HVAC`,value:`Degreased baffle filters · Positive clean-zone airflow`},{label:`Potable Water Check`,value:`Free Chlorine 0.2–0.5 ppm · Monthly Micro Test`}],tablePreview:{headers:[`Facility Area`,`Inspection Criterion`,`Status`,`Corrective Action & Target Date`],rows:[[`Main Prep Zone`,`Hands-free sink operational, soap & paper stocked`,`PASS`,`None required`],[`Exhaust Canopy`,`Baffle filters free of grease drip over stoves`,`PASS`,`Scheduled deep-clean every Sunday`],[`Chiller #2 Door`,`Magnetic door gasket intact; zero ice buildup`,`ACTION`,`Engineering WO #442 raised — seal replacement 24h`]]},signOffLine:`CDM Inspector ________ | Hospital Engineering Lead ________`},bulletPoints:[`Preventive Maintenance (PM): Maintain a live equipment asset register covering combi-ovens, blast chillers, dishmachines, and insulated meal trolleys.`,`Food-Grade Lubricants (NSF H1): Confirm hospital maintenance engineers exclusively use food-grade H1 lubricants on mixers, slicers, and conveyor belts.`],keyTakeaway:`A preventive engineering schedule avoids mid-service chiller failures, gasket leaks, and structural pest entry points.`}]},{id:`cdm-v-mod-3`,moduleNumber:3,title:`Essential Nutrition Science, Macronutrients, Hydration & Patient Screening`,estimatedMinutes:35,overview:`Apply core human nutrition principles to menu design, calculate patient calorie and protein delivery, monitor hydration needs, and execute first-line nutrition risk screening for timely RD escalation.`,internationalClauses:[`WHO / DRI Clinical Energy & Protein Guidelines`,`MST / MUST Hospital Malnutrition Screening Protocols`],keyPrinciples:[`Macronutrients supply energy (Carbohydrates 4 kcal/g, Protein 4 kcal/g, Fat 9 kcal/g), while vitamins, minerals, fiber, and water drive immunity, healing, and electrolyte homeostasis.`,`Hospital malnutrition increases length of stay and infection risk; CDMs track meal consumption percentages and screen weight/appetite changes to trigger prompt Clinical Dietitian referrals.`],criticalControlParameters:[{parameter:`Low Intake Escalation Trigger`,standardLimit:`Any hospitalized patient consuming < 50% of meals for 3 consecutive days (or experiencing unintentional weight loss)`,correctiveProtocol:`Document intake log, interview patient on food preferences/chewing issues, and submit immediate Clinical Dietitian Referral.`}],practicalChecklist:[`Verify daily hospital menus deliver balanced energy (1,800–2,200 kcal standard) and adequate high-biological-value protein.`,`Review ward meal-intake sheets and ensure hydration rounds supply ≥ 1.5–2.0 L fluids daily (unless fluid-restricted).`],quickCheck:{question:`A post-surgical patient eats only 25% of breakfast, lunch, and dinner for 3 consecutive days and reports loss of appetite. What is the Certified Dietary Manager’s correct action?`,options:[`Reduce the patient’s portion size permanently to save food cost`,`Document the low intake, check patient food preferences/texture tolerance, and submit an immediate referral to the Clinical Dietitian`,`Prescribe high-dose intravenous antibiotics and discharge the patient`,`Wait 14 days to see if appetite returns naturally before recording anything`],correctIndex:1,explanation:`Intake below 50% for 3 consecutive days is a clinical malnutrition red flag requiring documented preference review and prompt escalation to the Clinical Dietitian.`},presentationSlides:[{slideNumber:1,title:`Macronutrients, Micronutrients & Hospital Energy Density`,subtitle:`Translating Nutritional Science Into Healing Patient Meals`,tableBlock:{caption:`Clinical Nutrition Quick-Reference for Hospital Menu Planning`,headers:[`Nutrient Group`,`Energy / Role`,`Key Hospital Food Sources`,`Clinical Care Considerations`],rows:[[`Carbohydrates`,`4 kcal/g · Primary brain & muscle fuel`,`Whole grains, oats, brown rice, legumes, fruits`,`Control portion & glycemic index for Diabetic diets (45–60 g/meal)`],[`Proteins`,`4 kcal/g · Tissue repair, immunity & enzymes`,`Eggs, poultry, fish, lean meat, lentils, Greek yogurt`,`Increase to 1.2–1.5 g/kg for wounds, burns, sepsis & post-op healing`],[`Fats (Lipids)`,`9 kcal/g · Concentrated energy & Vitamins A,D,E,K`,`Olive/canola oil, fatty fish, nuts, avocado`,`Limit saturated (<7% kcal) & zero trans fats for Cardiac patients`],[`Key Micronutrients`,`0 kcal · Immunity, bone & wound healing`,`Vitamin C (citrus), Zinc (meat/seeds), Iron, Vit D, Ca`,`Protect water-soluble Vitamins B & C by steaming rather than over-boiling`],[`Fluids & Electrolytes`,`Hydration, renal balance & circulation`,`Potable water, broths, milk, herbal tea, oral shakes`,`Standard ~30 mL/kg/day; strictly measure for CHF & Dialysis fluid restrictions`]]},bulletPoints:[`Nutrient Retention in Bulk Cooking: Cook vegetables in small batches using steam/convection ovens to preserve Vitamin C, folate, color, and texture.`,`Food-First Fortification: Enrich soups, mashed potatoes, and porridge with skim milk powder, egg whites, or olive oil to boost calories/protein for frail elderly patients without increasing plate volume.`],keyTakeaway:`Every tray is clinical therapy — cooking methods directly determine whether patients absorb healing protein and vitamins.`},{slideNumber:2,title:`Nutrition Risk Screening, Malnutrition Red Flags & Intake Tracking`,subtitle:`Partnering With Nursing & Dietitians to Stop Hospital Malnutrition`,twoColumns:{leftTitle:`Malnutrition Red Flags (Refer to RD)`,leftTone:`rose`,leftItems:[`Unintentional weight loss ≥ 5% in 1 month or ≥ 10% in 6 months`,`Oral intake < 50% of prescribed meals for ≥ 3 consecutive days`,`Chewing pain, ill-fitting dentures, coughing on liquids, or nausea`,`Stage 2–4 pressure ulcers, severe burns, dialysis, or oncology cachexia`],rightTitle:`CDM Frontline Nutritional Support Actions`,rightTone:`emerald`,rightItems:[`Conduct friendly patient meal-satisfaction & preference interviews within 24–48h of admission`,`Honor cultural, religious (Halal/Vegetarian), and personal dislikes promptly`,`Provide prescribed mid-morning / evening high-protein snacks & oral supplements (ONS)`,`Track ward-level calorie/plate-waste trends and share with the Nutrition Committee`]},documentTemplateBlock:{docCode:`CDM-DOC-03`,version:`Rev 1.4`,codexStepLabel:`Clinical Nutrition Screening`,docTitle:`Patient Nutrition Preference, Intake & RD Referral Log`,purpose:`Captures admission food preferences, allergen verifications, 3-day meal intake %, and timely referrals to Clinical Dietitians.`,fields:[{label:`Screening Tool Used`,value:`Malnutrition Screening Tool (MST Score 0–5)`},{label:`Referral Threshold`,value:`MST ≥ 2 or Intake < 50% × 3 Days`},{label:`Allergen Cross-Check`,value:`Verified against EMR & Wristband`},{label:`Completed By`,value:`Certified Dietary Manager / Diet Tech`}],tablePreview:{headers:[`Patient / Bed`,`Diet Order`,`3-Day Avg Intake`,`MST Score / Trigger`,`CDM Action Taken`],rows:[[`Bed 304 (M, 72y)`,`Cardiac Low-Na`,`85%`,`0 (Low Risk)`,`Honored preference: grilled fish over chicken`],[`Bed 311 (F, 64y)`,`High-Protein Soft`,`35%`,`3 (High Risk)`,`Immediate RD Referral sent; added chilled ONS shake`],[`Bed 318 (M, 55y)`,`Renal Low-K+`,`75%`,`1 (Monitor)`,`Confirmed potassium-leached vegetables on ticket`]]},signOffLine:`CDM Signature ________ | Clinical Dietitian Received ________`},bulletPoints:[`Always verify patient food allergies against both the Electronic Medical Record (EMR) and bedside wristband.`,`Escalate MST scores ≥ 2 or 3-day intake < 50% immediately so Clinical Dietitians can initiate oral nutrition support.`],keyTakeaway:`Nutrition screening turns dietary staff into an early-warning shield against hospital-acquired malnutrition.`}]},{id:`cdm-v-mod-4`,moduleNumber:4,title:`Clinical Therapeutic Diets & Medical Nutrition Execution`,estimatedMinutes:40,overview:`Execute every major hospital therapeutic diet accurately — including Diabetic, Renal, Cardiac, Hepatic, Post-Operative, Neutropenic, and Allergen-Free orders — without kitchen cross-contact or nutrient errors.`,internationalClauses:[`Academy of Nutrition & Dietetics (AND) Nutrition Care Manual`,`Hospital Therapeutic Diet Formulary Standards`],keyPrinciples:[`A therapeutic diet modifies nutrients, calories, fluids, or food safety rules to treat medical disease; serving an unapproved condiment or wrong salt packet can destabilize a critically ill patient.`,`Therapeutic recipes must be prepared with measured seasonings (e.g., herbs/lemon instead of salt/MSG for cardiac/renal trays) and clearly coded on printed meal tickets.`],criticalControlParameters:[{parameter:`Therapeutic Diet & Condiment Restriction Accuracy`,standardLimit:`0% unauthorized sugar, salt sachets, high-potassium foods, or raw items on restricted clinical trays`,correctiveProtocol:`Pull the tray before cart loading, re-plate using verified therapeutic items, log Near-Miss / Variance Report, and coach tray-line server.`}],practicalChecklist:[`Verify salt packets are strictly removed from Cardiac/Low-Sodium and Renal trays, and sugar packets removed from Diabetic trays.`,`Confirm Neutropenic/Oncology trays contain zero raw salads, unpeeled fresh fruit, unpasteurized dairy, or pepper packets.`],quickCheck:{question:`Which food combination is UNSAFE and must NEVER be placed on a Renal (Chronic Kidney Disease / Low-Potassium, Low-Sodium) patient tray?`,options:[`Steamed white rice, herb-seasoned skinless chicken breast, and peeled apple slices`,`Banana, tomato soup, potato fries, orange juice, and salted packaged pickles`,`Egg-white omelet, white toast with unsalted butter, and cranberry juice`,`Boiled pasta with olive oil, garlic, and low-potassium cabbage`],correctIndex:1,explanation:`Bananas, tomatoes, un-leached potatoes, and orange juice are very high in Potassium (risking fatal cardiac arrhythmia in renal failure), and salted pickles are excessive in Sodium.`},presentationSlides:[{slideNumber:1,title:`The 6 Core Hospital Therapeutic Diets`,subtitle:`Clinical Rationale, Allowed Foods & Strictly Prohibited Items`,visualIllustration:`cdm-therapeutic-diets`,tableBlock:{caption:`Hospital Therapeutic Diet Execution Matrix`,headers:[`Therapeutic Diet`,`Target Clinical Limits`,`Recommended Kitchen Swaps`,`Strictly Avoid / Red Flags`],rows:[[`Diabetic (Carb-Controlled)`,`Consistent 45–60 g carbs/meal; zero simple sugars`,`Wholewheat chapati/oats, steamed veg, lean grilled protein, sugar-free jelly`,`Sweetened juices, white sugar sachets, syrups, pastries, sweet desserts`],[`Renal (Low Na+, K+, PO4)`,`Na <2,000 mg · K+ <2,000 mg · PO4 <800–1,000 mg`,`White rice, egg whites, peeled apples, grapes, double-boiled/leached veg`,`Bananas, oranges, tomatoes, potatoes, dark colas, dairy excess, salt substitutes (KCl!)`],[`Cardiac (Low-Na / Low-Fat)`,`Na ≤1,500–2,000 mg/day · Saturated fat <7%`,`Garlic, lemon, black pepper, herbs, baked fish, olive/canola oil`,`Table salt packets, soy sauce, stock cubes, processed deli meats, deep-fried food`],[`Clear vs Full Liquid`,`Post-op / GI rest progression`,`Clear: strained broth, apple juice, tea, gelatin · Full: milk, strained cream soup, yogurt`,`Clear liquid must NEVER contain milk, pulp, seeds, or opaque solids`],[`Neutropenic (Immunocompromised)`,`Minimal microbial load for chemotherapy/transplant`,`Well-done meat ≥75°C, UHT milk, canned fruit, individually sealed condiments`,`Raw salads, raw sprouts, soft unpasteurized cheese, deli cold cuts, raw honey`]]},calloutBanner:{label:`Critical Clinical Safety Alert — Potassium Chloride Salt Substitutes`,text:`NEVER give commercial "Lo-Salt" or potassium-chloride salt substitutes to Renal patients! They replace sodium with potassium and can trigger life-threatening hyperkalemia.`,tone:`rose`},bulletPoints:[`Double-check every tray ticket for hidden sodium (stock cubes, soy sauce, pickles) on Cardiac/Renal orders and simple sugars on Diabetic orders.`,`Potassium leaching (peeling, dicing, soaking, and double-boiling root vegetables in fresh water) significantly lowers potassium content for CKD meals.`],keyTakeaway:`Therapeutic diet accuracy is clinical medication delivered on a plate — verify every condiment, beverage, and side dish.`},{slideNumber:2,title:`Managing Allergens, Celiac (Gluten-Free) & Cultural Diets`,subtitle:`Dedicated Purple-Zone Equipment & Controlled Diet Census`,documentTemplateBlock:{docCode:`CDM-DOC-04`,version:`Rev 2.1`,codexStepLabel:`Therapeutic Production Control`,docTitle:`Daily Therapeutic & Allergen-Safe Diet Master Census Sheet`,purpose:`Translates live EMR physician diet orders into exact batch counts for the Diet Cook and Allergen-Free station before cooking begins.`,fields:[{label:`Diet Manual Version`,value:`Hospital Clinical Diet Manual 2026`},{label:`Allergen Kit Used`,value:`Dedicated Purple Boards, Knives & Pans`},{label:`Diet Cook Assigned`,value:`Senior Therapeutic Chef`},{label:`Pre-Service Tasting`,value:`Verified by CDM (Salt/Texture/Temp)`}],tablePreview:{headers:[`Diet Category`,`Batch Count`,`Key Modification Rule`,`Ticket Color / Tag`],rows:[[`Diabetic 1800 kcal`,`42 Trays`,`No sugar/honey; 1 measured starch portion`,`Blue Diabetic Band`],[`Renal Low-K+ / Low-Na`,`14 Trays`,`Zero salt, zero tomato/potato; leached carrots`,`Yellow Renal Band`],[`Neutropenic (Oncology)`,`9 Trays`,`Cooked ≥75°C; sealed UHT milk; zero raw garnish`,`Green Sterile Seal`],[`Celiac / Nut-Free`,`3 Trays`,`Purple station first-run; double-checked ingredient labels`,`RED ALLERGEN FLAG`]]},signOffLine:`Therapeutic Chef ________ | Certified Dietary Manager ________`},bulletPoints:[`Always prepare Allergen-Free and Celiac (Gluten-Free) meals FIRST on freshly sanitized surfaces using dedicated purple-handled tools, cover immediately, and label with patient full name & bed number.`,`Check every composite ingredient label (sauces, gravy thickeners, spice blends) for hidden wheat, milk, soy, egg, peanut, tree nuts, fish, shellfish, or sesame.`],keyTakeaway:`Dedicated purple utensils, label reading, and color-coded meal tickets stop fatal allergen and therapeutic errors.`}]},{id:`cdm-v-mod-5`,moduleNumber:5,title:`Texture-Modified Diets, Dysphagia Safety & The IDDSI Framework`,estimatedMinutes:35,overview:`Prevent choking and silent aspiration pneumonia by standardizing dysphagia foods and thickened liquids using the global IDDSI (Levels 0–7) framework and bedside Fork Drip, Spoon Tilt, and Syringe Flow tests.`,internationalClauses:[`IDDSI Global Framework v2.0 (Levels 0–7)`,`Speech-Language Pathologist (SLP) Dysphagia Safety Standards`],keyPrinciples:[`Dysphagia (swallowing impairment in stroke, elderly, ICU, and neurological patients) can cause fatal choking or aspiration pneumonia if food lumps are too big or liquids are too thin.`,`The CDM enforces standardized IDDSI testing (10 mL Syringe Flow Test for drinks; Fork Drip, Fork Pressure & Spoon Tilt Tests for foods) before every meal service.`],criticalControlParameters:[{parameter:`IDDSI Texture & Viscosity Verification`,standardLimit:`100% compliance with prescribed IDDSI Level (e.g., Level 4 Pureed: zero lumps, passes Spoon Tilt; Level 5 Minced: ≤4 mm particle size)`,correctiveProtocol:`Re-blend, strain, or adjust food-grade thickener to specification; never serve mixed thin-liquid + solid foods (e.g., watery soup with chunks) to dysphagia patients.`}],practicalChecklist:[`Keep a laminated IDDSI testing chart, 10 mL slip-tip syringes, and metal testing forks at the Diet Cooking station.`,`Verify ice cream, gelatin, and soup do not melt into thin Level 0 liquid in the mouth for patients ordered Thickened Liquids.`],quickCheck:{question:`A stroke patient is prescribed an IDDSI Level 4 (Pureed) diet with Level 2 (Mildly Thick) drinks. Which item is DANGEROUS and must be removed from their tray immediately?`,options:[`Smooth pureed chicken that holds shape on a spoon and slides cleanly off when tilted`,`A cup of vanilla ice cream and a bowl of thin clear broth with diced vegetable chunks`,`Smooth pureed sweet potato with no lumps or liquid separation`,`Pre-thickened apple juice verified at 6 mL remaining on a 10-second IDDSI syringe flow test`],correctIndex:1,explanation:`Ice cream melts into Level 0 thin liquid inside the mouth, and broth with vegetable chunks is a dangerous dual-consistency food that causes rapid aspiration.`},presentationSlides:[{slideNumber:1,title:`Understanding the Global IDDSI Dysphagia Scale (Levels 0–7)`,subtitle:`Eliminating Ambiguous Labels Like "Soft" or "Semi-Solid"`,visualIllustration:`cdm-iddsi-levels`,calloutBanner:{label:`Zero-Aspiration Kitchen Rule: Avoid Dual-Consistency & Melting Foods`,text:`Patients on Thickened Liquids (Levels 1–4) must NEVER receive ice cream, jelly/gelatin, watermelon, or cereal swimming in thin milk — these melt or separate into thin liquid in the throat and enter the lungs!`,tone:`amber`},bulletPoints:[`Why IDDSI Replaced Old Terms: Words like "soft diet" meant different things in every kitchen; IDDSI gives exact measurable particle sizes (4 mm for Level 5, 1.5 cm for Level 6) and objective tests.`,`Dignity & Presentation: Use food molds, piping bags, and vibrant natural colors for Level 4 pureed meals so patients enjoy eating and avoid malnutrition.`],keyTakeaway:`Standardized IDDSI testing transforms dysphagia meal prep from guesswork into measurable life-saving precision.`},{slideNumber:2,title:`Objective IDDSI Kitchen Testing Methods & Verification Log`,subtitle:`Syringe Flow Test, Fork Drip Test, Fork Pressure & Spoon Tilt`,tableBlock:{caption:`Mandatory IDDSI Pre-Service Verification Tests`,headers:[`IDDSI Test Method`,`Used For`,`How to Perform on the Line`,`Pass Criterion`],rows:[[`10 mL Syringe Flow Test`,`Drinks (Levels 0–3)`,`Fill 10 mL slip-tip syringe to 10 mL mark; release nozzle for exactly 10 seconds`,`L0: 0 mL · L1: 1–4 mL · L2: 4–8 mL · L3: >8 mL left`],[`Fork Drip Test`,`Level 3 & Level 4`,`Scoop food onto fork tines and observe drip behavior`,`L4 Pureed sits in a mound above fork; does not continuously drip through`],[`Spoon Tilt Test`,`Level 4 Pureed & L5`,`Hold sample on teaspoon, tilt sideways and flick gently`,`Holds shape on spoon, slides off cleanly with almost no sticky residue`],[`Fork Pressure Test`,`Level 5 (4 mm) & L6 (1.5 cm)`,`Press side/tines of fork until thumbnail blanches white`,`Sample squashes easily and does not spring back; fits 4 mm / 1.5 cm size rule`]]},documentTemplateBlock:{docCode:`CDM-DOC-05`,version:`Rev 1.5`,codexStepLabel:`Dysphagia Safety CCP Log`,docTitle:`Pre-Service IDDSI Texture & Thickened Fluid Verification Log`,purpose:`Verifies that every batch of pureed, minced-moist, soft bite-sized food and thickened liquid meets IDDSI standards at actual serving temperature.`,fields:[{label:`Service Shift`,value:`Lunch & Dinner Dysphagia Line`},{label:`Testing Tools`,value:`10 mL BD Syringe · Standard 4 mm Fork · Teaspoon`},{label:`Temperature Check`,value:`Tested at Serving Temp (≥ 63°C Hot / ≤ 5°C Cold)`},{label:`Verified By`,value:`Diet Chef & Certified Dietary Manager`}],tablePreview:{headers:[`Menu Item`,`Target IDDSI`,`Test Performed`,`Result`,`Sign-Off`],rows:[[`Pureed Roast Chicken & Gravy`,`Level 4 Pureed`,`Fork Drip + Spoon Tilt`,`PASS (Cohesive, zero lumps)`,`CDM ✓`],[`Minced Spinach & Lentils`,`Level 5 Minced`,`4 mm Slot + Fork Pressure`,`PASS (No liquid separation)`,`CDM ✓`],[`Thickened Orange Drink`,`Level 2 Mildly Thick`,`10 mL Syringe (10 sec)`,`6.2 mL left — PASS`,`CDM ✓`]]},signOffLine:`Diet Chef ________ | CDM Pre-Release Approval ________`},bulletPoints:[`Perform both the 10 mL Syringe Flow Test (for drinks) and Fork Drip / Spoon Tilt tests (for pureed/minced meals) before opening the tray line.`,`Document every batch test on CDM-DOC-05 and re-check viscosity whenever hot thickened soups sit longer than 20 minutes.`],keyTakeaway:`Always test IDDSI consistency at actual serving temperature — starches thicken as they cool and thin out if reheated.`}]},{id:`cdm-v-mod-6`,moduleNumber:6,title:`Hospital Food Safety Hazards, Microbiology & Vulnerable (YOPI) Patients`,estimatedMinutes:35,overview:`Protect immunologically vulnerable hospital populations (Young, Old, Pregnant, Immunocompromised — YOPI) by mastering the 4 hazard classes, bacterial growth kinetics on the interactive Germometer, and high-risk hospital food controls.`,internationalClauses:[`Codex Alimentarius CXC 1-1969 Hazard Control`,`WHO Five Keys to Safer Food in Healthcare Settings`],keyPrinciples:[`Hospital patients belong to the highest-risk YOPI demographic: low infectious doses of Listeria, Salmonella, E. coli, or Norovirus that cause mild upset in healthy adults can be fatal in hospitalized patients.`,`Controlling FATTOM factors — especially keeping perishable food out of the 5°C–63°C Temperature Danger Zone — prevents logarithmic bacterial multiplication and spore germination.`],criticalControlParameters:[{parameter:`Hospital Danger Zone & Core Lethality Control`,standardLimit:`Cold ≤ 5°C · Hot ≥ 63°C · Poultry/Minced/Reheated Core ≥ 75°C`,correctiveProtocol:`Discard any high-risk hospital meal exposed between 5°C and 63°C for > 2 hours (stricter hospital YOPI limit).`}],practicalChecklist:[`Enforce zero bare-hand contact with ready-to-eat (RTE) patient salads, fruits, sandwiches, and bread.`,`Verify chilled desserts, oral nutrition shakes, and cooked rice are rapidly chilled and never left on ward counters.`],quickCheck:{question:`Why are Listeria monocytogenes and Salmonella uniquely dangerous in a hospital dietary department compared to a standard public restaurant?`,options:[`Hospital kitchens operate at higher humidity than restaurants`,`Hospital patients are predominantly YOPI (Young, Old, Pregnant, Immunocompromised), where even low pathogen levels can cause sepsis, meningitis, or fatality`,`Listeria only grows inside stainless steel hospital trolleys`,`Antibiotics in hospitals make food bacteria immune to 75°C cooking`],correctIndex:1,explanation:`YOPI patients have weakened immune defenses, making zero-tolerance pathogen prevention, chilled ≤4°C control (Listeria grows slowly even in cold!), and ≥75°C cooking essential.`},presentationSlides:[{slideNumber:1,title:`The Four Food Safety Hazards in Hospital Kitchens`,subtitle:`Interactive Classification of Clinical Dietary Contamination Risks`,visualIllustration:`four-hazards`,bulletPoints:[`Microbiological: Salmonella (poultry/eggs), Listeria monocytogenes (chilled RTE foods, soft cheese — grows even at 4°C!), Bacillus cereus (warm rice), Clostridium perfringens (slow-cooled stews), Norovirus (sick food handlers).`,`Physical: Broken ceramic plate chips, metal scourer strands, bone splinters in fish/poultry, staples from grocery cartons.`,`Chemical: Quaternary sanitizer spray landing on patient trays, dishmachine detergent residue, unapproved pest sprays.`,`Allergenic: Cross-contact of peanuts, milk, egg, gluten, soy, or sesame onto allergen-restricted patient trays.`],classifierDrill:[{item:`Stainless steel wire bristle from a worn kitchen pot scourer found in pureed soup`,category:`Physical`,reason:`Hard metallic foreign object posing severe internal laceration or choking hazard to a patient.`},{item:`Listeria monocytogenes multiplying on pre-sliced chilled turkey stored at 7°C for 5 days`,category:`Microbiological`,reason:`Cold-tolerant pathogenic bacterium capable of causing fatal sepsis in elderly or pregnant patients.`},{item:`Alkaline oven degreaser overspray contaminating uncovered patient dessert bowls`,category:`Chemical`,reason:`Corrosive cleaning chemical entering ready-to-eat patient food.`},{item:`Trace walnut oil transferred via an unwashed ladle onto a nut-allergic pediatric tray`,category:`Allergenic`,reason:`Tree nut proteins can trigger life-threatening anaphylactic shock even in trace amounts.`}],keyTakeaway:`Never use steel wool scourers in hospital kitchens, store chemicals locked away from food, and segregate all allergens.`},{slideNumber:2,title:`Bacterial Spores, Danger Zone & Interactive Hospital Germometer`,subtitle:`Click Every Temperature Stop (-18°C to 100°C) to Master Thermal Control`,visualIllustration:`microbe-spore`,germometerInteractive:!0,highLowRiskDrill:[{food:`Cooked chicken biryani held in a disconnected ward cart at 42°C for 3 hours`,risk:`High-Risk`,reason:`High protein & moisture held at peak Danger Zone allows Bacillus cereus & Clostridium perfringens spore outgrowth.`},{food:`Unopened UHT tetra-pack milk stored in dry store at 20°C`,risk:`Low-Risk`,reason:`Commercially sterile aseptic packaging prevents microbial growth until opened.`},{food:`Freshly pureed custard dessert for geriatric ward held unchilled on counter`,risk:`High-Risk`,reason:`Dairy protein, neutral pH, high moisture, and zero downstream cooking step.`},{food:`Individually sealed packets of dry salted crackers for clear-liquid transition`,risk:`Low-Risk`,reason:`Very low water activity (Aw < 0.50) prevents bacterial multiplication.`}],bulletPoints:[`Click each stop on the interactive Germometer above to compare Freezing (-18°C), Chilled (1°C–5°C), Peak Danger Zone (37°C), Hot Hold (≥ 63°C), and Cooking Lethality (≥ 75°C).`,`Classify each hospital food item above — ready-to-eat high-protein, high-moisture dishes require strict cold/hot thermal control.`],keyTakeaway:`In hospital foodservice, keep cold food ≤ 4°C (limit ≤ 5°C), hot food ≥ 63°C, and discard time-temperature abused items after 2 hours.`}]},{id:`cdm-v-mod-7`,moduleNumber:7,title:`Hospital Dietary SOPs & Prerequisite Hygiene Programmes (PRPs)`,estimatedMinutes:35,overview:`Execute rock-solid Prerequisite Programmes on the hospital kitchen floor through 5 interactive Standard Operating Procedures: Hand Hygiene & 48-Hour Illness Exclusion, Color-Coded Boards, Commercial Dishmachine Sanitizing, Pest Control, and Allergen/NPO Controls.`,internationalClauses:[`Codex GHP Prerequisite Programmes`,`WHO Hand Hygiene & Hospital Infection Prevention (IPC)`],keyPrinciples:[`Prerequisite SOPs eliminate baseline environmental contamination before a single patient meal is cooked.`,`Every kitchen staff member must know exact sanitizer concentrations (e.g., 50–100 ppm chlorine or 200 ppm quat), dishmachine final rinse temperature (≥ 82°C), and the mandatory 48-hour symptom-free return rule after GI illness.`],criticalControlParameters:[{parameter:`Commercial Dishmachine Sanitizing Rinse`,standardLimit:`Wash tank 55°C–65°C · Thermal Sanitizing Final Rinse ≥ 82°C (or validated 50–100 ppm chlorine chemical rinse)`,correctiveProtocol:`Stop warewashing immediately if rinse gauge drops < 82°C; switch to validated 3-sink wash-rinse-sanitize manual SOP and call Engineering.`}],practicalChecklist:[`Inspect every food handler’s nails, hairnet/beard snood, clean uniform, zero jewelry, and health status at shift start.`,`Check dishmachine wash/rinse gauges and chemical sanitizer test strips at the start of every meal shift.`],quickCheck:{question:`What is the minimum required thermal sanitizing final rinse temperature in a commercial hospital dishmachine to kill foodborne pathogens on patient trays?`,options:[`45°C`,`60°C`,`82°C (180°F)`,`37°C`],correctIndex:2,explanation:`High-temperature commercial dishmachines must maintain a final sanitizing rinse of at least 82°C (180°F) so plate surface temperature reaches ≥ 71°C for effective thermal sanitization.`},presentationSlides:[{slideNumber:1,title:`Prerequisite Hygiene Programmes: Foundation of Hospital Food Safety`,subtitle:`Interactive Floor SOPs — Click Each Protocol Tab Below`,visualIllustration:`prp-foundation`,prpProceduresBlock:[{prpCode:`CDM-SOP-01`,prpName:`Hand Hygiene, PPE & 48-Hour Illness Rule`,objective:`Prevent Norovirus, Staphylococcus, and enteric pathogen transfer from food handlers to vulnerable patients.`,steps:[`Remove watches, rings, and nail polish; cover hair/beard completely with hairnets and wear clean department-issued uniform & apron.`,`Wash hands for ≥ 20 seconds using warm water and liquid antibacterial soap before entering kitchen, after restroom use, after touching raw meat, trash, or face, and before putting on gloves.`,`Cover minor clean cuts with a bright BLUE waterproof detectable plaster PLUS a disposable food-grade glove.`,`Exclude any staff reporting vomiting, diarrhea, jaundice, fever with sore throat, or infected skin lesions immediately — permit return ONLY after 48 hours completely symptom-free and medical clearance.`],verificationRecord:`Daily Staff Hygiene & Fitness-to-Work Sign-In Log (checked by CDM every morning).`},{prpCode:`CDM-SOP-02`,prpName:`Color-Coded Cutting Boards & Utensil Segregation`,objective:`Eliminate raw-to-cooked and allergen cross-contamination during meal preparation.`,steps:[`RED: Raw red meat · YELLOW: Raw poultry · BLUE: Raw fish/seafood.`,`GREEN: Raw fruits & washed salads · BROWN: Unwashed root vegetables.`,`WHITE: Bakery, dairy & ready-to-eat cooked items · PURPLE: Dedicated Allergen-Free / Celiac (Gluten-Free) preparation ONLY.`,`Wash, rinse, sanitize (200 ppm quat or 100 ppm chlorine), and air-dry boards vertically on slotted racks after each batch; discard deeply scored boards.`],verificationRecord:`Pre-Operational Sanitation Verification Checklist & Monthly Board Replacement Audit.`},{prpCode:`CDM-SOP-03`,prpName:`Commercial Dishmachine & 3-Sink Manual Sanitizing`,objective:`Guarantee every returning patient plate, lid, and utensil is sanitized free of hospital pathogens.`,steps:[`Scrape food waste into pedal-operated bins and pre-rinse soiled dishes in the isolated Zone 6 Scullery.`,`Verify commercial dishmachine Wash Tank = 55°C–65°C and Final Thermal Sanitizing Rinse ≥ 82°C (if chemical machine, verify 50–100 ppm chlorine with test strip).`,`If machine fails, execute 3-Compartment Sink SOP: Sink 1 Wash (detergent ≥ 45°C) → Sink 2 Clean Rinse → Sink 3 Sanitize (50–100 ppm chlorine ≥ 1 min or 200 ppm quat) → Air Dry ONLY (never towel-dry!).`,`Store sanitized trays inverted on clean mobile racks protected from splashes.`],verificationRecord:`Shift Dishmachine Temperature & Sanitizer Strip Log (logged 3× daily).`},{prpCode:`CDM-SOP-04`,prpName:`Integrated Pest Management (IPM) & Waste Control`,objective:`Maintain a 100% pest-free hospital kitchen without risking toxic pesticide contamination.`,steps:[`Seal door sweeps (< 3 mm gap), fit intact mesh flyscreens on windows, and install UV shatterproof electric fly killers AWAY from open food prep.`,`Line waste bins with heavy-duty bags, keep foot-pedal lids closed, and empty whenever 75% full via the external waste corridor.`,`Allow only licensed IPM contractors to service numbered external bait stations and internal non-toxic glue traps; maintain SDS sheets in the CDM binder.`,`Inspect incoming cardboard produce crates outside Zone 2 and transfer dry items into sealed food-grade containers.`],verificationRecord:`Monthly Licensed Pest Control Trend Report & Sighting Action Log.`},{prpCode:`CDM-SOP-05`,prpName:`Allergen Isolation & NPO Rapid-Pull Protocol`,objective:`Zero patient anaphylaxis events and zero surgical cancellations caused by NPO tray errors.`,steps:[`Highlight every patient allergy and NPO status in bold red on the Ward Diet Sheet and tray ticket.`,`Cook and plate allergen-free meals FIRST using Purple tools; seal tray with tamper-evident allergen sticker before regular line starts.`,`Upon receiving a phone or EMR "NPO" update from a ward nurse, immediately pull the tray from the line or call the cart runner via radio/phone BEFORE bedside delivery.`,`Verify every late/new admission meal ticket against the EMR before releasing from the kitchen.`],verificationRecord:`Daily Allergen & NPO Verification Register signed by Tray-Line Checker.`}],bulletPoints:[`Inspect all five interactive Hospital SOP tabs above — covering Hand Hygiene & 48h Illness Exclusion, Color-Coded Boards, Commercial Dishmachine ≥ 82°C Rinse, IPM, and Allergen/NPO Pulls.`,`Post waterproof SOP quick-reference charts directly at handwash sinks, prep tables, and the dishmachine control panel.`],keyTakeaway:`Written SOPs only protect patients when checked live on the floor every single shift with objective gauges and test strips.`}]},{id:`cdm-v-mod-8`,moduleNumber:8,title:`Cycle Menu Planning, Standardized Recipes & Portion Control Engineering`,estimatedMinutes:35,overview:`Design nutritionally balanced 14-day or 28-day hospital cycle menus, write ironclad Standardized Recipes with exact Edible Portion (EP) yields, and enforce calibrated scoops and ladles for consistent patient nutrition and food cost.`,internationalClauses:[`Institutional Cycle Menu Engineering Best Practices`,`Standardized Portion & Nutrient Consistency Standards`],keyPrinciples:[`A 14-day or 28-day Cycle Menu prevents patient menu fatigue, streamlines seasonal purchasing, stabilizes food cost, and simplifies staff training.`,`Standardized Recipes ensure every chef produces the exact same taste, calorie/sodium content, portion yield, and cost per serving — regardless of who is on shift.`],criticalControlParameters:[{parameter:`Portion Size & Nutrient Accuracy`,standardLimit:`± 5% tolerance on standardized scoop/ladle weight across all therapeutic and regular servings`,correctiveProtocol:`Re-calibrate tray-line serving utensils before startup; audit 3 random plated portions per meal on a digital scale.`}],practicalChecklist:[`Post laminated Standardized Recipe Cards and a Scoop/Ladle Portion Chart directly at the cooking and tray assembly stations.`,`Check seasonal ingredient availability and cultural/religious preferences (Halal, local favorites) before locking each quarterly cycle menu.`],quickCheck:{question:`If a hospital recipe uses a #8 portion scoop (disher) to serve mashed potatoes on Diabetic patient trays, approximately how much volume does one level #8 scoop hold?`,options:[`1 cup (240 mL)`,`1/2 cup (4 fl oz / ~120 mL)`,`1 tablespoon (15 mL)`,`2 cups (480 mL)`],correctIndex:1,explanation:`Scoop numbers equal the number of scoops per quart (32 fl oz): 32 ÷ 8 = 4 fl oz = 1/2 cup (~120 mL), ensuring exact carbohydrate consistency for Diabetic patients.`},presentationSlides:[{slideNumber:1,title:`Cycle Menu Architecture & Portion Utensil Calibration`,subtitle:`Balancing Patient Enjoyment, Clinical Accuracy & Kitchen Efficiency`,twoColumns:{leftTitle:`Cycle Menu Design Principles (14–28 Days)`,leftTone:`blue`,leftItems:[`Matches average hospital stay (long-term care uses 28-day; acute care uses 7–14 day cycles)`,`Balances color, texture, flavor, cooking method & equipment load (avoid overloading ovens)`,`Adapts seamlessly from one "Master Regular Menu" into Diabetic, Renal, Cardiac & IDDSI extensions`,`Incorporates seasonal produce to maximize freshness and keep PPD food cost predictable`],rightTitle:`Why Standardized Recipes Are Mandatory`,rightTone:`emerald`,rightItems:[`Guarantees identical Sodium, Potassium, Carbohydrate & Protein values per serving`,`Eliminates chef guesswork — new cooks deliver consistent hospital quality on Day 1`,`Prevents over-production waste and mid-service food run-outs (exact batch scaling)`,`Locks in accurate Food Cost per portion for monthly hospital budgeting`]},tableBlock:{caption:`Essential Hospital Portion Control Scoops (Dishers) & Ladles Guide`,headers:[`Utensil Size`,`Exact Volume (fl oz / mL)`,`Cup Equivalent`,`Typical Hospital Application`],rows:[[`#6 Scoop`,`5.3 fl oz (~160 mL)`,`2/3 Cup`,`Main starch (rice/pasta) for High-Calorie / Regular`],[`#8 Scoop`,`4.0 fl oz (~120 mL)`,`1/2 Cup`,`Diabetic measured rice, mashed potato, pureed entrée`],[`#10 Scoop`,`3.2 fl oz (~95 mL)`,`2/5 Cup`,`Standard cooked vegetables, hot cereal, custard`],[`#12 Scoop`,`2.7 fl oz (~80 mL)`,`1/3 Cup`,`Soft fruit, side salad, pudding desserts`],[`#16 Scoop`,`2.0 fl oz (~60 mL)`,`1/4 Cup`,`Pureed side veg, thick sauce, renal restricted sides`],[`4 oz / 6 oz Ladle`,`120 mL / 180 mL`,`1/2 – 3/4 Cup`,`Measured soups, dals, broths & gravies`]]},bulletPoints:[`Adapt one Master Cycle Menu cleanly across Regular, Diabetic, Cardiac, Renal, and IDDSI extensions to simplify kitchen prep and ordering.`,`Use calibrated numbered scoops (#6, #8, #10, #12, #16) and oz ladles on every tray-line shift to lock in exact calories and food cost.`],keyTakeaway:`Scoop Number = Scoops per 32 fl oz Quart (#8 = 1/2 cup; #16 = 1/4 cup) — the easiest way to guarantee therapeutic nutrient consistency.`},{slideNumber:2,title:`Hospital Standardized Recipe & Yield Engineering Card`,subtitle:`Integrating HACCP CCPs, Allergens & Cost Into One Master Card`,documentTemplateBlock:{docCode:`CDM-DOC-06`,version:`Rev 3.0`,codexStepLabel:`Production Standardization`,docTitle:`Standardized Hospital Recipe Card (50 Portions — Diabetic & Cardiac Friendly)`,purpose:`Controls exact ingredient weights (AP vs EP), allergen flags, cooking CCP lethality limit, serving utensil, nutrient profile, and cost per serving.`,fields:[{label:`Recipe Name & Yield`,value:`Herb-Steamed Lemon Chicken (50 × 100 g Cooked)`},{label:`Serving Utensil`,value:`Calibrated 100 g Tongs + 2 oz Low-Na Jus Ladle`},{label:`CCP Cooking Limit`,value:`Internal Core ≥ 75°C for 15 sec (Probe Thickest Piece)`},{label:`Nutrition / Allergens`,value:`165 kcal · 28 g Protein · 140 mg Na · Allergens: NONE`}],tablePreview:{headers:[`Ingredient`,`As Purchased (AP)`,`Edible Portion (EP)`,`Prep / Scaling Note`],rows:[[`Skinless Chicken Breast`,`6.25 kg`,`5.00 kg (80% yield)`,`Trim fat; cut uniform 125 g raw fillets`],[`Fresh Lemon Juice & Herbs`,`450 mL`,`450 mL (100%)`,`Zero table salt; rosemary, thyme & garlic`],[`Olive Oil (Cold-Pressed)`,`200 mL`,`200 mL (100%)`,`Light brush before combi-steam roast at 165°C`]]},signOffLine:`Executive Chef ________ | Clinical Dietitian & CDM Approved ________`},bulletPoints:[`Scaling Factor Formula: Factor = Desired Portions ÷ Original Recipe Yield. Multiply every ingredient weight by the exact Factor (always weigh dry/meat items in grams/kg rather than volume cups!).`,`As Purchased (AP) vs Edible Portion (EP): If spinach has 75% yield and you need 6 kg EP, order AP = 6 ÷ 0.75 = 8.0 kg.`],keyTakeaway:`Weighing ingredients and applying AP/EP yield factors prevents both clinical shortage and budget overruns.`}]},{id:`cdm-v-mod-9`,moduleNumber:9,title:`Ethical Procurement, Receiving Gatekeeper & FIFO/FEFO Inventory Control`,estimatedMinutes:30,overview:`Protect hospital food quality and budgets from the loading bay inward using written purchase specifications, Approved Supplier Lists, strict receiving temperature rejection rules, and FIFO/FEFO Par-Level store management.`,internationalClauses:[`ISO 22000 Supplier Evaluation & Purchasing Controls`,`Hospital Ethical Procurement & Cold-Chain Receiving SOP`],keyPrinciples:[`Food safety and cost control begin at the Receiving Bay: once you sign an invoice for warm meat or short-weight produce, the hospital inherits the hazard and the financial loss.`,`Strict FIFO (First-In, First-Out) and FEFO (First-Expired, First-Out) stock rotation, Par-Level reordering, and vertical chiller zoning eliminate spoilage and cross-contamination.`],criticalControlParameters:[{parameter:`Cold-Chain Receiving Temperature Gatekeeper`,standardLimit:`Chilled foods ≤ 5°C (Target ≤ 4°C) · Frozen foods ≤ -18°C (rock solid, zero thaw crystals) · Intact packaging & valid expiry`,correctiveProtocol:`REJECT warm, thawed, dented/swollen canned, pest-infested, or short-dated deliveries immediately; issue Supplier Non-Conformance Report and do not sign invoice.`}],practicalChecklist:[`Never sign a supplier delivery invoice before physically weighing items on a calibrated receiving scale and probing chilled/frozen temperatures.`,`Audit chiller vertical shelving daily: Ready-to-Eat on TOP, raw vegetables in MIDDLE, raw meat/poultry in leak-proof trays on BOTTOM.`],quickCheck:{question:`A supplier delivers 40 kg of fresh chilled chicken breasts for tomorrow’s hospital lunch. Your calibrated digital probe reads +9.5°C between packs. What must you do?`,options:[`Accept the chicken and immediately cook it at 85°C to save time`,`Accept it at a 20% discount and put it in the deep freezer immediately`,`Reject the delivery immediately at the receiving bay, record a Supplier Non-Conformance Report, and source from an approved backup vendor`,`Wash the chicken with hot water and store it on the top shelf of the chiller`],correctIndex:2,explanation:`Chilled poultry above 5°C has already entered the bacterial Danger Zone; it must be rejected at receiving to protect vulnerable hospital patients.`},presentationSlides:[{slideNumber:1,title:`Approved Supplier Gatekeeping & Receiving Bay Controls`,subtitle:`Stopping Unsafe or Short-Weight Stock Before It Enters Your Hospital`,visualIllustration:`approved-supplier`,bulletPoints:[`Written Purchase Specifications: Define exact grade, cut weight, fat %, Halal certification, packaging size, minimum remaining shelf-life, and delivery temperature for every item.`,`Ethical Procurement: Obtain competitive bids from Approved Suppliers only; enforce zero conflict-of-interest/kickback policies and verify Invoice vs Purchase Order vs Physical Delivery (3-Way Match).`,`Immediate Rejection Criteria: Chilled > 5°C, thawed/refrozen crystals, swollen/rusty/seam-dented cans (Botulism risk!), expired dates, broken seals, or dirty delivery trucks.`],keyTakeaway:`Your signature on the delivery note is a legal and clinical certification that the food is safe, complete, and correctly priced.`},{slideNumber:2,title:`Store Zoning, FIFO/FEFO Rotation & Par-Level Control`,subtitle:`Maximizing Shelf-Life While Maintaining Zero Spoilage`,visualIllustration:`cdm-inventory-fifo`,documentTemplateBlock:{docCode:`CDM-DOC-07`,version:`Rev 2.0`,codexStepLabel:`Receiving & Store Control`,docTitle:`Daily Cold-Chain Receiving & Supplier Non-Conformance Log`,purpose:`Records delivery weights, probed temperatures, supplier batch/lot codes (for 4-hour traceability), and immediate rejections.`,fields:[{label:`Receiving Scale Check`,value:`Calibrated ± 10 g Weekly`},{label:`Probe Thermometer ID`,value:`DIG-REC-01 (Ice-Point 0.0°C Verified)`},{label:`Chiller Limit / Freezer`,value:`≤ 5°C Chilled · ≤ -18°C Frozen`},{label:`Storekeeper / Receiver`,value:`Authorized Dietary Storekeeper`}],tablePreview:{headers:[`Time / Vendor`,`Item & Batch Lot #`,`Temp (°C)`,`Expiry / Spec`,`Accept / Reject`],rows:[[`07:15 · Al-Noor Poultry`,`Fresh Chicken Breast · LOT-P982`,`+3.2°C`,`Intact · Halal Cert OK`,`ACCEPTED`],[`07:40 · FreshDairy Co.`,`Pasteurized Milk · LOT-D441`,`+7.8°C`,`Above 5°C Limit!`,`REJECTED — NCR #19`],[`08:05 · MedFoods Dry`,`UHT Oral Shakes · LOT-U112`,`Ambient 21°C`,`Exp Nov 2027 · Sealed`,`ACCEPTED`]]},signOffLine:`Storekeeper ________ | CDM Daily Audit Sign-Off ________`},bulletPoints:[`Par-Level System: Set a Minimum Par (reorder trigger) and Maximum Par (storage cap) for every item so you never run out during emergencies or tie up hospital cash in rotting excess stock.`,`Physical Inventory Security: Keep high-value items (meat, cooking oil, dry milk, oral nutrition supplements) locked with signed Daily Store Issue Requisition slips.`],keyTakeaway:`FEFO rotation, vertical cold-store zoning, and signed store requisitions cut food pilferage and spoilage dramatically.`}]},{id:`cdm-v-mod-10`,moduleNumber:10,title:`Bulk Production, Batch Cooking, Rapid Blast-Chilling & Thermal Control`,estimatedMinutes:35,overview:`Control thermal Critical Control Points across both Cook-Serve and Cook-Chill hospital kitchens: safe thawing, batch cooking lethality, 2-stage rapid blast-chilling, calibrated probe checks, and safe reheating.`,internationalClauses:[`Codex Thermal Processing & Rapid Cooling Standards`,`Hospital Cook-Chill / Cook-Serve HACCP Controls`],keyPrinciples:[`Batch cooking in smaller staggered trays preserves vitamins, flavor, and hot-holding temperatures far better than cooking all hospital meals 3 hours ahead of service.`,`When cooling bulk cooked food (e.g., soups, gravies, cook-chill batches), pass rapidly through the Danger Zone using blast chillers or shallow pans + ice-water baths (60°C → 21°C in ≤ 2h, then 21°C → ≤ 5°C within 4 more hours; or 63°C → ≤ 5°C within 90 min in Cook-Chill).`],criticalControlParameters:[{parameter:`Core Cooking, Rapid Cooling & Reheating Limits`,standardLimit:`Cook ≥ 75°C · Reheat ≥ 75°C (once only) · Blast-Chill to ≤ 5°C within 90 mins (2-stage max 6h total)`,correctiveProtocol:`Continue heating until core reaches ≥ 75°C; if cooling fails time limits, discard batch immediately — reheating will NOT destroy heat-stable toxins!`}],practicalChecklist:[`Calibrate kitchen digital probe thermometers weekly using Ice-Point (0°C ± 0.5°C) and Boiling-Water (100°C ± 0.5°C) verification.`,`Sanitize thermometer probes with alcohol wipes BEFORE and AFTER every single dish check.`],quickCheck:{question:`A 25-liter deep stockpot of cooked chicken soup was left on the counter overnight to cool and reads 28°C the next morning. What must the Certified Dietary Manager order?`,options:[`Boil it vigorously at 100°C for 10 minutes so it becomes safe for patients`,`Move it into the blast chiller immediately and serve it for dinner`,`Discard the entire batch immediately and log a Corrective Action because surviving bacterial spores may have produced heat-stable toxins`,`Serve it only to the staff cafeteria and make a fresh batch for hospital patients`],correctIndex:2,explanation:`Slow overnight cooling allows Clostridium perfringens / Bacillus cereus spores to germinate and Staphylococcus aureus to form heat-stable toxins that boiling CANNOT destroy.`},presentationSlides:[{slideNumber:1,title:`Cook-Serve vs Cook-Chill Hospital Production & Safe Thawing`,subtitle:`Controlling Every Thermal Step From Defrost to Ward Dispatch`,flowDiagramData:{title:`Hospital Thermal Production CCP Map (Cook-Serve & Cook-Chill)`,isMultiStream:!1,mainSteps:[{step:`Safe Thawing (Bottom-Shelf Thaw Chiller ≤ 4°C)`,note:`Never counter-thaw! Drip pans under sealed meat · Use within 24h`},{step:`Staggered Batch Preparation & Seasoning`,note:`Minimize ambient exposure (< 30 min on prep bench)`},{step:`Thermal Cooking Lethality (Core ≥ 75°C)`,note:`Probe thickest thermal center of every batch; log time & temp`,isCcp:!0},{step:`Path A (Cook-Serve): Hot Hold ≥ 63°C OR Path B (Cook-Chill): Blast Chill ≤ 5°C in 90 min`,note:`Shallow pans (< 5 cm depth) for rapid cooling; label date & batch`,isCcp:!0},{step:`Reheating (Cook-Chill Only — Core ≥ 75°C Once Only)`,note:`Retherm carts / combi-ovens; never reheat in bain-marie warmers!`,isCcp:!0}]},bulletPoints:[`Batch Cooking Advantage: Cooking vegetables and proteins in rolling 15-minute waves keeps vitamin loss low, texture crisp, and temperatures safely ≥ 63°C.`,`Never Reheat in Hot-Holders: Bain-maries and soup warmers heat too slowly, holding food in the Danger Zone for hours — always reheat rapidly on stoves or combi-ovens to ≥ 75°C before transfer.`],keyTakeaway:`Fast cooking, fast blast-chilling, and zero slow warming break the bacterial growth cycle completely.`},{slideNumber:2,title:`Probe Thermometer Calibration & CCP Temperature Log`,subtitle:`Objective Proof of Thermal Safety for Every Hospital Meal`,visualIllustration:`thermometer-calibration`,documentTemplateBlock:{docCode:`CDM-DOC-08`,version:`Rev 2.2`,codexStepLabel:`Thermal Processing CCP Record`,docTitle:`Daily Cooking, Hot-Hold & Rapid Cooling CCP Temperature Log`,purpose:`Provides legal, time-stamped thermal verification for every regular and therapeutic dish served across all hospital wards.`,fields:[{label:`Cooking / Reheating CCP`,value:`Core ≥ 75°C (Sanitized Digital Probe)`},{label:`Hot-Hold / Cold-Hold CCP`,value:`Hot ≥ 63°C · Cold ≤ 5°C`},{label:`Probe Calibration Status`,value:`Ice Slurry 0.0°C Verified (Tolerance ± 0.5°C)`},{label:`Deviation Authority`,value:`Head Chef & Certified Dietary Manager`}],tablePreview:{headers:[`Dish / Batch`,`Cook Core (°C)`,`Hot Hold (11:30)`,`Blast Chill (90m)`,`Action / Status`],rows:[[`Herb Chicken (Diabetic/Reg)`,`79.4°C`,`71.0°C`,`N/A (Cook-Serve)`,`PASS ✓`],[`Pureed Lentil Soup (IDDSI L4)`,`84.2°C`,`73.5°C`,`N/A (Cook-Serve)`,`PASS ✓`],[`Custard Dessert (Cook-Chill)`,`76.8°C`,`N/A`,`3.8°C in 75 min`,`PASS ✓`]]},signOffLine:`Shift Cook ________ | Certified Dietary Manager Verification ________`},bulletPoints:[`Verify digital probe thermometers weekly in an agitated ice-water slurry (0.0°C ± 0.5°C) and boiling water (100.0°C ± 0.5°C).`,`Sanitize thermometer stems with alcohol wipes before probing every dish to prevent cross-contamination between raw and cooked trays.`],keyTakeaway:`An uncalibrated thermometer produces false confidence — verify ice-point 0°C weekly and record real-time readings honestly.`}]},{id:`cdm-v-mod-11`,moduleNumber:11,title:`Patient Tray Line Operations, Meal Ticket Auditing & Zero-Error Delivery`,estimatedMinutes:35,overview:`Run a high-precision hospital patient tray assembly line using Pre-Service Test Trays, the 4-Gate Tray Accuracy Checker, insulated thermal trolleys, and seamless late-tray / hold-tray coordination with wards.`,internationalClauses:[`JCI IPSG.1 Dual Patient Identification Standard`,`Hospital Tray-Line Quality & Thermal Delivery SOP`],keyPrinciples:[`The Tray-Line Checker (Starter + Final Auditor) is the final safety firewall before meals reach patients — checking Patient Name + Bed/MRN, Diet Order, Allergen/NPO flag, Portion, Appearance, and Temperature.`,`Always plate and audit a "Test Tray" 15 minutes before line startup to taste every dish (regular + therapeutic), probe hot/cold temperatures, and verify IDDSI texture.`],criticalControlParameters:[{parameter:`Patient Tray Accuracy & Ward Delivery Time`,standardLimit:`≥ 98% tray accuracy (0% allergen/NPO/therapeutic errors) · Hot food ≥ 63°C & Cold ≤ 5°C at bedside · Delivery ≤ 30 mins from plating`,correctiveProtocol:`Intercept and replace any defective tray immediately; investigate root cause of recurring ticket or plating errors during post-meal debrief.`}],practicalChecklist:[`Taste and temperature-probe a full Test Tray (including salt-free therapeutic & IDDSI pureed items) 15 minutes before every meal.`,`Pre-heat insulated thermal bases/pellet warmers and pre-chill cold-cart compartments before loading patient trays.`],quickCheck:{question:`Why must the Certified Dietary Manager (or Shift Supervisor) assemble and taste a "Test Tray" 15 minutes before launching the patient tray line?`,options:[`To ensure kitchen staff get to eat before patients`,`To verify dish flavor, therapeutic seasoning (salt-free/sugar-free), IDDSI texture, visual presentation, and hot/cold serving temperatures before any patient is served`,`To reduce leftover food in the pots`,`Because hospital policy prohibits tasting food during cooking`],correctIndex:1,explanation:`A pre-service Test Tray catches burnt, over-salted, wrong-texture, or lukewarm dishes BEFORE 200+ patient trays are plated and dispatched.`},presentationSlides:[{slideNumber:1,title:`The 4-Gate Patient Tray Accuracy System & Floor SOPs`,subtitle:`Delivering Zero-Error Therapeutic Trays Within 30 Minutes`,visualIllustration:`cdm-tray-accuracy`,prpProceduresBlock:[{prpCode:`TRAY-SOP-01`,prpName:`Pre-Line Setup & 15-Minute Test Tray Approval`,objective:`Verify temperature, taste, therapeutic compliance, and equipment readiness before tray assembly starts.`,steps:[`Pre-heat hot bain-marie wells (water ≥ 85°C), pellet plate heaters, and insulated thermal carts 30 minutes prior to service.`,`Reconcile final Ward Census updates (new admissions, discharges, diet upgrades, NPO orders) and print sorted tray tickets.`,`Assemble 1 Regular + 1 Therapeutic/IDDSI Test Tray: taste with clean disposable spoons, probe hot items (≥ 68°C at line so ≥ 63°C at bedside) and cold items (≤ 4°C).`,`Log Test Tray Approval — do NOT open the tray line until every defective dish is corrected.`],verificationRecord:`Daily Pre-Service Test Tray Taste & Temperature Log (CDM-DOC-09).`},{prpCode:`TRAY-SOP-02`,prpName:`Tray-Line Station Flow & Final Checker Audit`,objective:`Ensure 100% alignment between the printed diet ticket and every item placed on the patient tray.`,steps:[`Station 1 (Starter): Places clean tray mat, correct diet ticket, cutlery, and verifies NPO/Allergen red banners.`,`Stations 2–4 (Cold / Hot / Beverage): Plate exact standardized portions using calibrated scoops/ladles; cover hot plates immediately with thermal domes.`,`Final Checker (End of Line): Performs 100% visual & ticket audit — verifies Name + MRN/Bed, Diet Type, IDDSI texture, Allergen exclusion, condiment restrictions (no salt on cardiac, no sugar on diabetic), and clean plate rims.`,`Load completed trays into ward-labeled closed thermal carts immediately to lock in heat.`],verificationRecord:`Random 10-Tray Accuracy Audit Log (Target ≥ 98% overall · 100% Clinical Safety).`},{prpCode:`TRAY-SOP-03`,prpName:`Bedside Verification, Hold Trays & Late Admissions`,objective:`Guarantee safe bedside handoff and fresh hot meals for patients returning from diagnostics or dialysis.`,steps:[`Deliver closed carts to wards within 30 minutes of plating; coordinate with ward nurse for isolation-room precautions (disposable ware if required by IPC).`,`Verify TWO Patient Identifiers (Full Name + Medical Record Number / Bed) before placing tray at bedside — NEVER rely on room number alone!`,`For patients away at X-ray/MRI/Dialysis, do NOT leave meals cooling on bedside tables — hold fresh portion in kitchen and deliver hot upon nursing call.`,`Collect soiled trays within 60–90 minutes using dedicated soiled return trolleys routed directly to Zone 6 Scullery.`],verificationRecord:`Ward Dispatch Time Log & Late/Hold Tray Fulfillment Register.`}],bulletPoints:[`Use the 4-Gate Verification Protocol (Dual Patient ID, Diet & Allergen Match, Portion/Visual Inspection, and Thermal Delivery ≤ 30 min) on every single meal service.`,`Click through TRAY-SOP-01 to TRAY-SOP-03 above to review Test Tray approval, Final Checker sign-off, and Hold-Tray procedures.`],keyTakeaway:`Never leave a patient meal sitting on an empty bed — Hold Trays protect food safety and patient dignity.`},{slideNumber:2,title:`Controlled Tray Accuracy & Test-Tray Sign-Off Record`,subtitle:`Measuring Excellence at Every Breakfast, Lunch & Dinner`,documentTemplateBlock:{docCode:`CDM-DOC-09`,version:`Rev 2.0`,codexStepLabel:`Tray-Line QA Audit`,docTitle:`Daily Test-Tray & Patient Tray Accuracy Audit Sheet`,purpose:`Tracks pre-service thermal/taste approval and random post-assembly tray audits to sustain ≥ 98% tray accuracy and zero clinical diet errors.`,fields:[{label:`Meal Audited`,value:`Lunch Service · 218 Trays Dispatched`},{label:`Line Start / End Time`,value:`11:30 AM – 12:08 PM (38 Minutes)`},{label:`Bedside Test Temp (Last Tray)`,value:`Hot Entrée 66.2°C · Cold Salad 3.9°C`},{label:`Tray Accuracy Score`,value:`19/20 Audited Perfect (95% → Minor: Missing Napkin)`}],tablePreview:{headers:[`Audit Metric`,`Target`,`Actual Reading`,`Corrective Action`],rows:[[`Therapeutic / Allergen Match`,`100%`,`100% (20/20)`,`Compliant — zero clinical variance`],[`IDDSI Texture Match`,`100%`,`100% (4/4)`,`Fork & Spoon Tilt passed`],[`Hot / Cold Bedside Temp`,`≥ 63°C / ≤ 5°C`,`66.2°C / 3.9°C`,`Thermal domes pre-heated properly`],[`Missing Non-Food Item`,`0 Errors`,`1 Missing Napkin`,`Reminded Starter Station #1 at debrief`]]},signOffLine:`Tray-Line Checker ________ | Certified Dietary Manager ________`},bulletPoints:[`Audit at least 10–20 random completed patient trays per meal against printed diet tickets and track both Clinical Safety (100% target) and Overall Accuracy (≥ 98%).`,`Debrief any minor tray variance immediately with station staff before the next meal shift.`],keyTakeaway:`Measure the temperature of the LAST tray delivered to the farthest ward — if it arrives ≥ 63°C, your thermal chain works.`}]},{id:`cdm-v-mod-12`,moduleNumber:12,title:`Foodservice Budgeting, Food Cost Control, Yield % & Plate Waste Reduction`,estimatedMinutes:35,overview:`Master the financial engine of a Certified Dietary Manager: calculate Food Cost %, Patient-Per-Day (PPD) meal cost, Inventory Turnover, AP/EP Yield %, and Plate Waste % to run a high-quality, fiscally disciplined department.`,internationalClauses:[`Healthcare Foodservice Financial Accounting KPIs`,`Sustainable Hospital Plate-Waste Reduction Standards`],keyPrinciples:[`Hospital administrators evaluate a CDM on both Clinical Safety AND Financial Stewardship — especially Patient-Per-Day (PPD) Food Cost, Labor Productivity (Meals per Labor Hour), and Plate Waste %.`,`Reducing patient plate waste below 15% simultaneously improves clinical nutrition absorption AND saves thousands of dollars/rupees every month.`],criticalControlParameters:[{parameter:`Monthly Food Cost & Patient Plate Waste Threshold`,standardLimit:`Food Cost within ± 3% of approved monthly PPD budget · Patient Plate Waste < 15%`,correctiveProtocol:`Conduct immediate menu popularity review, audit store pilferage/spoilage logs, re-verify portion scoops, and recalibrate batch forecasting.`}],practicalChecklist:[`Calculate weekly Patient-Per-Day (PPD) food cost and compare actual spend against budget before month-end.`,`Run a monthly Plate Waste Audit across wards to identify unpopular dishes or oversized portions.`],quickCheck:{question:`A hospital dietary department spent Rs. 450,000 on raw food during a 30-day month with an average of 150 active inpatients per day (4,500 patient-days). What is the Patient-Per-Day (PPD) food cost?`,options:[`Rs. 3,000 per patient-day`,`Rs. 100 per patient-day`,`Rs. 150 per patient-day`,`Rs. 450 per patient-day`],correctIndex:1,explanation:`PPD Food Cost = Total Monthly Food Cost ÷ Total Patient-Days = Rs. 450,000 ÷ (150 patients × 30 days = 4,500) = Rs. 100 per patient-day.`},presentationSlides:[{slideNumber:1,title:`Essential Certified Dietary Manager Financial Formulas`,subtitle:`Turning Kitchen Numbers Into Executive Boardroom Clarity`,tableBlock:{caption:`Core Financial & Operational Formulas Every CDM Must Master`,headers:[`KPI Metric`,`Exact Formula`,`Worked Hospital Example`,`Benchmark Target`],rows:[[`Cost of Food Used`,`Opening Inventory + Purchases − Closing Inventory`,`100k + 420k − 70k = 450k`,`Reconcile monthly`],[`Food Cost % (Cafeteria)`,`(Cost of Food Used ÷ Total Food Sales) × 100`,`(180k ÷ 600k) × 100 = 30%`,`28% – 35%`],[`Patient-Per-Day (PPD) Cost`,`Total Patient Food Cost ÷ Total Patient-Days`,`450,000 ÷ 4,500 = Rs. 100/day`,`Within ± 3% of budget`],[`Edible Yield %`,`(Edible Cooked Weight ÷ As-Purchased Weight) × 100`,`(4.0 kg ÷ 5.0 kg) × 100 = 80%`,`Track meat & produce`],[`Plate Waste %`,`(Weight of Uneaten Food ÷ Weight Served) × 100`,`(12 kg ÷ 100 kg) × 100 = 12%`,`< 15% Hospital Best Practice`],[`Meals Per Labor Hour (MPLH)`,`Total Meal Equivalents ÷ Total Paid Labor Hours`,`600 meals ÷ 120 hrs = 5.0 MPLH`,`3.5 – 5.5 (Acute Care)`]]},twoColumns:{leftTitle:`Top Causes of Hidden Cost Overruns`,leftTone:`rose`,leftItems:[`Over-production cooking without consulting live ward census`,`Unstandardized portion scooping ("free-pouring" meat & gravies)`,`Poor FIFO/FEFO rotation causing expired dairy & rotting produce`,`Unlocked dry stores, missing receiving scales & unlogged cafeteria staff meals`],rightTitle:`Smart Cost Control Without Cutting Quality`,rightTone:`emerald`,rightItems:[`Enforce calibrated scoops, daily requisition slips & locked high-value stores`,`Shift menus toward seasonal regional vegetables and competitive supplier bids`,`Reduce plate waste by interviewing patients on taste, temp & portion sizes`,`Cross-train kitchen staff to balance peak tray-line labor hours efficiently`]},bulletPoints:[`Master Cost of Food Used (Opening + Purchases − Closing) and Patient-Per-Day (PPD) Cost so budget variances are spotted weekly instead of after month-end.`,`Track Plate Waste % alongside PPD cost — high plate waste means wasted money AND undernourished patients.`],keyTakeaway:`Never slash nutritional quality to cut costs — eliminate spoilage, over-portioning, and plate waste instead.`},{slideNumber:2,title:`Monthly PPD Financial & Plate Waste Executive Dashboard`,subtitle:`Controlled Management Reporting to Hospital Administration`,documentTemplateBlock:{docCode:`CDM-DOC-10`,version:`Rev 1.6`,codexStepLabel:`Financial & Waste Governance`,docTitle:`Monthly Patient-Per-Day (PPD) Food Cost & Plate Waste Report`,purpose:`Summarizes monthly raw food expenditure, inventory turnover, patient-days served, and ward plate waste for Hospital Finance & Administration.`,fields:[{label:`Reporting Period`,value:`Monthly Operating Summary (30 Days)`},{label:`Total Patient-Days`,value:`6,420 Patient-Days (Avg 214 Beds)`},{label:`Inventory Turnover Rate`,value:`3.2× / Month (Target 2.5–4.0×)`},{label:`Overall Plate Waste %`,value:`11.4% (Target < 15% — ON TARGET)`}],tablePreview:{headers:[`Cost Category`,`Monthly Budget`,`Actual Spend`,`Variance & CDM Commentary`],rows:[[`Patient Raw Food (PPD)`,`Rs. 1,926,000`,`Rs. 1,881,000`,`-2.3% Favorable (seasonal veg savings)`],[`Oral Nutrition Supplements`,`Rs. 240,000`,`Rs. 254,000`,`+5.8% (higher ICU oncology census)`],[`Disposables & Sanitation`,`Rs. 165,000`,`Rs. 161,000`,`-2.4% Favorable (auto-dosing chemicals)`],[`Cafeteria Revenue Offset`,`Rs. 750,000`,`Rs. 812,000`,`+8.3% Revenue growth (new healthy combos)`]]},signOffLine:`Certified Dietary Manager ________ | Hospital Finance Director ________`},bulletPoints:[`Explain every positive or negative budget variance clearly using census shifts (e.g., ICU oncology ONS demand) and seasonal market rates.`,`Maintain healthy Inventory Turnover (2.5× to 4.0× per month) so food stays fresh and cash is not trapped in overstocked storerooms.`],keyTakeaway:`A CDM who presents clear PPD variances and plate-waste solutions earns strong leadership trust and capital equipment budgets.`}]},{id:`cdm-v-mod-13`,moduleNumber:13,title:`Human Resource Management, Shift Rostering, Training & Workplace Safety`,estimatedMinutes:30,overview:`Build a loyal, high-performing hospital dietary team through fair shift rostering, structured onboarding and annual food-safety competency tracking, progressive coaching, and kitchen occupational safety (ergonomics, burns, slips, chemicals).`,internationalClauses:[`ISO 45001 Kitchen Occupational Health & Safety`,`Food Handler Medical Screening & Competency Standards`],keyPrinciples:[`A hospital dietary department operates 365 days a year across early morning, afternoon, and relief shifts — fair rotating rosters, clear job descriptions, and cross-training prevent burnout and turnover.`,`Every food handler must hold an up-to-date Medical Fitness Certificate (typhoid/hepatitis/stool & chest screening per local Food Authority) and documented annual HACCP & Therapeutic Diet training.`],criticalControlParameters:[{parameter:`Staff Medical Fitness & Induction Compliance`,standardLimit:`100% of active kitchen staff hold valid Medical Fitness Certificates & completed Day-1 Food Hygiene Induction before handling food`,correctiveProtocol:`Reassign any staff member with an expired medical certificate to non-food duties until renewed lab clearance is filed.`}],practicalChecklist:[`Audit the Staff Medical Fitness & Training Matrix monthly to catch expiring certificates 30 days ahead.`,`Verify anti-slip safety shoes, cut-resistant gloves for slicers, Class K/F fire extinguisher, first-aid kit, and Chemical SDS binder are in place.`],quickCheck:{question:`A newly hired diet aide arrives for their first shift during a busy lunch rush. What MUST the Certified Dietary Manager ensure BEFORE assigning them to assemble patient trays?`,options:[`Let them learn by trial and error on the diabetic tray line and train them next month`,`Verify valid medical clearance, clean PPE/hairnet, handwashing competency, and provide structured induction on diet tickets, allergens, and NPO safety`,`Ask them to wash pots without gloves for the first week`,`Only give them the written handbook to read at home after the shift`],correctIndex:1,explanation:`Untrained or medically unscreened staff on a hospital tray line create immediate clinical and foodborne risks; Day-1 hygiene and safety induction is mandatory.`},presentationSlides:[{slideNumber:1,title:`Dietary Department Staffing, Shift Rosters & Progressive Leadership`,subtitle:`Coaching Excellence While Preventing Kitchen Injuries`,tableBlock:{caption:`Sample 200-Bed Hospital Dietary Shift Roster Architecture`,headers:[`Shift Window`,`Core Operational Responsibilities`,`Key Roles On Duty`,`Handover Protocol`],rows:[[`Morning Shift (05:30 – 13:30)`,`Receiving bay, Breakfast & Lunch production, Tray Line, Mid-morning ONS`,`CDM, Head Chef, Diet Cook, Storekeeper, 6 Tray Aides, 3 Stewards`,`13:15 Written Census & Chiller Temp Handover`],[`Evening Shift (12:30 – 20:30)`,`Evening tea/snacks, Dinner production, Tray Line, Deep Scullery & Sanitation`,`Shift Supervisor, Evening Chef, Diet Cook, 5 Tray Aides, 3 Stewards`,`20:15 End-of-Day Lockup, Gas Shutoff & Prep List`],[`Relief / Staggered Pool`,`Covers weekly days off, annual leave & high-census surges without overtime`,`Cross-trained Relief Cook & Relief Diet Aides`,`Published 14 days in advance`]]},twoColumns:{leftTitle:`Progressive Coaching & Discipline Ladder`,leftTone:`blue`,leftItems:[`Step 1: Private Coaching & Retraining (fix skill gaps respectfully)`,`Step 2: Documented Verbal Warning with clear 14-day expectation`,`Step 3: Written Warning signed with HR for repeated SOP breaches`,`Immediate Suspension: Intentional food tampering, falsifying CCP logs, or working while hiding severe GI illness`],rightTitle:`Kitchen Occupational Health & Safety (OH&S)`,rightTone:`amber`,rightItems:[`Slips & Falls: Mandatory oil-resistant anti-slip shoes + immediate spill mop + wet-floor cones`,`Burns & Steam: Dry heat-resistant oven mitts (wet cloths conduct steam burns!), open combi-oven doors standing back`,`Cuts & Machinery: Unplug slicers before cleaning; use cut-resistant mesh gloves on blades`,`Chemicals & Fire: Never mix Bleach + Acid/Ammonia (toxic chlorine gas!); keep Class K/F extinguisher & fire blanket accessible`]},bulletPoints:[`Publish fair rotating shift rosters at least 14 days in advance with structured written shift handovers between Morning and Evening teams.`,`Verify Class K/F kitchen fire extinguishers, fire blankets, cut-resistant gloves, and Chemical Safety Data Sheets (SDS) during monthly safety rounds.`],keyTakeaway:`Praise staff publicly, coach mistakes privately, and treat kitchen safety (burns, slips, chemicals) with the same urgency as food safety.`},{slideNumber:2,title:`Food Handler Medical Fitness & Competency Tracking Matrix`,subtitle:`Audit-Ready HR Documentation for Food Authorities & JCI`,documentTemplateBlock:{docCode:`CDM-DOC-11`,version:`Rev 1.9`,codexStepLabel:`HR & Competency Compliance`,docTitle:`Dietary Staff Medical Fitness & Annual Training Matrix`,purpose:`Ensures 100% of kitchen and tray-line personnel maintain active health screening and verified competency in HACCP, Allergens, and IDDSI.`,fields:[{label:`Total Active Staff`,value:`26 Full-Time Equivalents (FTEs)`},{label:`Medical Screening Cycle`,value:`Every 6–12 Months (Per Local Food Authority)`},{label:`Mandatory Annual Modules`,value:`Hand Hygiene · HACCP · Allergens · IDDSI · Fire`},{label:`Compliance Target`,value:`100% Valid Certificates (Zero Expired)`}],tablePreview:{headers:[`Staff Name & Role`,`Medical Cert Expiry`,`HACCP / Hygiene`,`IDDSI & Allergen`,`Status`],rows:[[`Ahmed R. (Diet Chef)`,`Aug 2027`,`Completed (92%)`,`Verified Practical ✓`,`COMPLIANT`],[`Sana K. (Tray Checker)`,`May 2027`,`Completed (95%)`,`Verified Practical ✓`,`COMPLIANT`],[`Bilal M. (Steward)`,`Expires in 18 Days`,`Completed (84%)`,`N/A (Scullery)`,`RENEWAL SCHEDULED`]]},signOffLine:`Certified Dietary Manager ________ | Hospital HR / IPC Nurse ________`},bulletPoints:[`Flag expiring Medical Fitness Certificates 30 days early so zero kitchen staff work with lapsed health clearance.`,`Keep signed Day-1 Hygiene Induction forms and practical competency evaluations on file for every active and relief employee.`],keyTakeaway:`Auditors always ask for two HR files first: Medical Fitness Certificates and Signed Food Hygiene Training Attendance Sheets.`}]},{id:`cdm-v-mod-14`,moduleNumber:14,title:`Quality Assurance (CQI), 72-Hour Food Samples, Traceability & Disaster Planning`,estimatedMinutes:35,overview:`Protect hospital continuity and legal due diligence through 72-hour retained food sample protocols, 4-hour batch traceability, quantitative risk scoring, foodborne outbreak containment, and 72-hour emergency/disaster menu plans.`,internationalClauses:[`Hospital Emergency Preparedness & 72-Hour Reserve Standards`,`Codex Traceability, Recall & Outbreak Investigation Protocols`],keyPrinciples:[`Retaining 150 g sterile samples of every cooked hospital meal item at ≤ 4°C (or frozen) for 72 hours provides objective laboratory evidence if an outbreak is ever suspected.`,`Every hospital dietary department must maintain a written 72-Hour Disaster Menu, potable water reserve (≥ 3 L/patient/day), and power-outage cold-chain contingency SOP.`],criticalControlParameters:[{parameter:`72-Hour Retained Food Samples & Outbreak Traceability`,standardLimit:`150 g sealed labeled sample per dish retained for 72 hours at ≤ 4°C · Full supplier lot traceability within ≤ 4 hours`,correctiveProtocol:`Upon any cluster of patient GI symptoms, immediately lock down retained samples for Infection Control / Lab testing, isolate implicated batches, and trace supplier lots.`}],practicalChecklist:[`Verify the dedicated 72-Hour Food Sample Refrigerator has sterile bags, dated labels (Meal, Dish, Date, Time, Collector), and daily temperature log ≤ 4°C.`,`Rotate 72-hour emergency canned/UHT stock every 3–6 months using FIFO so disaster supplies never expire.`],quickCheck:{question:`Three hospitalized patients report acute vomiting 4 hours after lunch. What is the Certified Dietary Manager’s FIRST priority action?`,options:[`Immediately discard all leftover food and 72-hour samples so inspectors cannot find them`,`Preserve all remaining meal batches and 72-hour retained food samples untouched, notify Infection Control & Medical Director, and start 4-hour batch/lot traceability`,`Blame the ward nurses before checking any kitchen temperature records`,`Close the hospital kitchen permanently without arranging patient meals`],correctIndex:1,explanation:`Preserving 72-hour retained samples and notifying Infection Control immediately enables rapid scientific root-cause identification and protects other patients.`},presentationSlides:[{slideNumber:1,title:`72-Hour Disaster Menus, Power Outages & Outbreak Containment`,subtitle:`Keeping Hospital Patients Fed Safely When Utilities Fail`,visualIllustration:`cdm-emergency-plan`,riskMatrixHighlight:!0,bulletPoints:[`72-Hour Retained Sample Protocol: Using sanitized spoons, collect ≥ 150 g of every cooked regular & therapeutic dish into sterile zip-bags/containers; label Date, Meal, Dish Name, Temp & Initials; hold at ≤ 4°C for exactly 72 hours before safe disposal.`,`Power Outage Cold-Chain Rule: Keep chiller/freezer doors SHUT! A closed freezer stays safe ~24–48h and chiller ~4h; if chilled high-risk food climbs > 5°C for > 2–4 hours, discard — "When in doubt, throw it out!"`,`Boil-Water Alert: Halt ice machines, vegetable washing with tap water, and coffee brewers; immediately switch to bottled potable water, disposable ware, and no-cook shelf-stable menus.`],keyTakeaway:`Emergency preparedness is tested BEFORE a flood, power outage, or boil-water alert hits — never during the crisis.`},{slideNumber:2,title:`72-Hour Food Sample & Emergency Contingency Register`,subtitle:`Controlled Evidence for Infection Control & Regulatory Audits`,documentTemplateBlock:{docCode:`CDM-DOC-12`,version:`Rev 2.1`,codexStepLabel:`Traceability & Emergency Control`,docTitle:`72-Hour Retained Food Sample & Emergency Readiness Log`,purpose:`Documents daily retention and controlled disposal of 150 g hospital meal samples alongside monthly 72-hour emergency stock rotation checks.`,fields:[{label:`Sample Fridge ID / Temp`,value:`FRIDGE-SMP-01 (Target 2.0°C · Limit ≤ 4°C)`},{label:`Sample Weight & Hold`,value:`150 g per Dish · Retained Full 72 Hours`},{label:`Emergency Water Stock`,value:`2,250 Liters Bottled (250 Beds × 3 L × 3 Days)`},{label:`Mock Recall Drill Time`,value:`Completed in 1 hr 45 mins (Limit ≤ 4 hrs)`}],tablePreview:{headers:[`Date / Meal`,`Dish Sampled (150 g)`,`Batch / Lot Ref`,`Collected By`,`72h Disposal Date`],rows:[[`Mon · Lunch`,`Herb-Steamed Chicken`,`LOT-P982`,`Shift Supv ✓`,`Thu 14:00 (Logged)`],[`Mon · Lunch`,`Pureed Lentil Soup (L4)`,`LOT-L204`,`Shift Supv ✓`,`Thu 14:00 (Logged)`],[`Mon · Dinner`,`Baked Fish (Cardiac)`,`LOT-F519`,`Evening Supv ✓`,`Thu 20:00 (Logged)`]]},signOffLine:`CDM Quality Lead ________ | Hospital Infection Control Officer ________`},bulletPoints:[`Store 150 g sterile labeled samples of every cooked regular and therapeutic dish at ≤ 4°C for a full 72 hours before documented disposal.`,`Run semi-annual timed mock recall drills proving supplier batch-to-ward traceability within ≤ 4 hours.`],keyTakeaway:`Never skip 72-hour sample collection — it is your hospital’s strongest scientific protection during any patient GI complaint.`}]},{id:`cdm-v-mod-15`,moduleNumber:15,title:`Hospital Accreditation Readiness (JCI / ISO 22000), Revision & Exam Mastery`,estimatedMinutes:35,overview:`Connect all 14 prior modules into one executive CQI & Hospital Accreditation Audit Blueprint (JCI, ISO 22000, Provincial/National Food Authorities), test your recall of official CDM definitions, and prepare to excel on the 40-MCQ Final Examination.`,internationalClauses:[`JCI Hospital Food & Nutrition Accreditation Standards`,`ISO 22000:2018 & Food Authority Inspection Readiness`],keyPrinciples:[`Accreditation readiness is NOT a one-week cleanup before inspectors arrive — it is daily living compliance across temperature logs, medical certificates, IDDSI verification, tray accuracy, and patient satisfaction surveys.`,`A Certified Dietary Manager continuously tracks 5 core KPIs (Tray Accuracy ≥ 98%, Meal Temp Compliance ≥ 63°C/≤ 5°C, Plate Waste < 15%, 72h Samples 100%, Traceability ≤ 4h) and presents monthly CQI improvements.`],criticalControlParameters:[{parameter:`Continuous Audit & Legal Due Diligence Readiness`,standardLimit:`100% real-time, honestly signed records (zero back-dated or pre-filled logs) archived for ≥ 12–24 months`,correctiveProtocol:`Conduct unannounced weekly mock self-audits using the Food Authority / JCI checklist and close every CAPA finding with photographic proof.`}],practicalChecklist:[`Maintain an indexed "Audit Ready Master Binder" containing Food License, Staff Medical Certs, Calibration Certs, Pest Reports, Water Lab Tests, and SOPs.`,`Complete the interactive Recall & Reveal Revision Drill below before starting the 40-MCQ Final Examination.`],quickCheck:{question:`During a surprise Hospital Accreditation / Food Authority inspection, an auditor notices that next Friday’s refrigerator temperature log is already filled out with "3.5°C". What does this represent?`,options:[`Proactive time management by an efficient kitchen supervisor`,`A critical compliance failure (record falsification) that destroys legal due diligence and invalidates the entire food safety system`,`An acceptable shortcut if the chiller is brand new`,`A minor cosmetic error requiring no corrective action`],correctIndex:1,explanation:`Pre-filling or back-dating food safety logs is falsification of legal records; every temperature, calibration, and cleaning check must be recorded honestly in real time.`},presentationSlides:[{slideNumber:1,title:`Master CDM Accreditation & CQI Performance Dashboard`,subtitle:`Every Hospital Benchmark Connected Across One Audit-Ready View`,visualIllustration:`cdm-quality-audit`,tableBlock:{caption:`Master Certified Dietary Manager Audit & Operational Reference Chart`,headers:[`Audit Domain`,`Mandatory Standard / Limit`,`Key Controlled Document`,`Audit Verification Proof`],rows:[[`Clinical Coordination`,`Live Ward Census + Dual Patient ID + NPO pull`,`CDM-DOC-01 & DOC-04`,`Zero NPO/diet mix-ups; signed census`],[`Dysphagia (IDDSI)`,`Levels 0–7 verified via Syringe / Fork / Spoon`,`CDM-DOC-05`,`Live IDDSI testing tools & shift log`],[`Cold-Chain & Stores`,`Chilled ≤ 5°C · Frozen ≤ -18°C · FEFO · 15 cm floor`,`CDM-DOC-07`,`Calibrated probe & zero expired stock`],[`Thermal CCPs`,`Cook/Reheat ≥ 75°C · Hot ≥ 63°C · Blast-Chill 90m`,`CDM-DOC-08`,`Real-time signed logs + Ice-Point 0°C`],[`Tray-Line & Warewash`,`Test Tray 15m pre-line · Rinse ≥ 82°C · ≥ 98% Acc`,`CDM-DOC-09 & SOP-03`,`Bedside temp probe & dishmachine gauge`],[`HR, Cost & Emergency`,`100% Medical Certs · PPD ±3% · 72h Samples/Stock`,`CDM-DOC-10, 11 & 12`,`Master Audit Binder + ≤ 4h mock recall`]]},bulletPoints:[`Review all 6 Hospital Audit Domains above prior to JCI, ISO 22000, or Provincial Food Authority inspections.`,`Keep every temperature, dishmachine rinse, calibration, medical fitness, and 72-hour sample record signed honestly in real time.`],keyTakeaway:`When your daily logs are honest, your Test Trays are verified, and your staff are trained, your kitchen is audit-ready 365 days a year.`},{slideNumber:2,title:`Interactive Revision: Recall & Reveal Official CDM Definitions`,subtitle:`Test Yourself on 10 Core Terms Before Launching the 40-MCQ Final Exam`,definitionMatchDrill:[{term:`NPO (Nil Per Os)`,definition:`A strict physician order meaning "Nothing by Mouth" (no food, water, or ice) — typically before surgery or diagnostic procedures; meal trays must be pulled immediately.`},{term:`IDDSI Framework (Levels 0–7)`,definition:`International Dysphagia Diet Standardisation Initiative defining objective viscosity and particle-size levels (Drinks 0–4, Foods 3–7) using Syringe Flow, Fork Drip, and Spoon Tilt tests.`},{term:`YOPI Population`,definition:`Young, Old, Pregnant, and Immunocompromised patients — the most vulnerable demographic in healthcare requiring strict zero-tolerance food safety controls.`},{term:`FEFO (First-Expired, First-Out)`,definition:`Inventory rotation system ensuring stock with the earliest expiration/use-by date is issued and consumed first to prevent spoilage and expired ingredients.`},{term:`As Purchased (AP) vs Edible Portion (EP)`,definition:`AP is the raw weight bought from the supplier including peel/bone/trim; EP is the usable weight remaining after trimming and cooking (Yield % = EP ÷ AP × 100).`},{term:`PPD (Patient-Per-Day) Food Cost`,definition:`Core hospital dietary financial KPI calculated as Total Patient Food Cost divided by Total Patient-Days served during the accounting period.`},{term:`Plate Waste Percentage`,definition:`Percentage of served patient food returned uneaten on trays — tracked below 15% to optimize both patient clinical nutrition intake and food budget.`},{term:`72-Hour Retained Food Sample`,definition:`A sealed, labeled 150 g sample of every cooked dish stored at ≤ 4°C for 72 hours for microbiological investigation if a foodborne illness outbreak occurs.`},{term:`Neutropenic (Low-Microbial) Diet`,definition:`Specialized diet for severely immunocompromised/oncology patients excluding raw salads, unpeeled raw fruits, unpasteurized dairy, and undercooked foods.`},{term:`Pre-Service Test Tray`,definition:`Sample regular and therapeutic tray assembled 15 minutes before meal service so the CDM verifies flavor, seasoning compliance, IDDSI texture, and temperature prior to patient dispatch.`}],calloutBanner:{label:`Final Exam Readiness Strategy (40 MCQs · 60% Pass · 75% Distinction)`,text:`Read each hospital scenario carefully — pay close attention to exact clinical limits (75°C core, 63°C hot hold, ≤ 5°C chilled, 82°C dishmachine rinse, 48h illness exclusion, 72h food samples, 15% plate waste, 98% tray accuracy) and patient-first safety priorities.`,tone:`emerald`},bulletPoints:[`Click each hidden row in the Revision Drill above to verify your recall of all 10 high-yield Certified Dietary Manager terms.`,`Achieve ≥ 60% (24/40) to Pass or ≥ 75% (30/40) for Distinction on the 40-MCQ Final Examination to unlock your official QR-Verified Portrait PDF Certificate.`],keyTakeaway:`You have mastered all 15 Certified Dietary Manager modules — launch the 40-MCQ Final Exam below to earn your Official QR-Verified CDM Certificate!`}]}],c=[{id:`cdm-q01`,question:`How do the professional roles of a Clinical Dietitian (RD) and a Certified Dietary Manager (CDM) work together in a hospital?`,options:[`The CDM writes physician drug orders while the Dietitian operates the commercial dishmachine`,`The Clinical Dietitian performs nutrition assessment and prescribes Medical Nutrition Therapy, while the CDM manages kitchen operations, HACCP, budgets, staffing, and accurate therapeutic meal delivery`,`Both roles have identical legal authority to cancel surgical NPO orders without consulting a doctor`,`The CDM is limited exclusively to the visitor coffee shop and has no role in patient meal quality`],correctIndex:1,explanation:`Clinical Dietitians lead clinical assessment and MNT prescriptions; Certified Dietary Managers direct foodservice operations, food safety, budgeting, staffing, and accurate patient tray execution.`,moduleRef:`Module 1: Scope of Practice & Interdisciplinary Care Team`},{id:`cdm-q02`,question:`A nurse calls the dietary office 10 minutes before lunch dispatch to report that Bed 204 has been switched from "Regular Diet" to "NPO" for emergency surgery. What must the CDM do immediately?`,options:[`Send the tray anyway and let the patient decide whether to eat`,`Replace the solid lunch with a cup of clear apple juice and broth`,`Immediately pull Bed 204’s tray from the line or notify the cart runner before delivery and update the Ward Census log`,`Wait until dinner service to update the diet sheet`],correctIndex:2,explanation:`NPO (Nil Per Os) means nothing by mouth; delivering food or drink to a pre-surgical NPO patient risks severe anesthesia aspiration and surgical cancellation.`,moduleRef:`Module 1: Scope of Practice & Interdisciplinary Care Team`},{id:`cdm-q03`,question:`What is the primary food safety purpose of enforcing a strict "One-Way Flow" (Dirty-to-Clean) layout in a hospital kitchen?`,options:[`To reduce electricity usage by placing chillers next to ovens`,`To ensure raw ingredients and returning soiled ward trays never cross paths with clean cooked food and plated patient trays`,`To allow delivery trucks to drive directly into the tray assembly zone`,`To eliminate the need for separate handwashing sinks`],correctIndex:1,explanation:`One-Way forward flow physically separates raw receiving, prep, clean tray assembly, and returning soiled ward carts to prevent cross-contamination.`,moduleRef:`Module 2: Hospital Kitchen Architecture & One-Way Flow`},{id:`cdm-q04`,question:`Which facility lighting and floor specification is standard for a hygienic hospital food preparation and tray assembly area?`,options:[`Unshielded glass bulbs and rough porous concrete flooring`,`Dim ambient lighting (< 100 lux) and carpeted walkways`,`Shatterproof-sleeved lighting (≥ 500 lux) with smooth, anti-slip, washable flooring and coved wall-to-floor junctions`,`Open floor trenches without drain traps to speed up hosing`],correctIndex:2,explanation:`Shatterproof ≥ 500 lux lighting prevents glass contamination and improves visual inspection; coved anti-slip floors prevent dirt buildup and staff slips.`,moduleRef:`Module 2: Hospital Kitchen Architecture & One-Way Flow`},{id:`cdm-q05`,question:`What type of lubricant must hospital maintenance engineers exclusively use on food mixers, meat slicers, and tray-line conveyors?`,options:[`Standard automotive motor oil`,`NSF H1 Food-Grade Lubricant`,`Industrial diesel grease`,`Used vegetable frying oil`],correctIndex:1,explanation:`NSF H1 food-grade lubricants are non-toxic and approved for incidental food contact on kitchen processing machinery.`,moduleRef:`Module 2: Hospital Kitchen Architecture & One-Way Flow`},{id:`cdm-q06`,question:`How many kilocalories (kcal) are supplied per gram by Carbohydrates, Protein, and Fat respectively?`,options:[`4 kcal/g Carbohydrate, 4 kcal/g Protein, 9 kcal/g Fat`,`9 kcal/g Carbohydrate, 4 kcal/g Protein, 4 kcal/g Fat`,`2 kcal/g Carbohydrate, 6 kcal/g Protein, 12 kcal/g Fat`,`4 kcal/g Carbohydrate, 9 kcal/g Protein, 4 kcal/g Fat`],correctIndex:0,explanation:`Carbohydrates and Proteins each provide 4 kcal/g, whereas Fats provide concentrated energy at 9 kcal/g.`,moduleRef:`Module 3: Essential Nutrition Science & Screening`},{id:`cdm-q07`,question:`A hospitalized geriatric patient eats less than 50% of their meals for 3 consecutive days and mentions difficulty chewing. What is the CDM’s mandatory action?`,options:[`Serve half portions permanently to cut plate waste`,`Document the low intake, interview the patient on preferences/denture comfort, and submit an immediate Clinical Dietitian Referral`,`Ignore the observation until the patient requests a doctor`,`Switch the patient to an unprescribed clear liquid diet independently`],correctIndex:1,explanation:`Consuming < 50% of meals for 3 consecutive days is a key hospital malnutrition trigger requiring documented intake review and prompt RD escalation.`,moduleRef:`Module 3: Essential Nutrition Science & Screening`},{id:`cdm-q08`,question:`Which cooking practice best preserves water-soluble vitamins (Vitamin C and B-complex) and natural color in hospital vegetables?`,options:[`Boiling vegetables in large pots of water for 60 minutes and holding for 3 hours`,`Steaming or batch-cooking in small staggered quantities just prior to tray assembly`,`Adding baking soda to boiling water to brighten green vegetables`,`Reheating leftover vegetables three times across consecutive shifts`],correctIndex:1,explanation:`Small-batch steaming minimizes water leaching and prolonged heat destruction of Vitamin C and folate.`,moduleRef:`Module 3: Essential Nutrition Science & Screening`},{id:`cdm-q09`,question:`Which condiment or ingredient is DANGEROUS and must NEVER be offered to a Renal (Chronic Kidney Disease) patient as a salt alternative?`,options:[`Fresh lemon juice and dried rosemary`,`Garlic powder (salt-free) and black pepper`,`Commercial Potassium Chloride ("Lo-Salt") salt substitute`,`Fresh chopped parsley and white vinegar`],correctIndex:2,explanation:`Commercial salt substitutes replace sodium with potassium chloride, which can cause fatal hyperkalemia and cardiac arrest in renal patients.`,moduleRef:`Module 4: Clinical Therapeutic Diets`},{id:`cdm-q10`,question:`Which meal item must be STRICTLY excluded from a Neutropenic (Low-Microbial) oncology patient’s tray?`,options:[`Well-cooked herb chicken probed at 78°C internal core temperature`,`Unopened UHT pasteurized milk tetra-pack`,`Fresh raw mixed garden salad with unpeeled berries and soft unpasteurized cheese`,`Individually sealed canned peaches in light syrup`],correctIndex:2,explanation:`Immunocompromised neutropenic patients face life-threatening infections from raw unpeeled produce and unpasteurized dairy; all foods must be thoroughly cooked or commercially sterile.`,moduleRef:`Module 4: Clinical Therapeutic Diets`},{id:`cdm-q11`,question:`Which menu item is ACCEPTABLE on a strict post-operative Clear Liquid diet?`,options:[`Strained fat-free clear broth, clear apple juice, plain gelatin, and black tea`,`Cream of mushroom soup, whole milk, and vanilla yogurt`,`Oatmeal porridge with mashed banana`,`Orange juice with thick fruit pulp and blended lentil soup`],correctIndex:0,explanation:`A Clear Liquid diet permits only transparent, residue-free liquids that are liquid at body temperature — zero milk, cream, pulp, or opaque solids.`,moduleRef:`Module 4: Clinical Therapeutic Diets`},{id:`cdm-q12`,question:`What is the primary operational goal of a Diabetic (Carbohydrate-Controlled) hospital menu?`,options:[`Eliminate 100% of all carbohydrates including grains and vegetables`,`Deliver consistent, measured complex carbohydrates (typically 45–60 g/meal), high fiber, and zero refined simple sugars aligned with insulin/medication timing`,`Double the fat and salt content to replace sugar calories`,`Serve all daily calories in one single evening meal`],correctIndex:1,explanation:`Consistent measured carbohydrate portions and timely meal delivery prevent dangerous blood glucose spikes and insulin-induced hypoglycemia.`,moduleRef:`Module 4: Clinical Therapeutic Diets`},{id:`cdm-q13`,question:`Under the global IDDSI Framework, which objective kitchen test is used to verify Thickened Drinks (Levels 0 to 3)?`,options:[`Measuring fluid temperature with a laser gun`,`The 10 mL Slip-Tip Syringe Flow Test timed for exactly 10 seconds`,`Pouring the beverage through a pasta colander`,`Weighing the drinking cup on a receiving scale`],correctIndex:1,explanation:`The IDDSI 10 mL Syringe Flow Test measures exact liquid remaining after 10 seconds of gravity flow (L0: 0 mL; L1: 1–4 mL; L2: 4–8 mL; L3: > 8 mL).`,moduleRef:`Module 5: Texture-Modified Diets & IDDSI Framework`},{id:`cdm-q14`,question:`Why must vanilla ice cream and gelatin (jelly) NEVER be served to a dysphagia patient ordered IDDSI Level 2 (Mildly Thick) liquids?`,options:[`They contain too much dietary fiber for dysphagia patients`,`They melt inside the warm mouth into thin Level 0 liquid, creating a high risk of silent aspiration pneumonia`,`They are too expensive for standard hospital budgets`,`They cannot be served on color-coded hospital trays`],correctIndex:1,explanation:`Foods that turn into thin liquid at body temperature (ice cream, gelatin, ice chips) bypass thickened-fluid precautions and can enter the airway.`,moduleRef:`Module 5: Texture-Modified Diets & IDDSI Framework`},{id:`cdm-q15`,question:`What particle size and fork behavior define an IDDSI Level 5 (Minced & Moist) meal?`,options:[`Whole roasted cuts requiring a steak knife`,`Soft, moist lumps no larger than 4 mm (adult) that squash easily with light fork pressure and have zero thin liquid separation`,`Completely watery thin broth that passes freely through fork tines`,`Dry crispy bread cubes of 3 cm size`],correctIndex:1,explanation:`IDDSI Level 5 Minced & Moist requires soft, cohesive particles ≤ 4 mm (fitting between standard fork prongs) with no separate thin liquid draining out.`,moduleRef:`Module 5: Texture-Modified Diets & IDDSI Framework`},{id:`cdm-q16`,question:`What does the food safety acronym "YOPI" represent in healthcare foodservice?`,options:[`Yearly Operational Productivity Index`,`Young, Old, Pregnant, and Immunocompromised — the most vulnerable patient groups`,`Yield Output Per Ingredient`,`Yellow, Orange, Purple, and Indigo cutting boards`],correctIndex:1,explanation:`YOPI patients have immature, weakened, or altered immune defenses, making strict pathogen prevention mandatory in hospital kitchens.`,moduleRef:`Module 6: Hospital Food Safety Hazards & YOPI Patients`},{id:`cdm-q17`,question:`Which pathogenic bacterium is uniquely hazardous in chilled hospital ready-to-eat foods (sliced meats, soft cheeses, sandwiches) because it can continue multiplying slowly even at +4°C?`,options:[`Listeria monocytogenes`,`Lactobacillus acidophilus`,`Saccharomyces cerevisiae`,`Bifidobacterium longum`],correctIndex:0,explanation:`Listeria monocytogenes is psychrotrophic (cold-tolerant) and can cause fatal listeriosis/meningitis in elderly, pregnant, and immunocompromised hospital patients.`,moduleRef:`Module 6: Hospital Food Safety Hazards & YOPI Patients`},{id:`cdm-q18`,question:`Between which temperatures does the bacterial "Temperature Danger Zone" occur, and what is the stricter hospital maximum ambient exposure rule for perishable patient meals?`,options:[`-18°C to 0°C; maximum 12 hours`,`5°C to 63°C; discard high-risk hospital food abused beyond 2 hours`,`65°C to 95°C; maximum 6 hours`,`0°C to 4°C; maximum 30 minutes`],correctIndex:1,explanation:`Pathogens multiply rapidly between 5°C and 63°C; hospitals enforce a strict 2-hour cumulative Danger Zone limit to protect vulnerable YOPI patients.`,moduleRef:`Module 6: Hospital Food Safety Hazards & YOPI Patients`},{id:`cdm-q19`,question:`Which color-coded cutting board and utensil set is reserved EXCLUSIVELY for Allergen-Free and Celiac (Gluten-Free) patient meal preparation?`,options:[`Red board`,`Yellow board`,`Purple board and dedicated purple-handled tools`,`Brown root-vegetable board`],correctIndex:2,explanation:`Purple boards, knives, and pans are internationally recognized for dedicated allergen-free / gluten-free preparation to prevent trace cross-contact.`,moduleRef:`Module 7: Hospital Dietary SOPs & Prerequisite Programmes`},{id:`cdm-q20`,question:`A kitchen cook reports having acute vomiting and diarrhea early in the morning. When may the Certified Dietary Manager legally allow them to return to food handling?`,options:[`Immediately if they wear two pairs of disposable gloves`,`After taking an over-the-counter tablet and waiting 4 hours`,`Only after being completely symptom-free for at least 48 hours and receiving medical fitness clearance`,`The same afternoon if they only wash dishes`],correctIndex:2,explanation:`Food handlers with vomiting or diarrhea (Norovirus/enteric pathogens) must be excluded immediately and remain off duty until at least 48 hours completely symptom-free.`,moduleRef:`Module 7: Hospital Dietary SOPs & Prerequisite Programmes`},{id:`cdm-q21`,question:`What is the required final sanitizing rinse temperature in a high-temperature commercial hospital dishmachine?`,options:[`50°C`,`65°C`,`≥ 82°C (180°F)`,`40°C`],correctIndex:2,explanation:`A final thermal sanitizing rinse of ≥ 82°C ensures dish surface temperature achieves ≥ 71°C for validated pathogen destruction.`,moduleRef:`Module 7: Hospital Dietary SOPs & Prerequisite Programmes`},{id:`cdm-q22`,question:`After sanitizing patient dishes in a 3-compartment manual sink (Wash → Rinse → Sanitize), how must the clean dishes be dried?`,options:[`Wiped quickly with a reusable cotton kitchen towel`,`Air-dried completely on clean sanitized slatted racks`,`Dried with paper napkins from the cafeteria`,`Stacked wet immediately inside closed meal trolleys`],correctIndex:1,explanation:`Cloth towels re-contaminate sanitized tableware with bacteria; air-drying on sanitized drain racks is mandatory.`,moduleRef:`Module 7: Hospital Dietary SOPs & Prerequisite Programmes`},{id:`cdm-q23`,question:`If a standardized hospital recipe requires 12 kg of Edible Portion (EP) peeled carrots and carrots have an 80% yield, how many kg of As Purchased (AP) carrots must you order?`,options:[`9.6 kg`,`12.0 kg`,`15.0 kg`,`18.5 kg`],correctIndex:2,explanation:`AP Weight = EP Weight ÷ Yield % = 12 kg ÷ 0.80 = 15.0 kg As Purchased.`,moduleRef:`Module 8: Cycle Menus, Standardized Recipes & Portion Control`},{id:`cdm-q24`,question:`On a hospital tray line, how much volume does one level #16 portion scoop (disher) measure?`,options:[`2.0 fl oz (1/4 cup / ~60 mL)`,`4.0 fl oz (1/2 cup / ~120 mL)`,`8.0 fl oz (1 cup / ~240 mL)`,`16 fl oz (2 cups / ~480 mL)`],correctIndex:0,explanation:`Scoop number equals scoops per quart (32 fl oz): 32 ÷ 16 = 2 fl oz = 1/4 cup (~60 mL).`,moduleRef:`Module 8: Cycle Menus, Standardized Recipes & Portion Control`},{id:`cdm-q25`,question:`Why are 14-day or 28-day Cycle Menus preferred over static daily menus in hospitals and long-term care facilities?`,options:[`They eliminate the need for therapeutic diets`,`They reduce patient menu fatigue, streamline seasonal procurement, standardize labor forecasting, and stabilize PPD food cost`,`They allow chefs to improvise recipes daily without written cards`,`They avoid the requirement to inspect incoming deliveries`],correctIndex:1,explanation:`Cycle menus balance patient variety with predictable purchasing, consistent standardized recipes, and disciplined budget control.`,moduleRef:`Module 8: Cycle Menus, Standardized Recipes & Portion Control`},{id:`cdm-q26`,question:`During receiving inspection, a pallet of canned tomato paste includes 6 cans with swollen, bulging lids and deep seam dents. What is the correct decision?`,options:[`Accept them and use the swollen cans first under FIFO`,`Reject the swollen and seam-dented cans immediately due to Clostridium botulinum (Botulism) risk and log a Supplier NCR`,`Open and boil the swollen cans for 5 minutes to remove gas`,`Store them in the deep freezer until next month`],correctIndex:1,explanation:`Swollen or seam-dented cans indicate loss of hermetic seal or anaerobic Clostridium botulinum gas/toxin growth — immediate rejection is mandatory.`,moduleRef:`Module 9: Procurement, Receiving & FIFO/FEFO Inventory`},{id:`cdm-q27`,question:`In a walk-in hospital chiller (+1°C to +4°C), what is the mandatory vertical shelf-stacking hierarchy from TOP to BOTTOM?`,options:[`Top: Raw poultry · Middle: Raw red meat · Bottom: Ready-to-eat patient desserts`,`Top: Ready-to-Eat cooked meals, salads & dairy · Middle: Washed vegetables · Bottom: Raw meat & poultry in leak-proof drip trays`,`All items mixed together alphabetically by supplier name`,`Raw meat stored directly on the tiled chiller floor for coldest airflow`],correctIndex:1,explanation:`Storing raw meat/poultry on the bottom shelf in sealed drip trays prevents raw blood or juices from dripping onto ready-to-eat hospital foods.`,moduleRef:`Module 9: Procurement, Receiving & FIFO/FEFO Inventory`},{id:`cdm-q28`,question:`How high above the floor must dry store shelving be raised in a compliant hospital food store?`,options:[`Flush on the floor with cardboard sheets underneath`,`At least 15 cm (6 inches) off the floor and 5 cm away from walls`,`1 cm off the floor`,`Height does not matter if bags are sealed in plastic`],correctIndex:1,explanation:`Maintaining ≥ 15 cm floor clearance and 5 cm wall spacing enables floor mopping, airflow circulation, and rapid visual pest inspection.`,moduleRef:`Module 9: Procurement, Receiving & FIFO/FEFO Inventory`},{id:`cdm-q29`,question:`What is the minimum validated internal core cooking temperature for poultry, minced meats, and reheated cook-chill hospital meals?`,options:[`55°C`,`63°C`,`≥ 75°C (verified at the thickest thermal center with a sanitized digital probe)`,`100°C for 30 minutes`],correctIndex:2,explanation:`An internal core temperature of ≥ 75°C (or validated equivalent 70°C for 2 min) guarantees thermal lethality of vegetative pathogens like Salmonella and Campylobacter.`,moduleRef:`Module 10: Bulk Production, Rapid Cooling & Thermal Control`},{id:`cdm-q30`,question:`How should frozen raw chicken breasts be safely thawed in a hospital dietary kitchen?`,options:[`Submerged in a sink of warm tap water for 4 hours`,`Left uncovered on a stainless steel prep table overnight`,`Inside a dedicated bottom-shelf thaw chiller maintained at ≤ 4°C in covered drip pans`,`Placed near the exhaust hood above the hot cooking range`],correctIndex:2,explanation:`Thawing in a bottom-shelf chiller at ≤ 4°C keeps outer meat surfaces out of the Danger Zone while preventing raw thaw drip onto other foods.`,moduleRef:`Module 10: Bulk Production, Rapid Cooling & Thermal Control`},{id:`cdm-q31`,question:`When calibrating a digital food probe thermometer using the Ice-Point method (crushed ice + clean water slurry), what exact reading confirms calibration?`,options:[`+4.0°C ± 2.0°C`,`0.0°C (within ± 0.5°C tolerance)`,`-18.0°C ± 1.0°C`,`+10.0°C ± 0.5°C`],correctIndex:1,explanation:`An agitated ice-water slurry stabilizes at exactly 0.0°C (32°F); probes deviating beyond ± 0.5°C must be recalibrated or replaced.`,moduleRef:`Module 10: Bulk Production, Rapid Cooling & Thermal Control`},{id:`cdm-q32`,question:`Before handing a patient their meal tray at the hospital bedside, how must staff verify patient identity per JCI IPSG.1 safety standards?`,options:[`Check the room number on the door only`,`Verify TWO patient identifiers (Full Patient Name + Medical Record Number / Bed or Date of Birth) against the printed diet ticket`,`Ask the visitor in the hallway which bed ordered chicken`,`Place the tray silently on the bedside table without checking the wristband`],correctIndex:1,explanation:`Room numbers change frequently; verifying two independent patient identifiers prevents serving a regular or allergen-containing meal to the wrong patient.`,moduleRef:`Module 11: Patient Tray Line & Zero-Error Delivery`},{id:`cdm-q33`,question:`What is the target hot-holding and cold-holding temperature at the point of patient bedside meal service?`,options:[`Hot ≥ 50°C · Cold ≤ 12°C`,`Hot ≥ 63°C · Cold ≤ 5°C`,`Hot ≥ 45°C · Cold ≤ 15°C`,`Temperature does not need checking once plated`],correctIndex:1,explanation:`Hot entrées must remain ≥ 63°C and cold salads/desserts ≤ 5°C through bedside delivery (ideally within ≤ 30 minutes of plating) to stay safely outside the Danger Zone.`,moduleRef:`Module 11: Patient Tray Line & Zero-Error Delivery`},{id:`cdm-q34`,question:`A patient is temporarily away from their ward for a 90-minute MRI scan during lunch delivery. What is the correct Hold-Tray procedure?`,options:[`Leave the hot tray uncovered on the empty bed until the patient comes back`,`Discard the patient’s lunch record and wait until dinner`,`Hold the meal order in the kitchen and deliver a freshly plated hot tray (≥ 63°C) when the ward nurse confirms the patient has returned`,`Give the patient’s therapeutic tray to the neighboring bed`],correctIndex:2,explanation:`Leaving meals unattended on empty beds drops food into the Danger Zone and leaves the returning patient with cold, unsafe food.`,moduleRef:`Module 11: Patient Tray Line & Zero-Error Delivery`},{id:`cdm-q35`,question:`A hospital kitchen starts the month with Rs. 120,000 in inventory, purchases Rs. 580,000 of food, and ends the month with Rs. 100,000 in closing inventory. What is the Cost of Food Used?`,options:[`Rs. 560,000`,`Rs. 600,000`,`Rs. 700,000`,`Rs. 800,000`],correctIndex:1,explanation:`Cost of Food Used = Opening Inventory (120,000) + Purchases (580,000) − Closing Inventory (100,000) = Rs. 600,000.`,moduleRef:`Module 12: Budgeting, Food Cost & Plate Waste`},{id:`cdm-q36`,question:`During a ward Plate Waste Audit, 100 kg of patient food was served and 24 kg came back uneaten (24% waste vs < 15% benchmark). Which action best addresses the root cause?`,options:[`Stop weighing returning waste so the numbers look better`,`Analyze which dishes/wards drive the waste, interview patients on flavor, temperature, and portion size, and refine recipes/cycle menus`,`Force patients to finish their trays before discharge`,`Cut food quality further to offset the wasted weight`],correctIndex:1,explanation:`High plate waste (> 15%) signals palatability, temperature, cultural mismatch, or oversized portions — targeted patient feedback fixes both nutrition and budget.`,moduleRef:`Module 12: Budgeting, Food Cost & Plate Waste`},{id:`cdm-q37`,question:`Why must kitchen staff NEVER mix Chlorine Bleach with Acid descalers or Ammonia-based floor cleaners?`,options:[`The mixture loses its color on white tiles`,`It triggers a hazardous chemical reaction releasing lethal toxic chlorine/chloramine gas inside the kitchen`,`It makes the floor slightly slippery`,`It increases the cost of cleaning supplies by 5%`],correctIndex:1,explanation:`Mixing bleach with acids or ammonia releases highly toxic chlorine or chloramine vapors that cause acute respiratory injury; always follow SDS sheets.`,moduleRef:`Module 13: Human Resources, Rostering & Kitchen Safety`},{id:`cdm-q38`,question:`For how many hours and at what temperature must a hospital kitchen retain 150 g labeled food samples of every cooked patient meal item?`,options:[`12 hours at room temperature (25°C)`,`24 hours in the hot-holding cabinet`,`72 hours at ≤ 4°C (or frozen) in sealed sterile containers`,`30 days in the dry grocery store`],correctIndex:2,explanation:`Retaining 150 g samples of every cooked dish at ≤ 4°C for 72 hours covers standard foodborne illness incubation windows for laboratory root-cause testing.`,moduleRef:`Module 14: Quality Assurance, 72h Samples & Disaster Planning`},{id:`cdm-q39`,question:`If the hospital experiences a sudden municipal "Boil-Water Alert" due to water main contamination, what must the Certified Dietary Manager do immediately?`,options:[`Continue washing raw salads with tap water since sanitizer is unnecessary`,`Shut down ice machines and tap-water prep, switch immediately to bottled potable water (≥ 3 L/patient/day reserve), no-cook emergency menus, and single-use disposable tableware`,`Serve only dry bread with zero beverages for 48 hours`,`Wait for local television news to confirm before taking kitchen action`],correctIndex:1,explanation:`During a boil-water alert, contaminated tap water can taint ice, produce, and dishwashing — bottled water, disposable ware, and disaster menus protect patients immediately.`,moduleRef:`Module 14: Quality Assurance, 72h Samples & Disaster Planning`},{id:`cdm-q40`,question:`Within what maximum time window should a well-managed hospital dietary department trace any ingredient batch/lot number from supplier delivery to ward service during a recall or outbreak?`,options:[`Within 2 to 4 hours using Receiving Lot Logs and Daily Production Records`,`Within 30 business days`,`Within 6 months during the annual financial audit`,`Batch traceability is only required for pharmaceutical drugs, not hospital food`],correctIndex:0,explanation:`Logging supplier lot numbers at receiving and daily production allows a Certified Dietary Manager to isolate recalled ingredients within 2 to 4 hours.`,moduleRef:`Module 15: Accreditation Readiness & Exam Mastery`}],l={id:`mgr-food-dietary-2026`,code:`CDM-CERT`,title:`Certified Dietary Manager`,levelBadge:`Visual Interactive Course (15 Modules · Clinical SOPs, Hospital Docs & Drills · 40 MCQs)`,accreditationStandard:`ANFP / Codex CXC 1-1969 • Certified Dietary Manager (CDM) Professional Standard`,duration:`15 Interactive Modules (Clinical SOPs, Controlled Docs & Drills) + 40-MCQ Final Exam`,certificateFeeRs:8e3,passPercentage:60,distinctionPercentage:75,totalExamQuestions:40,description:`Comprehensive Certified Dietary Manager (CDM) hospital & institutional foodservice certification featuring custom clinical visual diagrams, interactive Hospital Dietary & Tray-Line SOPs, 12 controlled sample hospital document forms (CDM-DOC-01 to 12), IDDSI dysphagia controls, interactive Germometer, Risk Matrix & Hazard Drills, financial PPD dashboards, and a 40-MCQ final exam.`,modules:s,coreExamPool:c.map(e=>({q:e.question,options:e.options,correctIndex:e.correctIndex,explanation:e.explanation}))},u={id:l.id,category:`International Certification`,title:`Certified Dietary Manager`,standardCode:`CDM-CERT`,accreditationStandard:l.accreditationStandard,certificateFeeRs:l.certificateFeeRs,subType:l.levelBadge,description:l.description,duration:l.duration,fees:`Free Study & Exam · Rs. 8,000 Certificate`,enrollLink:`#trainings`,isActive:!0,customModules:s.map(e=>({id:e.id,subject:e.title,description:`${e.overview}\n\n${e.keyPrinciples.join(`

`)}`})),customMcqs:c.map(e=>({id:e.id,question:e.question,options:e.options,correctIndex:e.correctIndex,explanation:e.explanation}))},d=[{id:`cert-2026-food-safety-level-03`,code:`FS-L3`,title:`Food Safety Level 03`,levelBadge:`Simple Presentation Course (05 Modules · 40 Slides · 40 MCQs · 60% Pass)`,accreditationStandard:`International Supervising Food Safety & Hygiene Level 03 • Presentation Course`,duration:`05 Presentation Modules (40 Slides) + 40-MCQ Final Exam`,certificateFeeRs:1e3,passPercentage:60,distinctionPercentage:75,totalExamQuestions:40,description:`Comprehensive Slide Presentation Course on Supervising Food Safety (Level 03) for Kitchen Supervisors, Restaurant Managers, Production Line Leaders, and QA Officers. Covers Food Microbiology & Foodborne Illness, Temperature Control & Safe Storage, Cross-Contamination & Allergen Supervision, Premises Hygiene, Cleaning & Pest Control, and Supervisory Inspections & Food Safety Law.`,modules:[{id:`fs3-mod-1`,moduleNumber:1,title:`Supervisory Responsibilities, Food Microbiology & Foodborne Illness`,estimatedMinutes:40,overview:`Simple presentation on the role of a Level 03 Food Safety Supervisor, how bacteria multiply (FATTOM), key food poisoning pathogens, and high-risk vs. low-risk foods.`,internationalClauses:[`Codex General Principles of Food Hygiene & Level 03 Supervisory Standards`],keyPrinciples:[`A Food Safety Level 03 Supervisor leads by example, trains food handlers, checks daily hygiene and temperature logs, and corrects unsafe practices on the spot.`,`Bacteria require 6 conditions to multiply (FATTOM): Food (protein/moisture), Acidity (neutral pH 4.6–7.5), Time, Temperature (+5°C to +60°C), Oxygen, and Moisture (aw > 0.85).`,`High-Risk Foods are Ready-to-Eat, high-protein, moist foods (cooked meat, poultry, dairy, cooked rice, seafood, egg dishes) that support rapid bacterial growth without further cooking.`,`Major foodborne pathogens include Salmonella, Campylobacter, E. coli O157, Listeria monocytogenes, Staphylococcus aureus, Clostridium perfringens, Bacillus cereus, and Norovirus.`],criticalControlParameters:[{parameter:`Bacterial Binary Fission in the Temperature Danger Zone`,standardLimit:`Keep high-risk foods out of +5°C to +60°C (bacteria double every 10–20 minutes at +37°C)`,correctiveProtocol:`Discard any high-risk ready-to-eat food left in the Danger Zone for more than 4 hours.`},{parameter:`High-Risk Ready-to-Eat (RTE) Food Protection`,standardLimit:`Store covered at ≤ +4°C (+5°C max), separate from raw foods, with strict Use-By date labels`,correctiveProtocol:`Never prepare or store High-Risk RTE foods on surfaces used for raw meat.`}],practicalChecklist:[`Conduct a daily pre-shift hygiene inspection of all food handlers and workstations.`,`Check that all High-Risk Ready-to-Eat foods in chillers are covered, date-labeled, and stored above raw items.`,`Coach new staff on the 6 FATTOM conditions and why time-temperature control is critical.`],presentationSlides:[{slideNumber:1,title:`The Role of a Level 03 Food Safety Supervisor`,subtitle:`Why Supervisors Are the Backbone of Safe Food Operations`,bulletPoints:[`Food Safety Level 03 is designed for Supervisors, Sous Chefs, Shift Managers, and QA Officers who oversee food handlers.`,`Your key duties: Train and coach staff, monitor daily temperature and cleaning logs, inspect deliveries, and enforce personal hygiene.`,`Good food safety prevents food poisoning outbreaks, protects brand reputation, reduces food waste, and ensures legal compliance.`],keyTakeaway:`As a Supervisor, what you walk past is what you accept—always correct unsafe food handling immediately.`},{slideNumber:2,title:`High-Risk vs. Low-Risk Foods`,subtitle:`Knowing Which Foods Require Strict Refrigeration`,bulletPoints:[`High-Risk Foods: Ready-to-Eat (RTE) foods that are moist and high in protein, where bacteria can grow quickly and which will be eaten without further cooking.`,`Examples of High-Risk Foods: Cooked meat and poultry, cooked rice and pasta, milk, cream, soft cheeses, cooked eggs/mayonnaise, smoked fish, and prepared salads.`,`Low-Risk Foods: Dry, acidic, salty, or high-sugar foods where bacteria cannot easily grow (e.g., dry flour, uncooked rice, biscuits, pickles, jam, cooking oil).`],keyTakeaway:`Note: Cooked rice is a High-Risk Food because Bacillus cereus spores survive boiling and multiply if rice is left warm!`},{slideNumber:3,title:`How Bacteria Multiply (The 6 FATTOM Factors)`,subtitle:`Understanding What Bacteria Need to Grow`,bulletPoints:[`Bacteria multiply by splitting in two (Binary Fission) every 10 to 20 minutes under ideal conditions.`,`F — Food: High-protein, nutrient-rich foods.`,`A — Acidity: Bacteria prefer neutral pH (between pH 4.6 and 7.5); strong acid (pH < 4.6 like vinegar/lemon) stops most bacterial growth.`,`T — Time & T — Temperature: In the Temperature Danger Zone (+5°C to +60°C), a few bacteria can become millions in just a few hours.`,`O — Oxygen: Some bacteria need air (aerobic), while others grow in vacuum packs or deep pots without air (anaerobic).`,`M — Moisture: Bacteria need available water (Water Activity aw > 0.85) to grow.`],keyTakeaway:`By controlling Time and Temperature (keeping food ≤ +5°C or ≥ +63°C), you break the FATTOM chain.`},{slideNumber:4,title:`Key Food Poisoning Bacteria Every Supervisor Must Know (Part 1)`,subtitle:`Salmonella, Campylobacter & E. coli O157`,bulletPoints:[`Salmonella: Found in raw poultry, raw eggs, and unpasteurized milk. Killed by cooking to ≥ +75°C and using pasteurized eggs.`,`Campylobacter jejuni: The most common bacterial cause of foodborne diarrhea; found in raw chicken. Never wash raw chicken in the sink (splashing water spreads Campylobacter across the kitchen!).`,`E. coli O157 (STEC): Found in raw minced beef, unwashed salad vegetables, and contaminated water. Has a very low infective dose and can cause severe kidney failure in children.`],keyTakeaway:`Never wash raw chicken at a kitchen sink—cook it thoroughly to ≥ +75°C to kill Salmonella and Campylobacter.`},{slideNumber:5,title:`Key Food Poisoning Bacteria (Part 2)`,subtitle:`Staphylococcus aureus, Clostridium perfringens & Bacillus cereus`,bulletPoints:[`Staphylococcus aureus: Carried in the nose, throat, skin, and cuts of healthy humans. Transfers to cooked ham, salads, or cream pastries via bare hands and produces a heat-stable vomiting toxin within 1–6 hours.`,`Clostridium perfringens: Spore-former found in soil and raw meat; multiplies in large pots of gravy, stew, or curry cooled too slowly.`,`Bacillus cereus: Spore-former found in rice, cereals, and spices; produces a heat-stable vomiting toxin if cooked rice is left at room temperature.`],keyTakeaway:`Cool cooked rice, curries, and gravies rapidly (to ≤ +4°C) and never handle Ready-to-Eat foods with bare hands.`},{slideNumber:6,title:`Listeria monocytogenes & Foodborne Viruses`,subtitle:`Cold-Tolerant Bacteria & Highly Contagious Viruses`,bulletPoints:[`Listeria monocytogenes: Found in soft cheeses, pâté, sliced deli meats, smoked fish, and wet chiller drains. Crucially, it can grow slowly even inside a refrigerator at +1°C to +4°C!`,`Norovirus ("Winter Vomiting Bug") & Hepatitis A: Viruses do NOT multiply in food, but just 10 to 100 viral particles from an infected food handler’s unwashed hands can infect dozens of diners.`,`Strict handwashing with soap and water + 48-hour exclusion after vomiting/diarrhea are essential to stop Norovirus.`],keyTakeaway:`Alcohol hand gel alone does NOT kill Norovirus effectively—thorough handwashing with soap and running warm water is mandatory.`},{slideNumber:7,title:`Food Spoilage vs. Food Poisoning`,subtitle:`Why "Smelling the Food" Cannot Protect You`,bulletPoints:[`Spoilage Bacteria & Molds: Break down food so it smells sour, looks slimy, or shows visible green/white mold—people see or smell it and do not eat it.`,`Pathogenic (Food Poisoning) Bacteria: Do NOT change the look, smell, or taste of food!`,`A chicken sandwich contaminated with a lethal dose of Salmonella or Listeria looks, smells, and tastes 100% normal.`],keyTakeaway:`Never taste or smell food to decide if it is safe—rely on calibrated thermometers and strict time/date logs.`},{slideNumber:8,title:`Vulnerable Groups (YOPI) & Outbreak Reporting`,subtitle:`Protecting Those at Highest Risk`,bulletPoints:[`YOPI Groups: Young children/infants, Old/elderly people, Pregnant women, and Immunocompromised patients have weaker immune systems and face the highest risk of hospitalization or death.`,`If 2 or more customers or staff report similar illness after eating the same meal, treat it as a suspected outbreak: quarantine remaining food, preserve reference samples, and notify management/authorities.`],keyTakeaway:`Fast supervisory containment during a suspected illness complaint prevents a single case from becoming a major outbreak.`}]},{id:`fs3-mod-2`,moduleNumber:2,title:`Temperature Control, Delivery, Storage, Cooking, Cooling & Reheating`,estimatedMinutes:40,overview:`Simple presentation on all critical food safety temperatures from receiving to service, how to calibrate and use probe thermometers, and how to supervise safe thawing, cooking, blast chilling, and hot/cold holding.`,internationalClauses:[`International Food Code Time-Temperature Controls`],keyPrinciples:[`Cold Chain Rule: Chilled deliveries and refrigerators must be maintained at +1°C to +4°C (maximum +5°C); Freezers must operate at ≤ -18°C.`,`Thermal Cooking & Reheating Rule: Cook and reheat high-risk foods to a core temperature of ≥ +75°C for 30 seconds (or ≥ +70°C for 2 minutes).`,`Rapid Cooling Rule: Cool hot food from +60°C to +20°C within ≤ 2 hours and then from +20°C to ≤ +4°C within ≤ 4 hours (or ≤ 90 minutes in a Blast Chiller).`,`Service Holding Rule: Keep hot food at ≥ +63°C and cold food at ≤ +5°C.`],criticalControlParameters:[{parameter:`Safe Core Cooking, Reheating & Hot/Cold Holding Limits`,standardLimit:`Cook/Reheat ≥ +75°C; Hot Hold ≥ +63°C; Cold Hold ≤ +5°C; Freezer ≤ -18°C`,correctiveProtocol:`Reheat once to ≥ +75°C if hot holding drops below +63°C for < 2 hours, or discard immediately.`},{parameter:`Probe Thermometer Calibration & Sanitization`,standardLimit:`Ice-point check at 0.0°C (±0.5°C to ±1.0°C) and boiling check at 100.0°C; sanitize probe before and after every use`,correctiveProtocol:`Replace or recalibrate any thermometer that drifts by more than ±1.0°C.`}],practicalChecklist:[`Check and sign morning and evening temperature logs for all walk-in chillers, reach-in fridges, and freezers.`,`Verify that staff sanitize probe thermometers with alcohol wipes before and after probing food.`,`Ensure cooked batches are cooled in shallow pans or blast chillers and labeled with a 72-hour maximum Use-By date.`],presentationSlides:[{slideNumber:1,title:`The Complete Temperature Summary Chart`,subtitle:`Every Number You Need for Level 03 Exams & Daily Supervision`,bulletPoints:[`Freezer Storage & Frozen Delivery: ≤ -18°C.`,`Chiller Storage & Chilled Delivery: +1°C to +4°C (Legal maximum ≤ +5°C; Fresh fish on ice ≤ +2°C).`,`Temperature Danger Zone (TDZ): +5°C to +60°C (Optimal bacterial growth at +37°C).`,`Hot Holding (Buffet / Bain-Marie): ≥ +63°C.`,`Core Cooking & Reheating Temperature: ≥ +75°C for 30 seconds (or ≥ +70°C for 2 minutes; ≥ +82°C for reheating in Scotland).`,`Dishwasher Final Sanitizing Rinse: ≥ +82°C.`],keyTakeaway:`Post this temperature chart near the kitchen pass so every cook and server knows the exact limits.`},{slideNumber:2,title:`How to Use & Calibrate Digital Probe Thermometers`,subtitle:`Getting Accurate Core Readings Without Cross-Contamination`,bulletPoints:[`Never rely on a fridge’s outside wall dial alone—check actual food temperatures using a digital core probe thermometer.`,`How to Probe Correctly: Wipe the metal stem with a food-safe antibacterial alcohol wipe, insert the tip into the thickest center part of the food (avoiding bone or pan metal), wait 15 seconds for the reading to stabilize, then wipe clean again.`,`Ice-Point Calibration: Fill a cup with crushed ice and cold water (50:50 slurry); stir and insert the probe—it must read 0.0°C (±0.5°C).`,`Boiling-Point Calibration: In rapidly boiling water, the probe must read 100.0°C (±1.0°C).`],keyTakeaway:`Always sanitize the thermometer probe before AND after probing each food item, and use separate probes for raw and cooked foods.`},{slideNumber:3,title:`Supervising Safe Delivery & Cold Storage`,subtitle:`Maintaining the Unbroken Cold Chain`,bulletPoints:[`Inspect deliveries immediately at the receiving bay—transfer chilled and frozen goods into cold storage within 15 minutes.`,`Do not overload refrigerators or pack cartons tightly against the back wall, as cold air must circulate freely around shelves.`,`Never put hot pans directly into a storage chiller, as the steam raises the chiller temperature and puts all other stored food into the Danger Zone.`,`Follow FEFO (First Expired, First Out) and label all prepped/opened items with a clear Use-By date.`],keyTakeaway:`Overloading a refrigerator blocks airflow and creates warm pockets where food spoils rapidly.`},{slideNumber:4,title:`Supervising Safe Thawing (Defrosting)`,subtitle:`Eliminating Raw Drip & Surface Bacterial Growth`,bulletPoints:[`Why is room-temperature thawing dangerous? Because the outside of a frozen chicken reaches +25°C (Danger Zone) while the center is still frozen solid!`,`Standard Thawing Method: Place frozen meat/poultry in a deep covered container on the BOTTOM shelf of a dedicated Thawing Chiller at ≤ +4°C.`,`Make sure raw thawing liquid (drip) cannot splash or drip onto any other food or shelf.`,`Label the container with the date/time moved to the chiller, cook within 24 hours of thawing, and NEVER refreeze thawed raw meat.`],keyTakeaway:`Thaw meat in a covered drip tray on the bottom shelf of a chiller (≤ +4°C) and never refreeze once thawed.`},{slideNumber:5,title:`Supervising Safe Cooking (Thermal Kill Step)`,subtitle:`Ensuring 100% Pathogen Destruction`,bulletPoints:[`Cooking is the main Critical Control Point (CCP) that destroys vegetative pathogens like Salmonella, E. coli, Campylobacter, and Listeria.`,`Check the thickest piece in the coldest part of the oven or grill—it must reach ≥ +75°C (or ≥ +70°C for 2 minutes).`,`Stir liquid dishes (soups, sauces, curries, gravies) before probing so heat is distributed evenly and there are no cold pockets.`,`Whole rolled joints of meat, stuffed poultry, and minced meat burgers must always be cooked all the way through to ≥ +75°C with zero pink meat or red juices.`],keyTakeaway:`Minced meats and rolled joints have surface bacteria mixed into the center—they must always be cooked thoroughly to ≥ +75°C.`},{slideNumber:6,title:`Supervising Rapid Cooling of Cooked Food`,subtitle:`Beating Spore Germination in the Danger Zone`,bulletPoints:[`Slow cooling of cooked food is one of the biggest causes of Clostridium perfringens and Bacillus cereus food poisoning.`,`Target Cooling Limit: Cool from +60°C to +20°C within 2 hours, and from +20°C to ≤ +4°C within 4 hours (or from +70°C to ≤ +3°C in ≤ 90 minutes using a Blast Chiller).`,`Practical Ways to Speed Up Cooling: Portion large batches into shallow stainless-steel gastronorm pans (< 5 cm deep), place pans in an ice-water bath, stir with a sanitized cooling paddle, or use a Blast Chiller.`],keyTakeaway:`Decant deep pots of curry, soup, or rice into shallow pans immediately after cooking so they cool rapidly.`},{slideNumber:7,title:`Supervising Reheating & Hot Holding`,subtitle:`Keeping Buffet & Service Food Safe`,bulletPoints:[`Hot Holding Rule: Pre-heat the bain-marie or hot cabinet BEFORE loading hot food, and keep food at ≥ +63°C.`,`Never use a bain-marie to cook cold food or reheat chilled food—it heats too slowly!`,`Never "top up" (mix) a fresh batch of food on top of an old batch sitting in the buffet pan—replace the pan completely with a clean one.`,`Reheating Rule: Reheat chilled food rapidly to ≥ +75°C core temperature, reheat ONLY ONCE, and discard any unserved reheated leftovers at the end of service.`],keyTakeaway:`Pre-heat hot-holding units before loading, keep food ≥ +63°C, never top-up old pans, and reheat food only once to ≥ +75°C.`},{slideNumber:8,title:`Supervising Cold Display & Buffet Service`,subtitle:`Protecting Salads, Sandwiches & Desserts`,bulletPoints:[`Cold display units, salad bars, and sandwich chillers must hold food at ≤ +5°C (ideally ≤ +4°C).`,`Use sneeze guards (protective glass canopies), clean serving tongs for each dish, and small display batches replenished frequently from the back chiller.`,`If cold high-risk food is displayed out of refrigeration for a short buffet event, enforce the strict 2-Hour / 4-Hour Rule (return to chiller within 2 hours, or use within 4 hours max and discard).`],keyTakeaway:`Cold buffets need sneeze guards, separate tongs per dish (to prevent allergen cross-contact), and core temperatures ≤ +5°C.`}]},{id:`fs3-mod-3`,moduleNumber:3,title:`Preventing Cross-Contamination, Allergen Control & Personal Hygiene`,estimatedMinutes:40,overview:`Simple presentation on direct vs. indirect cross-contamination, color-coded equipment, managing major food allergens in kitchens and factories, and supervising staff personal hygiene and medical fitness.`,internationalClauses:[`Codex CXC 80-2020 Food Allergen Management & Hygiene Controls`],keyPrinciples:[`Direct Cross-Contamination happens when raw food touches or drips onto Ready-to-Eat food; Indirect Cross-Contamination happens via hands, knives, chopping boards, cloths, or worktables.`,`Enforce physical separation and color-coded utensils for Raw Meat (Red), Raw Fish (Blue), Cooked Meat (Yellow), Salads/Fruit (Green), Root Veg (Brown), Bakery/Dairy (White), and Allergen-Free (Purple).`,`Food Allergies involve an immune reaction to specific proteins (even micrograms can cause fatal anaphylaxis); Food Intolerances (like lactose intolerance) are digestive and non-life-threatening.`,`Supervisors must enforce the 20-second handwashing method, ban jewelry/nail polish/watches, and enforce the 48-hour symptom-free exclusion rule for gastrointestinal illness.`],criticalControlParameters:[{parameter:`Physical & Color-Coded Separation of Raw vs. Ready-to-Eat (RTE)`,standardLimit:`Zero shared chopping boards, knives, slicers, or vacuum packers between raw and RTE foods`,correctiveProtocol:`Immediately discard any Ready-to-Eat food that contacts a raw meat surface or utensil.`},{parameter:`Allergen Communication & Preparation Protocol`,standardLimit:`Accurate written Allergen Matrix + clean uniform/gloves + washed surface + Purple kit for allergy orders`,correctiveProtocol:`Never guess ingredients—check the recipe allergen matrix and original ingredient labels every time.`}],practicalChecklist:[`Inspect all chopping boards and knives to confirm color-coding is followed and worn/grooved boards are replaced.`,`Verify that the current Menu Allergen Matrix is available at the service point and in the kitchen.`,`Check handwashing stations twice daily to ensure warm water, antibacterial liquid soap, and paper towels are fully stocked.`],presentationSlides:[{slideNumber:1,title:`Direct vs. Indirect Cross-Contamination`,subtitle:`How Germs Travel From Raw Food to Ready-to-Eat Food`,bulletPoints:[`Direct Cross-Contamination: Raw meat, poultry, fish, or unwashed soil vegetables directly touching or dripping blood/juices onto cooked or Ready-to-Eat food.`,`Indirect Cross-Contamination (Vehicles of Contamination): Germs transferring via unwashed hands, shared chopping boards, knives, meat slicers, door handles, or reusable wiping cloths.`,`Remember: Raw food has a future cooking step to kill bacteria; Ready-to-Eat food has NO further cooking step, so even tiny contamination is dangerous!`],keyTakeaway:`Eliminate reusable wiping cloths in high-care areas—use single-use paper towels and food-safe sanitizer sprays.`},{slideNumber:2,title:`Enforcing the 7-Color Hygiene Coding System`,subtitle:`Visual Discipline on the Preparation Line`,bulletPoints:[`Red: Raw Meat & Poultry`,`Blue: Raw Fish & Seafood`,`Yellow: Cooked Meat & Poultry`,`Green: Washed Salads & Fresh Fruit`,`Brown: Unwashed Root Vegetables (Potatoes, Carrots, Onions)`,`White: Bakery, Bread & Dairy Products`,`Purple: Allergen-Free & Special Diet Preparation`,`Wash, sanitize, and store color-coded boards vertically in a rack so air circulates between them.`],keyTakeaway:`Never stack wet chopping boards flat on top of each other—store them upright in a sanitized rack to air-dry.`},{slideNumber:3,title:`Food Allergy vs. Food Intolerance`,subtitle:`Understanding Why Allergens Are a Life-or-Death Issue`,bulletPoints:[`Food Allergy: An immediate, severe immune system reaction to a specific food protein (such as peanuts, tree nuts, milk, egg, fish, shellfish, soy, wheat, or sesame).`,`Can trigger Anaphylactic Shock within minutes: swelling of throat and tongue, difficulty breathing, drop in blood pressure, collapse, and death if not treated with an adrenaline (EpiPen) injection.`,`Food Intolerance (e.g., Lactose intolerance): A digestive difficulty (bloating, cramps) that does not involve the immune system and is not immediately life-threatening (Note: Celiac disease is a serious autoimmune reaction to gluten requiring < 20 ppm gluten).`],keyTakeaway:`Even a microscopic crumb or droplet of an allergen on a knife, fryer oil, or grill can trigger fatal anaphylaxis.`},{slideNumber:4,title:`Controlling Allergens in Kitchens & Factories`,subtitle:`Practical Rules for Preparing an Allergy-Safe Meal`,bulletPoints:[`Maintain an accurate written Allergen Matrix showing which of the major allergens are present in every menu dish or product.`,`When a customer or patient declares an allergy:`,`• Inform the Shift Supervisor / Head Chef immediately.`,`• Wash hands thoroughly, put on fresh gloves and a clean apron.`,`• Wash and detergent-scrub the prep surface (remember: sanitizer spray alone does NOT remove allergenic proteins!).`,`• Use dedicated Purple allergen utensils, fresh unopened ingredients, and clean cooking oil (never fry in oil previously used for battered fish or breaded chicken!).`],keyTakeaway:`Deep-frying oil shared with breaded or battered items is contaminated with gluten/egg/fish allergens—always use a separate clean pan.`},{slideNumber:5,title:`Controlling Physical & Chemical Contamination`,subtitle:`Foreign Body Prevention Rules on the Floor`,bulletPoints:[`No Glass & Brittle Plastic Policy: Decant ingredients from glass jars into food-grade plastic containers outside the cooking zone.`,`No Wood, Staples, or Wire Scrubbers: Use stainless-steel tables, plastic pallets, and nylon/green scouring pads.`,`Decanting & Sieving: Sift flour and dry powders through an intact stainless-steel mesh sieve (checked before and after use for broken wires).`,`Chemical Control: Store cleaning chemicals in a locked cupboard in their original labeled bottles—never put bleach or detergent into an empty drinking water bottle!`],keyTakeaway:`Never decant cleaning chemicals into food or beverage containers, and check sieves/blades daily for missing metal pieces.`},{slideNumber:6,title:`Supervising Handwashing Technique & Facilities`,subtitle:`The Most Important 20 Seconds in Food Safety`,bulletPoints:[`Dedicated Handwash Basin: Must be used ONLY for washing hands (never for washing food or utensils!) and fitted with non-hand-operated taps (knee, foot, or sensor taps).`,`Stocked at all times with warm running water (+38°C to +45°C), antibacterial liquid soap, and single-use paper towels (no shared cloth towels).`,`6-Step Handwashing Technique (20–30 seconds): Wet hands → Apply soap → Rub palms, backs of hands, between fingers, backs of fingers, thumbs, and fingertips/nails → Rinse → Dry with paper towel and use the towel to turn off the tap.`],keyTakeaway:`If a handwash basin runs out of soap or paper towels, restock it immediately before allowing staff to continue food prep.`},{slideNumber:7,title:`Protective Clothing, Jewelry & Bad Habits`,subtitle:`Setting the Standard for Floor Discipline`,bulletPoints:[`Protective Clothing: Clean light-colored uniform without external pockets or loose buttons (which can fall into food), put on at work (never worn while commuting on buses/streets).`,`Hair Restraint: Put on hairnet/mob cap FIRST before putting on the uniform coat so loose hairs do not fall onto the shoulders.`,`Zero Jewelry Policy: Remove watches, rings, bracelets, and visible piercings (studs and stones harbor bacteria and can fall into food).`,`Strictly prohibit eating, chewing gum, smoking/vaping, spitting, or touching mobile phones in food handling areas.`],keyTakeaway:`Mobile phones carry heavy bacterial contamination—ban personal mobile phones at food prep tables.`},{slideNumber:8,title:`Managing Staff Sickness & Return-to-Work Interviews`,subtitle:`Enforcing the 48-Hour Exclusion Rule`,bulletPoints:[`Any staff member suffering from diarrhea, vomiting, fever with sore throat, jaundice, or infected skin lesions must report to the Supervisor before entering the building.`,`Exclude the worker from food handling immediately and log it in the Sickness & Return-to-Work Register.`,`The employee may only return to food handling after being completely symptom-free for at least 48 hours after stopping anti-diarrheal medication (or with medical clearance for Typhoid/Salmonella/Hepatitis A).`],keyTakeaway:`Conduct a signed Return-to-Work Interview with every staff member returning from stomach illness to confirm 48 hours symptom-free.`}]},{id:`fs3-mod-4`,moduleNumber:4,title:`Hygienic Premises Design, Cleaning & Disinfection (SSOPs), Waste & Pest Control`,estimatedMinutes:40,overview:`Simple presentation on hygienic kitchen/factory design, the difference between detergents and disinfectants, Sinner’s Circle (TACT), Master Cleaning Schedules, waste management, and Integrated Pest Management (IPM).`,internationalClauses:[`Codex Section 3 & 6: Establishment Design, Cleaning & Pest Control`],keyPrinciples:[`Hygienic premises use smooth, impervious, washable surfaces, coved floor-to-wall joints, adequate drainage, good lighting, and extraction ventilation.`,`Detergents remove grease and organic dirt; Disinfectants/Sanitizers reduce bacteria to a safe level—always clean with detergent BEFORE applying disinfectant.`,`Cleaning effectiveness depends on 4 factors (Sinner’s Circle — T.A.C.T.): Time (contact time), Action (scrubbing/water pressure), Chemical concentration, and Temperature.`,`Integrated Pest Management (IPM) combines pest-proofing (exclusion), good housekeeping (denying food/water), and regular monitoring by a licensed pest contractor.`],criticalControlParameters:[{parameter:`Two-Stage Cleaning & Chemical Contact Time`,standardLimit:`Stage 1: Detergent wash to remove grease/soil → Rinse → Stage 2: Disinfectant at correct ppm for full contact time → Air dry`,correctiveProtocol:`Re-clean and re-sanitize any surface where sanitizer was wiped off immediately without waiting for contact time.`},{parameter:`Pest Proofing & Zero Infestation Tolerance`,standardLimit:`Zero evidence of rodents, cockroaches, or flies in food areas; door gaps ≤ 3 mm; fly screens intact`,correctiveProtocol:`If pest signs (droppings/gnawing) are found near food, quarantine & discard affected food, deep-clean, and call pest control immediately.`}],practicalChecklist:[`Audit the Master Cleaning Schedule (What, Who, How, Chemical dilution, Frequency, Sign-off) across all kitchen sections.`,`Check chemical dilution dispensers and test sanitizer spray bottles with chemical test strips.`,`Inspect external doors, window fly screens, floor drains, and UV fly-killer glue boards weekly.`],presentationSlides:[{slideNumber:1,title:`Hygienic Design of Food Premises & Equipment`,subtitle:`Building a Kitchen or Factory That Is Easy to Clean`,bulletPoints:[`Walls, Floors & Ceilings: Must be smooth, waterproof, non-absorbent, light-colored, and free from cracks or peeling paint.`,`Coved Corners: Floor-to-wall junctions should be rounded (coved) so dirt and water cannot hide in sharp 90-degree corners.`,`Equipment Design: Made of food-grade 304/316 stainless steel, smooth welds, easy to dismantle for cleaning, and mounted on legs (at least 15–30 cm off the floor) or mobile lockable castors.`],keyTakeaway:`Report cracked tiles, peeling ceiling paint, or rusted equipment frames to maintenance immediately.`},{slideNumber:2,title:`Detergents vs. Disinfectants vs. Sanitizers`,subtitle:`Knowing What Each Cleaning Chemical Actually Does`,bulletPoints:[`Detergent (Soap / Degreaser): Dissolves grease, oil, and food dirt so it can be rinsed away—does NOT kill bacteria.`,`Disinfectant: Kills pathogenic microorganisms to a safe level, but ONLY works on a clean, grease-free surface.`,`Sanitizer: A chemical that combines cleaning and disinfecting properties (though heavily soiled surfaces still require a two-stage clean first).`,`Sterilization: Destroying 100% of all microorganisms and spores (used for surgical tools, baby bottles, and UHT/retort processing).`],keyTakeaway:`Disinfectants are inactivated by grease and food scraps—always wash with detergent and rinse before disinfecting!`},{slideNumber:3,title:`The 4 Factors of Effective Cleaning (T.A.C.T. / Sinner’s Circle)`,subtitle:`Why Contact Time and Chemical Dilution Matter`,bulletPoints:[`T — Time: Every disinfectant requires a specific Contact Time (e.g., 30 seconds to 5 minutes) sitting wet on the surface to kill bacteria. Wiping it off after 2 seconds leaves bacteria alive!`,`A — Action: Physical scrubbing with a color-coded brush or pad breaks up sticky bacterial biofilms.`,`C — Chemical Concentration: Too weak = fails to kill bacteria; Too strong = leaves toxic chemical residue in food. Always use calibrated dosing pumps and test strips.`,`T — Temperature: Warm water (+45°C–+55°C) melts fat, while water above +50°C causes chlorine bleach to evaporate.`],keyTakeaway:`Always leave food-safe disinfectant on the surface for the manufacturer’s full Contact Time before rinsing or air-drying.`},{slideNumber:4,title:`Managing the Master Cleaning Schedule (SSOPs)`,subtitle:`What, Who, When, How & Verification`,bulletPoints:[`A Master Cleaning Schedule (Sanitation Standard Operating Procedure — SSOP) lists every piece of equipment and room in the facility:`,`• WHAT item is to be cleaned (e.g., Meat Slicer, Walk-in Chiller, Floor Drains, Canopy Filters).`,`• WHO is responsible for cleaning it.`,`• WHEN (Frequency): Clean-as-you-go, end of every shift, daily, or weekly.`,`• HOW to clean it (step-by-step dismantling, safety lock-out, chemical name & dilution rate, contact time, and safety PPE).`,`• WHO verifies and signs off that it is clean.`],keyTakeaway:`Always unplug electrical machines (slicers, mixers, mincers) before dismantling them for cleaning!`},{slideNumber:5,title:`Color-Coded Cleaning Equipment (Mops, Buckets & Brushes)`,subtitle:`Never Use a Washroom Mop in the Kitchen!`,bulletPoints:[`Just like chopping boards, mops, buckets, brooms, and squeegees must be color-coded by area:`,`• Red Mops/Buckets: Staff Toilets, Washrooms & Changing Rooms.`,`• Green / Blue Mops/Buckets: Food Preparation & Cooking Areas.`,`• Yellow Mops/Buckets: Dishwashing / Scullery & Waste Areas.`,`After cleaning, wash mops and brushes in hot disinfectant, shake dry, and hang them upside-down off the floor on a wall rack.`],keyTakeaway:`Never leave dirty mops soaking in a bucket of stagnant water overnight—it becomes a breeding soup for bacteria.`},{slideNumber:6,title:`Hygienic Waste Management Inside & Outside`,subtitle:`Removing Food Waste Before It Attracts Pests`,bulletPoints:[`Internal Bins: Foot-pedal operated, lidded, washable bins lined with strong polythene bags; emptied whenever 75% full and at the end of every shift.`,`External Waste Compound: Located away from raw material receiving doors, on a washable concrete pad with drainage, with heavy closed dumpster lids locked at all times.`,`Wash hands thoroughly after handling garbage bags or wheelie bins.`],keyTakeaway:`Overflowing bins and open external dumpsters are the #1 magnet for flies, rats, and cockroaches.`},{slideNumber:7,title:`Integrated Pest Management (IPM) — The 3 Lines of Defense`,subtitle:`Exclusion, Restriction & Destruction`,bulletPoints:[`1st Line — Exclusion (Pest-Proofing the Building): Seal all holes around pipes, keep external doors closed with brush/rubber strips (< 3 mm gap), fit fine mesh fly screens on windows, and keep drain covers on.`,`2nd Line — Restriction (Good Housekeeping): Store all food in lidded containers off the floor, clean up spills immediately, and keep stores dry so pests have zero food or water.`,`3rd Line — Destruction (Monitoring & Eradication): Use UV glue-board fly killers and a licensed Pest Control Contractor with a site bait-map.`],keyTakeaway:`Pest control is 80% good housekeeping and building proofing, and 20% traps and contractor visits.`},{slideNumber:8,title:`Spotting Signs of Rodents, Cockroaches & Stored-Product Insects`,subtitle:`What Supervisors Must Look For During Daily Walks`,bulletPoints:[`Rats & Mice: Dark spindle-shaped droppings, gnaw marks on sacks/cables/doors, greasy smear marks along base of walls, footprints in dust, and ammonia smell.`,`Cockroaches: Dark pepper-like droppings, brown egg cases (oothecae) behind warm motors/fridges, and unpleasant almond-like odor.`,`Flies & Stored-Product Weevils: Maggots near drains/bins, webbing or tiny holes in flour and grain sacks.`,`If you spot any live pest or droppings in a food room: Quarantine and discard contaminated food, wash and disinfect all surfaces, and call the pest contractor immediately.`],keyTakeaway:`Check behind warm refrigerator motors, under sinks, and in dark store corners weekly using a bright flashlight.`}]},{id:`fs3-mod-5`,moduleNumber:5,title:`Supervisory Auditing, Staff Training, Food Safety Law & Due Diligence`,estimatedMinutes:35,overview:`Simple presentation on how to train and coach kitchen/factory teams, conduct daily supervisory inspections, cooperate with Environmental Health / Food Authority Officers, understand enforcement notices, and maintain Legal Due Diligence.`,internationalClauses:[`Food Safety Legislation, Enforcement Powers & Legal Due Diligence`],keyPrinciples:[`Supervisors must deliver induction training before new hires touch food, refresher training annually, and on-the-job coaching whenever procedures change.`,`Food Safety Enforcement Officers (Inspectors) have the legal right to enter food premises unannounced, take samples/photos, inspect records, seize unsafe food, and issue Improvement or Prohibition Notices.`,`A Statutory Due Diligence Defense requires proving with signed records that the business took all reasonable precautions to prevent a food safety offense.`,`Daily Supervisory Walkthroughs and honest record-keeping ensure your facility is audit-ready 365 days a year.`],criticalControlParameters:[{parameter:`New Starter Food Hygiene Induction Rule`,standardLimit:`100% of new, temporary, or agency staff receive basic hygiene & allergen induction BEFORE starting work`,correctiveProtocol:`Never place an untrained worker on a food line without first completing induction and medical screening.`},{parameter:`Cooperation with Regulatory Food Safety Inspectors`,standardLimit:`Immediate polite access, honest records presentation, and prompt action on any inspector findings`,correctiveProtocol:`Obstructing an authorized Food Safety Inspector is a criminal offense.`}],practicalChecklist:[`Maintain an up-to-date Staff Training Matrix signed by both the employee and the trainer.`,`Conduct a daily 15-minute Supervisory Hygiene & Temperature Walkthrough across all areas.`,`Ensure all daily logbooks (Receiving, Fridges, Cooking, Cooling, Cleaning, Pest Control) are signed and archived neatly.`],presentationSlides:[{slideNumber:1,title:`How to Train & Motivate Your Food Handling Team`,subtitle:`Turning Knowledge Into Everyday Safe Habits`,bulletPoints:[`Induction Training (Day 1 before touching food): Cover handwashing, uniform rules, illness reporting (48-hour rule), allergen awareness, and fire/safety rules.`,`Job-Specific Training: Teach cooks how to probe temperatures and dishwashers how to check 82°C rinse / 3-sink chemical levels.`,`Refresher Training: Repeat food safety training at least once a year and whenever a mistake or audit finding occurs.`,`Keep signed Training Records showing the date, topics covered, trainer name, and employee signature.`],keyTakeaway:`If a staff member’s training is not signed and documented, an auditor treats them as untrained.`},{slideNumber:2,title:`Conducting Daily & Weekly Supervisory Inspections`,subtitle:`Being Your Own Toughest Inspector`,bulletPoints:[`Do not wait for the Food Authority or QA Auditor to find dirty equipment or expired food.`,`Use a simple 1-Page Daily Supervisor Inspection Checklist:`,`• Staff uniforms, hairnets, nails, and handwash stations.`,`• Chiller and freezer temperatures + FEFO date labels + raw/cooked separation.`,`• Cooking, cooling, and hot-holding probe logs.`,`• Cleanliness under tables, inside slicers, and around floor drains.`],keyTakeaway:`A 15-minute daily supervisory inspection keeps standards high across every shift.`},{slideNumber:3,title:`Powers of Food Authority / Environmental Health Officers`,subtitle:`What Regulatory Inspectors Are Legally Authorized to Do`,bulletPoints:[`Authorized Food Safety Officers have the legal right to:`,`• Enter and inspect any food business at any reasonable hour WITHOUT prior appointment.`,`• Inspect food, equipment, stores, and written/digital HACCP records.`,`• Take food samples, surface swabs, and photographic evidence.`,`• Detain or seize food that is unfit for human consumption.`,`• Serve legal enforcement notices or close down dangerous premises.`],keyTakeaway:`Always verify the inspector’s official ID badge, accompany them politely, and provide requested records promptly.`},{slideNumber:4,title:`Understanding Legal Enforcement Notices`,subtitle:`Hygiene Improvement Notice vs. Emergency Prohibition Notice`,bulletPoints:[`Hygiene Improvement Notice (Corrective Notice): Issued when a legal standard is not met (e.g., broken chiller seal, cracked tiles, missing training records) giving a set deadline (e.g., 14 to 28 days) to fix the defect while staying open.`,`Hygiene Emergency Prohibition Notice (Immediate Closure / Sealing): Issued when there is an imminent risk of injury to health (e.g., active rat/cockroach infestation in the kitchen, sewage backup, or no running water). The business must STOP operating immediately until cleared!`],keyTakeaway:`An Improvement Notice gives a deadline to fix a defect; an Emergency Prohibition Notice closes the operation immediately.`},{slideNumber:5,title:`Penalties for Breaching Food Safety Law`,subtitle:`Why Compliance Protects Both the Business and Individuals`,bulletPoints:[`Selling unsafe, contaminated, or mislabeled food can lead to:`,`• Heavy financial fines and confiscation of stock.`,`• Immediate suspension or revocation of the Food Business License.`,`• Public "Name and Shame" closure notices that ruin customer trust.`,`• Personal criminal prosecution and imprisonment for owners/managers in cases of gross negligence or fatal allergen/poisoning incidents.`],keyTakeaway:`Strong daily food safety management protects consumers, workers, and your career.`},{slideNumber:6,title:`Proving "Due Diligence" in Court or Audits`,subtitle:`How Your Daily Logs Protect You`,bulletPoints:[`Under Food Safety Law, the primary legal defense is Due Diligence—proving that you took "all reasonable precautions and exercised all due diligence" to avoid committing the offense.`,`To prove Due Diligence, you need 3 things:`,`• A written HACCP / Food Safety System.`,`• Positive action (staff training, approved suppliers, calibrated probes, pest control contracts).`,`• Honest, signed daily monitoring and corrective action records.`],keyTakeaway:`No records = No Due Diligence defense. Keep your logs accurate, honest, and signed every shift.`},{slideNumber:7,title:`Handling Customer Complaints & Product Recalls`,subtitle:`Turning Complaints Into System Improvements`,bulletPoints:[`Log every customer complaint (foreign object, off-taste, packaging defect, or alleged illness) in the Customer Complaint Register.`,`Check the batch code, inspect retained reference samples, and review the shift’s HACCP and cleaning logs.`,`If a serious safety defect affects other packs in the market, initiate an immediate Withdrawal or Recall and notify management and regulators.`],keyTakeaway:`Investigate every complaint within 24 hours to ensure no wider batch safety risk exists.`},{slideNumber:8,title:`Course Summary & Exam Readiness`,subtitle:`Ready for the Food Safety Level 03 Final Assessment`,bulletPoints:[`You have completed all 5 Modules of Food Safety Level 03:`,`• Module 1: Food Microbiology, FATTOM & Pathogens`,`• Module 2: Safe Temperatures (Delivery, Storage, Cooking, Cooling & Holding)`,`• Module 3: Cross-Contamination, Color-Coding, Allergens & Personal Hygiene`,`• Module 4: Premises Design, 6-Step Cleaning, Waste & Pest Control`,`• Module 5: Supervisory Inspections, Food Law & Due Diligence`],keyTakeaway:`Click "Complete Course & Start 40-MCQ Final Exam" below (60% passing score = 24/40 correct).`}]}],coreExamPool:[{q:`What are the 6 conditions bacteria need to multiply (known by the acronym FATTOM)?`,options:[`Food, Acidity, Time, Temperature, Oxygen, and Moisture`,`Fire, Air, Tables, Trays, Oil, and Milk`,`Freezing, Acid, Testing, Training, Ovens, and Metal`,`Flour, Apples, Tea, Tomatoes, Onions, and Meat`],correctIndex:0,explanation:`FATTOM stands for Food, Acidity, Time, Temperature, Oxygen, and Moisture.`},{q:`Which of the following is classified as a "High-Risk Ready-to-Eat (RTE) Food"?`,options:[`Cooked sliced chicken breast and cooked boiled rice`,`Dry uncooked wheat flour`,`Refined white sugar in a sealed jar`,`Pure vegetable cooking oil`],correctIndex:0,explanation:`Cooked meat and cooked rice are moist, protein/starch-rich Ready-to-Eat foods that support rapid bacterial growth if temperature-abused.`},{q:`Why must staff NEVER wash raw chicken under a running tap in a kitchen sink?`,options:[`Splashing water droplets spread Campylobacter and Salmonella bacteria up to 80 cm onto surrounding tables, utensils, and Ready-to-Eat foods`,`Because water makes chicken heavier`,`Because chicken is already sterile`,`Because water ruins the sink drain`],correctIndex:0,explanation:`Washing raw poultry splashes Campylobacter and Salmonella aerosols across nearby surfaces; thorough cooking (≥ 75°C) kills the bacteria safely.`},{q:`Which foodborne pathogen can continue to grow slowly even inside a refrigerator at +1°C to +4°C?`,options:[`Listeria monocytogenes`,`Salmonella Typhi`,`Campylobacter jejuni`,`E. coli O157`],correctIndex:0,explanation:`Listeria monocytogenes is psychrotrophic (cold-tolerant) and can multiply slowly at refrigeration temperatures (+1°C to +4°C).`},{q:`Can you tell if food is contaminated with food poisoning bacteria (such as Salmonella or E. coli) by looking at it or smelling it?`,options:[`No — pathogenic food poisoning bacteria do NOT change the appearance, smell, or taste of food`,`Yes — contaminated food always turns bright green`,`Yes — it always smells like vinegar`,`Yes — it always tastes bitter`],correctIndex:0,explanation:`Unlike spoilage bacteria, pathogenic bacteria do not alter taste, smell, or appearance.`},{q:`What reading must a calibrated digital probe thermometer show when placed in a 50:50 crushed ice and water slurry?`,options:[`0.0°C (within ±0.5°C to ±1.0°C)`,`+10.0°C`,`-18.0°C`,`+25.0°C`],correctIndex:0,explanation:`Melting ice-water slurry has a fixed reference temperature of 0.0°C.`},{q:`What is the difference between a Detergent and a Disinfectant?`,options:[`A Detergent removes grease and dirt; a Disinfectant kills bacteria to a safe level on a pre-cleaned surface`,`A Detergent kills spores; a Disinfectant adds grease`,`They are identical`,`Disinfectants work best on thick layers of grease without washing`],correctIndex:0,explanation:`Detergents emulsify grease and soil, while disinfectants kill microorganisms once grease has been removed.`},{q:`When an inspector serves a "Hygiene Emergency Prohibition Notice", what must the food business do?`,options:[`Stop operating the affected premises or equipment IMMEDIATELY because there is an imminent risk to public health`,`Continue operating for 6 months`,`Ignore the notice`,`Only change the menu prices`],correctIndex:0,explanation:`An Emergency Prohibition Notice requires immediate closure/stoppage due to imminent risk of injury to health.`}]},{id:`cert-2026-food-safety-level-04`,code:`FS-L4`,title:`Food Safety Level 04`,levelBadge:`Simple Presentation Course (05 Modules · 40 Slides · 40 MCQs · 60% Pass)`,accreditationStandard:`RQF / Highfield Level 4 Award in Managing Food Safety & Hygiene • Presentation Course`,duration:`05 Presentation Modules (40 Slides) + 40-MCQ Final Exam`,certificateFeeRs:1e3,passPercentage:60,distinctionPercentage:75,totalExamQuestions:40,description:`Executive Managerial Slide Presentation Course on Food Safety Level 04 for Operations Managers, Factory Managers, Executive Chefs, and QA Heads. Covers Advanced Foodborne Pathogens & Outbreak Epidemiology, Hygienic Facility Engineering & High-Care Zoning, Advanced CIP/Sanitation Chemistry & Environmental Monitoring (Zones 1–4), Supplier Quality Assurance & Laboratory Governance, and Food Safety Culture, Auditing & Crisis Leadership.`,modules:[{id:`fs4-mod-1`,moduleNumber:1,title:`Advanced Food Microbiology, Toxins, Viruses & Outbreak Investigation`,estimatedMinutes:45,overview:`Simple presentation on managing complex microbiological risks (infectious dose, incubation periods, heat-stable toxins, water activity, pH hurdles) and leading epidemiological outbreak investigations.`,internationalClauses:[`Level 4 Advanced Food Microbiology & Outbreak Forensics`],keyPrinciples:[`Hurdle Technology combines multiple preservation barriers (Temperature, pH < 4.6, Water Activity aw < 0.85, Salt/Sugar, Vacuum/MAP packaging, and Preservatives) so pathogens cannot survive or multiply.`,`Low-Acid Canned/Vacuum Foods (pH > 4.6, aw > 0.85) require strict control of anaerobic Clostridium botulinum (using ≥ 121.1°C retort for 3 mins, or ≥ 3.5% salt / ≤ 10 days shelf-life at ≤ 3°C).`,`During a suspected foodborne illness outbreak, the Incubation Period (time from eating to symptoms) and main symptoms (vomiting vs. fever/bloody diarrhea) point to the likely pathogen.`,`Epidemiological Attack Rate % calculates the percentage of diners who ate a specific dish and became ill compared to those who did not eat it.`],criticalControlParameters:[{parameter:`pH and Water Activity (aw) Safety Hurdles`,standardLimit:`pH ≤ 4.6 blocks Clostridium botulinum growth; Water Activity aw ≤ 0.85 blocks bacterial growth`,correctiveProtocol:`Quarantine any acidified sauce, pickle, or sushi rice batch that fails pH verification before release.`},{parameter:`Vacuum-Packed & Sous-Vide Chilled Shelf-Life Control`,standardLimit:`Store at ≤ +3°C with max 10-day shelf life unless thermal kill (90°C for 10m) or aw/pH/nitrite hurdle is validated`,correctiveProtocol:`Never assign > 10 days chilled shelf life to vacuum-packed foods without scientific C. botulinum validation.`}],practicalChecklist:[`Review pH and Water Activity (aw) specifications for all ambient and chilled sauces, dressings, and bakery fillings.`,`Verify that vacuum-packing and Modified Atmosphere Packaging (MAP) machines are segregated between raw and RTE products.`,`Ensure the 72-hour Reference Sample Bank and Outbreak Investigation Protocol are ready at all times.`],presentationSlides:[{slideNumber:1,title:`What is "Hurdle Technology" in Food Preservation?`,subtitle:`Combining Multiple Barriers to Stop Bacterial Growth`,bulletPoints:[`Instead of relying on just one extreme treatment, Hurdle Technology puts multiple hurdles in front of microorganisms so they cannot jump over all of them:`,`• Hurdle 1: Thermal Treatment (Cooking / Pasteurization)`,`• Hurdle 2: Acidity (Lowering pH below 4.6 using vinegar, citric acid, or lactic fermentation)`,`• Hurdle 3: Reduced Water Activity (Binding water with salt or sugar so aw < 0.85)`,`• Hurdle 4: Chilled Storage (≤ +4°C) and Modified Atmosphere Packaging (CO2/N2).`],keyTakeaway:`If you reduce salt, sugar, or acid in a recipe for health reasons, you have weakened a safety hurdle and must re-validate shelf life!`},{slideNumber:2,title:`Critical pH and Water Activity (aw) Thresholds`,subtitle:`Key Numbers Every Level 04 Manager Must Know`,bulletPoints:[`Pure distilled water has a Water Activity (aw) of 1.00. Fresh meat/milk is ~0.99.`,`aw ≤ 0.85: Stops growth of pathogenic bacteria (including Staphylococcus aureus aerobic growth).`,`aw ≤ 0.60: Stops ALL microbial growth (including osmophilic yeasts and xerophilic molds).`,`pH ≤ 4.6: The critical acidification boundary—blocks germination and neurotoxin production of Clostridium botulinum (and pH ≤ 4.1 is used for acidified sushi rice).`],keyTakeaway:`Remember the two golden intrinsic boundaries: pH ≤ 4.6 and Water Activity (aw) ≤ 0.85.`},{slideNumber:3,title:`Controlling Non-Proteolytic Clostridium botulinum in Vacuum Packs`,subtitle:`Why Vacuum Packing & Sous-Vide Need Special Rules`,bulletPoints:[`Vacuum packing and Sous-Vide remove oxygen, which stops aerobic spoilage bacteria—making food look fresh longer.`,`However, Clostridium botulinum is an ANAEROBE (it loves zero-oxygen vacuum packs!), and Type E / non-proteolytic strains can grow slowly at temperatures down to +3.3°C!`,`Safety Rule for Chilled Vacuum-Packed Foods: Either (1) Keep strictly at ≤ +3°C and limit shelf life to ≤ 10 days, OR (2) Heat to ≥ +90°C for 10 minutes in the pack, OR (3) Maintain pH ≤ 5.0 / Salt ≥ 3.5% / aw ≤ 0.97.`],keyTakeaway:`Never give vacuum-packed chilled food more than 10 days shelf life unless it has a validated 90°C/10m cook or pH/salt hurdle.`},{slideNumber:4,title:`Matching Symptoms & Incubation Periods to Pathogens`,subtitle:`How Managers & Doctors Identify the Cause of an Outbreak`,bulletPoints:[`Very Short Incubation (1 to 6 Hours — Sudden Vomiting, No Fever): Pre-formed heat-stable toxin from Staphylococcus aureus (handled cooked meats/cream cakes) or Bacillus cereus emetic toxin (cooked rice).`,`Medium Incubation (8 to 22 Hours — Watery Diarrhea & Cramps): Clostridium perfringens (slow-cooled gravies, stews, large meat joints).`,`Longer Incubation (12 to 72 Hours — Diarrhea, Fever, Vomiting): Salmonella, Campylobacter, Norovirus, or E. coli O157.`,`Very Long Incubation (3 to 70 Days): Listeria monocytogenes or Hepatitis A (15–50 days).`],keyTakeaway:`Vomiting within 1–6 hours of eating points to a pre-formed toxin (S. aureus or B. cereus); diarrhea 12–72 hours later points to bacterial/viral infection.`},{slideNumber:5,title:`Calculating Attack Rate (%) in Outbreak Investigations`,subtitle:`Finding Which Menu Item Caused the Illness`,bulletPoints:[`When investigating a banquet or cafeteria outbreak, interview both people who got sick AND people who stayed healthy.`,`Calculate the Attack Rate (AR %) for each dish:`,`Attack Rate % = (Number of Sick People Who Ate the Dish ÷ Total People Who Ate the Dish) × 100.`,`The dish with the highest Attack Rate among eaters (and lowest Attack Rate among non-eaters) is the contaminated vehicle!`],keyTakeaway:`Compare the Attack Rate of those who ate each dish vs. those who did not eat it to pinpoint the exact source of food poisoning.`},{slideNumber:6,title:`Controlling Parasites in Fish & Meat`,subtitle:`Freezing & Cooking Rules for Parasite Destruction`,bulletPoints:[`Anisakis simplex (Parasitic worms in wild raw fish used for sushi/ceviche): Must be blast-frozen to ≤ -20°C for at least 24 hours (or ≤ -20°C for 7 days / ≤ -35°C for 15 hours under FDA/EU rules) to kill larvae.`,`Cryptosporidium & Giardia: Protozoan parasites spread via contaminated water (resistant to normal chlorine; controlled by water filtration, UV, or boiling ≥ 1 minute).`,`Trichinella & Toxoplasma: Eliminated by cooking meat thoroughly to ≥ +70°C/+75°C.`],keyTakeaway:`Any fish intended to be served raw or lightly marinated (sushi/sashimi) must have a validated parasite-freezing record (≤ -20°C).`},{slideNumber:7,title:`Scombroid Fish Poisoning (Histamine) & Marine Biotoxins`,subtitle:`Chemical Toxins in Seafood That Cooking Cannot Destroy`,bulletPoints:[`Scombroid Fish (Tuna, Mackerel, Mahi-Mahi, Sardines) naturally contain high levels of the amino acid histidine.`,`If these fish are left above +4°C even for a few hours, bacteria convert histidine into Histamine (Scombrotoxin).`,`Eating high-histamine fish causes flushing, rash, headache, and breathing trouble within 30 minutes—and histamine CANNOT be destroyed by cooking, canning, or freezing!`,`Always receive and store fresh fish packed in melting ice at ≤ +2°C.`],keyTakeaway:`Histamine in temperature-abused tuna survives all cooking and retorting—strict cold chain (≤ +2°C on ice) from catch to kitchen is the only defense.`},{slideNumber:8,title:`Low-Moisture Food Safety (Salmonella Survival)`,subtitle:`Why Dry Powders, Chocolate, Tahini & Spices Can Cause Outbreaks`,bulletPoints:[`Although Salmonella cannot MULTIPLY in dry foods (aw < 0.85), it can SURVIVE for months or years in milk powder, infant formula, chocolate, peanut butter, tahini, and black pepper!`,`Moreover, Salmonella in dry/fatty foods becomes extra heat-resistant.`,`Rule for Dry Processing Zones: Keep dry mixing and packing zones 100% DRY—never use high-pressure water hoses in dry powder areas, as moisture wakes up dormant Salmonella!`],keyTakeaway:`Keep dry powder/bakery/chocolate zones completely dry (use dry vacuuming and alcohol wipes) to prevent Salmonella growth.`}]},{id:`fs4-mod-2`,moduleNumber:2,title:`Hygienic Facility Engineering, High-Care Zoning & Utilities Management`,estimatedMinutes:40,overview:`Simple presentation on factory/kitchen zoning (Low-Risk vs. High-Care vs. High-Risk), positive air pressure, drainage flow direction, hygienic equipment welding, and water/air/steam utility controls.`,internationalClauses:[`ISO/TS 22002-1 & 22002-2 Hygienic Engineering & Facility Zoning`],keyPrinciples:[`Facilities handling Ready-to-Eat foods must segregate Low-Risk (raw/unwashed) areas from High-Care / High-Risk (cooked/RTE) areas using physical walls, barrier changing rooms, and pass-through ovens/chillers.`,`High-Care RTE rooms require Positive Air Pressure (+5 to +15 Pascals) with HEPA/F8 filtered air so unfiltered air cannot enter when doors open.`,`Floor drainage must flow from High-Care (Clean) toward Low-Risk (Dirty) areas, never the reverse.`,`Water, ice, culinary steam, and compressed air that touch food must be microbiologically and chemically tested to potable standards.`],criticalControlParameters:[{parameter:`High-Care Positive Air Pressure & Barrier Changing Protocol`,standardLimit:`+5 to +15 Pa positive air pressure; captive footwear & dedicated color-coded coat/hairnet change at barrier`,correctiveProtocol:`Repair air-handling filters immediately if positive pressure drops; never prop barrier doors open.`},{parameter:`Directional Floor Drainage Rule`,standardLimit:`Effluent flows from High-Care/Clean zones toward Low-Risk/Dirty zones with trapped gullies`,correctiveProtocol:`Never allow a drain line from a raw meat or toilet area to pass unsealed through a High-Care room.`}],practicalChecklist:[`Verify that High-Care / RTE assembly rooms maintain positive air pressure and ambient temperatures ≤ +12°C–+15°C.`,`Check that barrier changing rooms enforce captive boot changes and handwashing before entering High-Care.`,`Review annual potable water, ice machine, and compressed air microbiological test certificates.`],presentationSlides:[{slideNumber:1,title:`Understanding Facility Hygiene Zones`,subtitle:`Non-Food, Low-Risk, High-Care & High-Risk RTE Zones`,bulletPoints:[`Non-Food Zone: Offices, exterior yards, engineering workshops, and boilers.`,`Enclosed Product / Ambient Zone: Warehouses storing sealed cartons and cans.`,`Low-Risk Zone: Raw meat prep, unwashed vegetable washing, and pre-cooking areas (products here will undergo a thermal kill step later).`,`High-Care / High-Risk RTE Zone: Where cooked, pasteurized, or washed Ready-to-Eat foods are cooled, sliced, assembled, or packed before sealing.`],keyTakeaway:`Staff, trolleys, and utensils from Low-Risk raw zones must NEVER enter High-Care RTE zones without going through a full hygiene barrier.`},{slideNumber:2,title:`Designing a High-Care Barrier Changing Room`,subtitle:`Step-by-Step Entry Protocol for High-Care Staff`,bulletPoints:[`Entering a High-Care RTE zone requires a physical "Sit-Over Bench" barrier:`,`• Put on hairnet and beard snood first.`,`• Remove outdoor/low-risk shoes on the "Dirty Side" of the bench, swing legs over the barrier bench, and step into Captive High-Care Boots (which never leave the High-Care zone).`,`• Wash and dry hands at the barrier basin.`,`• Put on a dedicated High-Care color-coded coat/smock and sanitize hands.`],keyTakeaway:`Captive boots must stay inside the High-Care zone permanently and be washed in a boot-washer at the end of each shift.`},{slideNumber:3,title:`Air Handling, Positive Pressure & Condensation Control`,subtitle:`Preventing Airborne Contamination & Roof Drips`,bulletPoints:[`Why Positive Air Pressure? By supplying slightly more filtered air into the High-Care room than is extracted (+5 to +15 Pa), air blows OUTWARD when a door opens—blocking dust, flies, and mold spores from entering.`,`Air Filtration: Air entering High-Care rooms passes through fine F8 / HEPA filters maintained on a regular replacement schedule.`,`Condensation Control: Overhead chiller coils and cold water pipes must be insulated and fitted with plumbed drip trays—roof condensation dripping onto open food is a major source of Listeria!`],keyTakeaway:`Condensation droplets hanging above open food are a Critical Audit Failure—keep extractor fans and chiller defrost drains clear.`},{slideNumber:4,title:`Floor Slopes & Directional Drainage Engineering`,subtitle:`Keeping Wastewater Moving Away From Clean Food`,bulletPoints:[`Floors must slope evenly (1:50 to 1:100 gradient) toward stainless-steel drainage channels so no stagnant water puddles remain on the floor.`,`Directional Flow Rule: Underground drains must ALWAYS flow from High-Care (Cleanest) → toward Low-Risk (Dirty) → to main sewer.`,`If a drain flowed from Raw Meat through High-Care and got blocked, raw meat sewage would back up onto the High-Care floor!`,`Fit all drains with removable perforated strainer baskets and water-seal P-traps.`],keyTakeaway:`Never clean floor drains with high-pressure hoses during active food production, as aerosols spray Listeria onto tables!`},{slideNumber:5,title:`Hygienic Equipment Design Principles (EHEDG / 3-A)`,subtitle:`What to Check Before Buying a New Food Machine`,bulletPoints:[`Food-Contact Surfaces: Smooth, non-toxic 304 or 316 stainless steel with continuous ground welds (no rough spot-welds, rivets, or open screw threads).`,`Zero Dead-Legs: Pipes must not have T-junction "dead ends" where stagnant milk or sauce sits untouched by CIP cleaning.`,`Self-Draining: Tanks and vats must have sloped bottoms so 100% of liquid drains out after washing.`,`Hollow Frameworks: Machine frames must be hermetically sealed or open-profile angle iron—hollow square tubes crack and harbor Listeria inside!`],keyTakeaway:`Involve the QA/Food Safety Manager before purchasing any new machine to verify it can be dismantled and cleaned easily.`},{slideNumber:6,title:`Managing Potable Water, Ice & Culinary Steam`,subtitle:`Testing the Invisible Ingredients in Your Facility`,bulletPoints:[`Water & Ice: Ice is a food! Plumbed ice machines must be emptied, descaled, and sanitized monthly, with ice scoops stored in an external sanitized holder (never left buried inside the ice!).`,`Test water and ice at an accredited lab at least every 6–12 months for Total Coliforms (0 CFU/100mL) and E. coli (0 CFU/100mL).`,`Culinary Steam & Compressed Air: Steam or compressed air that touches food or blows open packaging bags must use food-grade boiler chemicals and 0.01-micron sterile air filters.`],keyTakeaway:`Treat your ice machine like a High-Risk food container—sanitize it monthly and never store the ice scoop inside the ice bin.`},{slideNumber:7,title:`Preventive Maintenance & Post-Maintenance Hygiene Clearance`,subtitle:`Controlling Engineering Risks on the Production Line`,bulletPoints:[`Engineers bringing dirty toolboxes, metal filings, and black grease onto a food line can contaminate an entire batch.`,`Maintenance Rules in Food Zones:`,`• Use ONLY certified Food-Grade Lubricants (NSF H1) on conveyors, mixers, and slicers.`,`• Count all nuts, bolts, drill bits, and tools before and after the repair (Zero Temporary Repairs with tape, wire, or cardboard!).`,`• Before restarting the line, QA/Supervisor must inspect, clean, sanitize, and sign the Post-Maintenance Hygiene Clearance Permit.`],keyTakeaway:`Ban temporary repairs (string, tape, wire, cardboard) on food equipment, and require QA sign-off after every maintenance job.`},{slideNumber:8,title:`Contractor & Visitor Control in Food Facilities`,subtitle:`Ensuring Outsiders Follow Every Hygiene Rule`,bulletPoints:[`External contractors (electricians, plumbers, refrigeration technicians) and visitors must sign a Health & Hygiene Questionnaire at reception.`,`Provide full visitor protective clothing (coat, hairnet, beard cover, captive overshoes) and escort them at all times.`,`Never allow a contractor with recent vomiting/diarrhea to enter food production or storage rooms.`],keyTakeaway:`Contractors and visitors must follow the exact same hygiene and medical screening rules as permanent staff.`}]},{id:`fs4-mod-3`,moduleNumber:3,title:`Advanced Sanitation, CIP Systems, Biofilms & Environmental Monitoring (Zones 1–4)`,estimatedMinutes:45,overview:`Simple presentation on automated Clean-In-Place (CIP) engineering, removing bacterial biofilms, chemical sanitizer comparison (Chlorine, Quats, PAA), ATP bioluminescence, and Zone 1–4 Listeria/Salmonella Environmental Monitoring.`,internationalClauses:[`GFSI / ISO 22000 Environmental Monitoring & CIP Validation Standards`],keyPrinciples:[`Clean-In-Place (CIP) cleans closed pipes and tanks automatically using 5 stages (Pre-Rinse → Caustic Wash → Intermediate Rinse → Acid Wash → Disinfection/Final Rinse) at flow velocity ≥ 1.5 m/s.`,`Bacterial Biofilms are slimy protective layers secreted by bacteria (especially Listeria and Pseudomonas) on poorly cleaned steel and rubber gaskets that resist normal sanitizer sprays.`,`An Environmental Monitoring Program (EMP) divides the plant into 4 Hygienic Zones (Zone 1 = Food Contact, Zone 2 = Adjacent Equipment, Zone 3 = Floors/Drains/Walls, Zone 4 = Outside Production) for regular pathogen swabbing.`,`ATP Bioluminescence swabs measure residual organic matter (food + microbes) in Relative Light Units (RLU) within 15 seconds to verify cleaning before starting production.`],criticalControlParameters:[{parameter:`CIP Pipeline Flow Velocity, Temperature & Conductivity`,standardLimit:`Turbulent flow velocity ≥ 1.5 meters/second; Caustic (1%–2% NaOH at 70°C–80°C); Acid (0.5%–1% HNO3 at 60°C)`,correctiveProtocol:`Abort and repeat the CIP cycle automatically if return-line conductivity, temperature, or flow rate drops below setpoint.`},{parameter:`Zone 1 to 4 Environmental Pathogen Swabbing (Listeria / Salmonella)`,standardLimit:`Absent (0 CFU / Negative) in all Zone 1 and Zone 2 swabs; immediate vector-swabbing if Zone 3/4 is positive`,correctiveProtocol:`If a Zone 1 (food-contact) swab tests positive for Listeria or Salmonella, quarantine all batches produced on that line and deep-sanitize.`}],practicalChecklist:[`Review daily CIP chart records (return temperature, conductivity, flow velocity, and final rinse pH neutrality).`,`Verify that rubber gaskets, slicer blades, and O-rings are dismantled weekly for biofilm scrubbing and inspection.`,`Audit the monthly Zone 1–4 Environmental Swab Map to ensure drains, rollers, and cold-room fans are tested.`],presentationSlides:[{slideNumber:1,title:`How Automated Clean-In-Place (CIP) Systems Work`,subtitle:`The 5-Stage CIP Cycle for Dairy, Beverage & Liquid Plants`,bulletPoints:[`Clean-In-Place (CIP) cleans closed pipelines, homogenizers, pasteurizers, and storage silos without dismantling them:`,`Stage A — Pre-Rinse: Ambient/warm potable water flushes out loose product residue.`,`Stage B — Caustic Wash (1%–2% Sodium Hydroxide NaOH at 70°C–80°C): Dissolves fats and proteins.`,`Stage C — Intermediate Water Rinse: Flushes out caustic soap.`,`Stage D — Acid Wash (0.5%–1.0% Nitric/Phosphoric Acid at 60°C): Removes mineral scale ("milkstone" / hard water scale).`,`Stage E — Final Potable Rinse & Thermal/PAA Sanitization (verified by neutral pH / zero conductivity on the return line).`],keyTakeaway:`Caustic removes fat and protein; Acid removes mineral scale (milkstone)—and turbulent flow (≥ 1.5 m/s) is essential to scrub pipe walls.`},{slideNumber:2,title:`What Are Bacterial Biofilms & How Do You Destroy Them?`,subtitle:`The Hidden Slime Shield That Protects Listeria`,bulletPoints:[`When bacteria sit on a damp surface (like a conveyor belt underside, rubber gasket, or floor drain), they secrete a sticky polysaccharide slime coat called a Biofilm.`,`Once inside a mature Biofilm, bacteria are up to 1,000 times more resistant to chemical sanitizers!`,`Simply spraying sanitizer onto a biofilm does NOT kill the bacteria inside.`,`How to Destroy Biofilms: Dismantle gaskets/parts, scrub physically with alkaline/enzymatic detergent and mechanical friction to break the slime shield, rinse, and then apply disinfectant.`],keyTakeaway:`Physical scrubbing + enzymatic/alkaline detergent is the only way to break open a bacterial biofilm so sanitizer can reach the germs.`},{slideNumber:3,title:`Comparing Industrial Disinfectants (Chlorine, Quats, PAA & Alcohol)`,subtitle:`Choosing the Right Sanitizer for the Job`,bulletPoints:[`Chlorine (Sodium Hypochlorite — 50 to 200 ppm): Fast, broad-spectrum, low cost; works best at pH 6.0–7.5 and water temp < 48°C, but is corrosive to stainless steel if left un-rinsed and easily inactivated by organic dirt.`,`QAC / Quats (Quaternary Ammonium — 200 to 400 ppm): Non-corrosive, odorless, leaves residual film; ideal for tables, walls, and cold rooms.`,`Peracetic Acid (PAA — 100 to 250 ppm): Strong oxidizing sanitizer ideal for CIP systems and cold rooms; breaks down safely into vinegar, water, and oxygen.`,`70% Isopropyl/Ethyl Alcohol: Evaporates dry with zero water—ideal for dry bakery/powder lines and thermometer probes.`],keyTakeaway:`Rotate your disinfectants periodically (e.g., Quats during the week, oxidizing PAA/Chlorine on weekends) so bacteria do not build resistance.`},{slideNumber:4,title:`Rapid Hygiene Verification: ATP Bioluminescence vs. Protein Swabs`,subtitle:`Checking Cleanliness in 15 Seconds Before Starting the Line`,bulletPoints:[`Traditional agar plate lab tests take 24 to 48 hours—too slow to tell you if a machine is clean enough to start the morning shift!`,`ATP Bioluminescence Swabs: Measure Adenosine Triphosphate (ATP—energy molecule found in all food residues and living cells) in 15 seconds, displayed as Relative Light Units (RLU).`,`If an ATP swab fails (e.g., > 30 RLU), the operator re-washes and re-sanitizes the machine immediately BEFORE any food touches it.`,`Allergen Protein Swabs: Specifically detect residual protein/allergens after an allergen changeover.`],keyTakeaway:`ATP swabs give an instant 15-second pass/fail check on cleaning before production starts.`},{slideNumber:5,title:`The 4-Zone Environmental Monitoring Program (EMP)`,subtitle:`Seeking & Destroying Listeria and Salmonella in the Plant`,bulletPoints:[`An Environmental Monitoring Program (EMP) divides the facility into 4 concentric rings (Zones 1 to 4):`,`Zone 1 (Food-Contact Surfaces): Slicer blades, conveyor belts, filler nozzles, mixing bowls, and utensils.`,`Zone 2 (Non-Food-Contact Surfaces Immediately Adjacent to Food): Machine frames, control buttons, chiller drip trays, and table legs.`,`Zone 3 (Surrounding Room Surfaces): Floors, floor drains, walls, door handles, handwash taps, and forklifts inside the production room.`,`Zone 4 (Areas Outside the Production Room): Locker rooms, corridors, loading docks, and maintenance workshops.`],keyTakeaway:`Finding and eliminating Listeria in Zone 3 (floor drains) stops it before it ever reaches Zone 1 (food-contact surfaces)!`},{slideNumber:6,title:`What to Do When an Environmental Swab Tests Positive`,subtitle:`Vector Swabbing & Seek-and-Destroy Protocol`,bulletPoints:[`If a Zone 3 (floor drain) swab is positive: Deep-clean and sanitize the area, and take 5 to 10 surrounding "Vector Swabs" (upward toward Zone 2 and Zone 1) across 3 consecutive days until 3 consecutive negative results are achieved.`,`If a Zone 1 (food-contact surface) swab is positive for Listeria or Salmonella: Immediately STOP the line, quarantine all product batches made on that line, dismantle and deep-sanitize the machine, and perform finished-product pathogen testing.`],keyTakeaway:`Always require 3 consecutive negative swabs after a positive environmental finding to prove the harborage niche is eliminated.`}]},{id:`fs4-mod-4`,moduleNumber:4,title:`Supplier Quality Assurance (SQA), Laboratory Governance & Foreign Body Detection`,estimatedMinutes:40,overview:`Simple presentation on managing risk-based Supplier Approval Programs, interpreting ISO/IEC 17025 laboratory certificates, and managing inline Metal Detectors, X-Ray inspection, optical sorters, and magnets/sieves.`,internationalClauses:[`GFSI Supplier Quality Assurance & Foreign Body Control Standards`],keyPrinciples:[`Risk-based Supplier Quality Assurance classifies suppliers into High-Risk (requiring GFSI certification or 2nd-party site audit + COA per batch) and Low-Risk (questionnaire + annual review).`,`All external pathogen, mycotoxin, and chemical residue testing must be performed by an ISO/IEC 17025 accredited laboratory (and internal pathogen labs must be physically isolated from production).`,`Foreign-body detection devices (Sieves, Rare-Earth Magnets ≥ 10,000 Gauss, Metal Detectors, and X-Ray Inspection systems) must have fail-safe reject mechanisms into locked bins.`,`Glass and Brittle Plastic Registers must be audited monthly across all production and storage zones.`],criticalControlParameters:[{parameter:`Metal Detector & X-Ray Fail-Safe Reject Verification`,standardLimit:`Hourly test with Fe, Non-Fe, and SS 316 test pieces; automatic rejection into a locked reject bin`,correctiveProtocol:`Verify that belt-stop or air-blast reject confirm-sensors work; quarantine back to last good check if failed.`},{parameter:`ISO/IEC 17025 Laboratory Accreditation & Internal Lab Segregation`,standardLimit:`External food safety lab tests accredited to ISO 17025; zero live pathogen culturing inside open food zones`,correctiveProtocol:`Never culture Salmonella or Listeria inside an unsealed factory quality office.`}],practicalChecklist:[`Verify that all raw material and primary packaging suppliers have valid approval records and annual performance scores.`,`Check that the Metal Detector / X-Ray reject bin is kept locked and that only the QA Supervisor holds the key.`,`Audit the monthly Glass, Brittle Plastic & Ceramic Register and the Knife/Blade Register.`],presentationSlides:[{slideNumber:1,title:`Risk-Based Supplier Quality Assurance (SQA)`,subtitle:`Approving and Grading Suppliers Before You Buy`,bulletPoints:[`Classify every raw material and food-contact packaging supplier by Risk:`,`• High-Risk Ingredients (Raw meat, dairy, eggs, spices, nuts, infant ingredients): Require GFSI Certification (BRCGS, FSSC 22000, IFS, SQF) OR an on-site 2nd-Party Audit by your QA team, plus a Certificate of Analysis (COA) with every delivery.`,`• Low-Risk Ingredients: Approved via Supplier Questionnaire, product specification, and legal compliance declaration.`,`Evaluate suppliers annually on delivery temperature compliance, COA pass rate, and zero foreign-body complaints.`],keyTakeaway:`Maintain a clear emergency Emergency Supplier Approval procedure in case a primary supplier suffers a fire or shortage.`},{slideNumber:2,title:`Managing Outsourced Processes & Brokers/Agents`,subtitle:`Ensuring Traceability Back to the Actual Manufacturer`,bulletPoints:[`If you buy ingredients through a Broker, Trader, or Agent rather than directly from the factory, you must still know and approve the ACTUAL manufacturing site of origin!`,`A broker’s invoice alone does not tell you if the factory that made the spice or milk powder is hygienic.`,`Similarly, any subcontracted storage warehouse or transport company must sign a Service Level Agreement (SLA) covering cold-chain temperatures, pest control, and security.`],keyTakeaway:`Always trace brokered ingredients back to the original manufacturing plant and approve that site.`},{slideNumber:3,title:`Inline Foreign-Body Controls: Sieves, Filters & Rare-Earth Magnets`,subtitle:`Catching Physical Contaminants During Processing`,bulletPoints:[`Sieves & Strainers: Inspect mesh screens before and after every shift. If a wire is broken on a flour sieve at the end of the shift, the missing metal wire is inside today’s dough batch—quarantine the batch!`,`Rare-Earth Magnets (Neodymium ≥ 10,000–12,000 Gauss): Installed in powder chutes and liquid pipelines to trap fine iron/steel wear particles.`,`Clean magnet bars on a set schedule, photograph/log any metal shavings found, and test magnet pull-strength annually.`],keyTakeaway:`A damaged sieve or filter found at the end of a shift requires immediate quarantine of all product made since the start of the shift.`},{slideNumber:4,title:`Metal Detectors vs. X-Ray Inspection Systems`,subtitle:`Comparing Capabilities & Fail-Safe Reject Controls`,bulletPoints:[`Balanced-Coil Metal Detectors: Detect Ferrous (Iron/Steel), Non-Ferrous (Brass/Aluminum/Copper), and Stainless Steel (SS 316 is hardest to detect because it is non-magnetic). Cannot be used on foil-wrapped trays (use Ferrous-in-Foil or X-Ray).`,`X-Ray Inspection Systems: Detect dense foreign objects based on density—catching Metal, Glass, Calcified Bone, Stone, and Dense Rubber/Plastic even inside aluminum foil or metal cans!`,`Fail-Safe Reject Bin: Rejected packs must be diverted into a LOCKED reject bin with a photo-eye confirmation sensor.`],keyTakeaway:`X-Ray detects metal, glass, stone, and dense bone; Metal Detectors detect Fe, Non-Fe, and Stainless Steel.`},{slideNumber:5,title:`Glass, Brittle Plastic, Knife & Needle Control Registers`,subtitle:`Preventing Internal Sharp Object Contamination`,bulletPoints:[`Glass & Brittle Plastic Register: List every essential glass/plastic item in the factory (gauge dials, sight glasses, clock faces, EFK tubes) and inspect them monthly for cracks.`,`Glass Breakage Procedure: Stop the line immediately, quarantine all open food within the splash radius (typically 3 to 5 meters), discard affected product, sweep up fragments using dedicated red glass-cleanup tools, and get QA sign-off before restarting.`,`Knife & Blade Register: Issue numbered knives/snap-off blades prohibited; log blade condition at the start and end of every shift.`],keyTakeaway:`Snap-off utility blades are strictly banned in food plants because broken blade segments easily fall into packaging and food!`},{slideNumber:6,title:`Laboratory Governance & ISO/IEC 17025 Accreditation`,subtitle:`Ensuring Lab Test Results Are Legally & Scientifically Valid`,bulletPoints:[`All critical food safety testing (Salmonella, Listeria, E. coli, Mycotoxins, Pesticides, Water Potability) must be done by a laboratory accredited to ISO/IEC 17025.`,`If your factory has an on-site microbiology lab, it must be completely isolated from food production with negative air pressure, autoclave sterilization of waste plates, and restricted access.`,`When sending a finished batch for pathogen testing, follow "Positive Release"—keep the batch on hold in the warehouse until the written lab pass certificate arrives!`],keyTakeaway:`Under Positive Release, never ship a batch that is undergoing pathogen lab testing until the written negative (pass) report is received.`}]},{id:`fs4-mod-5`,moduleNumber:5,title:`Food Safety Management Systems (FSMS), Auditing, KPIs & Executive Leadership`,estimatedMinutes:40,overview:`Simple presentation on integrating GMP, HACCP, VACCP, and TACCP into a complete Food Safety Management System (FSMS), tracking executive KPIs, managing unannounced third-party audits, and leading crisis response.`,internationalClauses:[`GFSI Benchmarking Requirements, ISO 22000 & Level 4 Leadership Standards`],keyPrinciples:[`A complete Food Safety Management System (FSMS) integrates Prerequisite Programs (GMP/GHP), HACCP, Traceability/Recall, Food Fraud (VACCP), Food Defense (TACCP), and Food Safety Culture.`,`Managers use trend analysis of KPIs (Right-First-Time %, CCP compliance %, ATP pass %, Foreign-Body Complaints per Million Packs, Audit closure rate) to drive continual improvement.`,`Unannounced Audit Readiness means every shift operates to audit standard every day, supported by a trained Audit Reception Protocol.`,`Effective Crisis Management protects consumer health first through rapid quarantine, transparent regulatory notification, and root-cause elimination.`],criticalControlParameters:[{parameter:`Unannounced Audit Readiness Protocol`,standardLimit:`Auditor granted access to production floor within ≤ 30 minutes of arrival at security gate`,correctiveProtocol:`Train security and shift managers on the Unannounced Audit SOP so entry is never delayed or refused.`},{parameter:`Foreign-Body & Food Safety Complaint Trend Analysis`,standardLimit:`Monthly pareto/trend review of all complaints with mandatory CAPA for any recurring defect`,correctiveProtocol:`Convene a cross-functional engineering and QA team whenever 2+ complaints occur on the same SKU.`}],practicalChecklist:[`Verify that security gate staff and night/weekend shift leaders know the Unannounced Audit Reception Procedure.`,`Compile the monthly Food Safety KPI Dashboard for Top Management Review.`,`Complete all 5 modules and proceed to the 40-MCQ Food Safety Level 04 Final Exam.`],presentationSlides:[{slideNumber:1,title:`The Complete Food Safety Management System (FSMS) House`,subtitle:`How PRPs, HACCP, VACCP, TACCP & Culture Fit Together`,bulletPoints:[`Think of your Food Safety Management System (FSMS) as a strong building:`,`• Foundation: Top Management Commitment & Food Safety Culture.`,`• Ground Floor: Prerequisite Programs (GMPs, Hygiene, SSOPs, Pest Control, Approved Suppliers).`,`• Pillars: (1) HACCP (Unintentional Safety Hazards), (2) VACCP (Food Fraud Prevention), (3) TACCP (Food Defense / Site Security), and (4) 4-Hour Traceability & Recall.`,`• Roof: Internal Auditing, Management Review & Continual Improvement (PDCA).`],keyTakeaway:`Every pillar of the FSMS House works together to protect consumers and pass international GFSI audits.`},{slideNumber:2,title:`Managing Unannounced Audits With Confidence`,subtitle:`Being Ready Every Single Day of the Year`,bulletPoints:[`Under BRCGS, FSSC 22000, McDonald’s SQMS, and Food Authority rules, unannounced audits are mandatory.`,`Train your Security Gate: When an auditor arrives and shows their ID, security calls the QA Manager / Senior Shift Manager immediately and gets the auditor onto the shop floor within 15 to 30 minutes.`,`Refusing entry to an unannounced GFSI or regulatory auditor results in immediate certificate suspension or legal action!`],keyTakeaway:`Build an everyday culture where "every shift is audit-ready" so unannounced audits are stress-free.`},{slideNumber:3,title:`Key Performance Indicators (KPIs) for Level 04 Managers`,subtitle:`Measuring What Matters on a Monthly Dashboard`,bulletPoints:[`Leading Indicators (Preventive):`,`• Pre-Op ATP Swab Pass Rate % (Target ≥ 98%)`,`• Preventive Maintenance On-Time Completion % for CCP Equipment (Target 100%)`,`• Staff Hygiene & HACCP Training Completion % (Target 100%)`,`Lagging Indicators (Outcome):`,`• Customer Complaints per Million Units (CPMU)`,`• Number of CCP Deviations & Quarantine Batches`,`• Third-Party Audit Grade & Non-Conformity Count`],keyTakeaway:`Track both Leading (preventive) and Lagging (outcome) KPIs every month to spot trends early.`},{slideNumber:4,title:`Document Control & Record Integrity Governance`,subtitle:`Eliminating Uncontrolled Forms on the Floor`,bulletPoints:[`Every SOP, recipe card, and daily log sheet must have a Document Code, Version Number, Issue Date, and "Approved By" signature.`,`When you update an SOP or log sheet from Version 2 to Version 3, collect and remove all old Version 2 copies from the production floor immediately and stamp the archive copy "OBSOLETE".`,`Never allow operators to use photocopied scrap paper, sticky notes, or outdated log forms.`],keyTakeaway:`Using an obsolete version of a CCP form on the production floor is a common audit non-conformity—control document versions strictly.`},{slideNumber:5,title:`Leading Crisis Management & Regulatory Notification`,subtitle:`Acting Fast When a Serious Incident Happens`,bulletPoints:[`What triggers the Crisis Management Team? Confirmed pathogen in dispatched food, undeclared allergen label error, tampered product threat, factory fire/flood, or regulatory enforcement notice.`,`Golden Rules of Crisis Leadership:`,`• Consumer safety comes first—never hide a known food safety hazard to save money.`,`• Freeze all warehouse dispatches of the suspect lot within 30 minutes.`,`• Notify the Certification Body (within 3 working days for recalls) and Food Authority (within 24 hours).`],keyTakeaway:`Fast, honest containment during a food safety crisis protects human lives and preserves long-term company survival.`},{slideNumber:6,title:`Course Completion & Final Exam Guide`,subtitle:`Ready for the Food Safety Level 04 Final Assessment`,bulletPoints:[`Congratulations on completing all 5 Modules of Food Safety Level 04!`,`You have mastered Advanced Microbiology & Hurdle Technology, High-Care Facility Engineering, CIP & Zone 1–4 Environmental Monitoring, Supplier & Foreign-Body Controls, and Executive FSMS Leadership.`,`Click below to start the 40-MCQ Final Exam (60% passing score = 24/40 correct; 75% for Distinction).`],keyTakeaway:`Review the Key Takeaway boxes on each slide and proceed to your 40-MCQ Final Exam!`}]}],coreExamPool:[{q:`What are the critical pH and Water Activity (aw) safety boundaries used in Hurdle Technology to stop Clostridium botulinum and pathogenic bacterial growth?`,options:[`pH ≤ 4.6 and Water Activity (aw) ≤ 0.85`,`pH = 9.0 and Water Activity = 0.99`,`pH = 7.0 and Water Activity = 1.00`,`pH and Water Activity have no effect on bacteria`],correctIndex:0,explanation:`pH ≤ 4.6 prevents Clostridium botulinum growth and toxin formation, while aw ≤ 0.85 prevents pathogenic bacterial growth.`},{q:`Why must chilled vacuum-packed and Sous-Vide foods be restricted to ≤ 10 days shelf life at ≤ +3°C unless additional thermal or intrinsic hurdles are validated?`,options:[`To prevent growth and neurotoxin production by anaerobic non-proteolytic Clostridium botulinum, which can grow without oxygen down to +3.3°C`,`Because plastic bags melt after 10 days`,`Because vacuum packing adds extra oxygen`,`Vacuum-packed chilled meat can be kept at room temperature for 6 months`],correctIndex:0,explanation:`Non-proteolytic Clostridium botulinum thrives in anaerobic vacuum packs and can grow down to +3.3°C unless controlled by ≤ 10-day shelf life at ≤ +3°C, a 90°C/10m cook, or pH/salt hurdles.`},{q:`If 15 banquet guests develop sudden projectile vomiting 2.5 hours after eating cream pastries and sliced ham (with no fever), which hazard is the primary suspect?`,options:[`Pre-formed heat-stable Staphylococcus aureus enterotoxin (or Bacillus cereus emetic toxin in starchy foods)`,`Listeria monocytogenes (incubation 3 to 70 days)`,`Hepatitis A virus (incubation 15 to 50 days)`,`Trichinella spiralis`],correctIndex:0,explanation:`A short incubation period of 1 to 6 hours with acute vomiting and no fever indicates a pre-formed heat-stable toxin such as Staphylococcus aureus enterotoxin.`},{q:`In what direction must floor drainage channels flow inside a food manufacturing facility?`,options:[`From High-Care / High-Risk (Cleanest) zones toward Low-Risk (Dirty) zones—never from raw/dirty areas into High-Care`,`From Raw Meat and Toilets directly through the High-Care RTE packing room`,`Upward onto the ceiling`,`Drainage direction does not matter`],correctIndex:0,explanation:`Floor drains must flow from High-Care (clean) toward Low-Risk (dirty) zones so contaminated effluent can never back up into Ready-to-Eat rooms.`},{q:`What are the 5 sequential stages of a standard industrial Clean-In-Place (CIP) cycle, and what minimum pipeline flow velocity is required?`,options:[`Pre-Rinse → Caustic Wash → Intermediate Rinse → Acid Wash → Disinfection/Final Rinse, at a turbulent flow velocity of ≥ 1.5 m/s`,`Cold water rinse only at 0.1 m/s`,`Acid wash first without rinsing`,`Blowing warm air through the pipe once a month`],correctIndex:0,explanation:`A 5-stage CIP uses Caustic (for fat/protein) and Acid (for mineral scale) at ≥ 1.5 m/s turbulent flow velocity to scrub pipe walls clean.`},{q:`How do you effectively remove a mature bacterial Biofilm from stainless-steel equipment and rubber gaskets?`,options:[`Dismantle parts and apply mechanical scrubbing with alkaline/enzymatic detergent to break the protective polysaccharide slime layer BEFORE applying chemical disinfectant`,`Lightly mist with cold water from 2 meters away`,`Wipe with a dry paper towel only`,`Spray alcohol over the grease without scrubbing`],correctIndex:0,explanation:`Biofilms shield bacteria from sanitizers; mechanical scrubbing with detergent/enzymes is required to break the slime matrix before disinfecting.`},{q:`In a 4-Zone Environmental Monitoring Program (EMP), what constitutes "Zone 1" vs. "Zone 3"?`,options:[`Zone 1 = Direct Food-Contact Surfaces (slicer blades, conveyor belts, filler nozzles); Zone 3 = Surrounding Room Surfaces (floors, floor drains, walls, forklifts)`,`Zone 1 = Exterior parking lot; Zone 3 = Slicer blades`,`Zone 1 = Staff washrooms; Zone 3 = Office desks`,`All zones are outside the factory`],correctIndex:0,explanation:`Zone 1 covers direct food-contact surfaces, Zone 2 covers adjacent equipment frames, Zone 3 covers floors/drains/walls in the room, and Zone 4 covers areas outside production.`},{q:`Which foreign-body inspection technology can detect metal, glass shards, calcified bone, and stones even inside aluminum-foil trays or metal cans?`,options:[`X-Ray Inspection System`,`A standard wooden ruler`,`A basic pH meter`,`A room thermometer`],correctIndex:0,explanation:`X-Ray inspection works by density difference and detects metal, glass, stone, and dense bone even inside foil or metal packaging.`}]}],f=d.map(t),p=[{id:`cert-2026-iso-9001-awareness`,code:`ISO-9001-AW`,title:`ISO 9001 Awareness Certificate`,levelBadge:`Simple Presentation Course (05 Modules · 35 Slides · 40 MCQs · 60% Pass)`,accreditationStandard:`ISO 9001:2015 Quality Management Systems (QMS) • Awareness Presentation Course`,duration:`05 Presentation Modules (35 Slides) + 40-MCQ Final Exam`,certificateFeeRs:1e3,passPercentage:60,distinctionPercentage:75,totalExamQuestions:40,description:`Clear, easy-to-follow Slide Presentation Course on ISO 9001:2015 Quality Management Systems (QMS). Covers the 7 Quality Management Principles, Annex SL High-Level Structure (Clauses 4 to 10), Process Approach & PDCA Cycle, Risk-Based Thinking, Documented Information, Operational Quality Controls, Internal Auditing, and Continual Improvement.`,modules:[{id:`iso9001-mod-1`,moduleNumber:1,title:`Introduction to ISO 9001, Quality Principles & PDCA Cycle`,estimatedMinutes:35,overview:`Simple presentation on what ISO 9001:2015 is, why companies implement a Quality Management System (QMS), the 7 Quality Management Principles, the Process Approach, and the Plan-Do-Check-Act (PDCA) cycle.`,internationalClauses:[`ISO 9001:2015 Clauses 0.1 to 0.3 & ISO 9000 Seven Quality Principles`],keyPrinciples:[`ISO 9001:2015 is the world’s most recognized standard for a Quality Management System (QMS), ensuring an organization consistently delivers products and services that meet customer and regulatory requirements.`,`The 7 Quality Management Principles are: Customer Focus, Leadership, Engagement of People, Process Approach, Improvement, Evidence-Based Decision Making, and Relationship Management.`,`The Process Approach manages activities as interconnected processes (Inputs → Process Activities → Outputs) rather than isolated silos.`,`Every clause of ISO 9001 follows Deming’s PDCA Cycle: Plan (Clauses 4, 5, 6) → Do (Clauses 7, 8) → Check (Clause 9) → Act (Clause 10).`],criticalControlParameters:[{parameter:`7 Quality Management Principles (ISO 9000 / 9001)`,standardLimit:`Customer Focus, Leadership, Engagement of People, Process Approach, Improvement, Evidence-Based Decisions, Relationship Management`,correctiveProtocol:`Align all departmental quality KPIs and SOPs with these 7 core principles.`},{parameter:`Annex SL High-Level Structure (Clauses 4 to 10)`,standardLimit:`Plan (Clauses 4, 5, 6) → Do (Clauses 7, 8) → Check (Clause 9) → Act (Clause 10)`,correctiveProtocol:`Use the unified Annex SL structure to integrate ISO 9001 seamlessly with ISO 22000, ISO 14001, and ISO 45001.`}],practicalChecklist:[`Understand the 7 Quality Management Principles and how they apply to your job.`,`Map your department’s core processes showing Inputs, Process Steps, Controls, and Outputs.`,`Identify which clauses belong to Plan, Do, Check, and Act.`],presentationSlides:[{slideNumber:1,title:`What is ISO 9001:2015?`,subtitle:`The Global Benchmark for Quality Management Systems (QMS)`,bulletPoints:[`ISO stands for the International Organization for Standardization, based in Geneva, Switzerland.`,`ISO 9001:2015 is the international standard that specifies requirements for a Quality Management System (QMS).`,`It applies to ANY organization—food manufacturing, hospitals, laboratories, packaging plants, logistics, or software companies.`,`Note: ISO 9001 certifies the Management System processes, NOT the product itself—ensuring consistent quality "Right First Time" every day.`],keyTakeaway:`ISO 9001:2015 helps organizations consistently meet customer and legal requirements while continually improving satisfaction.`},{slideNumber:2,title:`Why Do Organizations Implement ISO 9001?`,subtitle:`Key Benefits for Customers, Staff & Business`,bulletPoints:[`Consistent Quality: Standardized SOPs ensure products and services meet exact specifications on every shift.`,`Fewer Mistakes & Less Waste: Catching risks early reduces rework, scrap, customer complaints, and financial loss.`,`Customer Confidence & Market Access: Many multinational clients, retailers, and government tenders require suppliers to hold ISO 9001 certification.`,`Clear Roles & Accountability: Every employee knows their responsibilities, SOPs, and quality targets.`],keyTakeaway:`A working QMS reduces costly rework and builds long-term customer trust.`},{slideNumber:3,title:`The 7 Quality Management Principles (Part 1)`,subtitle:`Customer Focus, Leadership, Engagement & Process Approach`,bulletPoints:[`Customer Focus: The primary focus of quality management is to meet customer requirements and strive to exceed customer expectations.`,`Leadership: Leaders at all levels establish unity of purpose and direction and create conditions in which people are engaged in achieving quality objectives.`,`Engagement of People: Competent, empowered, and engaged people at all levels throughout the organization are essential to enhance its capability to create and deliver value.`,`Process Approach: Consistent and predictable results are achieved more effectively when activities are understood and managed as interrelated processes.`],keyTakeaway:`Customer Focus is Principle #1 of ISO 9001—every process exists to deliver value to the customer.`},{slideNumber:4,title:`The 7 Quality Management Principles (Part 2)`,subtitle:`Improvement, Evidence-Based Decisions & Relationship Management`,bulletPoints:[`Improvement: Successful organizations have an ongoing focus on continual improvement.`,`Evidence-Based Decision Making: Decisions based on the analysis and evaluation of real data and information (KPIs, audit findings, lab trends) are more likely to produce desired results.`,`Relationship Management: For sustained success, an organization manages its relationships with interested parties, such as suppliers, partners, and contractors.`],keyTakeaway:`Never make quality decisions based on guesswork—use real data and facts (Evidence-Based Decision Making).`},{slideNumber:5,title:`Understanding the Process Approach (SIPOC)`,subtitle:`Suppliers → Inputs → Process → Outputs → Customers`,bulletPoints:[`Every activity in a business is a Process that transforms Inputs into Outputs:`,`• Suppliers provide Inputs (raw materials, information, customer orders).`,`• The Process applies controlled activities, machines, and trained staff.`,`• The Output (finished product or service) is delivered to the internal or external Customer.`,`Monitor KPIs at each process interface so defects are never passed to the next department.`],keyTakeaway:`Treat the next department on the line as your "Internal Customer" and never pass a defective item forward.`},{slideNumber:6,title:`The PDCA Cycle & Annex SL Structure (Clauses 4 to 10)`,subtitle:`How ISO 9001 Is Organized`,bulletPoints:[`Clauses 1, 2, and 3 cover Scope, Normative References, and Terms/Definitions.`,`The auditable requirements sit in Clauses 4 to 10 following the PDCA Cycle:`,`• PLAN: Clause 4 (Context of the Organization), Clause 5 (Leadership), Clause 6 (Planning & Risks).`,`• DO: Clause 7 (Support, Resources, Competence & Documents), Clause 8 (Operation).`,`• CHECK: Clause 9 (Performance Evaluation, Internal Audit & Management Review).`,`• ACT: Clause 10 (Improvement, Nonconformity & Corrective Action).`],keyTakeaway:`All modern ISO standards (9001, 22000, 14001, 45001) share this exact same Clauses 4–10 Annex SL structure!`},{slideNumber:7,title:`What is "Risk-Based Thinking" in ISO 9001:2015?`,subtitle:`Preventing Problems Before They Happen`,bulletPoints:[`ISO 9001:2015 replaced the old separate "Preventive Action" procedure with Risk-Based Thinking built into the entire system.`,`Risk is the "effect of uncertainty"—it can be negative (a threat/failure) or positive (an opportunity for improvement).`,`Every department identifies what could go wrong in its process and puts preventive controls in place upfront.`],keyTakeaway:`Risk-Based Thinking makes quality management proactive rather than waiting for things to break.`}]},{id:`iso9001-mod-2`,moduleNumber:2,title:`Clauses 4, 5 & 6: Context, Leadership, Quality Policy & Planning`,estimatedMinutes:35,overview:`Simple presentation on Clause 4 (Internal/External Issues, Interested Parties, QMS Scope), Clause 5 (Leadership Commitment, Quality Policy, Roles), and Clause 6 (Addressing Risks & Opportunities, SMART Quality Objectives).`,internationalClauses:[`ISO 9001:2015 Clauses 4, 5, and 6 (The PLAN Phase)`],keyPrinciples:[`Clause 4 requires understanding internal and external issues (e.g., SWOT/PESTLE), identifying the needs of Interested Parties (customers, regulators, owners, staff, suppliers), and defining the QMS Scope.`,`Clause 5 requires Top Management to demonstrate active leadership, establish a customer-focused Quality Policy, and assign clear organizational roles and authorities.`,`Clause 6 requires planning actions to address Risks and Opportunities,设置 measurable SMART Quality Objectives at relevant functions/levels, and planning changes systematically.`],criticalControlParameters:[{parameter:`Quality Policy Requirements (Clause 5.2)`,standardLimit:`Appropriate to company purpose, commits to meeting requirements & continual improvement, communicated & understood by staff`,correctiveProtocol:`Train employees to explain how the Quality Policy relates to their daily work rather than just memorizing words.`},{parameter:`SMART Quality Objectives (Clause 6.2)`,standardLimit:`Specific, Measurable, Achievable, Relevant, and Time-bound targets with an action plan (What, Resources, Who, When, How evaluated)`,correctiveProtocol:`Review Quality Objective progress monthly and initiate corrective action if any target falls behind.`}],practicalChecklist:[`Verify that your organization has a documented Context & Interested Parties Matrix (Clause 4.1 & 4.2).`,`Check that the signed Quality Policy is displayed and understood by staff across all departments.`,`Confirm that each department has measurable SMART Quality Objectives tracked monthly.`],presentationSlides:[{slideNumber:1,title:`Clause 4.1 & 4.2: Context of the Organization & Interested Parties`,subtitle:`Knowing Your Business Environment & Stakeholders`,bulletPoints:[`Clause 4.1 (Internal & External Issues): Identify factors that affect your ability to achieve quality results—External (regulations, market competition, raw material inflation, technology) and Internal (company culture, equipment age, staff skills).`,`Simple Tool: Most companies use a SWOT Analysis (Strengths, Weaknesses, Opportunities, Threats) to document Clause 4.1.`,`Clause 4.2 (Interested Parties): List all stakeholders who care about your quality—Customers, Regulatory Authorities, Shareholders, Employees, Suppliers, and Local Community—and write down what they expect from you.`],keyTakeaway:`Understanding internal/external issues and stakeholder expectations ensures your QMS addresses real-world business needs.`},{slideNumber:2,title:`Clause 4.3 & 4.4: Defining the QMS Scope & Processes`,subtitle:`Setting the Boundaries of Your Quality System`,bulletPoints:[`Clause 4.3 (QMS Scope): Clearly write down which physical site locations, products, and services are covered by your ISO 9001 certificate.`,`Can any clause of ISO 9001 be excluded? A clause (such as Clause 8.3 Design and Development) can ONLY be declared "Not Applicable" if your company genuinely does not perform product design and excluding it does not affect product conformity.`,`Clause 4.4: Establish, implement, maintain, and continually improve the QMS processes and their interactions.`],keyTakeaway:`Any exclusion from the QMS Scope (like Clause 8.3 Design) must be justified in writing.`},{slideNumber:3,title:`Clause 5.1: Leadership and Commitment`,subtitle:`Top Management Can No Longer Delegate All Quality Duties`,bulletPoints:[`In ISO 9001:2015, Top Management (CEO / Managing Director / General Manager) is directly accountable for the effectiveness of the QMS.`,`Leadership must ensure that the Quality Policy and Quality Objectives match the company’s strategic direction.`,`They must provide necessary resources (staff, equipment, training), promote the Process Approach and Risk-Based Thinking, and actively lead Management Review.`],keyTakeaway:`Auditors interview Top Management directly to verify their active involvement in Clause 5.`},{slideNumber:4,title:`Clause 5.2 & 5.3: Quality Policy, Roles & Authorities`,subtitle:`Setting the Company’s Quality Compass`,bulletPoints:[`The Quality Policy (Clause 5.2) must include:`,`• A commitment to satisfy applicable customer, statutory, and regulatory requirements.`,`• A commitment to continual improvement of the QMS.`,`• A framework for setting measurable Quality Objectives.`,`How should staff understand the Quality Policy? Employees do not need to recite it word-for-word, but they must know what it means for their daily job! (Clause 5.3 defines organization charts and job descriptions).`],keyTakeaway:`Every employee should know how their daily work contributes to the company’s Quality Policy.`},{slideNumber:5,title:`Clause 6.1: Actions to Address Risks and Opportunities`,subtitle:`Maintaining a Department Risk Register`,bulletPoints:[`Each department evaluates risks (what could cause non-conforming product, late delivery, or customer dissatisfaction) and opportunities (new automation, training, waste reduction).`,`Options to address a Risk: Avoid the risk, Eliminate the risk source, Reduce likelihood or severity (install controls), Share the risk (insurance/supplier contract), or Accept minor informed risk.`,`Evaluate the effectiveness of your risk controls during internal audits and management reviews.`],keyTakeaway:`Keep a practical Risk & Opportunity Register for each process and review it whenever processes change.`},{slideNumber:6,title:`Clause 6.2 & 6.3: SMART Quality Objectives & Planning of Changes`,subtitle:`Turning Quality Policy Into Measurable Targets`,bulletPoints:[`Quality Objectives (Clause 6.2) must be SMART: Specific, Measurable, Achievable, Relevant, and Time-bound.`,`Examples: "Achieve ≥ 98.5% On-Time In-Full (OTIF) customer delivery in 2026" or "Reduce customer quality complaints by 25% by Q4 2026."`,`Each objective needs a written plan: What will be done, What resources are required, Who is responsible, When it will be completed, and How results will be evaluated.`,`Clause 6.3 requires planning any QMS changes systematically so quality is never disrupted.`],keyTakeaway:`Vague goals like "improve quality" fail ISO 9001 audits—Quality Objectives must have measurable numbers and deadlines.`}]},{id:`iso9001-mod-3`,moduleNumber:3,title:`Clause 7: Support — Resources, Calibration, Competence & Documented Information`,estimatedMinutes:35,overview:`Simple presentation on Clause 7 requirements: people, infrastructure, work environment, calibration of measuring equipment (Clause 7.1.5), staff competence and awareness (7.2–7.3), communication (7.4), and control of Documented Information (7.5).`,internationalClauses:[`ISO 9001:2015 Clause 7 (Support & Resource Management)`],keyPrinciples:[`Clause 7.1 covers providing adequate personnel, maintained infrastructure (buildings, machinery, IT), a suitable work environment, and calibrated measuring instruments.`,`Clause 7.1.5 requires all measuring equipment affecting product quality (scales, thermometers, pH meters, gauges) to be calibrated at specified intervals against international/national traceable standards.`,`Clause 7.2 & 7.3 require defining competence requirements for every role, providing training, evaluating training effectiveness, and ensuring staff awareness.`,`Clause 7.5 (Documented Information) governs creating, approving, updating, controlling versions, and retaining procedures ("Maintain") and records ("Retain").`],criticalControlParameters:[{parameter:`Calibration Traceability & Out-of-Calibration Action (Clause 7.1.5)`,standardLimit:`All quality-critical instruments calibrated to national/ISO 17025 standards, labeled with status, and protected from damage`,correctiveProtocol:`If an instrument is found out of calibration, assess the validity of all previous measurements taken with it and quarantine affected stock.`},{parameter:`Control of Documented Information (Clause 7.5)`,standardLimit:`Current approved version available at point of use; obsolete versions removed; records legible and retained per schedule`,correctiveProtocol:`Withdraw any uncontrolled or outdated SOP/form found on the shop floor immediately.`}],practicalChecklist:[`Check the Master Calibration Register and verify that every scale, thermometer, and gauge has a valid calibration sticker.`,`Review the Staff Competence & Training Matrix to confirm training effectiveness is evaluated.`,`Verify that all SOPs and forms on the floor show the current controlled revision number.`],presentationSlides:[{slideNumber:1,title:`Clause 7.1.1 to 7.1.4: People, Infrastructure & Work Environment`,subtitle:`Providing the Right Tools and Conditions for Quality Work`,bulletPoints:[`People (7.1.2): Provide enough qualified staff so workloads do not cause quality errors.`,`Infrastructure (7.1.3): Maintain buildings, production machinery, utilities, transport vehicles, and IT software through a Preventive Maintenance schedule.`,`Environment for the Operation of Processes (7.1.4): Maintain suitable physical conditions (temperature, humidity, lighting, cleanliness, noise control) and social/psychological conditions (safe, respectful workplace).`],keyTakeaway:`Well-maintained machines and a clean, well-lit work environment are essential prerequisites for quality.`},{slideNumber:2,title:`Clause 7.1.5: Monitoring and Measuring Resources (Calibration)`,subtitle:`How Do You Know Your Scales and Gauges Are Accurate?`,bulletPoints:[`Any instrument used to verify product conformity (weighing scales, thermometers, pressure gauges, pH meters, refractometers, micrometers) MUST be calibrated.`,`Calibration Rules under Clause 7.1.5:`,`• Calibrate at specified intervals against measurement standards traceable to international or national standards.`,`• Identify each instrument with a unique ID and Calibration Status Sticker (Calibrated Date + Due Date).`,`• Safeguard instruments from unauthorized adjustment, dropping, or corrosion.`,`Crucial Rule: If an instrument is found out of calibration during a check, you MUST assess the validity of previous batch measurements and take action on any affected product!`],keyTakeaway:`Finding a scale or thermometer out of calibration requires checking whether recent batches measured with it are still within specification!`},{slideNumber:3,title:`Clause 7.1.6 & 7.2: Organizational Knowledge & Competence`,subtitle:`Building and Retaining Skilled Teams`,bulletPoints:[`Organizational Knowledge (7.1.6): Capture lessons learned, technical know-how, and best practices in SOPs so valuable knowledge is not lost when a senior employee retires or leaves.`,`Competence (7.2): Determine required education, training, or experience for each role → Provide training/mentoring to close any skill gaps → Evaluate the EFFECTIVENESS of the training (via test, observation, or audit) → Retain documented records (certificates, training matrix).`],keyTakeaway:`Attendance on a training sheet is not enough—Clause 7.2 requires evaluating whether the training actually made the employee competent.`},{slideNumber:4,title:`Clause 7.3 & 7.4: Awareness and Communication`,subtitle:`What Every Employee Must Know During an Audit Interview`,bulletPoints:[`Under Clause 7.3, every person working under the organization’s control must be aware of 4 things:`,`• The Quality Policy.`,`• Relevant Quality Objectives for their department.`,`• Their contribution to QMS effectiveness (benefits of improved performance).`,`• The implications of NOT conforming with QMS requirements (risks of defects, complaints, or recalls).`,`Clause 7.4 defines Internal and External Communication (what, when, with whom, how, and who communicates).`],keyTakeaway:`Make sure every operator can answer the 4 Awareness questions in simple language before an ISO 9001 audit.`},{slideNumber:5,title:`Clause 7.5: Documented Information ("Maintain" vs. "Retain")`,subtitle:`Controlling Procedures and Records`,bulletPoints:[`ISO 9001 uses the term "Documented Information" for both documents and records:`,`• "Maintain Documented Information" = Written Documents / SOPs / Manuals / Work Instructions that guide how to work (subject to version updates).`,`• "Retain Documented Information" = Completed Records / Logs / Test Reports / Checklists that provide evidence of results achieved (cannot be altered once signed).`,`Document Control Rules: Approve documents before issue, ensure the current version is at the workstation, remove obsolete versions, and back up electronic records.`],keyTakeaway:`"Maintain" means SOPs and Procedures; "Retain" means Records and Logs.`}]},{id:`iso9001-mod-4`,moduleNumber:4,title:`Clause 8: Operation — Customer Orders, Design, Purchasing, Production & Nonconforming Outputs`,estimatedMinutes:40,overview:`Simple presentation on Clause 8 (The DO Phase): reviewing customer orders (8.2), design and development (8.3), controlling external suppliers (8.4), production and service controls (8.5), product release (8.6), and controlling nonconforming outputs (8.7).`,internationalClauses:[`ISO 9001:2015 Clause 8 (Operational Planning and Control)`],keyPrinciples:[`Clause 8.2 requires reviewing customer requirements (product specs, delivery dates, statutory rules) BEFORE committing to supply.`,`Clause 8.4 requires evaluating, selecting, monitoring, and re-evaluating external suppliers, contractors, and outsourced processes.`,`Clause 8.5 & 8.6 govern controlled production conditions, identification and traceability, preserving product quality during storage/handling, and formal QC inspection release.`,`Clause 8.7 requires identifying and segregating Nonconforming Outputs (defective items) so they cannot be used or delivered unintentionally.`],criticalControlParameters:[{parameter:`Customer Order Review Before Acceptance (Clause 8.2.3)`,standardLimit:`100% review of product specs, quantity, delivery lead time, and legal requirements before confirming order`,correctiveProtocol:`Resolve any contract discrepancy with the customer in writing before starting production.`},{parameter:`Control of Nonconforming Outputs (Clause 8.7)`,standardLimit:`Immediate physical segregation/hold tagging of defective items + documented disposition (Rework, Scrap, Concession)`,correctiveProtocol:`Re-inspect 100% of any reworked batch against original specifications before release.`}],practicalChecklist:[`Check that Sales/Customer Service reviews and signs off customer specifications before accepting orders.`,`Verify the Approved Supplier List and annual supplier evaluation scores (Clause 8.4).`,`Inspect the Quarantine / Nonconforming Product Hold area to confirm all rejected items are tagged and logged (Clause 8.7).`],presentationSlides:[{slideNumber:1,title:`Clause 8.1 & 8.2: Operational Planning & Customer Requirements`,subtitle:`Never Promise What the Factory Cannot Deliver`,bulletPoints:[`Clause 8.1: Plan and control production processes by setting clear product acceptance criteria (specifications) and keeping production records.`,`Clause 8.2 (Requirements for Products and Services): Before accepting a customer order or contract, review it to confirm:`,`• Product specifications, packaging, and delivery dates are clearly defined.`,`• Applicable statutory and regulatory laws are met.`,`• Your facility actually has the capacity and capability to meet the order on time.`,`If a customer changes an order later, amend the documents and notify production/QA immediately.`],keyTakeaway:`Reviewing customer contracts before acceptance prevents late deliveries and specification disputes.`},{slideNumber:2,title:`Clause 8.3: Design and Development of Products and Services`,subtitle:`Turning a New Idea Into a Safe, Tested Commercial Product`,bulletPoints:[`When developing a new product or recipe, follow structured Design Stages:`,`• Design Inputs: Customer needs, legal regulations, functional/safety targets, and lessons from previous similar products.`,`• Design Controls: Design Reviews (checking progress), Design Verification (do lab recipes meet input specs?), and Design Validation (do pilot/factory trials work in real customer use?).`,`• Design Outputs: Approved final formula, raw material specs, packaging specs, and inspection criteria.`],keyTakeaway:`Design Verification checks if outputs meet design inputs on paper/lab; Design Validation proves the final product works in real-world use.`},{slideNumber:3,title:`Clause 8.4: Control of Externally Provided Processes, Products & Services`,subtitle:`Supplier Approval, Monitoring & Outsourced Processes`,bulletPoints:[`Your finished product is only as good as the raw materials and services you buy.`,`Establish criteria for evaluating, selecting, monitoring performance, and re-evaluating suppliers (Clause 8.4.1).`,`Clearly communicate specifications, quality requirements, and COA needs on Purchase Orders (Clause 8.4.3).`,`Remember: If you outsource a process (e.g., external warehousing, lab testing, or contract packing), YOU remain responsible for its quality and must control it under Clause 8.4!`],keyTakeaway:`Outsourced processes cannot be ignored—they must be controlled and audited under Clause 8.4.`},{slideNumber:4,title:`Clause 8.5.1 & 8.5.2: Production Control, Identification & Traceability`,subtitle:`Running Controlled Shifts & Tracking Every Batch`,bulletPoints:[`Controlled Conditions (8.5.1): Operators must have clear work instructions/specs, suitable calibrated equipment, in-process monitoring checks, and human-error prevention controls.`,`Identification & Traceability (8.5.2): Every raw material, work-in-progress bin, and finished carton must carry a clear Batch/Lot ID AND Inspection Status (e.g., "Under Test / Hold", "QC Passed", or "Rejected").`,`Never leave unlabeled containers or unmarked pallets on the shop floor.`],keyTakeaway:`Every pallet or bin in the facility must clearly show both What it is (Batch ID) and its Inspection Status (Passed / Hold / Rejected).`},{slideNumber:5,title:`Clause 8.5.3 to 8.5.6: Customer Property, Preservation & Change Control`,subtitle:`Protecting Goods & Managing Operational Changes`,bulletPoints:[`Customer or External Provider Property (8.5.3): If a customer supplies their own branded packaging, molds, or raw materials, label and protect them carefully and report any damage/loss.`,`Preservation (8.5.4): Protect product quality during internal handling, packaging, storage (FIFO/FEFO, temperature/humidity control), and transport.`,`Post-Delivery Activities (8.5.5) & Control of Changes (8.5.6): Handle warranty/feedback and document approval before making any production process change.`],keyTakeaway:`Preservation (Clause 8.5.4) covers proper packaging, warehousing, FIFO/FEFO rotation, and safe shipping conditions.`},{slideNumber:6,title:`Clause 8.6 & 8.7: Release of Products & Nonconforming Outputs`,subtitle:`Final QC Gate & Handling Defective Batches`,bulletPoints:[`Release of Products (8.6): Finished goods must NOT be shipped to customers until all planned inspections/tests are completed and signed off by an authorized person (e.g., QC Release Officer).`,`Control of Nonconforming Outputs (8.7): If raw material, WIP, or finished product fails specification:`,`• Identify and physically segregate it immediately (Red Hold Tag / Quarantine Area) to prevent unintended use.`,`• Authorized Actions: (a) Correction / Rework (followed by full re-inspection!), (b) Segregation/Return/Scrap, or (c) Obtaining written Concession from the customer (only if legal/safe).`,`• Retain records describing the defect, action taken, and who authorized the decision.`],keyTakeaway:`Any reworked product under Clause 8.7 MUST be re-inspected to prove it now meets 100% of original specifications.`}]},{id:`iso9001-mod-5`,moduleNumber:5,title:`Clauses 9 & 10: Performance Evaluation, Internal Audit, Management Review & Improvement`,estimatedMinutes:35,overview:`Simple presentation on Clause 9 (Monitoring KPIs, Customer Satisfaction, Internal Audits, Management Review) and Clause 10 (Nonconformity & Corrective Action, Root Cause Analysis, and Continual Improvement).`,internationalClauses:[`ISO 9001:2015 Clauses 9 and 10 (The CHECK & ACT Phases)`],keyPrinciples:[`Clause 9.1 requires monitoring process KPIs, analyzing data trends, and actively measuring Customer Satisfaction (surveys, repeat orders, complaint trends, OTIF).`,`Clause 9.2 requires conducting planned, impartial Internal Audits to verify that the QMS conforms to ISO 9001 and company procedures and is effectively maintained.`,`Clause 9.3 requires Top Management to review the QMS at planned intervals considering mandatory Review Inputs and generating documented Review Outputs.`,`Clause 10.2 requires reacting to nonconformities, determining Root Cause, implementing Corrective Actions, and verifying effectiveness to prevent recurrence.`],criticalControlParameters:[{parameter:`Internal Audit Impartiality & Scope (Clause 9.2)`,standardLimit:`Audit program covers all QMS processes based on status/importance; auditors do NOT audit their own work`,correctiveProtocol:`Ensure timely correction and corrective action without undue delay for every audit nonconformity.`},{parameter:`Correction vs. Corrective Action (Clause 10.2)`,standardLimit:`Correction = Immediate fix of the defect; Corrective Action = Eliminating the Root Cause so it cannot recur`,correctiveProtocol:`Review the effectiveness of every Corrective Action taken before closing the CAR/CAPA log.`}],practicalChecklist:[`Review customer satisfaction survey results, complaint trends, and process KPIs (Clause 9.1).`,`Verify that the Annual Internal Audit Program and Management Review minutes are complete (Clauses 9.2 & 9.3).`,`Complete all 5 modules and take the 40-MCQ ISO 9001 Awareness Final Exam.`],presentationSlides:[{slideNumber:1,title:`Clause 9.1: Monitoring, Measurement, Analysis & Evaluation`,subtitle:`Measuring Process Performance & Customer Satisfaction`,bulletPoints:[`Determine what needs to be monitored and measured, when, and how the data will be analyzed.`,`Customer Satisfaction (Clause 9.1.2): You must monitor customer perceptions of the degree to which their needs and expectations have been fulfilled.`,`Methods to measure Customer Satisfaction: Customer surveys, feedback on delivered quality, On-Time-In-Full (OTIF) delivery scores, customer complaints, compliments, and repeat business.`,`Analyze data (Clause 9.1.3) to evaluate product conformity, process trends, and supplier performance.`],keyTakeaway:`Waiting for complaints is not enough—Clause 9.1.2 requires proactively monitoring customer satisfaction perceptions.`},{slideNumber:2,title:`Clause 9.2: Internal Audit Program`,subtitle:`Checking That Your QMS Works as Planned`,bulletPoints:[`Conduct internal audits at planned intervals to verify whether the QMS:`,`• Conforms to your organization’s own procedures and requirements.`,`• Conforms to the requirements of ISO 9001:2015.`,`• Is effectively implemented and maintained.`,`Plan the audit schedule based on the importance of the processes, changes affecting the company, and the results of previous audits.`,`Select trained, objective, and impartial auditors (auditors must never audit their own work!).`],keyTakeaway:`Internal audits must be scheduled based on process risk/importance and previous audit findings.`},{slideNumber:3,title:`Clause 9.3: Management Review (Inputs & Outputs)`,subtitle:`Top Management’s Strategic Review of the QMS`,bulletPoints:[`Top Management must review the QMS at planned intervals (e.g., quarterly or annually).`,`Mandatory Management Review Inputs (9.3.2): Status of previous actions, changes in external/internal issues, customer satisfaction & feedback, achievement of Quality Objectives, process performance & nonconformities, audit results, supplier performance, adequacy of resources, and effectiveness of risk actions.`,`Mandatory Outputs (9.3.3): Decisions and actions related to Opportunities for Improvement, any need for changes to the QMS, and Resource needs.`],keyTakeaway:`Make sure your Management Review meeting agenda includes every single mandatory input listed in Clause 9.3.2!`},{slideNumber:4,title:`Clause 10.2: Nonconformity and Corrective Action`,subtitle:`Correction vs. Corrective Action (Key Exam Distinction)`,bulletPoints:[`When a nonconformity (including a customer complaint or audit finding) occurs:`,`Step 1 — React & Apply Immediate Correction: Take action to control and correct the immediate defect and deal with the consequences.`,`Step 2 — Root Cause Analysis: Evaluate the need for action to eliminate the cause(s) of the nonconformity (using 5-Whys or Fishbone/Ishikawa diagram) so it does not recur.`,`Step 3 — Implement Corrective Action & Review Effectiveness: Put the systemic fix in place, update risks/SOPs if needed, and verify later that the problem did not return.`],keyTakeaway:`Correction fixes the immediate symptom; Corrective Action eliminates the Root Cause so the problem cannot happen again.`},{slideNumber:5,title:`Clause 10.3: Continual Improvement & Course Summary`,subtitle:`Making the Organization Stronger Every Year`,bulletPoints:[`The organization must continually improve the suitability, adequacy, and effectiveness of the QMS.`,`Use outputs from data analysis, internal audits, customer feedback, and management reviews to drive Kaizen (continuous small improvements) and breakthrough projects.`,`Congratulations on completing all 5 Modules of the ISO 9001 Awareness Certificate! Proceed to the 40-MCQ Final Exam (60% passing score).`],keyTakeaway:`ISO 9001 is a continuous PDCA journey of quality excellence—click below to start your 40-MCQ Final Exam!`}]}],coreExamPool:[{q:`What is the primary purpose of the ISO 9001:2015 standard?`,options:[`To specify requirements for a Quality Management System (QMS) so an organization consistently provides products/services that meet customer and regulatory requirements`,`To set retail prices for food products`,`To calculate employee income tax`,`To design company logos`],correctIndex:0,explanation:`ISO 9001:2015 defines the requirements for an effective Quality Management System (QMS).`},{q:`How many Quality Management Principles form the foundation of ISO 9000 / ISO 9001:2015?`,options:[`7 Quality Management Principles`,`3 Quality Management Principles`,`14 Quality Management Principles`,`20 Quality Management Principles`],correctIndex:0,explanation:`ISO 9001:2015 is built on 7 Quality Management Principles: Customer Focus, Leadership, Engagement of People, Process Approach, Improvement, Evidence-Based Decision Making, and Relationship Management.`},{q:`In the Annex SL structure of ISO 9001:2015, which clauses correspond to the PLAN, DO, CHECK, and ACT phases?`,options:[`Plan = Clauses 4, 5, 6; Do = Clauses 7, 8; Check = Clause 9; Act = Clause 10`,`Plan = Clause 1; Do = Clause 2; Check = Clause 3; Act = Clause 4`,`Plan = Clause 10; Do = Clause 9; Check = Clause 8; Act = Clause 7`,`ISO 9001 does not use PDCA`],correctIndex:0,explanation:`Clauses 4–6 represent Plan, Clauses 7–8 represent Do, Clause 9 represents Check, and Clause 10 represents Act.`},{q:`Under ISO 9001:2015 Clause 7.5 (Documented Information), what is the difference between "Maintain documented information" and "Retain documented information"?`,options:[`"Maintain" refers to procedures/SOPs/manuals that guide work; "Retain" refers to records/logs that provide objective evidence of results achieved`,`They both mean throwing away old files`,`"Maintain" means repairing trucks; "Retain" means hiring staff`,`ISO 9001 does not require any records`],correctIndex:0,explanation:`In Annex SL terminology, "Maintain documented information" means controlled procedures/documents, while "Retain documented information" means records.`},{q:`Under Clause 7.1.5 (Monitoring and Measuring Resources), what must you do if a weighing scale or thermometer is found to be out of calibration?`,options:[`Tag the instrument out of service, recalibrate/repair it, AND assess the validity of previous measurements taken with it (checking if recent batches were affected)`,`Continue using it until the end of the year`,`Change the calibration sticker date with a pen`,`Do nothing`],correctIndex:0,explanation:`Clause 7.1.5.2 requires assessing and recording the validity of previous measurement results whenever measuring equipment is found unfit for purpose.`},{q:`Under Clause 10.2 of ISO 9001:2015, what is the exact difference between "Correction" and "Corrective Action"?`,options:[`Correction fixes the immediate detected nonconformity; Corrective Action eliminates the Root Cause of the nonconformity to prevent recurrence`,`Correction is for managers; Corrective Action is for operators`,`They mean the exact same thing`,`Corrective Action means ignoring the defect`],correctIndex:0,explanation:`Correction addresses the immediate symptom/defect, while Corrective Action eliminates the underlying root cause so it cannot happen again.`}]},{id:`cert-2026-iso-22000-awareness`,code:`ISO-22000-AW`,title:`ISO 22000 Awareness Certificate`,levelBadge:`Simple Presentation Course (05 Modules · 35 Slides · 40 MCQs · 60% Pass)`,accreditationStandard:`ISO 22000:2018 Food Safety Management Systems (FSMS) • Awareness Presentation Course`,duration:`05 Presentation Modules (35 Slides) + 40-MCQ Final Exam`,certificateFeeRs:1e3,passPercentage:60,distinctionPercentage:75,totalExamQuestions:40,description:`Simple Slide Presentation Course on ISO 22000:2018 Food Safety Management Systems (FSMS) across the entire "Farm-to-Fork" food chain. Covers the 4 Pillars of ISO 22000, the Dual PDCA Cycle (Organizational vs. Operational HACCP), Clauses 4 to 7, Clause 8 Operational Control (PRPs vs. OPRPs vs. CCPs, Traceability & Emergency Preparedness), and Clauses 9 & 10 Auditing and Improvement.`,modules:[{id:`iso22000-mod-1`,moduleNumber:1,title:`Introduction to ISO 22000:2018, The 4 Key Elements & Dual PDCA Cycle`,estimatedMinutes:35,overview:`Simple presentation on what ISO 22000:2018 is, which food chain organizations can use it, its 4 core pillars (Interactive Communication, System Management, PRPs, HACCP Principles), and its unique Dual PDCA Cycle.`,internationalClauses:[`ISO 22000:2018 Clauses 1 to 4 & Dual PDCA Architecture`],keyPrinciples:[`ISO 22000:2018 is the international Food Safety Management System (FSMS) standard applicable to all organizations in the "Farm-to-Fork" food chain (farms, processors, catering, packaging, transport, chemicals).`,`It combines 4 key elements: (1) Interactive Communication across the food chain, (2) System Management (ISO 9001 Annex SL structure), (3) Prerequisite Programs (PRPs), and (4) Codex HACCP Principles.`,`ISO 22000:2018 uses a Dual PDCA Cycle: The Outer PDCA manages Organizational Business Risk (Clauses 4–10), while the Inner PDCA inside Clause 8 manages Operational Food Safety Risk (HACCP).`],criticalControlParameters:[{parameter:`Four Pillars of ISO 22000:2018`,standardLimit:`Interactive Communication + System Management + Prerequisite Programs (PRPs) + HACCP Principles`,correctiveProtocol:`Ensure all 4 elements are active and integrated in the company FSMS.`},{parameter:`Dual PDCA Cycle (Organizational vs. Operational)`,standardLimit:`Level 1 Organizational Risk (Clause 6.1) + Level 2 Operational Food Safety Hazard Analysis (Clause 8.5)`,correctiveProtocol:`Maintain both an Organizational Business Risk Register (Clause 6.1) and a HACCP Hazard Analysis (Clause 8.5).`}],practicalChecklist:[`Learn the 4 key elements of ISO 22000:2018.`,`Understand how the Inner Operational PDCA (Clause 8 HACCP) sits inside the Outer Organizational PDCA (Clauses 4–10).`,`Identify your organization’s upstream suppliers and downstream customers in the food chain.`],presentationSlides:[{slideNumber:1,title:`What is ISO 22000:2018?`,subtitle:`The Global Standard for Food Safety Management Systems (FSMS)`,bulletPoints:[`ISO 22000:2018 is the international standard created specifically for Food Safety Management Systems (FSMS).`,`It combines the management system structure of ISO 9001 with Codex Alimentarius HACCP and Prerequisite Programs (PRPs).`,`It applies to ANY organization in the "Farm-to-Fork" food chain: crop/dairy farms, food & beverage manufacturers, hospital/hotel kitchens, transport & cold storage, food packaging makers, and cleaning chemical suppliers.`],keyTakeaway:`ISO 22000:2018 unites ISO 9001 management discipline with Codex HACCP food safety science.`},{slideNumber:2,title:`The 4 Key Elements (Pillars) of ISO 22000:2018`,subtitle:`The Building Blocks of the Standard`,bulletPoints:[`Interactive Communication: Structured food safety communication upstream (with suppliers) and downstream (with customers and regulators) across the food chain.`,`System Management: Structured policies, planning, document control, internal auditing, and management review (Clauses 4 to 10).`,`Prerequisite Programs (PRPs): Basic hygiene and facility conditions (GMPs/GHPs) tailored to your sector (using ISO/TS 22002 series).`,`HACCP Principles: Science-based hazard analysis and control via OPRPs and CCPs.`],keyTakeaway:`Memorize the 4 Pillars of ISO 22000: Interactive Communication, System Management, PRPs, and HACCP Principles.`},{slideNumber:3,title:`The Unique "Dual PDCA Cycle" in ISO 22000:2018`,subtitle:`Two Levels of Plan-Do-Check-Act Working Together`,bulletPoints:[`A major highlight of ISO 22000:2018 is that it operates TWO PDCA cycles simultaneously:`,`Cycle 1 — Outer Organizational PDCA (Clauses 4 to 10): Manages high-level business context, leadership, organizational risks/opportunities (Clause 6.1), resources, audits, and continual improvement.`,`Cycle 2 — Inner Operational PDCA (Inside Clause 8): Manages hands-on Food Safety—PRPs, Traceability, Emergency Preparedness, Hazard Analysis, OPRPs/CCPs, Validation, Monitoring, and Verification.`],keyTakeaway:`Clause 6.1 addresses Business/Organizational Risks; Clause 8.5 addresses Operational Food Safety Hazards (HACCP).`},{slideNumber:4,title:`Interactive Communication Across the Food Chain`,subtitle:`Why One Link Cannot Ensure Safe Food Alone`,bulletPoints:[`Contamination can enter at any point from farm feed to retail display.`,`Upstream Communication (With Suppliers): Sharing raw material specifications, allergen profiles, COA requirements, and audit findings.`,`Downstream Communication (With Customers & Consumers): Providing accurate allergen labeling, storage temperatures ("Keep Chilled ≤ 4°C"), shelf life, and safe cooking instructions.`,`Regulatory Communication: Reporting statutory notifications and recalls promptly.`],keyTakeaway:`Clear communication with suppliers and customers ensures hazards are controlled across the entire food chain.`},{slideNumber:5,title:`Overview of ISO 22000:2018 Clauses 4 to 10`,subtitle:`Matching the High-Level Annex SL Structure`,bulletPoints:[`Clause 4: Context of the Organization, Interested Parties & FSMS Scope.`,`Clause 5: Leadership, Food Safety Policy & Food Safety Team Leader (FSTL) Role.`,`Clause 6: Planning (Organizational Risks/Opportunities & FSMS Objectives).`,`Clause 7: Support (Resources, Competence, Awareness, Communication & Documented Information).`,`Clause 8: Operation (PRPs, Traceability, Emergency Preparedness, HACCP Hazard Analysis, OPRPs & CCPs).`,`Clause 9: Performance Evaluation (Monitoring, Verification, Internal Audit & Management Review).`,`Clause 10: Improvement (Nonconformity, Corrective Action & Continual Improvement).`],keyTakeaway:`Because ISO 22000 shares the Clauses 4–10 layout with ISO 9001, companies can easily combine both into one Integrated Management System.`}]},{id:`iso22000-mod-2`,moduleNumber:2,title:`Clauses 5, 6 & 7: Leadership, Food Safety Team Leader (FSTL), Planning & Support`,estimatedMinutes:35,overview:`Simple presentation on Top Management commitment, the Food Safety Policy, the mandatory duties of the Food Safety Team Leader (FSTL), FSMS Objectives, Calibration, Competence, and control of Externally Developed Elements.`,internationalClauses:[`ISO 22000:2018 Clauses 5, 6, and 7`],keyPrinciples:[`Clause 5.3 requires Top Management to appoint a qualified Food Safety Team Leader (FSTL) who manages the Food Safety Team, ensures training, maintains the FSMS, and reports effectiveness to Top Management.`,`The Food Safety Policy (Clause 5.2) must commit to satisfying applicable food safety/legal/customer requirements, continual improvement, and addressing internal/external food safety communication.`,`Clause 7.1.5 requires explicitly controlling any "Externally Developed Elements" of the FSMS (e.g., government hygiene guides or group head-office HACCP templates) to ensure they fit the local site.`,`Clause 7.4 defines mandatory External and Internal Food Safety Communication channels.`],criticalControlParameters:[{parameter:`Appointment & Duties of the Food Safety Team Leader (Clause 5.3.2)`,standardLimit:`Formally appointed FSTL responsible for managing the FS Team, organizing work/training, and reporting FSMS suitability`,correctiveProtocol:`Ensure the FSTL has formal HACCP/ISO 22000 training and direct reporting access to Top Management.`},{parameter:`Internal Food Safety Change Communication (Clause 7.4.3)`,standardLimit:`Food Safety Team notified BEFORE any change in new products, raw materials, equipment, cleaning chemicals, or packaging`,correctiveProtocol:`Enforce a Management of Change (MOC) sign-off by the FSTL prior to implementing any operational change.`}],practicalChecklist:[`Check that the Food Safety Team Leader (FSTL) appointment letter and Food Safety Team list are signed by Top Management.`,`Verify that the Food Safety Policy is displayed and includes a commitment to safe food, legal compliance, communication, and continual improvement.`,`Confirm that Clause 7.4.3 internal change notifications are logged whenever recipes, suppliers, or machines change.`],presentationSlides:[{slideNumber:1,title:`Clause 5.2: The Food Safety Policy`,subtitle:`Top Management’s Written Commitment to Safe Food`,bulletPoints:[`Top Management must establish, implement, and maintain a Food Safety Policy that:`,`• Is appropriate to the purpose and context of the food organization.`,`• Provides a framework for setting and reviewing measurable FSMS Objectives.`,`• Includes a commitment to satisfy applicable food safety requirements (statutory, regulatory, and mutually agreed customer requirements).`,`• Addresses internal and external communication.`,`• Includes a commitment to continual improvement and ensuring food safety competence.`],keyTakeaway:`Unlike a generic quality policy, an ISO 22000 Food Safety Policy must specifically mention food safety communication and competence.`},{slideNumber:2,title:`Clause 5.3: The Food Safety Team Leader (FSTL)`,subtitle:`A Mandatory Role Under ISO 22000:2018`,bulletPoints:[`While ISO 9001 removed the mandatory title "Management Representative", ISO 22000:2018 STILL strictly requires appointing a Food Safety Team Leader (FSTL)!`,`Core Responsibilities of the FSTL (Clause 5.3.2):`,`• Ensure the FSMS is established, implemented, maintained, and updated.`,`• Manage and organize the work of the multidisciplinary Food Safety Team.`,`• Ensure relevant training and competencies for the Food Safety Team.`,`• Report to Top Management on the effectiveness and suitability of the FSMS.`],keyTakeaway:`Every ISO 22000 facility must have a formally appointed Food Safety Team Leader (FSTL).`},{slideNumber:3,title:`Clause 6: Planning Organizational Risks & FSMS Objectives`,subtitle:`Separating Business Risks from HACCP Hazards`,bulletPoints:[`Clause 6.1 (Organizational Risks & Opportunities): Evaluates business-level risks that could impact food safety—such as skilled staff shortage, supplier bankruptcy, power grid instability, or regulatory law changes.`,`Clause 6.2 (FSMS Objectives): Measurable targets consistent with the Food Safety Policy—such as "Zero Class I/II recalls", "100% CCP monitoring compliance", or "≥ 98% pre-op ATP swab pass rate".`],keyTakeaway:`Track your measurable FSMS Objectives monthly and review them in Management Review.`},{slideNumber:4,title:`Clause 7.1.2 to 7.1.6: External Experts, Labs & Suppliers`,subtitle:`Controlling External Support for the FSMS`,bulletPoints:[`If you use External Experts (e.g., a food safety consultant or pest control advisor) to help develop or maintain the FSMS, you must keep a written agreement defining their competence, responsibility, and authority (Clause 7.1.2).`,`If you use Externally Developed Elements (e.g., industry-wide PRP guides or corporate HACCP plans), you must prove they are adapted specifically to your factory lines (Clause 7.1.5).`],keyTakeaway:`Never copy-paste a generic HACCP plan—Clause 7.1.5 requires adapting any external template to your exact site processes.`},{slideNumber:5,title:`Clause 7.4: External & Internal Food Safety Communication`,subtitle:`Ensuring the Food Safety Team Is Never Left in the Dark`,bulletPoints:[`External Communication (7.4.2): Assign authorized personnel to communicate food safety information with suppliers, customers, statutory/regulatory authorities, and other organizations.`,`Internal Communication (7.4.3): The Food Safety Team MUST be informed in a timely manner of any changes in: New products, raw materials/ingredients, production systems/equipment, cleaning & sanitation programs, packaging/storage/distribution, staff qualification levels, or legal requirements.`],keyTakeaway:`Clause 7.4.3 guarantees that no department can change an ingredient, chemical, or machine without informing the Food Safety Team first.`}]},{id:`iso22000-mod-3`,moduleNumber:3,title:`Clause 8.1 to 8.4: Prerequisite Programs (PRPs), Traceability & Emergency Preparedness`,estimatedMinutes:40,overview:`Simple presentation on Clause 8.2 Prerequisite Programs (PRPs and the ISO/TS 22002 series), Clause 8.3 Traceability System (one step back, one step forward, rework tracking), and Clause 8.4 Emergency Preparedness and Response.`,internationalClauses:[`ISO 22000:2018 Clauses 8.1, 8.2, 8.3, and 8.4`],keyPrinciples:[`Clause 8.2 requires establishing Prerequisite Programs (PRPs) to prevent and reduce contaminants in the processing environment, aligned with the ISO/TS 22002 technical specification for your sector.`,`Clause 8.2.3 lists 12 mandatory PRP areas including building layout, air/water/energy utilities, pest control, waste disposal, equipment suitability, cleaning/sanitizing, personal hygiene, rework, and product information.`,`Clause 8.3 requires a Traceability System that uniquely identifies incoming materials, rework, and finished distribution pathways.`,`Clause 8.4 requires written Emergency Preparedness procedures (fire, flood, power/water outage, bioterrorism/sabotage) tested periodically through drills.`],criticalControlParameters:[{parameter:`Sector-Specific PRP Alignment (Clause 8.2 & ISO/TS 22002)`,standardLimit:`Food Manufacturing = ISO/TS 22002-1; Catering = ISO/TS 22002-2; Packaging = ISO/TS 22002-4; Storage/Transport = ISO 22002-5`,correctiveProtocol:`Verify and inspect all 12 PRP categories listed in Clause 8.2.3 on a scheduled frequency.`},{parameter:`Emergency Preparedness Testing & Mock Recalls (Clause 8.3 & 8.4)`,standardLimit:`Periodic testing of emergency response plans and traceability/recall drills at least annually`,correctiveProtocol:`Update emergency contact lists and SOPs immediately after every drill or real incident.`}],practicalChecklist:[`Verify that your PRP Manual covers all 12 sub-clauses of ISO 22000 Clause 8.2.3.`,`Check that Rework (if used) is clearly batch-coded, allergen-segregated, and recorded in your Traceability system (Clause 8.3).`,`Confirm that an annual Emergency Drill (e.g., power outage or water contamination) and Mock Recall have been documented.`],presentationSlides:[{slideNumber:1,title:`Clause 8.2: Prerequisite Programs (PRPs)`,subtitle:`The 12 Mandatory PRP Topics in Clause 8.2.3`,bulletPoints:[`ISO 22000 Clause 8.2.3 requires your PRPs to cover at least these 12 areas:`,`• Construction and layout of buildings & associated utilities.`,`• Layout of premises, including workspace and employee facilities.`,`• Supplies of air, water, energy, and other utilities.`,`• Pest control, waste, and sewage disposal.`,`• Suitability of equipment and its accessibility for cleaning and maintenance.`,`• Supplier approval and management of purchased materials, services, and subcontracted processes.`],keyTakeaway:`PRPs must be established BEFORE conducting the Clause 8.5 HACCP Hazard Analysis.`},{slideNumber:2,title:`Clause 8.2.3 (Continued) & The ISO/TS 22002 Series`,subtitle:`Matching Your PRPs to Your Exact Industry Sector`,bulletPoints:[`The remaining mandatory PRP topics in Clause 8.2.3:`,`• Measures for prevention of cross-contamination & allergen control.`,`• Cleaning and disinfecting.`,`• Personal hygiene and employee health facilities.`,`• Rework control, Product recall procedures, and Warehousing/Transport.`,`Sector Technical Specifications: ISO/TS 22002-1 (Food Manufacturing), ISO/TS 22002-2 (Catering), ISO/TS 22002-3 (Farming), ISO/TS 22002-4 (Food Packaging), ISO/TS 22002-5 (Transport & Storage).`],keyTakeaway:`ISO 22000 tells you WHAT PRPs are needed; the ISO/TS 22002 series gives the detailed technical rules for your sector.`},{slideNumber:3,title:`Clause 8.3: The Traceability System`,subtitle:`Tracking Materials, Rework & Distribution`,bulletPoints:[`The traceability system must uniquely identify incoming material from suppliers and the first stage of the distribution route of the end product.`,`Crucial ISO 22000 Requirement: When establishing traceability, you must explicitly include:`,`• Relation of lots of received materials, ingredients, and intermediate products to the end products.`,`• Reworking of materials/products (ensuring rework batch codes and allergens are 100% traced!).`,`• Distribution of the end product.`,`Test the effectiveness of the traceability system at defined intervals.`],keyTakeaway:`Unlabeled rework is one of the top causes of traceability failure in ISO 22000 audits—always label rework with its original batch and date!`},{slideNumber:4,title:`Clause 8.4: Emergency Preparedness and Response`,subtitle:`Preparing for Accidents, Utility Failures & Crises`,bulletPoints:[`Top Management must ensure procedures are in place to respond to potential emergency situations or accidents that can impact food safety.`,`Examples covered under Clause 8.4: Natural disasters (floods, earthquakes), environmental accidents, bioterrorism/sabotage, workplace accidents, and public health emergencies (pandemics, loss of potable water, extended power blackouts).`,`Periodically TEST the emergency procedures where practical, and review/update the plan after any drill or real incident.`],keyTakeaway:`An untested emergency plan on a shelf fails Clause 8.4—run at least one documented emergency simulation drill every year.`}]},{id:`iso22000-mod-4`,moduleNumber:4,title:`Clause 8.5 to 8.9: Hazard Control Plan — OPRPs vs. CCPs, Validation & Nonconformities`,estimatedMinutes:45,overview:`Simple presentation on the core of ISO 22000 Clause 8.5: Preliminary steps, Hazard Assessment, categorizing control measures into OPRPs (Action Criteria) vs. CCPs (Critical Limits), Validation (8.5.3), Verification (8.8), and Handling Potentially Unsafe Products (8.9).`,internationalClauses:[`ISO 22000:2018 Clauses 8.5, 8.6, 8.7, 8.8, and 8.9`],keyPrinciples:[`In ISO 22000:2018, the Hazard Control Plan combines both OPRPs (Operational Prerequisite Programs) and CCPs (Critical Control Points).`,`A CCP uses measurable Critical Limits (e.g., ≥ 75°C, pH ≤ 4.2), whereas an OPRP uses measurable OR observable Action Criteria (e.g., visual sieve integrity check, allergen label check).`,`When a CCP Critical Limit is breached, the affected product is automatically treated as "Potentially Unsafe Product" (Clause 8.9.4) and must be quarantined.`,`When an OPRP Action Criterion is not met, you determine the cause, evaluate whether food safety was affected, and take corrective action.`],criticalControlParameters:[{parameter:`OPRPs (Action Criteria) vs. CCPs (Critical Limits) in Clause 8.5.2.4`,standardLimit:`CCPs have measurable Critical Limits with real-time detection; OPRPs have measurable or observable Action Criteria`,correctiveProtocol:`Document the selection logic (likelihood of failure + severity of consequence + feasibility of monitoring) for every OPRP and CCP.`},{parameter:`Handling Potentially Unsafe Products (Clause 8.9.4)`,standardLimit:`Any batch failing a CCP Critical Limit is quarantined and evaluated via lab/scientific proof before release, rework, or destruction`,correctiveProtocol:`Initiate Clause 8.9.5 Withdrawal/Recall immediately if potentially unsafe product has already left the facility.`}],practicalChecklist:[`Check your Hazard Control Plan to see how significant hazards are assigned to either OPRPs (with Action Criteria) or CCPs (with Critical Limits).`,`Verify that validation records (Clause 8.5.3) exist for every OPRP and CCP prior to implementation.`,`Understand the exact difference in handling an OPRP deviation vs. a CCP Critical Limit failure under Clause 8.9.`],presentationSlides:[{slideNumber:1,title:`Clause 8.5.1 & 8.5.2: Preliminary Steps & Hazard Assessment`,subtitle:`Identifying Significant Food Safety Hazards`,bulletPoints:[`Clause 8.5.1 embeds the 5 Codex Preliminary Steps: Raw material/ingredient/food-contact material descriptions, End-product characteristics, Intended use, Flow diagrams, and Description of processes/environment.`,`Clause 8.5.2 (Hazard Identification & Assessment): For every step, identify all reasonably expected food safety hazards (Biological, Chemical, Physical, Radiological, Allergens) and determine the Acceptable Level in the end product.`,`Evaluate each hazard by Likelihood × Severity to identify Significant Food Safety Hazards.`],keyTakeaway:`Every Significant Food Safety Hazard identified in Clause 8.5.2.3 MUST be controlled by an OPRP or a CCP.`},{slideNumber:2,title:`OPRP vs. CCP in ISO 22000:2018 (The #1 Exam Topic!)`,subtitle:`Understanding Critical Limits vs. Action Criteria`,bulletPoints:[`In ISO 22000:2018, the Hazard Control Plan includes both CCPs and OPRPs:`,`Critical Control Point (CCP):`,`• Uses a measurable CRITICAL LIMIT (e.g., Pasteurization ≥ 72°C for 15s; Metal Detector 1.5 mm Fe).`,`• Monitoring detects any failure in time to isolate the product immediately.`,`• If breached → Product is automatically classified as "Potentially Unsafe Product" and quarantined!`,`Operational Prerequisite Program (OPRP):`,`• Uses a measurable OR observable ACTION CRITERION (e.g., Pre-op allergen clean visual/swab check, End-of-shift sieve intactness check, Glass inspection).`,`• If not met → Determine cause, assess if food safety was impacted, and take corrective action.`],keyTakeaway:`Remember: CCPs have measurable "Critical Limits"; OPRPs have measurable or observable "Action Criteria".`},{slideNumber:3,title:`How ISO 22000 Selects OPRPs vs. CCPs (Clause 8.5.2.4)`,subtitle:`Evaluating Control Measures Systematically`,bulletPoints:[`To categorize a control measure as an OPRP or a CCP, the Food Safety Team assesses:`,`• Likelihood of failure of its functioning (does the control fail easily or have an automatic fail-safe?).`,`• Severity of the consequence in case of failure (degree of effect on the significant hazard and proximity to the final consumer).`,`• Feasibility of establishing measurable Critical Limits and real-time monitoring to allow immediate correction.`,`Where a strict numerical Critical Limit and real-time isolation are feasible for a high-severity step, it is designated a CCP.`],keyTakeaway:`Document the exact reasoning in your HACCP/ISO 22000 file showing why each control measure was classified as an OPRP or CCP.`},{slideNumber:4,title:`Clause 8.5.3: Validation of Control Measures`,subtitle:`Proving OPRPs and CCPs Work Before Going Live`,bulletPoints:[`Before implementing the Hazard Control Plan, the Food Safety Team must VALIDATE that the selected OPRPs and CCPs are capable of achieving the intended control of the significant hazards.`,`If validation shows that a control measure cannot achieve the required safe level, the team must modify the control measure, the process parameter, or the raw material/recipe and re-assess.`],keyTakeaway:`Both CCPs and OPRPs must be validated prior to implementation and after any process change.`},{slideNumber:5,title:`Clause 8.8 & 8.9: Verification, Corrections & Potentially Unsafe Product`,subtitle:`What Happens When an OPRP or CCP Fails?`,bulletPoints:[`Clause 8.8 (Verification): Verify that PRPs and the Hazard Control Plan are implemented and effective (via lab tests, audits, and record reviews).Note: Verification cannot be done by the same person who performed the monitoring!`,`Clause 8.9.4 (Potentially Unsafe Products): Any batch produced when a CCP Critical Limit was breached MUST NOT be released until it is scientifically evaluated:`,`• If proven safe by independent lab/scientific evidence → Release.`,`• If it can be safely re-processed (e.g., re-pasteurized or re-passed through metal detector) → Rework.`,`• Otherwise → Destroy / Dispose as non-food waste!`],keyTakeaway:`Under Clause 8.8, the person who verifies CCP records must be independent of the operator who recorded the monitoring checks.`}]},{id:`iso22000-mod-5`,moduleNumber:5,title:`Clauses 9 & 10: Performance Evaluation, FSMS Updating & Continual Improvement`,estimatedMinutes:35,overview:`Simple presentation on Clause 9 (Analyzing Verification Results, Internal Audits, Management Review) and Clause 10 (Nonconformity & Corrective Action, Continual Improvement, and Mandatory Updating of the FSMS).`,internationalClauses:[`ISO 22000:2018 Clauses 9 and 10`],keyPrinciples:[`Clause 9.1.2 requires the Food Safety Team to analyze all verification results (lab tests, CCP/OPRP trends, audits, complaints) and report them to Top Management.`,`Clause 9.2 requires planned, impartial Internal Audits of the FSMS.`,`Clause 9.3 requires Top Management to conduct Management Reviews covering food safety performance, emergencies/recalls, and resource adequacy.`,`Clause 10.3 strictly requires the Food Safety Team to continually UPDATE the FSMS based on internal/external communication, audit findings, and verification analysis.`],criticalControlParameters:[{parameter:`Analysis of Verification Results by the Food Safety Team (Clause 9.1.2)`,standardLimit:`Formal periodic evaluation of PRPs, Hazard Control Plan trends, lab results, audits, and external alerts`,correctiveProtocol:`Use verification analysis to update the Hazard Assessment, PRPs, or OPRPs/CCPs.`},{parameter:`Continual Updating of the FSMS (Clause 10.3)`,standardLimit:`Planned updating of the FSMS by the Food Safety Team at defined intervals and upon any process/product change`,correctiveProtocol:`Retain documented records of all FSMS updating meetings and report them into Management Review.`}],practicalChecklist:[`Verify that the Food Safety Team conducts a documented Verification Analysis meeting (Clause 9.1.2).`,`Check that the FSMS Updating Log (Clause 10.3) records all updates made to PRPs, Flow Diagrams, and the Hazard Control Plan.`,`Complete all 5 modules and take the 40-MCQ ISO 22000 Awareness Final Exam.`],presentationSlides:[{slideNumber:1,title:`Clause 9.1: Analyzing Verification Results`,subtitle:`How the Food Safety Team Evaluates System Health`,bulletPoints:[`Under Clause 9.1.2, the Food Safety Team must analyze and evaluate the results of verification activities, including:`,`• Confirming overall FSMS performance meets planned arrangements.`,`• Identifying any need for updating or improving the FSMS.`,`• Identifying trends that indicate a higher incidence of potentially unsafe products or process failures.`,`• Establishing information for planning the Internal Audit program and prioritizing high-risk areas.`],keyTakeaway:`Verification data (swabs, lab reports, CCP deviations) must be analyzed by the Food Safety Team, not just filed away in a cabinet.`},{slideNumber:2,title:`Clause 9.2 & 9.3: Internal Audits & Management Review`,subtitle:`Auditing and Executive Oversight of the FSMS`,bulletPoints:[`Internal Audits (9.2): Audit all FSMS processes, PRPs, OPRPs, and CCPs across all shifts using trained, impartial auditors.`,`Management Review (9.3): Top Management reviews the FSMS considering:`,`• Results of FSMS updating activities and verification analysis.`,`• Emergency situations, incidents, and product withdrawals/recalls.`,`• External inspections, customer audits, and regulatory changes.`,`• Adequacy of resources and opportunities for continual improvement.`],keyTakeaway:`Any emergency drill, recall, or external customer audit report must be reviewed by Top Management under Clause 9.3.`},{slideNumber:3,title:`Clause 10.1 & 10.2: Nonconformity and Corrective Action`,subtitle:`Eliminating Root Causes Across the FSMS`,bulletPoints:[`When a nonconformity occurs in any PRP, OPRP, CCP, or management process:`,`• React to the nonconformity, control/correct it, and deal with the consequences.`,`• Review the nonconformity and conduct a Root Cause Analysis so it does not recur or occur elsewhere.`,`• Implement required Corrective Actions, review their effectiveness, and make changes to the FSMS if necessary.`],keyTakeaway:`Retain documented information of the nature of the nonconformities, actions taken, and the results of every corrective action.`},{slideNumber:4,title:`Clause 10.3: Update of the Food Safety Management System`,subtitle:`Keeping the FSMS Alive and Current`,bulletPoints:[`Clause 10.3 is unique to ISO 22000: Top Management must ensure that the FSMS is continually UPDATED!`,`To do this, the Food Safety Team evaluates the FSMS at planned intervals using inputs from:`,`• Internal and external communication (Clause 7.4).`,`• Analysis of verification activities (Clause 9.1.2).`,`• Outputs from Management Review (Clause 9.3).`,`Congratulations on completing all 5 Modules of the ISO 22000 Awareness Certificate! Proceed to the 40-MCQ Final Exam (60% passing score).`],keyTakeaway:`ISO 22000 Clause 10 has both Continual Improvement (10.2) AND Mandatory Updating of the FSMS (10.3).`}]}],coreExamPool:[{q:`What are the 4 Key Elements (Pillars) combined in ISO 22000:2018?`,options:[`Interactive Communication, System Management, Prerequisite Programs (PRPs), and HACCP Principles`,`Sales, Advertising, Accounting, and HR`,`Cooking, Freezing, Packing, and Billing`,`Only end-product laboratory testing`],correctIndex:0,explanation:`ISO 22000:2018 integrates Interactive Communication, System Management, Prerequisite Programs (PRPs), and Codex HACCP Principles.`},{q:`How does the "Dual PDCA Cycle" work in ISO 22000:2018?`,options:[`The Outer PDCA covers Organizational Management & Business Risk (Clauses 4–10), while the Inner PDCA inside Clause 8 covers Operational Food Safety & HACCP Controls`,`It means washing hands twice`,`It means running two factories at once`,`ISO 22000 does not use PDCA`],correctIndex:0,explanation:`ISO 22000:2018 operates an Organizational PDCA cycle (Clauses 4–10) and an Operational HACCP PDCA cycle within Clause 8.`},{q:`In ISO 22000:2018 Clause 8.5, what is the key difference between a CCP (Critical Control Point) and an OPRP (Operational Prerequisite Program)?`,options:[`A CCP uses measurable "Critical Limits" where failure makes the product Potentially Unsafe; an OPRP uses measurable or observable "Action Criteria"`,`An OPRP is only for offices; a CCP is only for warehouses`,`They are 100% identical with no difference`,`OPRPs do not need validation or monitoring`],correctIndex:0,explanation:`CCPs are governed by measurable Critical Limits, whereas OPRPs are governed by measurable or observable Action Criteria.`},{q:`Which Technical Specification in the ISO/TS 22002 series provides the detailed Prerequisite Program (PRP) requirements for Food Manufacturing vs. Catering?`,options:[`ISO/TS 22002-1 for Food Manufacturing; ISO/TS 22002-2 for Catering`,`ISO 9000 for Manufacturing; ISO 19011 for Catering`,`ISO 14001 for both`,`No PRP standards exist`],correctIndex:0,explanation:`ISO/TS 22002-1 covers Food Manufacturing PRPs, while ISO/TS 22002-2 covers Catering PRPs.`},{q:`Under ISO 22000:2018 Clause 5.3, what mandatory leadership role must Top Management appoint to lead the Food Safety Team?`,options:[`The Food Safety Team Leader (FSTL)`,`The Chief Marketing Officer`,`An External Sales Agent`,`No team leader is required`],correctIndex:0,explanation:`Clause 5.3 requires Top Management to appoint a Food Safety Team Leader (FSTL) with defined responsibilities.`},{q:`Under ISO 22000:2018 Clause 8.8 (Verification), can the operator who records the daily CCP monitoring checks also be the person who performs the formal Verification of those records?`,options:[`No — Clause 8.8 requires that verification activities shall NOT be carried out by the person responsible for monitoring the same activities`,`Yes — the same operator can verify and approve their own logs without a supervisor`,`Verification is optional in ISO 22000`,`Only customers can verify logs`],correctIndex:0,explanation:`To ensure impartiality, ISO 22000 Clause 8.8.1 states that verification shall not be carried out by the person responsible for monitoring the same activities.`}]},{id:`cert-2026-fssc-22000-v7-awareness`,code:`FSSC-V7-AW`,title:`FSSC 22000 v7 Awareness Certificate`,levelBadge:`Simple Presentation Course (05 Modules · 35 Slides · 40 MCQs · 60% Pass)`,accreditationStandard:`FSSC 22000 (Version 6 / v7 GFSI Scheme) • Three-Component Architecture & Additional Requirements`,duration:`05 Presentation Modules (35 Slides) + 40-MCQ Final Exam`,certificateFeeRs:1e3,passPercentage:60,distinctionPercentage:75,totalExamQuestions:40,description:`Comprehensive Slide Presentation Course on the FSSC 22000 Food Safety Certification Scheme (including latest v6/v7 GFSI requirements). Covers the 3-Pillar FSSC Architecture (ISO 22000:2018 + ISO/TS 22002 PRPs + FSSC Additional Requirements 2.5.1–2.5.18), Food Defense (TACCP), Food Fraud (VACCP), Allergen Management, Environmental Monitoring, Food Safety & Quality Culture, Equipment Management, Food Loss & Waste, and Unannounced GFSI Audit Rules.`,modules:[{id:`fssc-mod-1`,moduleNumber:1,title:`FSSC 22000 Architecture, GFSI Recognition & Food Chain Categories`,estimatedMinutes:35,overview:`Simple presentation on why FSSC 22000 was created, why ISO 22000 alone is not GFSI-benchmarked, the 3-Component Formula of FSSC 22000, and the Food Chain Categories (C, I, K, F, G).`,internationalClauses:[`FSSC 22000 Scheme Part 1 & Part 2 Overview`],keyPrinciples:[`FSSC 22000 (Food Safety System Certification 22000) is a Global Food Safety Initiative (GFSI) benchmarked certification scheme accepted by major global food brands and retailers.`,`The 3 Components of FSSC 22000 are: (1) ISO 22000:2018 + (2) Sector-Specific PRPs (ISO/TS 22002-x) + (3) FSSC 22000 Additional Requirements (Clause 2.5.1 to 2.5.18).`,`Food Chain Categories include Category C (Food Manufacturing: C0–C4), Category E (Catering), Category F (Trading/Retail), Category G (Transport & Storage), Category I (Food Packaging), and Category K (Bio/Chemicals).`],criticalControlParameters:[{parameter:`The 3-Component Formula of FSSC 22000`,standardLimit:`1) ISO 22000:2018 + 2) Sector ISO/TS 22002 PRP Standard + 3) FSSC Additional Requirements (2.5.1–2.5.18)`,correctiveProtocol:`Audit all three components together during internal and external FSSC 22000 audits.`},{parameter:`Mandatory Unannounced Audit Rule (3-Year Cycle)`,standardLimit:`At least 1 surveillance audit every 3-year certification cycle MUST be completely unannounced`,correctiveProtocol:`Maintain daily audit readiness and a gate reception protocol so unannounced auditors enter within 30 minutes.`}],practicalChecklist:[`Memorize the 3-Component Formula of FSSC 22000.`,`Identify which Food Chain Category (e.g., C1, C2, C3, C4, E, G, I, K) applies to your facility.`,`Understand the 3-year certification cycle and mandatory unannounced surveillance audit rule.`],presentationSlides:[{slideNumber:1,title:`Why Was FSSC 22000 Created?`,subtitle:`Bridging ISO 22000 and Global GFSI Recognition`,bulletPoints:[`Major global food companies (Nestlé, Unilever, PepsiCo, Mondelēz, Coca-Cola, Danone) and retailers require suppliers to hold a GFSI (Global Food Safety Initiative) recognized certificate.`,`Standalone ISO 22000 was not accepted by GFSI on its own because it lacked detailed sector-specific PRP rules and specific GFSI requirements (like Food Fraud, Food Defense, and Logo control).`,`Therefore, the Foundation FSSC created FSSC 22000—making it a fully GFSI-benchmarked scheme built on top of ISO 22000!`],keyTakeaway:`FSSC 22000 gives you both an ISO-based management system AND full GFSI global recognition.`},{slideNumber:2,title:`The 3-Pillar Formula of FSSC 22000`,subtitle:`How the 3 Standards Combine Into One Certification`,bulletPoints:[`Every FSSC 22000 certified site must comply with 3 documents simultaneously:`,`Pillar 1 — ISO 22000:2018: The core Food Safety Management System (Clauses 4 to 10 & HACCP).`,`Pillar 2 — Sector-Specific PRP Standard (ISO/TS 22002 series): e.g., ISO/TS 22002-1 for Food Manufacturing, ISO/TS 22002-2 for Catering, ISO/TS 22002-4 for Packaging, or ISO/TS 22002-5 for Storage/Transport.`,`Pillar 3 — FSSC 22000 Additional Requirements (Part 2, Clauses 2.5.1 to 2.5.18): Mandatory GFSI rules added by Foundation FSSC.`],keyTakeaway:`FSSC 22000 = ISO 22000:2018 + ISO/TS 22002-x (PRPs) + FSSC Additional Requirements (2.5.1–2.5.18).`},{slideNumber:3,title:`FSSC 22000 Food Chain Categories (ISO 22003-1)`,subtitle:`Knowing Which Category Applies to Your Site`,bulletPoints:[`Category C — Food Manufacturing: Divided into C1 (Perishable animal products: meat/dairy/fish), C2 (Perishable plant products: fruits/veg), C3 (Perishable mixed animal & plant ready meals), and C4 (Ambient stable products: biscuits, flour, sugar, oil, beverages, canned goods).`,`Category D — Animal Feed Production.`,`Category E — Catering (Hotels, hospitals, central kitchens, flight catering).`,`Category F — Trading, Wholesale & E-Commerce.`,`Category G — Transport & Cold/Dry Storage Services.`,`Category I — Production of Food Packaging Materials.`,`Category K — Production of Bio/Chemicals (Food additives, vitamins, processing aids).`],keyTakeaway:`Your FSSC 22000 audit scope and ISO/TS 22002 PRP standard depend directly on your Food Chain Category.`},{slideNumber:4,title:`The 3-Year FSSC Audit Cycle & Unannounced Audits`,subtitle:`Initial Certification, Surveillance & Recertification`,bulletPoints:[`Year 1 (Initial Certification): Stage 1 Audit (Document readiness review) + Stage 2 Audit (Full on-site operational audit).`,`Year 2 & Year 3: Annual Surveillance Audits (no more than 12 months apart).`,`Mandatory Unannounced Rule: At least ONE of the two Surveillance Audits in every 3-year cycle MUST be completely unannounced!`,`Year 4: Full Recertification Audit before the 3-year certificate expires.`],keyTakeaway:`In every 3-year FSSC 22000 cycle, at least one surveillance audit happens completely unannounced.`},{slideNumber:5,title:`Overview of FSSC Additional Requirements (Clauses 2.5.1 to 2.5.18)`,subtitle:`The 18 Extra Topics Every FSSC Site Must Implement`,bulletPoints:[`2.5.1 Management of Services & Purchased Materials | 2.5.2 Product Labeling & Printed Materials`,`2.5.3 Food Defense (TACCP) | 2.5.4 Food Fraud Mitigation (VACCP)`,`2.5.5 Logo Use | 2.5.6 Management of Allergens`,`2.5.7 Environmental Monitoring | 2.5.8 Food Safety and Quality Culture`,`2.5.9 Quality Control | 2.5.10 Transport, Storage & Warehousing`,`2.5.11 Hazard Control & Cross-Contamination | 2.5.12 PRP Verification`,`2.5.13 Product Design & Development | 2.5.14 Health Status (Feed) | 2.5.15 Equipment Management | 2.5.16 Food Loss and Waste | 2.5.17 Communication Requirements | 2.5.18 Multi-Site.`],keyTakeaway:`Modules 2, 3, and 4 break down each of these FSSC Additional Requirements in simple, practical detail.`}]},{id:`fssc-mod-2`,moduleNumber:2,title:`Sector PRPs (ISO/TS 22002-1) & FSSC Clauses 2.5.1 (Services/Materials) and 2.5.2 (Labeling)`,estimatedMinutes:35,overview:`Simple presentation on ISO/TS 22002-1 Prerequisite Programs and the first two FSSC Additional Requirements: 2.5.1 Management of Services & Purchased Materials (ISO 17025 Labs, Emergency Procurement, Recycled Packaging) and 2.5.2 Product Labeling & Artwork Control.`,internationalClauses:[`ISO/TS 22002-1 & FSSC Part 2 Clauses 2.5.1 and 2.5.2`],keyPrinciples:[`ISO/TS 22002-1 defines strict factory PRP standards for site perimeter, internal layout, utilities (potable water, filtered air, food-grade boiler steam), waste, equipment, maintenance, purchasing, cross-contamination, cleaning, pest control, and personal hygiene.`,`FSSC Clause 2.5.1 requires using ISO/IEC 17025 accredited laboratories (or proficiency-tested labs) for food safety testing, documenting an Emergency Procurement procedure, and verifying food-safety compliance of recycled packaging.`,`FSSC Clause 2.5.2 requires product labels to comply with all legal and allergen rules in the country of intended sale, plus strict artwork approval and packing line-clearance procedures.`],criticalControlParameters:[{parameter:`Laboratory Competence Requirement (FSSC Clause 2.5.1 a)`,standardLimit:`External/internal labs used for food safety verification must hold ISO/IEC 17025 accreditation or participate in proficiency testing`,correctiveProtocol:`Keep copies of external lab ISO 17025 accreditation scopes on file before sending pathogen/chemical samples.`},{parameter:`Product Labeling & Artwork Line-Clearance (FSSC Clause 2.5.2)`,standardLimit:`Labels verified against country-of-sale allergen/legal laws; signed line-clearance before and after every packing run`,correctiveProtocol:`Remove 100% of previous batch labels/film from the packing line before starting a changeover.`}],practicalChecklist:[`Verify that external laboratories hold valid ISO/IEC 17025 certificates covering the exact tests they perform for you.`,`Check that a documented Emergency Supplier Procurement procedure is in place (Clause 2.5.1).`,`Audit packing lines to confirm signed Label Verification & Line-Clearance checks are completed on every batch (Clause 2.5.2).`],presentationSlides:[{slideNumber:1,title:`Key Highlights of ISO/TS 22002-1 (Manufacturing PRPs)`,subtitle:`Utilities, Air, Water, Steam & Cross-Contamination`,bulletPoints:[`Water & Ice: Potable drinking water quality tested regularly; non-potable water pipes (fire/cooling) must be clearly color-coded with zero cross-connection to potable water.`,`Boiler Chemicals & Culinary Steam: If steam touches food directly, boiler water additives must be approved food-grade chemicals.`,`Compressed Air & Gases: Filtered to remove oil, water, and microbes (using oil-free compressors and micron filters at point of use).`,` Pest Control: Electric Fly Killers (EFKs) must be sticky glue-board units (high-voltage zappers that shatter insects are prohibited in food zones) placed > 3 meters away from open food.`],keyTakeaway:`High-voltage electric "zapper" fly killers are banned over food areas in ISO/TS 22002-1—always use sticky glue-board UV units.`},{slideNumber:2,title:`FSSC 2.5.1: Management of Services & Purchased Materials`,subtitle:`Lab Accreditation, Emergency Buying & Animal Slaughter Inspection`,bulletPoints:[`Lab Testing Competence (2.5.1 a): Where lab analysis is used for food safety verification/validation, it must be conducted by an ISO/IEC 17025 accredited lab (or a lab participating in proficiency testing programs).`,`Emergency Procurement (2.5.1 b): You must have a documented procedure for purchasing raw materials/packaging in emergency situations to ensure products still meet specifications and supplier evaluation happens before use.`,`Recycled Packaging: Verify legal/food-grade safety when recycled paper/plastic is used in food packaging.`],keyTakeaway:`Always keep your external laboratory’s ISO/IEC 17025 scope certificate in your FSSC audit folder.`},{slideNumber:3,title:`FSSC 2.5.2: Product Labeling & Printed Materials`,subtitle:`Complying With Country-of-Sale Laws & Stopping Label Mix-Ups`,bulletPoints:[`Country of Intended Sale (2.5.2 a): Finished products must be labeled according to all statutory and regulatory requirements (especially Allergen & Nutrition labeling) in the destination country where the product will be sold!`,`Unlabeled Bulk Products: If you ship bulk tankers or unprinted industrial bags, provide the allergen and legal specification sheet directly to the customer.`,`Artwork & Line-Clearance Procedure: Implement a strict procedure for approving new label artwork, destroying obsolete labels, and performing signed Line-Clearance checks on the packing line (including barcode/vision scanner checks).`],keyTakeaway:`If you export to the UK, EU, GCC, or USA, your label must comply with the exact allergen laws of that destination country.`},{slideNumber:4,title:`FSSC 2.5.5: FSSC 22000 Logo Use Rules`,subtitle:`Where You CAN and CANNOT Put the FSSC 22000 Logo`,bulletPoints:[`Certified companies are allowed to use the FSSC 22000 Logo on marketing brochures, websites, business cards, and letterheads.`,`STRICT PROHIBITION: You must NEVER print the FSSC 22000 Logo (or state FSSC certification) directly on a food product label, primary packaging, or secondary retail box!`,`Why? Because FSSC 22000 certifies your Management System, not the individual food pack—putting the logo on a product pack misleads consumers.`],keyTakeaway:`Never print the FSSC 22000 logo on a product pack or label—doing so is an immediate audit non-conformity!`}]},{id:`fssc-mod-3`,moduleNumber:3,title:`FSSC Clauses 2.5.3 (Food Defense), 2.5.4 (Food Fraud), 2.5.6 (Allergens) & 2.5.7 (Environmental Monitoring)`,estimatedMinutes:40,overview:`Simple presentation on the four high-priority risk clauses of FSSC 22000: Food Defense / TACCP (2.5.3), Food Fraud Mitigation / VACCP (2.5.4), Management of Allergens (2.5.6), and Environmental Monitoring / EMP (2.5.7).`,internationalClauses:[`FSSC 22000 Part 2 Clauses 2.5.3, 2.5.4, 2.5.6, and 2.5.7`],keyPrinciples:[`Clause 2.5.3 (Food Defense / TACCP) requires a documented Threat Assessment to identify potential intentional sabotage threats and a Food Defense Plan inside the FSMS.`,`Clause 2.5.4 (Food Fraud / VACCP) requires a documented Vulnerability Assessment for all raw materials/packaging to identify economically motivated adulteration risks and a Food Fraud Mitigation Plan.`,`Clause 2.5.6 (Management of Allergens) requires a list of all allergens handled on site, risk assessment of cross-contact, control measures (segregation/cleaning/labeling), and annual validation/verification.`,`Clause 2.5.7 (Environmental Monitoring) requires a risk-based pathogen/spoilage swabbing program across Zones 1 to 4 to verify cleaning effectiveness.`],criticalControlParameters:[{parameter:`Food Defense (2.5.3) & Food Fraud (2.5.4) Plans`,standardLimit:`Documented Threat Assessment (TACCP) + Vulnerability Assessment (VACCP) covering 100% of raw materials/site areas, reviewed annually`,correctiveProtocol:`Update TACCP and VACCP plans immediately whenever a new raw material, supplier, or emerging fraud/security alert occurs.`},{parameter:`Allergen Management & Validation (FSSC Clause 2.5.6)`,standardLimit:`Site allergen list + cross-contact risk assessment + validated cleaning + precautionary ("May contain") labeling only if scientifically justified`,correctiveProtocol:`Train all personnel in allergen awareness at least annually and retain training records.`}],practicalChecklist:[`Check that both the Food Defense Plan (2.5.3) and Food Fraud Mitigation Plan (2.5.4) have been reviewed within the last 12 months.`,`Verify that all raw materials AND food-contact packaging are included in the VACCP Food Fraud Vulnerability Assessment.`,`Confirm that the Allergen Management Plan (2.5.6) and Zone 1–4 Environmental Monitoring Program (2.5.7) are active and reviewed annually.`],presentationSlides:[{slideNumber:1,title:`FSSC 2.5.3: Food Defense (TACCP)`,subtitle:`Two-Step Requirement: Threat Assessment + Food Defense Plan`,bulletPoints:[`Step A — Threat Assessment: Conduct and document a Food Defense Threat Assessment using a defined methodology (like TACCP or CARVER+Shock) to identify and evaluate potential intentional threats (sabotage, tampering, cyber-attack, disgruntled insider, external intruder).`,`Step B — Food Defense Plan: For all significant threats identified, specify and implement mitigation measures (CCTV, keycard access, locked chemical/water tanks, tamper-evident tanker seals).`,`The Food Defense Plan must be supported by the FSMS, comply with legislation, and be kept up to date.`],keyTakeaway:`Clause 2.5.3 requires BOTH a documented Threat Assessment AND an active Food Defense Plan integrated into your FSMS.`},{slideNumber:2,title:`FSSC 2.5.4: Food Fraud Mitigation (VACCP)`,subtitle:`Two-Step Requirement: Vulnerability Assessment + Mitigation Plan`,bulletPoints:[`Step A — Vulnerability Assessment: Conduct and document a Food Fraud Vulnerability Assessment (using SSAFE or PAS 96) to identify potential vulnerabilities for Economically Motivated Adulteration (EMA), substitution, dilution, counterfeit, or mislabeling.`,`Crucial Note: Your VACCP assessment must cover ALL raw materials, ingredients, AND primary food-contact packaging!`,`Step B — Food Fraud Mitigation Plan: Implement control measures (approved manufacturer sourcing, COA authenticity testing, mass-balance checks) for all significant vulnerabilities.`],keyTakeaway:`Do not forget to include food-contact packaging materials in your Clause 2.5.4 Food Fraud Vulnerability Assessment!`},{slideNumber:3,title:`FSSC 2.5.6: Management of Allergens`,subtitle:`Strict Rules in FSSC v6/v7 for Allergen Control`,bulletPoints:[`Maintain a documented list of all allergens handled on site (including raw materials, processing aids, and finished products).`,`Conduct a Risk Assessment covering all potential sources of allergen cross-contact.`,`Implement control measures to reduce or eliminate cross-contact (segregated storage, dedicated Purple tools, production scheduling, and validated allergen cleaning).`,`Precautionary Allergen Labeling ("May contain traces of..."): Can ONLY be used if a thorough risk assessment proves cross-contact cannot be eliminated despite full GMPs—it must NEVER be used as an excuse for poor cleaning!`],keyTakeaway:`Under FSSC 2.5.6, all personnel must receive Allergen Awareness Training, and the Allergen Plan must be reviewed at least annually.`},{slideNumber:4,title:`FSSC 2.5.7: Environmental Monitoring Program (EMP)`,subtitle:`Risk-Based Pathogen & Spoilage Swabbing`,bulletPoints:[`Implement a risk-based Environmental Monitoring Program (Zones 1 to 4) for relevant pathogens (e.g., Listeria spp. / L. monocytogenes in wet/chilled plants; Salmonella in dry plants) and spoilage/indicator organisms (Enterobacteriaceae, Total Plate Count, Yeasts/Molds).`,`Document a written EMP procedure defining: Target organisms, sample locations (mapped on floor plan), swabbing frequency, lab methods, action limits, and mandatory corrective action when a positive or upward trend is found.`,`Review the EMP at least annually and whenever new equipment, building works, or positive results occur.`],keyTakeaway:`Building renovations or roof leaks inside a factory are major triggers to increase Environmental Monitoring swabs immediately.`}]},{id:`fssc-mod-4`,moduleNumber:4,title:`FSSC Clauses 2.5.8 to 2.5.16: Culture, Quality Control, Equipment & Food Loss/Waste`,estimatedMinutes:40,overview:`Simple presentation on the newer FSSC v6/v7 Additional Requirements: Food Safety & Quality Culture (2.5.8), Quality Control & Legal Weight/Volume (2.5.9), Transport & Tanker Cleaning (2.5.10), Cross-Contamination & Foreign Body Controls (2.5.11), Equipment Management (2.5.15), and Food Loss & Waste (2.5.16).`,internationalClauses:[`FSSC 22000 Part 2 Clauses 2.5.8, 2.5.9, 2.5.10, 2.5.11, 2.5.12, 2.5.13, 2.5.15, and 2.5.16`],keyPrinciples:[`Clause 2.5.8 (Food Safety and Quality Culture) requires a documented Culture Plan with measurable objectives, timelines, and employee feedback covering communication, training, behavioral measurement, and management review.`,`Clause 2.5.9 (Quality Control) embeds systematic quality parameters, start-up/line-changeover checks, and legal net weight/volume control directly into the FSSC audit.`,`Clause 2.5.15 (Equipment Management) requires hygienic design specifications BEFORE buying new equipment and a risk-based Change Management process for commissioning.`,`Clause 2.5.16 (Food Loss and Waste) requires a documented policy and measurable objectives to reduce food waste, safely manage charity donations, and prevent diversion of unsafe waste into the food chain.`],criticalControlParameters:[{parameter:`Food Safety & Quality Culture Plan (FSSC Clause 2.5.8)`,standardLimit:`Documented Culture Plan with measurable targets, timelines, staff survey/feedback, training, and Management Review evaluation`,correctiveProtocol:`Ensure the Culture Plan addresses both Food Safety AND Quality across all departments.`},{parameter:`Hygienic Equipment Specification & Commissioning (FSSC Clause 2.5.15)`,standardLimit:`Written hygienic design specification prepared BEFORE purchasing new equipment + supplier proof + commissioning validation`,correctiveProtocol:`Never install a new food machine without a pre-purchase hygienic specification and QA commissioning sign-off.`}],practicalChecklist:[`Verify that your site has a documented Food Safety & Quality Culture Plan with measurable targets and timelines (Clause 2.5.8).`,`Check that Net Weight / Volume metrological checks and startup quality checks are logged under Clause 2.5.9.`,`Confirm that Equipment Hygienic Specifications (2.5.15) and Food Loss & Waste targets (2.5.16) are documented.`],presentationSlides:[{slideNumber:1,title:`FSSC 2.5.8: Food Safety and Quality Culture`,subtitle:`Mandatory Written Culture Plan with Objectives & Timelines`,bulletPoints:[`Under FSSC v6/v7 Clause 2.5.8, top management must establish, implement, and maintain a Food Safety and Quality Culture Objective(s) as part of the management system.`,`Your documented Food Safety & Quality Culture Plan must address 4 core elements:`,`• Communication (open reporting, safety briefings, suggestion boxes).`,`• Training (coaching, culture workshops).`,`• Employee Feedback and Engagement (anonymous culture surveys, floor walks).`,`• Performance Measurement of defined activities covering all sections of the organization, supported by timelines and reviewed in Management Review.`],keyTakeaway:`Clause 2.5.8 requires a written Culture Plan with timelines and measurable objectives—not just a poster on the wall.`},{slideNumber:2,title:`FSSC 2.5.9: Quality Control & Legal Weight/Volume Checks`,subtitle:`Integrating Quality Parameters Into Your FSSC Audit`,bulletPoints:[`FSSC v6/v7 expanded the scheme to include Quality Control (Clause 2.5.9):`,`• Establish a Quality Policy and measurable Quality Objectives alongside Food Safety.`,`• Define, monitor, and record Quality Parameters (Brix, pH, color, viscosity, bake profile, sensory) in line with finished product specifications.`,`• Legal Metrology (Net Weight & Volume Control): Implement a procedure to verify that pack weights/volumes meet legal label declarations using calibrated checkweighers or statistical weight logs.`,`• Perform and record Line Start-Up and Line Changeover checks.`],keyTakeaway:`FSSC auditors now inspect your Net Weight / Volume logs and Quality Control checks under Clause 2.5.9!`},{slideNumber:3,title:`FSSC 2.5.10, 2.5.11 & 2.5.12: Tankers, Foreign Bodies & PRP Inspections`,subtitle:`Strengthened Operational Controls on the Floor`,bulletPoints:[`Clause 2.5.10 (Transport, Storage & Bulk Tankers): When receiving or shipping in bulk tankers, verify tanker cleaning certificates (prior load restriction + CIP wash certificate) and prevents cross-contamination.`,`Clause 2.5.11 (Foreign Matter & Cross-Contamination): Conduct a documented risk assessment to determine the need for magnets, metal detectors, X-ray equipment, filters, and sieves.`,`Clause 2.5.12 (PRP Verification): Conduct routine (e.g., monthly) site hygiene and PRP inspections to verify that building, equipment, and personal hygiene standards are maintained.`],keyTakeaway:`Never unload a bulk liquid tanker without first checking its Previous Load History and Validated Tanker Wash Certificate.`},{slideNumber:4,title:`FSSC 2.5.13 & 2.5.15: Product Design & Hygienic Equipment Management`,subtitle:`Designing Out Risks Before Buying or Launching`,bulletPoints:[`Clause 2.5.13 (Product Design & Development): For any new product or recipe modification, validate shelf life, safe cooking instructions, and impact on existing allergen/process lines (including ongoing shelf-life verification during commercial life).`,`Clause 2.5.15 (Equipment Management):`,`• Before purchasing new equipment, write a Hygienic Design Specification covering hygienic materials, cleanability, and legal rules.`,`• Obtain written evidence from the equipment manufacturer that the machine meets your specification BEFORE installation.`,`• Execute a risk-based commissioning and change-management sign-off before running commercial food.`],keyTakeaway:`Under Clause 2.5.15, you must write a Hygienic Design Specification BEFORE buying any new food processing equipment.`},{slideNumber:5,title:`FSSC 2.5.16: Food Loss and Waste`,subtitle:`Sustainability + Safe Charity Donation Rules`,bulletPoints:[`Aligned with UN Sustainable Development Goals, Clause 2.5.16 requires:`,`• A documented Policy and measurable Objectives outlining the organization’s strategy to reduce Food Loss and Waste inside the facility and supply chain.`,`• Safe Donation Controls: Any surplus food donated to charities/food banks must be stored, handled, and tracked safely so it remains 100% wholesome.`,`• By-Products & Animal Feed: Surplus food sent for animal feed must be protected from contamination and never diverted illegally back into human food.`],keyTakeaway:`Track monthly food waste %, set a reduction target, and ensure any charity food donations meet full cold-chain and safety rules.`}]},{id:`fssc-mod-5`,moduleNumber:5,title:`FSSC Clause 2.5.17 (CB Communication), Nonconformity Grading & Audit Readiness`,estimatedMinutes:35,overview:`Simple presentation on FSSC Clause 2.5.17 (3-Working-Day Mandatory Notification to the Certification Body), how FSSC grades Minor, Major, and Critical Nonconformities, the strict 28-Day CAPA Closure Deadline, and passing your FSSC audit.`,internationalClauses:[`FSSC 22000 Part 2 Clause 2.5.17 & Part 3 Audit Nonconformity Rules`],keyPrinciples:[`FSSC Clause 2.5.17 requires notifying your Certification Body (CB) within 3 working days of any serious event (public recall, regulatory action, outbreak, disaster, or fraud/legal investigation).`,`FSSC Audit Nonconformities are graded as Minor, Major, or Critical.`,`Under FSSC 22000 rules, for both Minor and Major Nonconformities, the certified site MUST submit objective evidence of Correction, Root Cause Analysis, and Corrective Action Plan within ≤ 28 calendar days of the last day of the audit!`,`Failing to close a Major Nonconformity within 28 calendar days results in immediate suspension of the FSSC 22000 certificate.`],criticalControlParameters:[{parameter:`3-Working-Day Certification Body Notification Rule (Clause 2.5.17)`,standardLimit:`Notify the Certification Body within ≤ 3 working days of any serious event, recall, regulatory enforcement, or disaster`,correctiveProtocol:`Include the Certification Body email/phone on the Crisis Management Team emergency contact sheet.`},{parameter:`28-Calendar-Day Audit Nonconformity Closure Rule`,standardLimit:`All Minor and Major audit nonconformities closed with Correction + RCA + CAPA evidence within ≤ 28 calendar days`,correctiveProtocol:`Submit CAPA evidence to the auditor by Day 20 so there is time for auditor review before Day 28.`}],practicalChecklist:[`Add the 3-Working-Day Certification Body notification requirement (Clause 2.5.17) into your Crisis & Recall SOP.`,`Memorize the strict 28-Calendar-Day deadline for closing Minor and Major FSSC audit findings.`,`Complete all 5 modules and take the 40-MCQ FSSC 22000 v7 Awareness Final Exam.`],presentationSlides:[{slideNumber:1,title:`FSSC 2.5.17: Communication Requirements With Your Certification Body`,subtitle:`The Mandatory 3-Working-Day Notification Rule`,bulletPoints:[`Under Clause 2.5.17, the organization MUST inform its Certification Body (e.g., SGS, Bureau Veritas, DNV, Intertek, LRQA) within 3 WORKING DAYS of the commencement of any serious event that impacts the FSMS, legality, or integrity of certification:`,`• Public food safety recalls or withdrawals.`,`• Regulatory enforcement notices, fines, or legal proceedings regarding food safety.`,`• Natural or man-made disasters (fires, floods, cyber-attacks, wars) halting safe production.`,`• Serious situations where the integrity of FSSC certification is at risk (food fraud or outbreak).`],keyTakeaway:`Memorize the number: 3 Working Days to notify your Certification Body of any recall, regulatory notice, or serious crisis!`},{slideNumber:2,title:`How FSSC 22000 Grades Audit Nonconformities`,subtitle:`Minor vs. Major vs. Critical Findings`,bulletPoints:[`Minor Nonconformity: Does not affect the capability of the management system to achieve intended food safety outcomes (e.g., an isolated documentation gap).`,`Major Nonconformity: Negatively affects the capability of the management system to achieve intended outcomes (e.g., missing validation of a CCP, uncalibrated CCP probes, or failure to follow an allergen changeover SOP).`,`Critical Nonconformity: Direct food safety impact occurs without proper action by the organization, OR when legality/certification integrity is at stake (e.g., falsified CCP logs or shipping contaminated product).`],keyTakeaway:`FSSC 22000 does NOT issue "Observations" or "Opportunities for Improvement (OFIs)" as soft substitutes for real nonconformities.`},{slideNumber:3,title:`The Strict 28-Calendar-Day Closure Rule in FSSC 22000`,subtitle:`Missing This Deadline Suspends Your Certificate!`,bulletPoints:[`FSSC 22000 has one of the strictest audit closure timelines in the world:`,`• For a MINOR Nonconformity: Submit objective evidence of Correction, Root Cause Analysis (RCA), and a Corrective Action Plan (CAPA) for auditor approval within 28 CALENDAR DAYS of the last day of the audit.`,`• For a MAJOR Nonconformity: Submit full Correction, RCA, and objective evidence of implemented CAPA within 28 CALENDAR DAYS (failure to close a Major NC by Day 28 results in immediate Certificate Suspension!).`,`• For a CRITICAL Nonconformity: The certificate is suspended immediately (for up to 6 months) and a follow-up on-site audit is required.`],keyTakeaway:`Remember: 28 Calendar Days is the absolute deadline to close Minor and Major nonconformities in FSSC 22000!`},{slideNumber:4,title:`Complete FSSC 22000 Audit Readiness Summary`,subtitle:`Final Checklist & Course Completion`,bulletPoints:[`You have completed all 5 Modules of the FSSC 22000 v7 Awareness Certificate:`,`• 3-Component Formula: ISO 22000:2018 + ISO/TS 22002-x + FSSC Additional Requirements (2.5.1–2.5.18).`,`• Core GFSI Pillars: TACCP (2.5.3), VACCP (2.5.4), Allergens (2.5.6), Environmental Monitoring (2.5.7), Culture (2.5.8), Quality Control (2.5.9), Equipment Management (2.5.15), and Food Waste (2.5.16).`,`• Key Timelines: 1 Unannounced Audit per 3-year cycle, 3 Working Days CB notification, and 28 Calendar Days NC closure.`],keyTakeaway:`Click below to start the 40-MCQ FSSC 22000 v7 Awareness Final Exam (60% passing score = 24/40 correct)!`}]}],coreExamPool:[{q:`What are the 3 mandatory components that make up the FSSC 22000 certification scheme?`,options:[`1) ISO 22000:2018 + 2) Sector-Specific PRPs (ISO/TS 22002 series) + 3) FSSC 22000 Additional Requirements (Clauses 2.5.1–2.5.18)`,`Only a local municipal trade license`,`Only ISO 9001 and ISO 14001`,`Only a financial balance sheet`],correctIndex:0,explanation:`FSSC 22000 is built on three pillars: ISO 22000:2018, the relevant ISO/TS 22002 PRP standard, and the FSSC 22000 Additional Requirements.`},{q:`Under FSSC 22000 rules, how often must a certified site undergo a mandatory Unannounced Surveillance Audit?`,options:[`At least once in every 3-year certification cycle`,`Once every 20 years`,`Never — all FSSC audits are announced`,`Every week`],correctIndex:0,explanation:`FSSC 22000 requires at least one surveillance audit in every 3-year certification cycle to be conducted unannounced.`},{q:`Under FSSC 22000 Additional Requirement 2.5.5 (Logo Use), is a certified food manufacturer allowed to print the FSSC 22000 logo directly on its retail food packaging or product label?`,options:[`No — the FSSC 22000 logo must NEVER be printed on a product label or retail packaging (as it certifies the management system, not the individual product)`,`Yes — it must be printed on the front of every biscuit packet`,`Yes — if printed in red ink`,`Logo use is not regulated`],correctIndex:0,explanation:`FSSC Clause 2.5.5 strictly prohibits using the FSSC 22000 logo on products, product labels, or primary/secondary retail packaging.`},{q:`Under FSSC 22000 Clause 2.5.17 (Communication Requirements), within how many days must a certified organization notify its Certification Body of a product recall, regulatory action, or serious crisis?`,options:[`Within 3 working days`,`Within 90 days`,`Within 1 year`,`Notification is not required`],correctIndex:0,explanation:`FSSC Clause 2.5.17 requires notifying the Certification Body within 3 working days of any serious event or recall.`},{q:`What is the strict maximum deadline to submit Correction, Root Cause Analysis, and Corrective Action evidence to close a Minor or Major Nonconformity raised during an FSSC 22000 audit?`,options:[`Within 28 calendar days from the last day of the audit`,`Within 6 months`,`Within 12 months`,`No deadline applies`],correctIndex:0,explanation:`Under FSSC 22000 rules, all Minor and Major nonconformities must be closed within 28 calendar days from the last day of the audit, or the certificate is suspended.`},{q:`Which new FSSC Additional Requirements were introduced/expanded in FSSC 22000 v6/v7 under Clauses 2.5.8, 2.5.9, 2.5.15, and 2.5.16?`,options:[`Food Safety & Quality Culture (2.5.8), Quality Control & Legal Weight/Volume (2.5.9), Hygienic Equipment Management (2.5.15), and Food Loss & Waste (2.5.16)`,`Social Media Advertising and Office Interior Design`,`Vehicle Car Wash and Parking Lot Striping`,`None of the above`],correctIndex:0,explanation:`Clauses 2.5.8 (Culture), 2.5.9 (Quality Control), 2.5.15 (Equipment Management), and 2.5.16 (Food Loss & Waste) are core FSSC Additional Requirements.`}]}],m=p.map(t),h=[e({id:`cert-2026-brcgs-issue-09-awareness`,code:`BRCGS-I9-AW`,title:`BRCGS Food Safety Issue 09 Awareness Certificate`,subtitle:`Global Standard for Food Safety Issue 9 — Product Safety Culture, HACCP, Site Standards & Audit Readiness`,category:`International Certification`,level:`Professional`,durationHours:24,totalModules:5,examQuestionsCount:40,passingScorePercent:60,certificateTitle:`Certified BRCGS Food Safety Issue 09 Awareness Professional`,accreditationStandard:`BRCGS Global Standard for Food Safety Issue 09 / GFSI Benchmark`,targetAudience:[`Food Quality Managers`,`Production & Warehouse Supervisors`,`Internal Auditors`,`Packaging & Processing Teams`],overview:`A clear, practical 05-Module slide presentation training covering all 9 sections of BRCGS Food Safety Issue 09, Fundamental Clauses, Product Safety Culture, High-Risk/High-Care Zoning, Foreign Body Prevention, and Unannounced Audit Readiness.`,learningOutcomes:[`Understand the 9 Sections and 12 Fundamental Clauses of BRCGS Food Safety Issue 09`,`Implement the BRCGS Product Safety Culture Plan and Senior Management Commitment`,`Manage Production Risk Zones (High-Risk, High-Care, Ambient High-Care, Low-Risk)`,`Control Labelling, Pack Verification, Foreign Body Detection, and Traceability within 4 hours`,`Prepare the site for Announced, Blended, and Mandatory Unannounced BRCGS Audits`],modules:[{moduleNumber:1,title:`Module 01: Introduction to BRCGS Issue 09 & Fundamental Clauses`,estimatedMinutes:60,learningObjectives:[`Explain the structure of BRCGS Food Safety Issue 09`,`Identify the 12 Fundamental Clauses where major failure blocks certification`,`Build a compliant Product Safety Culture Action Plan`],summary:`Covers the structure of BRCGS Issue 09, GFSI benchmarking, the 12 Fundamental Clauses, and Clause 1.1.2 Food Safety & Quality Culture.`,keyTakeaways:[`BRCGS Issue 09 contains 9 Core Sections and 12 Fundamental Clauses.`,`Failure of a Fundamental Clause results in non-certification or immediate suspension.`,`Clause 1.1.2 requires a multi-year Product Safety Culture Plan reviewed annually.`],practiceScenario:`An auditor asks how your factory measures Food Safety Culture under Clause 1.1.2. You present employee survey results, near-miss reporting metrics, and behavior walk-through records.`,presentationSlides:[{slideNumber:1,title:`What is BRCGS Food Safety Issue 09?`,subtitle:`Module 01 • Global Retail & Brand Recognition`,bullets:[`BRCGS stands for Brand Reputation through Compliance Global Standards.`,`Issue 09 (published August 2022, audits started February 2023) is GFSI-benchmarked.`,`Required by major global retailers, fast-food chains, and foodservice brands worldwide.`,`Focuses on product safety, authenticity, legality, and quality.`],Example:`A sauce manufacturer holding BRCGS Issue 09 Grade AA+ can supply international supermarket chains without separate retailer audits.`,keyPoint:`BRCGS Issue 09 covers four pillars: Food Safety, Product Authenticity, Legality, and Quality.`},{slideNumber:2,title:`The 9 Core Sections of BRCGS Issue 09`,subtitle:`Module 01 • Standard Architecture`,bullets:[`Section 1: Senior Management Commitment & Product Safety Culture.`,`Section 2: The Food Safety Plan — HACCP (based on Codex Alimentarius).`,`Section 3: Food Safety & Quality Management System (Document Control, Traceability, VACCP/TACCP).`,`Section 4: Site Standards (Layout, Hygiene, Maintenance, Pest Management, Foreign Body Control).`,`Sections 5 to 9: Product Control, Process Control, Personnel, Production Risk Zones, and Traded Products.`],Example:`If a site buys finished products strictly for resale without processing them, Section 9 (Traded Products) applies.`,keyPoint:`Sections 1 to 7 apply to all manufacturing sites; Sections 8 and 9 apply based on specific risk zones or traded goods.`},{slideNumber:3,title:`The 12 Fundamental Clauses Explained`,subtitle:`Module 01 • Zero-Tolerance Foundation`,bullets:[`BRCGS designates 12 clauses as "Fundamental" marked with a star icon in the standard.`,`Includes: Senior Management Commitment (1.1), HACCP (2), Internal Audits (3.4), Supplier Approval (3.5.1), Corrective Actions (3.7), Traceability (3.9).`,`Also includes: Layout & Product Flow (4.3), Housekeeping & Hygiene (4.11), Allergen Management (5.3), Control of Operations (6.1), Labelling & Pack Control (6.2), Training (7.1).`,`A Critical or Major non-conformity against a Fundamental Clause prevents certification.`],Example:`Failure to verify label changes on a packing line violates Fundamental Clause 6.2 (Labelling and Pack Control).`,keyPoint:`All 12 Fundamental Clauses must be continuously maintained every day on the shop floor.`},{slideNumber:4,title:`Clause 1.1.2: Product Safety & Quality Culture`,subtitle:`Module 01 • Key Update in Issue 09`,bullets:[`Senior management must define and maintain a clear plan for developing product safety culture.`,`The plan must cover all sections of the site that impact product safety.`,`Activities must include clear communication, training, employee feedback, and behavior measurement.`,`Senior management must review the effectiveness of culture activities at least annually.`],Example:`Holding monthly "Quality Champions" huddles and anonymous food safety suggestion boxes with visible management action.`,keyPoint:`Product safety culture in Issue 09 focuses on observable behaviours, not just posters on walls.`},{slideNumber:5,title:`Management Review & Resource Allocation (Clause 1.1)`,subtitle:`Module 01 • Leadership Accountability`,bullets:[`The most senior operational manager on site must attend the opening and closing BRCGS audit meetings.`,`Management Review meetings must be held at least annually to evaluate objectives, complaints, recalls, and audit results.`,`Site management must provide adequate financial, technical, and staffing resources.`,`There must be a clear organizational chart showing deputies for all key food safety roles.`],Example:`When the QA Manager is on leave, a trained Deputy QA Manager is formally designated to sign off product release.`,keyPoint:`Every key food safety position must have a documented, competent deputy.`}],sections:[],quiz:[]},{moduleNumber:2,title:`Module 02: Food Safety Plan (HACCP) & Management System (Sections 2 & 3)`,estimatedMinutes:60,learningObjectives:[`Align the HACCP plan with Section 2 of BRCGS Issue 09`,`Execute Internal Audits across at least 4 different audit dates per year`,`Complete vertical and horizontal traceability tests within 4 hours`],summary:`Explains Section 2 (Codex HACCP requirements in BRCGS) and Section 3 (Internal Audits, Supplier Approval, VACCP Food Fraud, TACCP Food Defence, Traceability, and Recall).`,keyTakeaways:[`Internal audits must be scheduled throughout the year (at least 4 different audit dates).`,`Traceability tests (forward and backward + mass balance) must be completed within 4 hours.`,`Significant food safety incidents or regulatory notices must be reported to the Certification Body within 3 working days.`],practiceScenario:`During an audit, the auditor picks a retail pack of biscuits from the warehouse and starts a stopwatch. Your team must trace all raw material batches, packaging reels, processing records, and customer shipments within 4 hours.`,presentationSlides:[{slideNumber:1,title:`Section 2: The Food Safety Plan (HACCP)`,subtitle:`Module 02 • Codex Alimentarius Alignment`,bullets:[`BRCGS Section 2 follows the 12 Codex HACCP steps (5 preliminary steps + 7 principles).`,`The HACCP team leader must have in-depth HACCP training and demonstrate competence.`,`Prerequisite programs (PRPs), process flow diagrams, hazard analysis, and CCPs must be verified at least annually.`,`Any change in raw materials, recipe, equipment, or packaging triggers a HACCP review before launch.`],Example:`Installing a new high-speed pouch filler requires verifying the heat-sealing CCP and updating the flow diagram on site.`,keyPoint:`Process flow diagrams must be verified by walking the actual production line at least once a year.`},{slideNumber:2,title:`Internal Audits & Hygiene Inspections (Clause 3.4)`,subtitle:`Module 02 • Year-Round Verification`,bullets:[`Internal audits must be spread across the year on at least 4 separate audit dates (not all done in one month).`,`Every clause of the BRCGS standard and all production activities must be audited at least once a year.`,`Auditors must be trained and independent of the area being audited.`,`Separate monthly Fabrication & Hygiene inspections must check walls, floors, drains, and equipment condition.`],Example:`Creating an annual audit programme covering Q1 (Sections 1-2), Q2 (Sections 3-4), Q3 (Sections 5-6), and Q4 (Sections 7-8).`,keyPoint:`Auditing the entire standard in the week before the external BRCGS audit is a non-conformity.`},{slideNumber:3,title:`Supplier Approval & Raw Material Authenticity (Clause 3.5)`,subtitle:`Module 02 • VACCP & Supply Chain Control`,bullets:[`Every raw material and primary packaging supplier must undergo risk assessment and formal approval.`,`Approved suppliers hold GFSI-benchmarked certificates or undergo supplier audits/questionnaires.`,`Vulnerability Assessment (VACCP) identifies raw materials at risk of economic adulteration, substitution, or fraud.`,`When buying through brokers or agents, the site must still know the identity of the actual manufacturer/processor.`],Example:`Knowing both the broker name and the actual manufacturing mill for imported cocoa powder or spices.`,keyPoint:`Buying from a broker without knowing the actual manufacturer of the ingredient violates BRCGS Clause 3.5.`},{slideNumber:4,title:`Traceability within 4 Hours & Mass Balance (Clause 3.9)`,subtitle:`Module 02 • Fundamental Clause Requirement`,bullets:[`The site must trace all raw material lots (including primary packaging) from supplier to finished product and customer.`,`Traceability must work in both directions (backward from finished good and forward from raw material) within 4 hours.`,`Annual traceability tests must include a Mass Balance (quantity check) comparing input weight vs output + waste.`,`Rework must maintain full traceability back to its original production batch.`],Example:`If 1,000 kg of organic flour is received, mass balance reconciles how many kg went into finished bread, rework, warehouse stock, and sweepings.`,keyPoint:`Target time for full traceability and mass balance in BRCGS is a maximum of 4 hours.`},{slideNumber:5,title:`Root Cause Analysis, Recalls & 3-Day Notification`,subtitle:`Module 02 • Clauses 3.7 & 3.11`,bullets:[`Root Cause Analysis (RCA) is mandatory for non-conformities, customer complaints trends, and CCP failures.`,`Mock product recall exercises must be carried out at least annually, including out-of-hours contact checks.`,`In the event of an actual product recall or regulatory food safety enforcement notice, the Certification Body (CB) must be notified within 3 working days.`,`The site must then provide full RCA Details within 21 calendar days.`],Example:`If a product is recalled due to undeclared milk allergen, the site emails its BRCGS Certification Body within 3 working days.`,keyPoint:`Always remember the 3-Working-Day rule for notifying your Certification Body of recalls or regulatory notices.`}],sections:[],quiz:[]},{moduleNumber:3,title:`Module 03: Site Standards, Foreign Body & Hygiene Controls (Section 4)`,estimatedMinutes:60,learningObjectives:[`Apply Site Security and Food Defence (TACCP) controls`,`Manage Glass, Brittle Plastic, Metal Detectors, X-Ray, Sieves, and Magnets`,`Enforce Environmental Monitoring (EMP) for Listeria and Salmonella`],summary:`Covers Section 4 of BRCGS Issue 09: Site Security, Equipment Hygienic Design, Maintenance, Housekeeping, Glass/Brittle Plastic Registers, Metal Detection, and Environmental Monitoring.`,keyTakeaways:[`Glass and brittle plastic in open product areas must be listed on a register and inspected at defined frequencies.`,`Metal detectors must have fail-safe reject systems, locked reject bins, and regular test piece checks (Fe, Non-Fe, SS).`,`Risk-based Environmental Monitoring Programs (Clause 4.11.8) are mandatory for open product areas.`],practiceScenario:`During a line walk, an operator notices a cracked plastic gauge cover above an open mixing bowl. You stop the line, quarantine the batch in the bowl, inspect surrounding area under the glass/brittle breakage procedure, and replace the cover before restarting.`,presentationSlides:[{slideNumber:1,title:`Site Security & Food Defence — TACCP (Clause 4.2)`,subtitle:`Module 03 • Protecting Against Intentional Contamination`,bullets:[`Threat Assessment Critical Control Point (TACCP) evaluates risks of malicious contamination or sabotage.`,`External perimeters, raw material intake bays, water tanks, and silos must be locked and access-controlled.`,`Visitors and contractors must sign in, show ID, and learn site food safety rules before entering.`,`Staff are trained to challenge unidentified or unauthorized individuals in production areas.`],Example:`Keeping external bulk liquid sugar intake valves locked in a security box that only QA/Receiving staff can unlock.`,keyPoint:`External storage silos, water tanks, and intake pipes must always be physically locked.`},{slideNumber:2,title:`Equipment Commissioning & Maintenance Hygiene (Clauses 4.6 & 4.7)`,subtitle:`Module 03 • Issue 09 Enhanced Equipment Controls`,bullets:[`Issue 09 expanded Clause 4.6 on Hygienic Equipment Design and purchase specifications.`,`New or Second-hand equipment must undergo formal hygienic inspection and food safety commissioning before use.`,`Temporary repairs (using tape, wire, string, or cardboard) are strictly prohibited.`,`After any engineering maintenance on a line, a documented Hygiene Clearance sign-off is required before production restarts.`],Example:`After a technician replaces a conveyor bearing, all bolts and tools are counted out, the belt is sanitized, and QA signs the Hygiene Handover form.`,keyPoint:`No tape, string, or cardboard temporary fixes are ever allowed in a BRCGS factory.`},{slideNumber:3,title:`Glass, Brittle Plastic, Ceramics & Wood Control (Clause 4.9)`,subtitle:`Module 03 • Preventing Physical Contamination`,bullets:[`Glass and hard brittle plastic must be excluded from open product areas wherever possible.`,`Remaining essential items (light diffusers, sight glasses, clock faces, pest units) must be recorded on a Glass & Brittle Plastic Register.`,`Regular documented inspections check every item on the register for cracks or damage.`,`Clean, undamaged wooden pallets are acceptable only where there is no risk of product splinters; open product zones use plastic/metal.`],Example:`Inspecting all 42 items on the Packaging Hall Glass Register every week and immediately logging any scratched plastic guard.`,keyPoint:`Any breakage of glass or brittle plastic near open product requires immediate line stop and product quarantine.`},{slideNumber:4,title:`Foreign Body Detection: Filters, Sieves, Magnets & Metal Detectors (Clause 4.10)`,subtitle:`Module 03 • Critical Physical Barriers`,bullets:[`Filters and sieves used for food safety must be inspected at a defined frequency (e.g., every shift) for tears or damage.`,`Metal detectors or X-ray units must be installed unless a documented risk assessment justifies an alternative.`,`Metal detector checks use Ferrous, Non-Ferrous, and Stainless Steel test pieces passed with product packs.`,`Automated reject mechanisms (air-blast, pusher arm, belt stop) must divert rejected packs into a locked bin.`],Example:`Passing a 1.5mm Fe, 2.0mm Non-Fe, and 2.5mm SS test card at start of run, hourly, batch change, and end of run.`,keyPoint:` testing not only checks that the metal detector alarms, but that the physical reject arm actually kicks the pack into the locked bin.`},{slideNumber:5,title:`Environmental Monitoring & Pest Management (Clauses 4.11.8 & 4.14)`,subtitle:`Module 03 • Pathogen & Pest Barriers`,bullets:[`Environmental Monitoring Program (EMP) tests food contact (Zone 1) and non-food contact surfaces (Zones 2–4) for pathogens/indicators.`,`Drains, wheels, undersides of conveyors, and chillers are prime targets for Listeria spp. swabbing.`,`Pest control requires regular contractor inspections AND in-house staff awareness.`,`Toxic rodent bait stations are prohibited inside open production/storage areas to prevent bait contamination.`],Example:`Using non-toxic snap traps or monitoring blocks inside raw material warehouses and toxic bait only in secured external perimeter boxes.`,keyPoint:`Toxic loose rodenticides must never be placed inside areas where open food or ingredients are handled.`}],sections:[],quiz:[]},{moduleNumber:4,title:`Module 04: Product Control, Labelling Verification & Risk Zones (Sections 5, 6, 7 & 8)`,estimatedMinutes:60,learningObjectives:[`Prevent the #1 cause of recalls using BRCGS Clause 6.2 Labelling & Pack Control`,`Control Allergens and Product Authenticity/Claims (Halal, Organic, Gluten-Free)`,`Understand High-Risk, High-Care, and Ambient High-Care Production Risk Zones`],summary:`Explains Section 5 (Allergens, Claims, Lab Testing), Section 6 (Process Control, Labelling & Pack Verification), Section 7 (Personnel Hygiene & Protective Clothing), and Section 8 (Production Risk Zones).`,keyTakeaways:[`Incorrect packaging/labelling is the single largest cause of product recalls globally (Fundamental Clause 6.2).`,`Every production run requires documented line clearance to remove all previous labels and packaging.`,`High-Risk and High-Care zones require strict barrier changing procedures for footwear and protective clothing.`],practiceScenario:`A line finishes packing "Peanut Butter Cookies" and switches to "Plain Butter Cookies". Under Clause 5.3 and Clause 6.2, the line undergoes full allergen wet cleaning, protein swab verification, removal of all Peanut Cookie film reels back to store, and barcode scanner verification of the new film reel.`,presentationSlides:[{slideNumber:1,title:`Allergen Management & Identity Preserved Claims (Clauses 5.3 & 5.4)`,subtitle:`Module 04 • Protecting Allergic Consumers & Brand Integrity`,bullets:[`Sites must map all allergens handled on site and prevent cross-contact during storage, weighing, production, and packing.`,`Rework containing allergens can only be used in products that already contain that exact same allergen.`,`When a product makes a special claim (Organic, Halal, Kosher, Vegan, Free-From, Protected Origin), mass balance must be verified at least every 6 months.`,`Allergen cleaning procedures must be validated (proven to work) and verified before switching to a non-allergen product.`],Example:`Conducting a 6-monthly mass balance calculation comparing Organic Raw Almond purchases against Organic Almond Butter sales.`,keyPoint:`Validated allergen cleaning and strict label verification are mandatory to prevent undeclared allergen recalls.`},{slideNumber:2,title:`Fundamental Clause 6.2: Labelling & Pack Control`,subtitle:`Module 04 • Preventing Wrong-Packaging Recalls`,bullets:[`Before starting any packing run, a formal Line Clearance check ensures all packaging from the previous run is removed.`,`Only the authorized packaging for the current product is issued to the line.`,`Checks at start of run, every reel change, and hourly verify: Product Name, Artwork Version, Allergen Statement, Date Code, and Barcode.`,`Where online vision cameras or barcode scanners are used, their fail-safe rejection must be tested at start and end of run.`],Example:`Physically attaching a snippet of the printed film reel and date code to the QC check sheet at the start of the shift and after every splice.`,keyPoint:`Never allow two different product labels or film reels to sit side-by-side at a packing machine.`},{slideNumber:3,title:`Quantity, Weight, Volume & Equipment Calibration (Clauses 6.3 & 6.4)`,subtitle:`Module 04 • Legal Metrology & Accuracy`,bullets:[`Checkweighers and volume fillers ensure packs meet legal weight/volume regulations in the country of sale.`,`All measuring devices critical to food safety and legality (thermometers, scales, pH meters, timers) must be calibrated.`,`Calibration must be traceable to a recognized national or international standard.`,`If a thermometer is found out of calibration (+2.5°C error), all batches measured since its last good check must be risk-assessed.`],Example:`Testing the working line thermometer daily against a certified reference thermometer in ice slurry (0°C) and boiling water (100°C).`,keyPoint:`Out-of-calibration instruments require a retroactive safety evaluation of products produced since the last passed check.`},{slideNumber:4,title:`Personnel Hygiene, Medical Screening & Protective Clothing (Section 7)`,subtitle:`Module 04 • People as Food Safety Guardians`,bullets:[`All staff, visitors, and contractors must complete medical screening before entering open food areas.`,`Watches, rings (except a plain wedding band if site policy allows), earrings, visible piercings, false fingernails, and perfume are prohibited.`,`Blue metal-detectable plasters must be used for any skin cuts and tested through the site metal detector.`,`Protective clothing must have no external pockets above the waist and no sewn-on buttons.`],Example:`Every shift, QA tests one strip from the first-aid box of blue detectable plasters through the line metal detector and logs it.`,keyPoint:`Protective coats in food handling areas must never have external upper pockets or buttons that can fall into product.`},{slideNumber:5,title:`Section 8: Production Risk Zones (High-Risk & High-Care)`,subtitle:`Module 04 • Zoning for Ready-to-Eat (RTE) Foods`,bullets:[`Low-Risk Areas: Foods that require cooking by the consumer (raw meat, dry pasta) or ambient stable products.`,`High-Care Areas: Chilled/frozen Ready-to-Eat foods that underwent a pathogen reduction step (e.g., washed salad, sandwiches).`,`High-Risk Areas: Chilled/frozen Ready-to-Eat foods that have had a full cook step (≥70°C for 2 min) and are vulnerable to recontamination before packing.`,`High-Risk/High-Care entry requires physical barrier benches, captive footwear changes, full garment change, and filtered air overpressure.`],Example:`Workers stepping over a physical sit-on barrier bench to remove factory shoes on the "dirty side" and put on captive white boots on the "High-Risk cooked meat side".`,keyPoint:`High-Risk zones require complete physical segregation and captive footwear/equipment that never leaves the zone.`}],sections:[],quiz:[]},{moduleNumber:5,title:`Module 05: BRCGS Audit Protocol, Grading & Unannounced Readiness`,estimatedMinutes:60,learningObjectives:[`Differentiate between Critical, Major, and Minor non-conformities and BRCGS Grades (AA+ to D)`,`Understand the Mandatory 1-in-3 Year Unannounced Audit rule in Issue 09`,`Close out audit non-conformities within 28 calendar days`],summary:`Covers the BRCGS Issue 09 Audit Protocol, Non-Conformity classification, Grading table (AA, A, B, C, D and "+" for unannounced), the mandatory unannounced audit cycle, and 28-day corrective action closure.`,keyTakeaways:[`Every certified site must have at least 1 Unannounced Audit every 3 years under Issue 09.`,`The auditor must be on the factory shop floor within 30 minutes of arriving on site for an unannounced audit.`,`All non-conformities must be closed with root cause and preventive evidence within 28 calendar days.`],practiceScenario:`At 8:15 AM on a Tuesday, a BRCGS Auditor arrives unannounced at your reception gate. Security verifies their BRCGS Auditor ID card, notifies the QA Lead, and escorts the auditor directly onto the production floor by 8:35 AM (within the mandatory 30-minute window).`,presentationSlides:[{slideNumber:1,title:`BRCGS Audit Options & Mandatory Unannounced Rule`,subtitle:`Module 05 • Issue 09 Audit Protocol`,bullets:[`Announced Audit: Scheduled date agreed in advance (Note: must still have 1 unannounced audit every 3 years!).`,`Blended Audit: Part 1 is remote document review; Part 2 is on-site physical factory audit within 28 days.`,`Unannounced Audit Programme: Auditor arrives unannounced within the last 4 months of the audit cycle; earns a "+" on the grade (e.g., AA+).`,`Refusing entry to an unannounced BRCGS auditor results in immediate suspension of the site certificate.`],Example:`A site choosing the Announced programme has announced audits in Year 1 and Year 2, and a mandatory Unannounced audit in Year 3.`,keyPoint:`Under Issue 09 (and GFSI rules), every site undergoes at least one Unannounced Audit every 3 years.`},{slideNumber:2,title:`The 30-Minute Shop Floor Rule`,subtitle:`Module 05 • Starting the Unannounced Audit`,bullets:[`In an unannounced audit, the inspection of the production floor begins within 30 minutes of the auditor arriving at the site.`,`Reception and security staff must have a clear "Auditor Arrival Procedure" ready on the front desk.`,`PPE (visitor coat, hairnet, safety shoes) in all sizes must be stocked and ready at reception.`,`At Least 50% of the total audit duration is spent on the factory floor inspecting operations, hygiene, and interviewing operators.`],Example:`Keeping an "Unannounced Audit Ready Box" at reception containing clean coats, beard snoods, hairnets, and a laminated contact list.`,keyPoint:`Train security guards and receptionists so the auditor reaches the production floor within 30 minutes of arrival.`},{slideNumber:3,title:`Non-Conformity Levels & BRCGS Grading (AA to D)`,subtitle:`Module 05 • How Audit Grades Are Calculated`,bullets:[`Critical Non-Conformity: Direct threat to food safety or legality → Immediate fail / certificate withdrawal.`,`Major Non-Conformity: Substantial failure to meet the intent of a clause.`,`Minor Non-Conformity: A clause is not fully met, but product safety is not compromised.`,`Grade AA (or AA+): 5 or fewer Minors (0 Majors). Grade A (or A+): 6 to 10 Minors (0 Majors). Grade B (or B+): 11 to 16 Minors OR 1 Major + up to 10 Minors.`],Example:`A site receiving 4 Minor non-conformities and 0 Majors during an unannounced audit achieves the highest rating: Grade AA+.`,keyPoint:`To achieve Grade AA or AA+, a site must have Zero Majors and 5 or fewer Minors.`},{slideNumber:4,title:`Closing Non-Conformities within 28 Calendar Days`,subtitle:`Module 05 • Post-Audit Certification Process`,bullets:[`After the audit closing meeting, the site has 28 calendar days (14 days for initial certification in some cases) to submit evidence.`,`For every non-conformity, the site must submit: 1) Immediate Correction, 2) Root Cause Analysis (5-Whys), and 3) Preventive Action Plan.`,`Documentary evidence includes photos, updated SOPs, training attendance sheets, and completed check logs.`,`If acceptable evidence is not submitted within 28 days, certification is not granted and a full re-audit is required.`],Example:`For a minor NC on a missing calibration sticker, submitting a photo of the calibrated scale, a 5-Why RCA, and a revised monthly calibration checklist.`,keyPoint:`Simply fixing the symptom is not enough—BRCGS requires documented Root Cause Analysis and systemic Preventive Action within 28 days.`}],sections:[],quiz:[]}]}),e({id:`cert-2026-iso-14001-awareness`,code:`ISO-14001-AW`,title:`ISO 14001 Awareness Certificate`,subtitle:`ISO 14001:2015 Environmental Management Systems (EMS) — Aspects, Impacts, Waste Control & Sustainability`,category:`International Certification`,level:`Foundation & Intermediate`,durationHours:16,totalModules:5,examQuestionsCount:40,passingScorePercent:60,certificateTitle:`Certified ISO 14001:2015 Environmental Management System (EMS) Awareness Professional`,accreditationStandard:`ISO 14001:2015 Environmental Management Systems Standard`,targetAudience:[`HSE Officers`,`Plant & Facility Managers`,`Production Supervisors`,`Sustainability & Quality Teams`],overview:`A comprehensive 05-Module slide presentation course on ISO 14001:2015 covering Environmental Aspects & Impacts, Life Cycle Perspective, Compliance Obligations, Waste Hierarchy, Spill Emergency Response, and Environmental Performance Auditing.`,learningOutcomes:[`Understand the purpose and Clauses 4–10 of ISO 14001:2015 Environmental Management Systems`,`Distinguish clearly between Environmental Aspects (Cause) and Environmental Impacts (Effect)`,`Evaluate Significant Environmental Aspects across Normal, Abnormal, and Emergency conditions`,`Apply the Waste Management Hierarchy, Wastewater (ETP) Controls, and Chemical Spill Response`,`Monitor Environmental KPIs, Compliance Obligations, and Internal EMS Audits`],modules:[{moduleNumber:1,title:`Module 01: Introduction to ISO 14001:2015 & EMS Fundamentals`,estimatedMinutes:45,learningObjectives:[`Explain the goal of an Environmental Management System (EMS)`,`Describe the High-Level Structure (Clauses 4 to 10) and PDCA Cycle in ISO 14001`,`Identify the three core commitments of an Environmental Policy`],summary:`Introduces ISO 14001:2015, sustainable development, the PDCA cycle, Context of the Organization, and the mandatory commitments of an ISO 14001 Environmental Policy.`,keyTakeaways:[`ISO 14001:2015 helps organizations protect the environment, fulfill legal compliance obligations, and improve environmental performance.`,`Every ISO 14001 Environmental Policy must contain 3 commitments: Protect the environment/prevent pollution, Fulfill compliance obligations, and Continual improvement.`],practiceScenario:`During an ISO 14001 awareness walkthrough, an auditor asks an operator how their daily work supports the Environmental Policy. The operator explains turning off idle conveyors to save electricity and segregating plastic waste.`,presentationSlides:[{slideNumber:1,title:`What is ISO 14001:2015?`,subtitle:`Module 01 • Global Environmental Management Standard`,bullets:[`ISO 14001:2015 is the international standard for an Environmental Management System (EMS).`,`Published by the International Organization for Standardization (ISO) and adopted globally.`,`Applies to any organization—manufacturing plants, food factories, hospitals, offices, and logistics hubs.`,`Helps organizations grow sustainably while reducing pollution, waste, energy use, and environmental fines.`],Example:`A beverage bottling plant using ISO 14001 to reduce water usage from 2.5 liters of water per liter of beverage down to 1.6 liters.`,keyPoint:`ISO 14001 is about systematically managing how your organization interacts with the air, water, land, and natural resources.`},{slideNumber:2,title:`The Three Pillars of an ISO 14001 EMS`,subtitle:`Module 01 • Core Purpose of the Standard`,bullets:[`Pillar 1: Enhancement of Environmental Performance (reducing resource consumption, emissions, and waste).`,`Pillar 2: Fulfillment of Compliance Obligations (meeting all environmental laws, permits, and customer requirements).`,`Pillar 3: Achievement of Environmental Objectives (setting and hitting measurable sustainability targets).`,`Uses the Plan-Do-Check-Act (PDCA) cycle across Clauses 4 to 10.`],Example:`Meeting local EPA wastewater discharge limits (Compliance) while cutting electricity use by 8% (Performance & Objective).`,keyPoint:`Legal compliance is the minimum baseline in ISO 14001; continual environmental improvement is the ongoing goal.`},{slideNumber:3,title:`Context of the Organization & Interested Parties (Clause 4)`,subtitle:`Module 01 • Understanding Environmental Conditions`,bullets:[`Clause 4.1 examines external and internal issues, including environmental conditions affecting the site (climate, water scarcity, air quality).`,`Clause 4.2 identifies Interested Parties: Environmental Regulators (EPA), Local Community/Neighbors, Customers, Employees, Investors.`,`Any voluntary agreement with a neighbor or customer that the company chooses to adopt becomes a binding "Compliance Obligation".`,`Clause 4.3 defines the physical and operational boundaries (Scope) of the EMS.`],Example:`If a factory promises nearby residents not to run noisy delivery trucks between 11 PM and 6 AM, that promise becomes a Compliance Obligation.`,keyPoint:`In ISO 14001, "Compliance Obligations" include both mandatory environmental laws AND voluntary commitments made by the company.`},{slideNumber:4,title:`Leadership & The Environmental Policy (Clause 5)`,subtitle:`Module 01 • Three Mandatory Policy Commitments`,bullets:[`Top Management must establish, sign, and communicate an Environmental Policy (Clause 5.2).`,`Commitment 1: Commitment to the protection of the environment, including prevention of pollution.`,`Commitment 2: Commitment to fulfill the organization’s compliance obligations (legal and other requirements).`,`Commitment 3: Commitment to continual improvement of the EMS to enhance environmental performance.`],Example:`Displaying the Environmental Policy at site entrances and making it publicly available on the company website for external stakeholders.`,keyPoint:`Unlike the Quality Policy, the Environmental Policy MUST be made available to the public / external interested parties.`}],sections:[],quiz:[]},{moduleNumber:2,title:`Module 02: Environmental Aspects, Impacts & Life Cycle Perspective (Clause 6)`,estimatedMinutes:50,learningObjectives:[`Differentiate clearly between an Environmental Aspect (Cause) and Impact (Effect)`,`Assess aspects under Normal, Abnormal, and Emergency operating conditions`,`Apply a Life Cycle Perspective from raw material sourcing to end-of-life disposal`],summary:`Explains Clause 6.1.2 (Environmental Aspects & Impacts), Significance Scoring, Normal/Abnormal/Emergency conditions, Life Cycle Perspective, and Compliance Obligations (Clause 6.1.3).`,keyTakeaways:[`Environmental Aspect = element of an organization’s activities/products that interacts with the environment (The Cause).`,`Environmental Impact = any change to the environment, whether adverse or beneficial, resulting from an aspect (The Effect).`,`Aspects must be evaluated across Normal, Abnormal (startup/maintenance), and Emergency (fire/spill) situations.`],practiceScenario:`You are preparing the Aspect-Impact Register for the Boiler Room. Burning natural gas is the Activity; Flue gas emission (CO2, NOx) is the Environmental Aspect; Air pollution / climate change is the Environmental Impact.`,presentationSlides:[{slideNumber:1,title:`Environmental Aspect vs. Environmental Impact`,subtitle:`Module 02 • Cause and Effect Relationship (Clause 6.1.2)`,bullets:[`Activity / Process: What we do (e.g., Operating a steam boiler, Washing processing tanks, Running air compressors).`,`Environmental Aspect (THE CAUSE): How the activity interacts with the environment (e.g., Emission of stack gases, Discharge of alkaline wastewater, Consumption of electricity).`,`Environmental Impact (THE EFFECT): The resulting change to the environment (e.g., Air pollution/global warming, Water contamination, Depletion of natural resources).`,`Impacts can be Adverse (negative, like chemical spill) or Beneficial (positive, like planting trees or recycling water).`],Example:`Activity: Forklift battery charging → Aspect: Electricity consumption & hydrogen gas release → Impact: Resource depletion & explosion hazard.`,keyPoint:`Always remember: Aspect = Cause (interaction with environment); Impact = Effect (change to the environment).`},{slideNumber:2,title:`Normal, Abnormal & Emergency Conditions`,subtitle:`Module 02 • Complete Operational Assessment`,bullets:[`ISO 14001 requires identifying aspects across three operating conditions:`,`1. Normal Conditions: Routine day-to-day production, standard office operations, regular wastewater treatment.`,`2. Abnormal Conditions: Startup and shutdown of boilers, annual deep cleaning, filter regeneration, maintenance overhauls.`,`3. Emergency Conditions: Chemical tank rupture, ammonia refrigerant leak, transformer oil fire, ETP overflow during heavy flood.`],Example:`Boiler soot-blowing during monthly maintenance produces much higher dust emissions than normal daily operation—this is an Abnormal aspect.`,keyPoint:`Many severe environmental incidents happen during Abnormal (maintenance/startup) or Emergency conditions, so all three must be assessed.`},{slideNumber:3,title:`Determining "Significant" Environmental Aspects`,subtitle:`Module 02 • Risk Scoring & Prioritization`,bullets:[`Organizations use objective scoring criteria to decide which aspects are "Significant" (SEAs).`,`Criteria typically include: Severity of environmental damage, Frequency/Probability, Quantity/Scale, Duration, and Legal/Regulatory status.`,`Any aspect regulated by an environmental law or permit limit is automatically prioritized.`,`Every Significant Environmental Aspect (SEA) MUST have operational controls, monitoring, or an improvement objective.`],Example:`Ammonia storage in the refrigeration plant scores high on Severity and Legal status, making it a Significant Environmental Aspect requiring leak detectors and emergency drills.`,keyPoint:`Employees working in an area must know the Significant Environmental Aspects of their specific job.`},{slideNumber:4,title:`Life Cycle Perspective & Compliance Obligations`,subtitle:`Module 02 • Clauses 6.1.2 & 6.1.3`,bullets:[`ISO 14001:2015 requires thinking beyond the factory walls using a Life Cycle Perspective (Cradle-to-Grave).`,`Stages include: Raw material acquisition → Design & Production → Transportation/Delivery → Product Use → End-of-Life Disposal/Recycling.`,`While a full numerical Life Cycle Assessment (LCA) is not mandatory, you must consider stages you can control or influence.`,`Compliance Obligations Register (Legal Register) tracks all environmental permits, air/noise/water limits, and hazardous waste licenses.`],Example:`Redesigning product packaging from non-recyclable multi-layer foil to recyclable mono-material PE film reduces end-of-life landfill impact.`,keyPoint:`Life Cycle Perspective means considering environmental impacts before raw materials arrive and after the customer finishes the product.`}],sections:[],quiz:[]},{moduleNumber:3,title:`Module 03: Operational Controls, Waste Hierarchy & Pollution Prevention (Clauses 7 & 8)`,estimatedMinutes:50,learningObjectives:[`Apply the 5-step Waste Management Hierarchy (Prevent, Reduce, Reuse, Recycle, Dispose)`,`Control Hazardous Waste, Secondary Containment (110% Rule), and Effluent Treatment (ETP)`,`Manage Environmental Controls for Contractors and Procurement`],summary:`Covers Clause 7 (Competence, Awareness, Communication) and Clause 8.1 (Operational Planning & Control: Waste Hierarchy, Hazardous Chemicals, Bunding/Secondary Containment, Wastewater & Air Emissions).`,keyTakeaways:[`The Waste Hierarchy prioritizes Prevention and Reduction first, followed by Reuse, Recycling, Energy Recovery, and Disposal last.`,`Liquid chemical and oil storage tanks require Secondary Containment (bund walls/drip trays) holding at least 110% of the largest tank volume.`],practiceScenario:`You inspect the chemical drum storage yard and find five 200-liter caustic soda drums sitting directly on bare soil near a rainwater drain. You immediately relocate the drums onto a bunded spill pallet inside a covered chemical store away from storm drains.`,presentationSlides:[{slideNumber:1,title:`The 5-Step Waste Management Hierarchy`,subtitle:`Module 03 • Best Practice Resource Efficiency`,bullets:[`1. Prevention / Reduce (Most Preferred): Avoid generating waste at source (optimize cutting patterns, stop overproduction).`,`2. Reuse: Use materials again for the same or different purpose (returnable plastic crates, IBC totes, wooden pallets).`,`3. Recycle / Compost: Reprocess materials into new products (cardboard baling, scrap metal, organic food waste to compost/biogas).`,`4. Energy Recovery: Generate heat or electricity from non-recyclable waste.`,`5. Disposal / Landfill (Least Preferred): Safe disposal only when no higher option is possible.`],Example:`Switching from single-use cardboard shipping boxes to returnable collapsible plastic crates with a dairy supplier eliminates 40 tons of waste per year.`,keyPoint:`Always start at the top of the Waste Hierarchy: preventing waste is far better than paying to recycle or dispose of it.`},{slideNumber:2,title:`Hazardous Waste & Color-Coded Segregation`,subtitle:`Module 03 • Safe Handling from Source to Licensed Disposal`,bullets:[`Non-hazardous waste (paper, cardboard, clean plastic, food scraps) must never be mixed with hazardous waste.`,`Hazardous waste includes: Used lubricant oil, chemical containers, oily rags, laboratory reagents, e-waste, batteries, fluorescent tubes.`,`Hazardous waste must be stored in labeled, covered, weatherproof, and bunded areas.`,`Disposal of hazardous waste is permitted ONLY through government-licensed hazardous waste contractors with a Waste Manifest.`],Example:`Keeping a signed Hazardous Waste Manifest certificate on file for every shipment of used compressor oil sent to an EPA-approved recycler.`,keyPoint:`Mixing one oily chemical rag into a bin of recyclable cardboard contaminates the entire load into hazardous waste.`},{slideNumber:3,title:`Chemical Storage & The 110% Secondary Containment Rule`,subtitle:`Module 03 • Preventing Soil & Water Contamination`,bullets:[`All liquid chemicals, fuels, oils, and liquid waste must have Secondary Containment (bund walls or spill pallets).`,`Standard engineering rule: Bund capacity must hold at least 110% of the volume of the largest container stored inside it.`,`Safety Data Sheets (SDS) must be available at the point of storage and use, including Section 6 (Accidental Release) and Section 12/13 (Ecology/Disposal).`,`Stormwater drains (rainwater) must be clearly marked and protected so no chemical wash-water ever enters them.`],Example:`A 1,000-liter diesel tank sits inside a concrete bund wall capable of holding at least 1,100 liters with its drain valve locked shut.`,keyPoint:`Rainwater/storm drains flow directly to rivers or soil—never pour wash-water, oils, or chemicals into a storm drain.`},{slideNumber:4,title:`Wastewater (ETP), Air Emissions & Contractor Control`,subtitle:`Module 03 • Clause 8.1 Operational Controls`,bullets:[`Process wastewater must flow to an Effluent Treatment Plant (ETP) before discharge, monitoring pH, BOD, COD, TSS, and Oil & Grease.`,`Air emission controls include boiler stack scrubbers/filters, generator maintenance, and preventing ozone-depleting refrigerant leaks.`,`Contractors working on site (painters, welders, cleaners, construction crews) must follow the site’s ISO 14001 rules.`,`Procurement checks environmental requirements before buying new chemicals or machinery.`],Example:`Requiring an external painting contractor to take back all empty paint tins and thinner cans rather than dumping them in factory bins.`,keyPoint:`Your site is legally and environmentally responsible for the actions of contractors working on your premises.`}],sections:[],quiz:[]},{moduleNumber:4,title:`Module 04: Emergency Preparedness & Spill Response (Clause 8.2)`,estimatedMinutes:45,learningObjectives:[`Identify potential environmental emergencies (spills, leaks, fires, ETP failure)`,`Use a Spill Response Kit using the STOP-CONTAIN-CLEAN-DISPOSE sequence`,`Conduct and evaluate periodic environmental emergency drills`],summary:`Explains Clause 8.2 Emergency Preparedness and Response, Spill Kits, managing firewater runoff, and revising emergency plans after drills or incidents.`,keyTakeaways:[`Spill response follows: Assess Safety (PPE) → Stop the Source → Contain the Spill (protect drains) → Clean Up → Dispose as Hazardous Waste.`,`Emergency plans must be tested periodically through practical drills and reviewed after any drill or real incident.`],practiceScenario:`A forklift punctures a 25-liter drum of phosphoric acid near an outdoor yard drain. The trained spill team puts on chemical gloves/goggles, places a drain cover mat over the storm drain immediately, surrounds the liquid with absorbent socks, absorbs the spill with pads, places used pads into a yellow hazardous waste bag, and restocks the spill kit.`,presentationSlides:[{slideNumber:1,title:`Identifying Environmental Emergencies (Clause 8.2)`,subtitle:`Module 04 • Preparing Before an Incident Happens`,bullets:[`Organizations must establish procedures to prepare for and respond to potential environmental emergencies.`,`Common environmental emergencies: Chemical or fuel spill, toxic gas/ammonia leak, fire & contaminated firewater runoff, ETP overflow.`,`Also includes natural disasters impacting the site: Flooding of chemical stores, lightning strike on fuel tanks, power blackout at ETP.`,`Emergency plans must protect both human safety AND the surrounding air, soil, and water.`],Example:`Installing an emergency holding lagoon at the ETP to catch untreated wastewater if the biological treatment pump fails.`,keyPoint:`During a factory fire, toxic firewater runoff entering rivers can cause massive environmental damage if drains are not blocked.`},{slideNumber:2,title:`Anatomy of a Chemical & Oil Spill Kit`,subtitle:`Module 04 • Essential Emergency Equipment`,bullets:[`Spill kits must be stationed near chemical stores, workshops, fuel tanks, loading bays, and laboratories.`,`Contents include: Absorbent Booms/Socks (to build a dam around the spill), Absorbent Pads/Pillows (to soak up liquid), and Granules.`,`Also includes: Neoprene Drain Covers/Putty (to seal storm drains), PPE (chemical gloves, goggles), Plastic Shovel/Brush, and Hazardous Waste Bags.`,`Spill kits are color-coded: Yellow for Chemicals/Acids, White for Oils/Hydrocarbons (repels water, floats on water), Grey for Universal liquids.`],Example:`Using a White Oil-Only Spill Kit when hydraulic oil leaks onto a wet concrete loading dock during rain.`,keyPoint:`Never use a Spill Kit as a trash bin—inspect spill kit seals monthly to ensure all pads, socks, and PPE are complete.`},{slideNumber:3,title:`The 5-Step Spill Response Procedure`,subtitle:`Module 04 • Action Sequence in an Emergency`,bullets:[`Step 1 — ASSESS & PROTECT: Check the chemical SDS, alert people nearby, and put on appropriate PPE (never touch unknown chemicals barehanded).`,`Step 2 — STOP THE SOURCE: Upright a tipped drum or close the leaking valve if safe to do so.`,`Step 3 — CONTAIN & BLOCK DRAINS: Place drain mats and absorbent socks around the outer edge of the spill to stop it reaching drains.`,`Step 4 — CLEAN UP: Place absorbent pads over the liquid from the outside inward until dry.`,`Step 5 — DISPOSE & RESTOCK: Seal used absorbents in labeled hazardous waste bags, report the incident, and replenish the spill kit.`],Example:`Blocking the storm drain FIRST before mopping up the middle of the puddle stops chemicals from escaping off-site.`,keyPoint:`Priority #1 in containment is always blocking nearby floor drains and rainwater grates before the liquid reaches them.`},{slideNumber:4,title:`Emergency Drills & Post-Incident Review`,subtitle:`Module 04 • Testing and Improving Response Plans`,bullets:[`ISO 14001 Clause 8.2 requires periodic testing (mock drills) of emergency response procedures where practicable.`,`Drills should test chemical spill containment, ammonia leak evacuation, and ETP overflow response.`,`After every mock drill or actual incident, the team must evaluate what worked and what failed.`,`Emergency procedures and training must be updated whenever weaknesses are found during a drill.`],Example:`Discovering during a mock spill drill that the nearest spill kit was blocked by stacked pallets, leading to painted yellow "Keep Clear" floor zones.`,keyPoint:`Every emergency drill must end with a documented evaluation report and corrective actions for any delays identified.`}],sections:[],quiz:[]},{moduleNumber:5,title:`Module 05: Performance Evaluation, Compliance Auditing & Continual Improvement (Clauses 9 & 10)`,estimatedMinutes:45,learningObjectives:[`Monitor Environmental KPIs and calibrate environmental measuring equipment`,`Perform Evaluation of Compliance (Clause 9.1.2) against environmental laws and permits`,`Drive Continual Improvement through Internal Audits, Management Review, and CAPA`],summary:`Covers Clause 9 (Monitoring & Measurement, Evaluation of Compliance, Internal EMS Audit, Management Review) and Clause 10 (Nonconformity, Corrective Action, and Continual Improvement).`,keyTakeaways:[`Clause 9.1.2 requires periodic Evaluation of Compliance with all legal permits and voluntary obligations, maintaining documented evidence.`,`Environmental monitoring instruments (pH meters, flow meters, gas analyzers) must be calibrated and verified.`],practiceScenario:`During your quarterly Evaluation of Compliance (Clause 9.1.2), you verify that third-party stack emission test reports, ETP effluent lab reports, and hazardous waste manifests are all within legal permit limits and renewable licenses are up to date.`,presentationSlides:[{slideNumber:1,title:`Monitoring, Measurement & Environmental KPIs (Clause 9.1.1)`,subtitle:`Module 05 • Data-Driven Environmental Management`,bullets:[`Organizations must define what needs to be monitored and measured, methods used, and frequency of analysis.`,`Key Environmental Performance Indicators (EPIs) are normalized per unit of production (e.g., kWh per ton, Liters of water per kg, % waste recycled).`,`Equipment used for environmental monitoring (ETP pH sensors, flow meters, noise meters) must be calibrated.`,`Reliable data shows whether environmental objectives are on track or slipping.`],Example:`Tracking "Specific Water Consumption (m³ water / ton of product)" monthly rather than just total water bills, to account for seasonal production volume changes.`,keyPoint:`Normalizing environmental KPIs per ton or unit of output gives an accurate picture of true resource efficiency.`},{slideNumber:2,title:`Evaluation of Compliance (Clause 9.1.2)`,subtitle:`Module 05 • Verifying Legal & Permit Adherence`,bullets:[`Identifying laws in Clause 6.1.3 is step one; Clause 9.1.2 requires evaluating whether you actually comply with every single requirement.`,`Checks include: Valid operating permits, air stack emission test certificates, wastewater lab reports, noise boundary surveys, and waste transfer notes.`,`If a legal non-compliance is discovered (e.g., ETP COD exceeded permit limit on Tuesday), immediate corrective action is mandatory.`,`Documented information (records) of all compliance evaluations must be retained.`],Example:`Conducting a twice-yearly Legal Compliance Audit where every condition printed on the factory’s Environmental Permit is checked against actual test records.`,keyPoint:`Even if a legal limit was exceeded only once and already fixed, the EMS must record the non-compliance and its root cause action.`},{slideNumber:3,title:`Internal EMS Audits & Management Review (Clauses 9.2 & 9.3)`,subtitle:`Module 05 • System Health Check`,bullets:[`Internal EMS audits check whether the environmental management system conforms to ISO 14001:2015 and site procedures.`,`Audit frequency is based on the environmental importance of the processes (e.g., ETP and Chemical Store audited more often than offices).`,`Management Review evaluates: status of objectives, significant aspects changes, compliance status, environmental incidents, and resource needs.`,`Outputs of Management Review drive budget allocation for cleaner technologies and waste reduction projects.`],Example:`Management Review approving capital budget to install solar panels and condensate heat recovery based on annual EMS energy data.`,keyPoint:`Audit schedules in ISO 14001 must prioritize areas with Significant Environmental Aspects.`},{slideNumber:4,title:`Nonconformity, Corrective Action & Continual Improvement (Clause 10)`,subtitle:`Module 05 • Closing the Loop`,bullets:[`When an environmental nonconformity or incident occurs, first take immediate action to mitigate adverse environmental impacts.`,`Perform Root Cause Analysis (5-Whys / Fishbone) so the spill, exceedance, or waste mix-up cannot happen again.`,`Update the Aspect-Impact Register or operational controls if necessary.`,`Continual Improvement in ISO 14001 means measurably improving actual environmental performance—not just adding more paperwork.`],Example:`Eliminating recurring ETP high-pH alarms by installing an automated acid-dosing neutralization valve rather than just retraining operators.`,keyPoint:`True continual improvement in ISO 14001 results in cleaner air, cleaner water, less waste, and lower resource consumption.`}],sections:[],quiz:[]}]}),e({id:`cert-2026-iso-45001-awareness`,code:`ISO-45001-AW`,title:`ISO 45001 Awareness Certificate`,subtitle:`ISO 45001:2018 Occupational Health & Safety (OH&S) — HIRA, Hierarchy of Controls, LOTO & Worker Safety`,category:`International Certification`,level:`Foundation & Intermediate`,durationHours:16,totalModules:5,examQuestionsCount:40,passingScorePercent:60,certificateTitle:`Certified ISO 45001:2018 Occupational Health & Safety (OH&S) Awareness Professional`,accreditationStandard:`ISO 45001:2018 Occupational Health & Safety Management Systems`,targetAudience:[`Safety Officers (HSE)`,`Plant Managers & Engineers`,`Line Supervisors`,`Warehouse & Maintenance Teams`],overview:`A practical 05-Module slide presentation course on ISO 45001:2018 covering Worker Consultation & Participation, Hazard Identification & Risk Assessment (HIRA), the 5-Level Hierarchy of Controls, Permit-to-Work (PTW), Lockout/Tagout (LOTO), and Incident Investigation.`,learningOutcomes:[`Understand ISO 45001:2018 requirements and Clause 5.4 Worker Consultation & Participation`,`Identify physical, mechanical, chemical, ergonomic, and psychosocial workplace hazards (HIRA)`,`Apply the 5-Level Hierarchy of Controls (Elimination, Substitution, Engineering, Administrative, PPE)`,`Execute Permit-to-Work (PTW), Lockout/Tagout (LOTO), Machine Guarding, and Confined Space controls`,`Investigate Near-Misses and Workplace Accidents using Root Cause Analysis without worker blame`],modules:[{moduleNumber:1,title:`Module 01: Introduction to ISO 45001:2018 & Worker Participation`,estimatedMinutes:45,learningObjectives:[`Explain the purpose of ISO 45001:2018 and how it replaced OHSAS 18001`,`Distinguish between Worker Consultation and Worker Participation (Clause 5.4)`,`Understand the Worker’s Right to Stop Unsafe Work (Clause 5.2 / 7.3)`],summary:`Covers the transition from OHSAS 18001 to ISO 45001:2018, the OH&S Policy commitments, Leadership accountability, Worker Consultation & Participation (Clause 5.4), and the right to refuse imminent danger.`,keyTakeaways:[`ISO 45001:2018 prevents work-related injury and ill health and provides safe and healthy workplaces.`,`Clause 5.4 requires active Consultation (seeking views before deciding) and Participation (joint decision-making) of non-managerial workers.`,`Clause 7.3 ensures workers can remove themselves from work situations that present an imminent and serious danger without reprisal.`],practiceScenario:`A maintenance technician notices that a scaffold has a missing guardrail and unstable base plates. Under ISO 45001 Clause 7.3, the technician stops the job, reports the hazard to the supervisor, and is protected from any disciplinary punishment for stopping unsafe work.`,presentationSlides:[{slideNumber:1,title:`What is ISO 45001:2018?`,subtitle:`Module 01 • Global Occupational Health & Safety Standard`,bullets:[`ISO 45001:2018 is the world’s first ISO international standard for Occupational Health & Safety (OH&S), replacing OHSAS 18001.`,`Designed to prevent work-related fatal accidents, injuries, and occupational diseases (hearing loss, musculoskeletal injury, stress).`,`Applies to full-time employees, temporary agency workers, contractors, and visitors under the organization’s control.`,`Built on the Annex SL High-Level Structure (Clauses 4 to 10) so it integrates smoothly with ISO 9001 and ISO 14001.`],Example:`Integrating ISO 9001 (Quality), ISO 14001 (Environment), and ISO 45001 (Safety) into one unified QHSE Management System.`,keyPoint:`ISO 45001 protects both physical safety (preventing injuries) and long-term occupational health (preventing physical and mental ill-health).`},{slideNumber:2,title:`Leadership & The OH&S Policy (Clauses 5.1 & 5.2)`,subtitle:`Module 01 • Management Ownership of Safety`,bullets:[`Top Management holds ultimate accountability for preventing work-related injury and ill-health (cannot be delegated solely to the Safety Officer).`,`The OH&S Policy must include commitments to: 1) Provide safe and healthy working conditions, 2) Eliminate hazards and reduce OH&S risks.`,`3) Fulfill legal and other requirements, 4) Continual improvement of the OH&S system, and 5) Consultation and participation of workers.`,`Leadership must foster a positive safety culture that encourages reporting near-misses without fear of blame.`],Example:`Plant Directors starting every morning production meeting with a 2-minute Safety Share and reviewing near-miss reports personally.`,keyPoint:`The OH&S Policy has 5 mandatory commitments, including eliminating hazards and consulting with workers.`},{slideNumber:3,title:`Clause 5.4: Consultation & Participation of Workers`,subtitle:`Module 01 • Engaging Non-Managerial Staff`,bullets:[`Consultation = Seeking workers’ views and feedback BEFORE management makes a safety decision (two-way communication).`,`Participation = Involving workers directly in safety decision-making (e.g., joint HIRA teams, selecting PPE, investigating incidents).`,`ISO 45001 specifically requires engaging non-managerial workers—the operators, drivers, and technicians on the front line.`,`Barriers to participation (language barriers, literacy, shift schedules, fear of retaliation) must be identified and removed.`],Example:`Having three line operators test three different styles of cut-resistant gloves and vote on which glove offers the best grip and comfort.`,keyPoint:`Never write a Risk Assessment (HIRA) sitting alone in an office—always involve the operators who actually perform the task.`},{slideNumber:4,title:`The Right to Stop Unsafe Work (Clause 7.3)`,subtitle:`Module 01 • Protection Against Imminent Danger`,bullets:[`Clause 7.3(e) & (f) requires workers to be aware of the ability to remove themselves from work situations that they consider present an imminent and serious danger to their life or health.`,`Workers must be protected from undue consequences (no pay deduction, firing, or punishment) when they stop unsafe work in good faith.`,`Everyone on site is empowered with a "Stop Work Authority" if a critical safety control fails.`,`Work only resumes once the hazard is inspected and made safe.`],Example:`A forklift driver refuses to drive a truck whose brakes failed the morning pre-start check; the supervisor tags the truck "Out of Service" and thanks the driver.`,keyPoint:`Every worker in an ISO 45001 workplace has the right and duty to stop work if there is imminent danger to life or health.`}],sections:[],quiz:[]},{moduleNumber:2,title:`Module 02: Hazard Identification & Risk Assessment — HIRA (Clause 6)`,estimatedMinutes:50,learningObjectives:[`Distinguish clearly between a Hazard, a Risk, an Incident, a Near-Miss, and an Accident`,`Identify the 6 categories of workplace hazards (Mechanical, Physical, Chemical, Biological, Ergonomic, Psychosocial)`,`Conduct a HIRA risk scoring matrix across Routine and Non-Routine tasks`],summary:`Explains core safety definitions (Hazard vs Risk, Near-Miss vs Accident), the 6 categories of workplace hazards including psychosocial factors in ISO 45001, and conducting HIRA.`,keyTakeaways:[`Hazard = source with a potential to cause injury and ill health. Risk = combination of likelihood and severity of injury.`,`Near-Miss = an incident where no injury or ill health occurs, but had the potential to do so.`,`ISO 45001 explicitly includes ergonomic and psychosocial hazards (workload, bullying, shift fatigue) alongside physical/mechanical hazards.`],practiceScenario:`An unguarded rotating conveyor chain is a Mechanical Hazard. The chance of an operator’s sleeve getting caught and causing a severe hand fracture is the OH&S Risk. Installing a fixed bolted mesh guard reduces that risk to an acceptable level.`,presentationSlides:[{slideNumber:1,title:`Essential Safety Definitions in ISO 45001`,subtitle:`Module 02 • Speaking the Language of Safety`,bullets:[`Hazard: A source or situation with a potential to cause injury and ill health (e.g., wet floor, live electrical wire, loud noise, toxic fumes).`,`OH&S Risk: Combination of the Likelihood of a hazardous event occurring and the Severity of the injury/ill health that could be caused.`,`Incident: Occurrence arising out of work that could or does result in injury and ill health.`,`Accident = Incident that DOES result in injury/ill health. Near-Miss (Close Call) = Incident where NO injury occurs, but could have.`],Example:`A heavy wrench falls from an overhead platform and lands 1 meter away from a worker—no one is hurt, so it is a Near-Miss that must be investigated immediately.`,keyPoint:`Today’s unaddressed Near-Miss is tomorrow’s serious Accident—investigating near-misses prevents injuries before they happen.`},{slideNumber:2,title:`The 6 Categories of Workplace Hazards (Clause 6.1.2.1)`,subtitle:`Module 02 • Comprehensive Hazard Identification`,bullets:[`1. Mechanical & Physical: Unguarded machinery, moving forklifts, working at height, slips/trips, noise (>85 dB), vibration, heat/cold, electricity.`,`2. Chemical: Acids, caustic soda, ammonia, solvents, dust, welding fumes, carbon monoxide.`,`3. Biological: Bacteria, viruses, mold spores, bloodborne pathogens, pest droppings.`,`4. Ergonomic: Repetitive manual lifting, awkward postures, poorly designed workstations.`,`5. Psychosocial (Highlighted in ISO 45001): Excessive workload, long night shifts, fatigue, workplace harassment, or bullying.`],Example:`Evaluating 12-hour night shift fatigue and manual lifting of 50 kg bags as part of the factory HIRA alongside machine hazards.`,keyPoint:`ISO 45001 requires assessing mental/psychosocial and ergonomic health hazards, not just physical machinery hazards.`},{slideNumber:3,title:`Routine, Non-Routine & Emergency Activities in HIRA`,subtitle:`Module 02 • Where Most Severe Accidents Happen`,bullets:[`HIRA must cover Routine Activities (daily line operation, packing, normal warehouse stacking).`,`HIRA must cover Non-Routine Activities (unblocking jammed machines, roof repair, annual tank entry, installing new lines).`,`Must also consider human factors, past incidents, and people near the workplace (visitors, neighbors, delivery drivers).`,`Statistics show a high percentage of fatal industrial accidents occur during Non-Routine maintenance or jam clearing.`],Example:`Writing a specific Job Safety Analysis (JSA) before a crane lifts a new cooling tower onto the factory roof (a non-routine task).`,keyPoint:`Never allow a non-routine maintenance or unjamming task to start without assessing its specific hazards first.`},{slideNumber:4,title:`Risk Assessment Matrix (Likelihood × Severity)`,subtitle:`Module 02 • Prioritizing Safety Actions`,bullets:[`Step 1: Score Initial Risk = Likelihood (1 to 5) × Severity (1 = First Aid to 5 = Fatality/Permanent Disability).`,`Step 2: If risk is High or Unacceptable, work cannot proceed until stronger controls are applied.`,`Step 3: Apply controls using the Hierarchy of Controls and re-score the Residual Risk.`,`Step 4: Review HIRA annually, after any incident/near-miss, or before any Management of Change (MOC).`],Example:`Working at 6 meters height without protection has Severity = 5, Likelihood = 4 (Score 20 = Critical); using a scissor lift with guardrails drops Likelihood to 1 (Residual Score 5 = Low).`,keyPoint:`Controls must reduce high risks down to an acceptable Residual Risk level before work begins.`}],sections:[],quiz:[]},{moduleNumber:3,title:`Module 03: The Hierarchy of Controls & High-Risk Operations (Clause 8.1)`,estimatedMinutes:55,learningObjectives:[`Apply the 5-Level Hierarchy of Controls in exact order from Most Effective to Least Effective`,`Execute Lockout/Tagout (LOTO) and Permit-to-Work (PTW) for high-risk jobs`,`Control Confined Space Entry, Working at Height, Hot Work, and Machine Guarding`],summary:`Explains Clause 8.1.2 Hierarchy of Controls (Elimination, Substitution, Engineering, Administrative, PPE) and critical life-saving rules: Lockout/Tagout (LOTO), Permit-to-Work (PTW), Machine Guarding, Confined Spaces, and Forklift Pedestrian Segregation.`,keyTakeaways:[`The 5-Level Hierarchy of Controls MUST be applied in order: 1. Elimination, 2. Substitution, 3. Engineering Controls, 4. Administrative Controls, 5. PPE (Last Resort).`,`Lockout/Tagout (LOTO) isolates all energy sources with a personal padlock and tag + Try/Test before any maintenance inside machinery.`],practiceScenario:`An operator needs to clean inside a dough mixer. Instead of just pressing the emergency stop button, the operator switches off the main electrical isolator, attaches their personal LOTO padlock and photo tag, keeps the single key in their pocket, and presses the start button (TRY step) to confirm zero energy before reaching inside.`,presentationSlides:[{slideNumber:1,title:`Clause 8.1.2: The 5-Level Hierarchy of Controls`,subtitle:`Module 03 • Most Effective to Least Effective`,bullets:[`1. ELIMINATION (Most Effective): Physically remove the hazard completely (e.g., perform inspection from ground level using a camera instead of climbing a ladder).`,`2. SUBSTITUTION: Replace the hazard with something safer (e.g., replace toxic solvent paint with water-based paint; replace 50 kg bags with 20 kg bags).`,`3. ENGINEERING CONTROLS: Isolate people from the hazard physically (e.g., interlocked machine guards, acoustic noise enclosures, local exhaust ventilation).`,`4. ADMINISTRATIVE CONTROLS: Change the way people work (e.g., SOPs, safety signs, job rotation, Permit-to-Work, training).`,`5. PERSONAL PROTECTIVE EQUIPMENT — PPE (Least Effective / Last Resort): Earplugs, safety glasses, helmets, gloves, safety shoes.`],Example:`Instead of just handing out earplugs (PPE) in a 95 dB compressor room, enclosing the compressor in soundproof panels (Engineering) drops room noise to 76 dB.`,keyPoint:`PPE is always the LAST line of defence because if a glove tears or a worker forgets goggles, the hazard is still 100% present.`},{slideNumber:2,title:`Lockout / Tagout (LOTO) — Zero Energy Isolation`,subtitle:`Module 03 • Life-Saving Control During Maintenance & Cleaning`,bullets:[`LOTO prevents unexpected startup or release of stored energy (electrical, pneumatic air, hydraulic, steam, gravity) during servicing or unjamming.`,`Rule: "One Person, One Lock, One Key" — every technician working on a machine attaches their own personal padlock to the hasp.`,`LOTO 6 Steps: 1) Prepare, 2) Shut down machine, 3) Isolate energy source at main disconnect, 4) Apply Lock & Tag, 5) Release stored energy (bleed air/pressure), 6) TRY/VERIFY.`,`Note: Emergency Stop buttons and control switches are NOT energy isolation points and must never be locked out instead of the main breaker.`],Example:`Three technicians repairing a packaging line attach a 6-hole group scissor hasp to the main breaker; the machine cannot be energized until all 3 technicians remove their own locks.`,keyPoint:`Always perform Step 6 (TRY Out): press the start button after applying your padlock to prove the machine is truly dead before entering.`},{slideNumber:3,title:`Permit-to-Work (PTW) System for High-Risk Tasks`,subtitle:`Module 03 • Formal Authorization Before Starting`,bullets:[`A Permit-to-Work (PTW) is a formal written safety checklist authorizing high-risk non-routine work for a specific shift and location.`,`Hot Work Permit (welding, grinding, cutting): Requires removing combustibles within 10–11m, gas check, fire extinguisher on standby, and 30–60 min fire watch after completion.`,`Confined Space Entry Permit (tanks, silos, deep pits): Requires gas testing BEFORE entry (Oxygen 19.5%–23.5%, LEL <10%, toxic gases CO/H2S = 0), continuous ventilation, standby attendant outside, and rescue harness.`,`Work at Height Permit (>2 meters): Requires certified scaffolding, full-body harness with double lanyard anchored securely, and tool lanyards.`],Example:`Before entering a flour silo for cleaning, atmospheric gas meter confirms 20.9% Oxygen, LOTO locks the auger screw, and a trained attendant stands at the manhole.`,keyPoint:`Never enter a Confined Space to rescue an unconscious colleague without breathing apparatus—over 50% of confined space fatalities are would-be rescuers.`},{slideNumber:4,title:`Machine Guarding & Forklift-Pedestrian Segregation`,subtitle:`Module 03 • Everyday Shop Floor Engineering Controls`,bullets:[`All nip points, rotating shafts, gears, chains, and cutting blades must have Fixed Guards (requiring a tool to remove) or Interlocked Guards (stopping the machine immediately when opened).`,`Bypassing, taping, or defeating a safety interlock switch is a gross safety violation.`,`Workplace transport (forklifts & trucks) must be physically separated from pedestrians using barriers, marked walkways, convex mirrors, speed limits, and blue warning spotlights.`,`Management of Change (Clause 8.1.3) requires a formal safety review before introducing any new machine, chemical, or layout change.`],Example:`Installing steel crash barriers between the warehouse pedestrian walkway and the main forklift aisle.`,keyPoint:`Never bypass a machine safety interlock switch—interlocks exist to prevent amputations and fatalities.`}],sections:[],quiz:[]},{moduleNumber:4,title:`Module 04: Contractor Safety, Procurement & Emergency Preparedness (Clauses 8.1.4 & 8.2)`,estimatedMinutes:45,learningObjectives:[`Control safety risks introduced by Procurement, Contractors, and Outsourcing (Clause 8.1.4)`,`Establish Emergency Preparedness plans for Fire, Medical Trauma, Chemical Release, and Evacuation`,`Apply Occupational Health monitoring (noise audiometry, ergonomics, first aid)`],summary:`Covers Clause 8.1.4 (Procurement, Contractors, Outsourcing), Occupational Health surveillance, and Clause 8.2 (Emergency Preparedness, Fire Safety, Evacuation Drills, First Aid).`,keyTakeaways:[`Procurement must verify safety specifications (CE/safety guarding, low noise, SDS) BEFORE purchasing equipment or chemicals.`,`Contractors must be pre-qualified, inducted, issued Permits-to-Work, and supervised on site.`,`Emergency evacuation drills must be conducted periodically across all shifts, including night shifts.`],practiceScenario:`An external roofing contractor arrives on site without safety harnesses. Under Clause 8.1.4.2, security and HSE refuse to issue a Work at Height Permit until the contractor provides inspected full-body harnesses, anchor lines, and worker fall-protection training certificates.`,presentationSlides:[{slideNumber:1,title:`Procurement, Contractors & Outsourcing (Clause 8.1.4)`,subtitle:`Module 04 • Stopping Hazards at the Factory Gate`,bullets:[`Procurement (8.1.4.1): Safety requirements must be checked BEFORE buying new machines, raw materials, or chemicals (never buy an unguarded machine or a chemical without an SDS).`,`Contractors (8.1.4.2): Coordinate safety with contractors considering: 1) How contractor work affects your workers, 2) How your factory hazards affect contractor workers, 3) How contractor work affects visitors/neighbors.`,`All contractors must complete Site Safety Induction, provide method statements/risk assessments (RAMS), and hold valid Permits-to-Work.`,`Outsourcing (8.1.4.3): Outsourced functions under the scope of the OH&S system must remain controlled.`],Example:`Requiring the Engineering Buyer to get HSE sign-off on noise levels (<80 dB) and interlocked guards before ordering a new case-packer.`,keyPoint:`Fixing safety flaws at the Procurement stage is 10 times cheaper and safer than retrofitting guards after a machine is installed.`},{slideNumber:2,title:`Occupational Health & Ergonomics Surveillance`,subtitle:`Module 04 • Protecting Long-Term Worker Health`,bullets:[`Occupational Health focuses on chronic exposures that develop over months or years.`,`Noise Control: Areas ≥85 dB(A) require mandatory hearing protection zones, engineering noise reduction, and annual Audiometry (hearing tests) for workers.`,`Hazardous Substances: Local Exhaust Ventilation (LEV), exposure monitoring, eyewash/safety showers within 10 seconds (unobstructed) of corrosive chemical handling.`,`Manual Handling & Ergonomics: Mechanical lifting aids (pallet jacks, vacuum lifters), team lifting, and ergonomic table heights.`],Example:`Testing emergency eyewash stations and deluge showers weekly to flush stagnant water and confirm instant flow.`,keyPoint:`Emergency eyewash and safety showers must be reachable within 10 seconds on the same level with zero locked doors or obstacles in the path.`},{slideNumber:3,title:`Emergency Preparedness & Fire Safety (Clause 8.2)`,subtitle:`Module 04 • Readiness Saves Lives`,bullets:[`Emergency plans cover: Fire/Explosion, Ammonia/Gas leak, Severe Medical Injury, Electric Shock, Structural Collapse, and Natural Disasters.`,`Fire exits and escape corridors must NEVER be locked, chained, or blocked by pallets during working hours.`,`Fire extinguishers (Water, Foam, CO2, Dry Powder, Wet Chemical) must be inspected monthly, unobstructed, and matched to the fire class.`,`Trained Fire Wardens and Certified First Aiders must be present on every shift (including night and weekend shifts).`],Example:`Ensuring CO2 fire extinguishers are placed outside electrical switchgear panels rather than water extinguishers.`,keyPoint:`A blocked or locked emergency fire exit in a populated building is a critical life-safety violation.`}],sections:[],quiz:[]},{moduleNumber:5,title:`Module 05: Incident Investigation, Safety KPIs & Audits (Clauses 9 & 10)`,estimatedMinutes:45,learningObjectives:[`Distinguish between Leading Safety Indicators (Proactive) and Lagging Safety Indicators (Reactive)`,`Investigate Incidents and Near-Misses with worker participation to find systemic Root Causes`,`Conduct ISO 45001 Internal Audits and Management Review`],summary:`Covers Clause 9 (Leading vs Lagging OH&S KPIs, Evaluation of Legal Compliance, Internal Audits, Management Review) and Clause 10 (Incident Investigation, Nonconformity, Corrective Action, and Continual Improvement).`,keyTakeaways:[`Leading Indicators measure proactive prevention (safety walks, near-misses closed, training); Lagging Indicators measure past failures (LTIFR, injury rates).`,`Incident investigations (Clause 10.2) must involve workers, focus on systemic root causes (not human blame), and be communicated to relevant workers.`],practiceScenario:`An operator slips and twists an ankle on oil near a filling machine. Instead of blaming the operator for "not looking", a 5-Why investigation with the operator finds a worn hydraulic seal leaking onto an ungrooved smooth tile. Corrective action: replace the seal type, add a drip tray, and apply anti-slip floor coating.`,presentationSlides:[{slideNumber:1,title:`Leading vs. Lagging Safety Indicators (Clause 9.1)`,subtitle:`Module 05 • Measuring Proactive Safety vs. Past Injuries`,bullets:[`Lagging Indicators (Reactive — measuring after harm occurs): Lost Time Injury Frequency Rate (LTIFR), Total Recordable Incident Rate (TRIR), Days Lost, Occupational Illness cases.`,`Leading Indicators (Proactive — measuring prevention activities): Number of Near-Misses reported & closed, % of HIRA actions completed on time, Safety Gemba Walks completed, Emergency Drill scores.`,`Relying only on "Zero Lost Time Injuries" can hide serious underlying hazards if near-misses are ignored.`,`Clause 9.1.2 requires periodic Evaluation of Compliance with national labor/OH&S laws (boiler certificates, crane load tests, fire certificates).`],Example:`Celebrating an increase in Near-Miss reporting from 5 per month to 45 per month because hazards are being spotted and fixed before anyone gets hurt.`,keyPoint:`High Near-Miss reporting combined with fast closure is the strongest indicator of a healthy safety culture.`},{slideNumber:2,title:`Incident Investigation & Root Cause Analysis (Clause 10.2)`,subtitle:`Module 05 • Learning Without Blame`,bullets:[`All accidents, occupational illnesses, and near-misses must be investigated promptly.`,`Step 1: Secure the scene and provide immediate medical care.`,`Step 2: Investigate with the participation of workers and worker representatives (Clause 10.2).`,`Step 3: Use 5-Whys or Fishbone analysis to identify underlying System Root Causes (design, guarding, maintenance, workload)—never stop at "worker carelessness".`,`Step 4: Apply corrective actions using the Hierarchy of Controls and update the HIRA.`],Example:`When a worker cuts a finger opening boxes, replacing open steel blades with spring-retractable safety cutters (Substitution/Engineering) rather than just issuing a warning letter.`,keyPoint:`Writing "Worker Error / Tell worker to be careful" as a root cause is rejected in ISO 45001—you must fix the system condition that allowed the error.`},{slideNumber:3,title:`Internal Audits, Management Review & Continual Improvement`,subtitle:`Module 05 • Clauses 9.2, 9.3 & 10.3`,bullets:[`Internal OH&S Audits verify that HIRA controls, LOTO, Permits-to-Work, and legal checks are actually working on the shop floor.`,`Auditors interview front-line workers to confirm they were consulted and know emergency procedures.`,`Results of incident investigations and corrective actions must be communicated to relevant workers and the Safety Committee.`,`Continual Improvement (Clause 10.3) enhances OH&S performance, builds safety culture, and eliminates workplace hazards.`],Example:`Sharing a 1-page visual "Safety Lesson Learned" alert across all factory noticeboards after fixing a near-miss in the warehouse.`,keyPoint:`ISO 45001 requires communicating investigation findings and corrective actions back to the workforce.`}],sections:[],quiz:[]}]})],g=h.map(t),_=[e({id:`cert-2026-microsoft-office-intro`,code:`MS-OFFICE`,title:`Introduction to Microsoft Office`,subtitle:`Practical Workplace Mastery of Microsoft Word, Excel, PowerPoint, Outlook & Cloud Productivity`,category:`International Certification`,level:`Foundation & Intermediate`,durationHours:16,totalModules:5,examQuestionsCount:40,passingScorePercent:60,certificateTitle:`Certified Microsoft Office Workplace Productivity Professional`,accreditationStandard:`International Digital Workplace & Office Productivity Competency Standard`,targetAudience:[`Quality & Production Supervisors`,`Administrative & HR Officers`,`Students & Fresh Graduates`,`Plant & Office Professionals`],overview:`A simple, step-by-step 05-Module slide presentation course teaching practical everyday skills in Microsoft Word (SOPs & Reports), Microsoft Excel (Formulas, Charts & Pivot Tables), Microsoft PowerPoint (Management Presentations), and Microsoft Outlook/OneDrive.`,learningOutcomes:[`Create professional SOPs, reports, tables, and automatic Table of Contents in Microsoft Word`,`Use essential Microsoft Excel formulas (SUM, AVERAGE, IF, COUNTIF, VLOOKUP/XLOOKUP) and Conditional Formatting`,`Build Pivot Tables, dynamic charts, and data validation drop-down lists in Excel`,`Design clean, engaging management presentations using Slide Master in Microsoft PowerPoint`,`Manage workplace emails, calendar invites, and OneDrive cloud file sharing in Microsoft Outlook`],modules:[{moduleNumber:1,title:`Module 01: Microsoft Office Fundamentals & Microsoft Word Mastery`,estimatedMinutes:50,learningObjectives:[`Navigate the Microsoft Office Ribbon, Quick Access Toolbar, and Backstage View`,`Format professional documents, SOPs, and reports using Heading Styles in MS Word`,`Insert tables, headers/footers, page numbers, and an automatic Table of Contents`],summary:`Covers the Microsoft Office interface, essential keyboard shortcuts, and creating structured SOPs, formal letters, and reports in Microsoft Word.`,keyTakeaways:[`Using built-in Heading Styles (Heading 1, Heading 2) in MS Word allows instant generation of an automatic Table of Contents.`,`Ctrl + S saves your work, Ctrl + Z undoes mistakes, and Exporting to PDF locks formatting for official distribution.`],practiceScenario:`You need to write a 10-page Standard Operating Procedure (SOP) in MS Word. You add a company logo and Document Control ID in the Header, apply Heading 1 to main sections, insert a 1-click Automatic Table of Contents on page 1, and export the final file as a read-only PDF.`,presentationSlides:[{slideNumber:1,title:`Getting Started with the Microsoft Office Suite`,subtitle:`Module 01 • Core Workplace Applications`,bullets:[`Microsoft Office (Microsoft 365) is the global standard software suite for business, manufacturing, healthcare, and education.`,`Microsoft Word (.docx): Creating SOPs, policies, business letters, audit reports, and manuals.`,`Microsoft Excel (.xlsx): Calculating data, production logs, budgets, KPI charts, and inventory sheets.`,`Microsoft PowerPoint (.pptx): Creating training slides and management review presentations.`,`Microsoft Outlook & OneDrive: Professional email, meeting scheduling, and cloud backup.`],Example:`Writing a monthly quality report in Word, analyzing defect data in Excel, and presenting summary slides in PowerPoint.`,keyPoint:`Know each file extension: .docx for Word, .xlsx for Excel, and .pptx for PowerPoint.`},{slideNumber:2,title:`Essential Time-Saving Keyboard Shortcuts`,subtitle:`Module 01 • Working Twice as Fast Across All Office Apps`,bullets:[`Ctrl + C (Copy), Ctrl + X (Cut), and Ctrl + V (Paste).`,`Ctrl + Z (Undo last mistake) and Ctrl + Y (Redo action).`,`Ctrl + S (Save document immediately) and Ctrl + P (Print or Save as PDF).`,`Ctrl + F (Find a word in the document) and Ctrl + A (Select All content).`],Example:`Pressing Ctrl + Z immediately if you accidentally delete a table in Word restores the entire table in one second.`,keyPoint:`Press Ctrl + S frequently (or enable AutoSave) so you never lose work during a power outage.`},{slideNumber:3,title:`Formatting Professional Documents in MS Word`,subtitle:`Module 01 • Fonts, Paragraphs & Heading Styles`,bullets:[`Use clean professional fonts (Calibri, Arial, Aptos, or Times New Roman) in size 11 or 12 for body text.`,`Apply built-in Styles (Heading 1 for main titles, Heading 2 for sub-sections) from the Home tab instead of manual bolding.`,`Use Format Painter (paintbrush icon) to copy exact formatting from one paragraph and apply it to another.`,`Use Page Breaks (Ctrl + Enter) to start a new section cleanly on the next page instead of pressing Enter 20 times.`],Example:`Pressing Ctrl + Enter at the end of a cover page so the next section always starts cleanly at the top of Page 2.`,keyPoint:`Always use Ctrl + Enter (Page Break) rather than blank Enter lines to keep pages aligned when editing.`},{slideNumber:4,title:`Tables, Headers/Footers & Automatic Table of Contents`,subtitle:`Module 01 • Controlled SOP & Report Layout`,bullets:[`Headers & Footers (Insert Tab): Place company name, SOP Code, Version Number, and "Page X of Y" automatically on every page.`,`Tables (Insert → Table): Organize schedules, checklists, and specifications cleanly; use "Repeat Header Rows" for multi-page tables.`,`Automatic Table of Contents (References Tab → Table of Contents): Automatically pulls all Heading 1, 2, and 3 titles with page numbers.`,`Track Changes & Comments (Review Tab): Allows managers to suggest edits and leave feedback notes without erasing original text.`],Example:`Turning on "Repeat Header Rows" under Table Layout so a 4-page inspection checklist shows column titles at the top of every page.`,keyPoint:`Heading Styles + References → Table of Contents creates a professional clickable contents page in 2 seconds.`}],sections:[],quiz:[]},{moduleNumber:2,title:`Module 02: Microsoft Excel Essentials & Everyday Formulas`,estimatedMinutes:55,learningObjectives:[`Understand Workbooks, Worksheets, Rows, Columns, Cells, and Relative vs Absolute ($A$1) references`,`Write essential Excel formulas: SUM, AVERAGE, MIN, MAX, COUNT, COUNTA, and IF`,`Use Freeze Panes, Filters, Sorting, and Data Validation Drop-Down Lists`],summary:`Introduces the Excel grid, cell formatting, Absolute vs Relative cell references ($A$1), core mathematical and logical formulas, Freeze Panes, and AutoFilter.`,keyTakeaways:[`Every formula or function in Microsoft Excel MUST begin with an equals sign (=).`,`Adding dollar signs ($A$1) creates an Absolute Reference that stays locked when you drag a formula down a column.`],practiceScenario:'You build an Exam Score sheet in Excel. In column D, you type `=IF(C2>=60, "PASS", "FAIL")` and double-click the bottom-right fill handle to automatically grade 200 trainees in one second.',presentationSlides:[{slideNumber:1,title:`Understanding the Microsoft Excel Grid`,subtitle:`Module 02 • Workbooks, Sheets, Columns, Rows & Cells`,bullets:[`An Excel file is called a Workbook (.xlsx) and can contain multiple Worksheet tabs at the bottom.`,`Columns run vertically and are labeled with Letters (A, B, C...); Rows run horizontally and are labeled with Numbers (1, 2, 3...).`,`A Cell is the intersection of a column and row, identified by its Cell Address (e.g., B5 is Column B, Row 5).`,`Format numbers properly (Currency, Percentage %, Date, Decimal places) on the Home tab so calculations stay accurate.`],Example:`Selecting a column of efficiency ratios (0.854) and clicking the "%" icon on the Home tab to display "85.4%".`,keyPoint:`Keep only one piece of data per cell, and never mix text units (like "25 kg") inside a cell you want to sum mathematically.`},{slideNumber:2,title:`The Golden Rule of Excel Formulas & Cell References`,subtitle:`Module 02 • Relative (A1) vs. Absolute ($A$1) References`,bullets:["Golden Rule: Every Excel formula MUST start with an equals sign (=), such as `=A2+B2` or `=B2*C2`.","Relative Reference (e.g., `A2`): Automatically shifts to `A3`, `A4`, `A5` when you drag the formula down a column.","Absolute Reference (e.g., `$F$1` — press F4 key): Locks the exact cell so it does NOT move when copied down.",`Use the tiny green square at the bottom-right corner of a cell (Fill Handle) to copy a formula down hundreds of rows instantly.`],Example:"Multiplying each product’s price in column B by a single Tax Rate sitting in cell `$H$1` using `=B2*$H$1`.",keyPoint:`Pressing the F4 key while typing a cell address automatically adds dollar signs ($A$1) to lock that cell.`},{slideNumber:3,title:`Top 7 Essential Excel Functions Every Professional Needs`,subtitle:`Module 02 • Built-in Calculation Power`,bullets:["`=SUM(B2:B50)`: Adds up all numbers in the selected range (Shortcut: Alt + =).","`=AVERAGE(B2:B50)`: Calculates the arithmetic mean of the numbers.","`=MAX(B2:B50)` and `=MIN(B2:B50)`: Finds the highest and lowest values in a list.","`=COUNT(B2:B50)` counts cells with numbers; `=COUNTA(B2:B50)` counts all non-empty cells (including text names).",'`=IF(logical_test, "Value if True", "Value if False")`: Makes automatic decisions based on a target limit.'],Example:'Using `=IF(D2>5, "Out of Spec - Hold", "OK")` on a chiller temperature log where the limit is 5°C.',keyPoint:`Remember: COUNT only counts numbers, while COUNTA counts any cell that is not blank (like employee names).`},{slideNumber:4,title:`Freeze Panes, AutoFilter & Drop-Down Lists`,subtitle:`Module 02 • Managing Large Data Tables Cleanly`,bullets:[`Freeze Panes (View Tab → Freeze Top Row): Keeps your column headers visible at the top while scrolling down 1,000 rows.`,`Sort & Filter (Data Tab → Filter / Ctrl + Shift + L): Adds drop-down arrows to headers to filter by department, date, or status.`,`Data Validation (Data Tab → Data Validation → List): Creates a clickable drop-down list in a cell (e.g., "Pass, Fail, Pending") to prevent typos.`,`Remove Duplicates (Data Tab): Cleans duplicate IDs or entries from a table in one click.`],Example:`Using Data Validation to restrict the "Shift" column to a drop-down menu of "Morning, Evening, Night" so nobody types spelling variations.`,keyPoint:`Data Validation drop-down lists eliminate human spelling mistakes so your reports and charts stay 100% accurate.`}],sections:[],quiz:[]},{moduleNumber:3,title:`Module 03: Excel Data Analysis — VLOOKUP, Pivot Tables & Charts`,estimatedMinutes:55,learningObjectives:[`Use COUNTIF, SUMIF, and VLOOKUP / XLOOKUP to search and summarize data across tables`,`Highlight critical numbers automatically using Conditional Formatting`,`Build a Pivot Table and visual Charts in under 60 seconds`],summary:`Covers advanced everyday analysis in Excel: Conditional Formatting, COUNTIF/SUMIF, VLOOKUP, Pivot Tables, and choosing the right Chart (Column, Line, Pie).`,keyTakeaways:[`VLOOKUP searches for an ID in the leftmost column of a table and returns matching information from a specified column.`,`Pivot Tables summarize thousands of rows of raw data into clean departmental or monthly totals with drag-and-drop ease—zero formulas needed.`],practiceScenario:`Your manager gives you an Excel sheet with 5,000 rows of daily production batches across 4 lines and asks for total output and waste per line by month. Instead of writing manual formulas, you click Insert → PivotTable, drag "Line" to Rows, "Month" to Columns, and "Output kg" to Values, finishing the report in 30 seconds.`,presentationSlides:[{slideNumber:1,title:`COUNTIF, SUMIF & VLOOKUP Made Simple`,subtitle:`Module 03 • Conditional Totals & Table Lookups`,bullets:['`=COUNTIF(range, criteria)`: Counts how many cells meet a condition (e.g., `=COUNTIF(E2:E100, "Fail")` counts all failed batches).','`=SUMIF(range, criteria, sum_range)`: Adds numbers only when a condition matches (e.g., total production only for "Line 1").',"`=VLOOKUP(lookup_value, table_array, col_index_num, FALSE)`: Looks up an Item Code in column 1 of a master table and pulls its Product Name or Price.","Always put `FALSE` (or `0`) at the end of VLOOKUP when you want an Exact Match for an ID or code."],Example:"Typing a raw material code in cell A2 and having `=VLOOKUP(A2, MasterList!$A$2:$D$500, 2, FALSE)` automatically fill in the Material Name.",keyPoint:`Always use FALSE (or 0) as the fourth argument in VLOOKUP to guarantee an exact match.`},{slideNumber:2,title:`Conditional Formatting — Instant Visual Alerts`,subtitle:`Module 03 • Making Important Data Stand Out Automatically`,bullets:[`Found on the Home Tab → Conditional Formatting.`,`Automatically colors cells Red, Yellow, or Green based on their numerical value or text.`,`Highlight Cells Rules: Color any temperature > 5°C in Red, or any word "Expired" in Red.`,`Data Bars & Color Scales: Adds visual progress bars directly inside cells to compare performance at a glance.`],Example:`Applying a Conditional Formatting rule on an inventory sheet so any item with stock < 50 units automatically turns bright red.`,keyPoint:`Conditional Formatting updates cell colors automatically whenever the number inside the cell changes.`},{slideNumber:3,title:`Pivot Tables — The Most Powerful Feature in Excel`,subtitle:`Module 03 • Summarizing Thousands of Rows in Seconds`,bullets:[`A Pivot Table (Insert Tab → PivotTable) summarizes large tables of data without writing a single formula.`,`Requires clean source data: Every column must have a header title, and there should be no merged cells or blank header columns.`,`Four drag-and-drop areas: Filters (top filter), Rows (categories on left), Columns (headers across top), and Values (numbers to Sum/Count/Average).`,`When source data changes, simply right-click the Pivot Table and click "Refresh" to update all numbers.`],Example:`Dragging "Department" into Rows and "Overtime Hours" into Values to see total overtime per department in 5 seconds.`,keyPoint:`Remember to right-click and press "Refresh" on a Pivot Table after adding new rows to your raw data sheet.`},{slideNumber:4,title:`Creating Clear Management Charts & Graphs`,subtitle:`Module 03 • Choosing the Right Chart for Your Data`,bullets:[`Column / Bar Chart: Best for comparing values across categories (e.g., Output of Line A vs. Line B vs. Line C).`,`Line Chart: Best for showing trends over time (e.g., Monthly Net Efficiency % from January to December).`,`Pie / Doughnut Chart: Best for showing parts of a 100% whole with few categories (e.g., Breakdown of downtime causes).`,`Always include a clear Chart Title, Axis Labels, and Data Labels so managers can read the chart immediately.`],Example:`Using a Line Chart with a target horizontal line at 85% to display daily OEE efficiency across a 30-day month.`,keyPoint:`Use Line Charts for trends over time, Bar/Column Charts for category comparisons, and Pie Charts only for shares of 100%.`}],sections:[],quiz:[]},{moduleNumber:4,title:`Module 04: Microsoft PowerPoint — Designing Impactful Presentations`,estimatedMinutes:45,learningObjectives:[`Apply the 6×6 Rule and high-contrast visual design for clear presentation slides`,`Use Slide Master to control fonts, colors, and company logos across all slides at once`,`Use SmartArt, Alignment tools, Presenter View, and professional slide transitions`],summary:`Covers Microsoft PowerPoint best practices, the 6×6 readability rule, Slide Master customization, SmartArt process diagrams, and delivering confident presentations.`,keyTakeaways:[`Slide Master (View → Slide Master) lets you place a company logo or change fonts once and apply it automatically to every slide in the deck.`,`Good slides use bullet points (6×6 Rule), high contrast text, and SmartArt graphics rather than walls of tiny paragraphs.`],practiceScenario:`You are preparing a 15-slide Training Deck in PowerPoint. Instead of pasting the company logo onto all 15 slides one by one, you open View → Slide Master, paste the logo on the top-right of the master layout, and close Master View—instantly updating the entire presentation.`,presentationSlides:[{slideNumber:1,title:`Golden Rules of Professional Slide Design`,subtitle:`Module 04 • Clarity Over Clutter in PowerPoint`,bullets:[`Slides are visual aids for your audience—never paste a full Word document wall of text onto a slide.`,`Follow the 6×6 Guide: Aim for a maximum of 5 to 6 bullet points per slide, with concise phrases rather than long paragraphs.`,`Minimum Font Size: Use at least 24–28 pt for slide titles and 18–20 pt for bullet text so people at the back of the room can read easily.`,`Maintain high color contrast: Dark text on a clean light background, or white text on a dark navy/slate background.`],Example:`Replacing a 120-word paragraph about HACCP steps with a clean 5-step visual SmartArt arrow diagram.`,keyPoint:`Never put yellow text on a white background or dark blue text on a black background—contrast is essential for readability.`},{slideNumber:2,title:`Using Slide Master for Instant Consistency`,subtitle:`Module 04 • View Tab → Slide Master`,bullets:[`Slide Master controls the background template, default fonts, bullet styles, footer, and logo for the entire presentation.`,`Any change made on the top Master Slide automatically updates all slides in your presentation at once.`,`Prevents logos or titles from "jumping around" to slightly different positions as you click from slide to slide.`,`Insert Slide Numbers and Date/Footer cleanly via Insert → Header & Footer.`],Example:`Changing the title font from Times New Roman to Arial on the Slide Master updates all 40 slides in 2 seconds.`,keyPoint:`Use Slide Master whenever you want to change a logo, color theme, or font across all slides simultaneously.`},{slideNumber:3,title:`SmartArt, Charts, Animations & Presenter View`,subtitle:`Module 04 • Visual Storytelling & Smooth Delivery`,bullets:[`SmartArt (Insert → SmartArt): Converts plain bullet points into professional Process Flows, Hierarchies (Org Charts), and Cycles in one click.`,`Align & Distribute (Shape Format → Align): Aligns boxes and images perfectly without dragging them by eye.`,`Keep Animations & Transitions subtle (e.g., simple "Fade" or "Appear"); avoid distracting spinning or bouncing effects in business meetings.`,`Shortcuts in Slide Show: Press F5 to start from Slide 1, Shift + F5 to start from Current Slide, and B key to black out the screen during discussion.`],Example:`Using Presenter View on a laptop connected to a projector so you can see your speaker notes and upcoming slide while the audience sees only the full slide.`,keyPoint:`Press F5 to launch your presentation from the first slide, and Shift + F5 to launch from the current slide.`}],sections:[],quiz:[]},{moduleNumber:5,title:`Module 05: Microsoft Outlook, OneDrive Cloud & Workplace Cybersecurity`,estimatedMinutes:45,learningObjectives:[`Use To, CC, and BCC correctly and write structured professional emails in MS Outlook`,`Schedule meetings using Calendar Scheduling Assistant and set Automatic Out-of-Office Replies`,`Collaborate in real-time using OneDrive/SharePoint and recognize phishing threats`],summary:`Covers Microsoft Outlook email etiquette (To/CC/BCC), Inbox Rules, Calendar Meeting Invites, OneDrive cloud collaboration, version history, and document security.`,keyTakeaways:[`TO is for people who must take action; CC keeps stakeholders informed; BCC hides recipient email addresses for privacy.`,`Storing files on OneDrive/SharePoint enables AutoSave, Version History recovery, and multi-user co-authoring.`],practiceScenario:`You need to schedule a Management Review meeting with 6 department heads. Instead of sending 10 back-and-forth emails asking "when are you free?", you open Outlook Calendar → New Meeting → Scheduling Assistant to see everyone’s free/busy slots at once and send a single calendar invite.`,presentationSlides:[{slideNumber:1,title:`Professional Email Management in Microsoft Outlook`,subtitle:`Module 05 • Using TO, CC, BCC & Clear Subject Lines`,bullets:[`TO Field: For the primary person(s) who are directly responsible for replying or taking action.`,`CC (Carbon Copy): For managers or colleagues who need to stay informed for visibility, but do not need to reply.`,`BCC (Blind Carbon Copy): Hides recipient addresses from each other—ideal when emailing a large external supplier/client list.`,`Always write a specific Subject Line (e.g., "[Action Required] Line 2 Monthly Hygiene Audit Report – Oct 2026" instead of just "Report").`],Example:`Putting the Maintenance Manager in "TO" to fix a chiller and putting the Plant Manager in "CC" for awareness.`,keyPoint:`Use "Reply All" carefully—only click Reply All if every single person on the thread genuinely needs to read your response.`},{slideNumber:2,title:`Outlook Calendar, Scheduling Assistant & Inbox Rules`,subtitle:`Module 05 • Organizing Your Workday`,bullets:[`Calendar Invites: Include agenda points, meeting room or MS Teams link, and required attachments directly inside the calendar invite.`,`Scheduling Assistant: Shows side-by-side free/busy calendars of colleagues so you can pick a time when everyone is available.`,`Automatic Replies (Out of Office): Automatically notifies senders when you are on annual leave and names your backup contact.`,`Inbox Rules & Flags: Automatically move automated system alerts into dedicated folders and flag important emails for follow-up.`],Example:`Setting an Automatic Out-of-Office reply before going on vacation that directs urgent quality queries to the Deputy QA Manager.`,keyPoint:`Scheduling Assistant eliminates back-and-forth emails by showing when all meeting attendees are free.`},{slideNumber:3,title:`OneDrive, Co-Authoring & Workplace File Security`,subtitle:`Module 05 • Modern Cloud Collaboration`,bullets:[`OneDrive & SharePoint store Office files securely in the cloud with automatic backup.`,`Real-Time Co-Authoring: Multiple team members can edit the same Excel tracker or Word report simultaneously without creating "Final_v2_v3.xlsx" copies.`,`Version History: Lets you view and restore an earlier version of a file if someone accidentally overwrites data.`,"Security Best Practice: Password-protect confidential files (File → Info → Protect Document) and never click suspicious links or unknown `.exe`/macro attachments."],Example:`Using Version History on OneDrive to restore yesterday’s clean version of an inventory sheet after an accidental deletion.`,keyPoint:`Cloud Version History protects shared Excel and Word files from accidental overwrites.`}],sections:[],quiz:[]}]}),e({id:`cert-2026-english-proficiency`,code:`ENG-PROF`,title:`English Language Proficiency Certificate`,subtitle:`Professional Business & Technical English — Grammar, SOP Writing, Email Etiquette, Meetings & Presentations`,category:`International Certification`,level:`Foundation & Intermediate`,durationHours:20,totalModules:5,examQuestionsCount:40,passingScorePercent:60,certificateTitle:`Certified Professional in Workplace & Business English Proficiency`,accreditationStandard:`CEFR (Common European Framework of Reference for Languages) B2/C1 Workplace Standard`,targetAudience:[`Managers & Supervisors`,`Quality & Production Engineers`,`Administrative & HR Staff`,`Students & Job Seekers`],overview:`A clear, practical 05-Module slide presentation course designed to build strong workplace English proficiency—covering Grammar & Tenses, Commonly Confused Words, Professional Email Writing, Technical SOP & Audit Report Writing, and Confident Spoken English for Meetings & Interviews.`,learningOutcomes:[`Use accurate English grammar, subject-verb agreement, articles, prepositions, and tenses in the workplace`,`Avoid common business English errors (Affect vs Effect, Ensure vs Insure, Principal vs Principle)`,`Write polite, structured, and persuasive business emails and customer responses`,`Draft clear Standard Operating Procedures (SOPs), incident reports, and non-conformity statements`,`Speak confidently during management meetings, audit interviews, and professional presentations`],modules:[{moduleNumber:1,title:`Module 01: Core Workplace English Grammar & Sentence Structure`,estimatedMinutes:50,learningObjectives:[`Apply Subject-Verb Agreement rules accurately with singular, plural, and collective subjects`,`Choose the correct Verb Tense (Present Simple, Past Simple, Present Perfect) for workplace reporting`,`Use Articles (a, an, the) and Prepositions of Time and Place (at, on, in, by) correctly`],summary:`Covers essential workplace English grammar: Subject-Verb Agreement, Present Simple vs Past Simple vs Present Perfect tenses, Articles (a/an/the), and Prepositions.`,keyTakeaways:[`Singular subjects take singular verbs ("The batch requires testing"), while words like "Each", "Everyone", and "Equipment" always take a singular verb.`,`Use Past Simple for completed actions at a stated past time ("We calibrated the scale yesterday") and Present Perfect for actions with current relevance ("We have completed the audit").`],practiceScenario:`When writing an audit summary, you choose between "Each of the operators have signed" and "Each of the operators has signed". Because "Each" is grammatically singular, you write: "Each of the operators has signed the training record."`,presentationSlides:[{slideNumber:1,title:`Parts of Speech & Clear Sentence Structure`,subtitle:`Module 01 • Building Strong Professional Sentences`,bullets:[`Every complete English sentence requires a Subject (who/what performs the action) and a Verb (the action or state).`,`Keep workplace sentences clear and direct: Subject + Verb + Object (e.g., "The QA team inspected the raw materials.").`,`Adjectives describe nouns ("a calibrated thermometer"); Adverbs describe verbs or adjectives ("measured accurately").`,`Avoid run-on sentences: break long, confusing 40-word chains into two clear 15-word sentences.`],Example:`Correct: "The technician repaired the pump quickly." (Adverb "quickly" describes the verb "repaired").`,keyPoint:`Clear professional English favors short, direct sentences (15–20 words) over overly complicated sentences.`},{slideNumber:2,title:`Subject-Verb Agreement Golden Rules`,subtitle:`Module 01 • Avoiding the #1 Workplace Grammar Error`,bullets:[`Singular subject takes a singular verb (ends in -s in present tense): "The supervisor checks the log every hour."`,`Plural subject takes a plural verb: "The supervisors check the logs every hour."`,`Words like Each, Every, Everyone, Anybody, Nobody, and One are ALWAYS Singular (e.g., "Everyone in the plant wears safety shoes.").`,`Uncountable nouns like Information, Equipment, Furniture, Advice, and Feedback are ALWAYS Singular (never say "equipments" or "informations").`],Example:`Correct: "All laboratory equipment IS calibrated monthly." (Incorrect: "All equipments ARE calibrated").`,keyPoint:`Words like "Equipment", "Information", and "Training" are uncountable in English—never add an "-s" to them and always use a singular verb.`},{slideNumber:3,title:`Mastering Workplace Verb Tenses`,subtitle:`Module 01 • Present, Past & Present Perfect`,bullets:[`Present Simple: Used for permanent facts, routines, and SOP policies (e.g., "The pasteurizer operates at 72°C.").`,`Past Simple: Used for finished events at a specific time in the past—yesterday, last week, at 10:00 AM (e.g., "Line 2 stopped at 14:30 yesterday.").`,`Present Perfect (has/have + past participle): Used for recent actions affecting the present or when no specific past time is stated (e.g., "We have updated the HACCP plan.").`,`Never use "did" with a past-tense verb: Say "Did you check the batch?" (NOT "Did you checked the batch?").`],Example:`After "did / didn’t", always use the base verb: "The supplier did not send the certificate" (NOT "did not sent").`,keyPoint:`After the helper word "Did" or "Didn’t", always keep the main verb in its base present form (Did you go? / It did not work).`},{slideNumber:4,title:`Articles (A, An, The) & Prepositions (In, On, At, By)`,subtitle:`Module 01 • Precision in Daily Communication`,bullets:[`Use "A" before consonant sounds ("a factory", "a university" — sounds like "yoo"); use "An" before vowel sounds ("an audit", "an hour" — silent h).`,`Use "The" when referring to a specific item both speaker and listener know ("Please sign the audit report on your desk.").`,`Prepositions of Time: AT for exact clock times ("at 9:00 AM"), ON for days and dates ("on Monday", "on 15th May"), IN for months/years ("in July", "in 2026").`,`Use "BY" for deadlines ("Please submit the report by Friday 5:00 PM" = no later than Friday).`],Example:`"An SOP" (because the letter S is pronounced "ess", starting with a vowel sound) vs. "A standard" (starts with consonant sound "st").`,keyPoint:`Choose "A" or "An" based on the starting SOUND of the word, not just the first letter ("an hour", "an SOP", "a uniform").`}],sections:[],quiz:[]},{moduleNumber:2,title:`Module 02: Business Vocabulary, Tone & Commonly Confused Words`,estimatedMinutes:45,learningObjectives:[`Distinguish between commonly confused English words (Affect/Effect, Ensure/Insure, Accept/Except)`,`Convert informal or blunt phrasing into polite, professional business English`,`Use professional action verbs and connectors (However, Therefore, Furthermore)`],summary:`Explains commonly confused words in business writing, upgrading casual phrasing to formal workplace tone, and using transition words for logical flow.`,keyTakeaways:[`"Affect" is usually a Verb (to influence), while "Effect" is usually a Noun (the result/impact).`,`"Ensure" means to make certain that something happens; "Insure" refers to financial insurance policies; "Assure" means to remove someone’s doubt.`],practiceScenario:`Instead of writing a blunt email saying "You forgot to send the COA, send it now", you use polite business tone: "Could you please share the Certificate of Analysis (COA) for Batch #402 at your earliest convenience so we can release the shipment?"`,presentationSlides:[{slideNumber:1,title:`Commonly Confused Words in Business English (Part 1)`,subtitle:`Module 02 • Choosing the Right Word Every Time`,bullets:[`Affect vs. Effect: Affect = Verb meaning to influence ("High humidity affected the powder."). Effect = Noun meaning the result ("The change had a positive effect.").`,`Ensure vs. Assure vs. Insure: Ensure = make certain ("Ensure the valve is closed."). Assure = promise a person ("I assure you we will deliver."). Insure = buy an insurance policy.`,`Accept vs. Except: Accept = receive/agree ("We accept the proposal."). Except = excluding ("All lines are running except Line 3.").`,`Advice (Noun) vs. Advise (Verb): "Thank you for your advice" vs. "Please advise us on the delivery date."`],Example:`"Temperature fluctuations can AFFECT shelf life, and the EFFECT on quality is significant."`,keyPoint:`Memory trick for Affect vs. Effect: RAVEN — Remember Affect is a Verb, Effect is a Noun.`},{slideNumber:2,title:`Commonly Confused Words in Business English (Part 2)`,subtitle:`Module 02 • Precision in Reports & Emails`,bullets:[`Principal vs. Principle: Principal = main/head or financial sum ("The principal root cause"). Principle = fundamental rule ("The 7 HACCP principles").`,`Compliment vs. Complement: Compliment = praise ("The auditor complimented the hygiene team."). Complement = go well together ("These two skills complement each other.").`,`Stationery vs. Stationary: Stationery = office paper/pens (e for envelope). Stationary = not moving ("Wait until the blade is completely stationary.").`,`Lose (Verb) vs. Loose (Adjective): "Do not lose the calibration key" vs. "Tighten the loose conveyor belt."`],Example:`"Never reach into a machine until all moving parts are completely STATIONARY."`,keyPoint:`StationEry with an "E" means Envelopes and pens; StationAry with an "A" means standing still (Parked).`},{slideNumber:3,title:`Upgrading Informal Words to Professional Workplace Tone`,subtitle:`Module 02 • Diplomatic & Courteous Phrasing`,bullets:[`Instead of "I want you to send..." → Write: "Could you please provide..." or "We would appreciate it if you could share..."`,`Instead of "You made a mistake in the invoice" → Write: "There appears to be a discrepancy in Invoice #104."`,`Instead of "We can’t do this by Monday" → Write: "To ensure thorough testing, we will be able to deliver the results by Wednesday."`,`Use connecting words: Therefore / Consequently (result), However / Nevertheless (contrast), Furthermore / In addition (adding points).`],Example:`Focusing on the issue rather than blaming the person ("The attachment appears to be missing" instead of "You forgot the attachment").`,keyPoint:`Polite modal verbs ("Could you please...", "Would it be possible to...") build respect and get faster cooperation.`}],sections:[],quiz:[]},{moduleNumber:3,title:`Module 03: Professional Email Writing & Business Correspondence`,estimatedMinutes:45,learningObjectives:[`Structure a professional business email using the 5-part international template`,`Write clear Subject Lines, Openings, Action Requests, and Sign-offs`,`Write professional apologies, customer complaint responses, and follow-up emails`],summary:`Teaches the 5-part structure of high-impact business emails, professional greetings and closings, attachment mentions, and responding to customer complaints.`,keyTakeaways:[`Every professional email follows 5 steps: 1) Clear Subject Line, 2) Formal Salutation, 3) Purpose / Context, 4) Specific Action / Deadline, 5) Professional Sign-off.`,`When matching greetings to closings: "Dear Mr. Khan" pairs with "Sincerely / Best regards"; "Dear Sir or Madam" pairs with "Yours faithfully".`],practiceScenario:`A customer writes to complain about a delayed delivery. You reply using the LAST model: Listen/Acknowledge, Apologize professionally ("We sincerely apologize for the delay"), Solve (state the new confirmed tracking time), and Thank ("Thank you for your patience and continued partnership").`,presentationSlides:[{slideNumber:1,title:`The 5-Part Structure of a Professional Email`,subtitle:`Module 03 • Writing Emails That Get Read and Answered`,bullets:[`1. Subject Line: Summarize the topic + action required in 5–8 words (e.g., "Approval Request: Q3 Packaging Supplier Audit Schedule").`,`2. Salutation / Greeting: "Dear Mr. Ahmed," or "Dear Quality Team," or "Hello Sarah,".`,`3. Opening Sentence: State the purpose immediately ("I am writing to share the results of yesterday’s mock recall exercise.").`,`4. Body & Call to Action: Use bullet points for key details and state clearly who needs to do what by when.`,`5. Closing & Signature: "Best regards," / "Kind regards," followed by your full name, job title, and phone number.`],Example:`Putting key questions in a numbered or bulleted list inside the email so the reader answers all three questions instead of just the first one.`,keyPoint:`Always put your main purpose in the very first sentence of the email so busy managers understand the message immediately.`},{slideNumber:2,title:`Useful Phrases for Every Workplace Email`,subtitle:`Module 03 • Ready-to-Use Professional Templates`,bullets:[`Referring to Previous Contact: "Further to our telephone conversation this morning..." / "Thank you for your email regarding..."`,`Mentioning Attachments: "Please find attached the updated production schedule." (Tip: Attach the file BEFORE typing the email so you never forget!).`,`Making a Polite Request: "Could you please confirm whether the batch has been released by 3:00 PM today?"`,`Offering Assistance: "Please let me know if you require any further information." / "Please feel free to reach out if you have any questions."`],Example:`Using "Please find attached the monthly KPI report in PDF format" and verifying the attachment is uploaded before clicking Send.`,keyPoint:`Avoid outdated, overly stiff phrases like "Please be advised that herewith I attach"—use natural, modern business English.`},{slideNumber:3,title:`Handling Complaints & Delicate Situations by Email`,subtitle:`Module 03 • Turning Problems into Trust`,bullets:[`Never reply in anger or use ALL CAPS (which reads like shouting).`,`Step 1 — Acknowledge & Thank: "Thank you for bringing this matter to our attention."`,`Step 2 — Apologize Professionally: "We sincerely apologize for the inconvenience caused by..."`,`Step 3 — Explain & Resolve: State the root cause briefly and explain the concrete action taken to resolve the issue.`],Example:`"We sincerely apologize for the damaged outer cartons in Delivery #882. Replacement cartons have been dispatched via express courier and will arrive by 10:00 AM tomorrow."`,keyPoint:`Say "We apologize for the inconvenience" rather than casual excuses—customers value accountability and a concrete solution.`}],sections:[],quiz:[]},{moduleNumber:4,title:`Module 04: Technical Writing — SOPs, Audit Non-Conformities & Incident Reports`,estimatedMinutes:50,learningObjectives:[`Use Imperative Action Verbs (Measure, Verify, Record) when writing Standard Operating Procedures`,`Choose Appropriately between Active Voice (SOPs/actions) and Passive Voice (laboratory/process descriptions)`,`Write objective, fact-based Audit Non-Conformity statements and Incident Reports`],summary:`Covers technical English for manufacturing, quality, and operations: writing step-by-step SOPs in imperative active voice, using passive voice in lab reports, and writing objective audit findings.`,keyTakeaways:[`SOP steps should start with a strong Imperative Action Verb ("Calibrate the pH meter", "Record the temperature") so instructions are 100% clear.`,`Technical and audit reports must be Objective and Fact-Based (stating exact times, measurements, and batch numbers) rather than emotional opinions.`],practiceScenario:`During an internal audit, instead of writing a vague opinion like "The warehouse was very messy and workers were careless", you write an objective non-conformity statement: "During the warehouse inspection on 12 Oct at 10:15 AM, 4 pallets of raw sugar (Lot #S-109) were observed stored directly against the north wall with zero floor clearance, contrary to SOP-WH-04."`,presentationSlides:[{slideNumber:1,title:`Writing Clear Standard Operating Procedures (SOPs)`,subtitle:`Module 04 • Using Imperative Action Verbs`,bullets:[`An SOP must tell the operator exactly what to do, step by step, with zero ambiguity.`,`Start every procedural step with a direct Action Verb (Imperative mood): "Wear", "Inspect", "Weigh", "Heat", "Verify", "Record".`,`Avoid vague words like "properly", "sufficiently", "a little bit", or "warm"—always state the exact number and unit.`,`Write one action per step so operators can follow the sequence easily on the shop floor.`],Example:`Weak SOP: "Heat the milk until it is hot enough." → Strong SOP: "Heat the milk to 72°C (±0.5°C) and hold for 15 seconds."`,keyPoint:`Replace vague adjectives ("hot", "clean", "fast") with measurable specifications ("75°C", "<100 RLU", "60 packs/min").`},{slideNumber:2,title:`Active Voice vs. Passive Voice in Workplace Writing`,subtitle:`Module 04 • When to Use Each Style`,bullets:[`Active Voice (Subject performs the action): "The QA Technician tests three samples every hour." → Best for SOPs, action plans, and emails because it clearly shows WHO is responsible.`,`Passive Voice (Object receives the action: be + past participle): "Three samples are tested every hour." → Useful in laboratory methods or process descriptions where the process itself is the focus.`,`Danger of overusing Passive Voice in action plans: "Corrective action will be taken" hides WHO will take the action!`,`In CAPA and meeting minutes, always use Active Voice with a named owner: "The Maintenance Lead will replace the valve by Friday."`],Example:`CAPA Action: "Mr. Bilal (Engineering) will install the stainless-steel mesh guard by 18 November." (Clear owner + clear deadline).`,keyPoint:`Always use Active Voice in Action Plans and CAPA logs so responsibility is unmistakably assigned to a specific person.`},{slideNumber:3,title:`Writing Objective Audit Findings & Incident Reports`,subtitle:`Module 04 • Facts, Evidence & Neutral Language`,bullets:[`Technical and audit writing must be 100% objective, factual, and verifiable—never emotional, exaggerated, or personal.`,`Use the 3-Part Audit Non-Conformity Formula: 1) Requirement (What the standard/SOP says), 2) Failure (What was deficient), 3) Objective Evidence (Exact date, location, batch/equipment ID observed).`,`Avoid judgmental words like "terrible", "lazy", "obviously", or "always fails".`,`State exact observations: "At 11:20 AM in Chiller #2, the digital display read 9.4°C against the critical limit of ≤4.0°C."`],Example:`Objective Incident Report: "At 09:05 AM on 4 Nov, a 20 L container of sanitizer tipped off Pallet #4 in Bay B, spilling approximately 3 L onto the floor."`,keyPoint:`If a statement cannot be proven with a measurement, document, or timestamped observation, it is an opinion—keep audit reports strictly factual.`}],sections:[],quiz:[]},{moduleNumber:5,title:`Module 05: Spoken English — Meetings, Presentations, Audits & Interviews`,estimatedMinutes:45,learningObjectives:[`Use professional English phrases to open, lead, agree, politely disagree, and summarize meetings`,`Structure a clear oral presentation using Signposting Language (Introduction, Transitions, Conclusion)`,`Answer auditor and interview questions confidently using the STAR method (Situation, Task, Action, Result)`],summary:`Covers spoken workplace English for participating in management meetings, delivering presentations with signposting phrases, answering external auditor questions, and using the STAR method in interviews.`,keyTakeaways:[`Signposting phrases ("First, let’s look at...", "Moving on to...", "To summarize...") guide listeners smoothly through a presentation.`,`The STAR Method (Situation, Task, Action, Result) provides a structured, confident way to answer competency and audit questions.`],practiceScenario:`During a certification audit, the auditor asks how you handled a past customer complaint. Using the STAR method, you calmly explain the Situation (foreign body complaint in Q1), Task (find root cause within 24h), Action (inspected sieves and installed a finer 1mm mesh screen), and Result (zero complaints over the next 9 months).`,presentationSlides:[{slideNumber:1,title:`Professional Phrases for Business Meetings`,subtitle:`Module 05 • Participating Confidently in Discussions`,bullets:[`Opening a Meeting: "Good morning everyone, thank you for joining. Let’s go over today’s agenda."`,`Giving an Opinion: "From a food safety perspective, I believe we should..." / "In my experience, the most effective approach is..."`,`Agreeing & Politely Disagreeing: "I completely agree with Sarah’s point." / "I see your point; however, have we considered the impact on line speed?"`,`Clarifying & Summarizing: "Could you clarify what you mean by...?" / "Before we close, let’s summarize the key action items."`],Example:`Using "I understand your perspective, however..." instead of saying "No, you are wrong" keeps management meetings constructive and respectful.`,keyPoint:`Polite disagreement ("I see your point; however...") shows leadership maturity and keeps team discussions collaborative.`},{slideNumber:2,title:`Delivering Presentations with "Signposting" Language`,subtitle:`Module 05 • Guiding Your Audience Smoothly`,bullets:[`Introduction: "Good morning. Today I will present our Q3 Production Efficiency results in three brief parts."`,`Transitioning Between Slides: "Moving on to the next slide..." / "Now let’s turn our attention to..." / "This chart illustrates..."`,`Highlighting Key Data: "As you can see from this graph, net efficiency increased by 6.5% in October."`,`Concluding & Q&A: "To summarize our three main takeaways..." / "Thank you for your attention. I would be happy to answer any questions."`],Example:`If someone asks a difficult question during Q&A, start with: "That’s an important question. Based on our current data..."`,keyPoint:`Signposting phrases act like road signs for your listeners so they always know where you are in your presentation.`},{slideNumber:3,title:`The STAR Method for Interviews & Audit Questions`,subtitle:`Module 05 • Giving Structured, High-Impact Spoken Answers`,bullets:[`S — SITUATION: Briefly set the context (When and where did it happen? What was the challenge?).`,`T — TASK: Explain what your specific responsibility or goal was.`,`A — ACTION: Describe the specific steps YOU and your team took to solve the problem.`,`R — RESULT: Share the measurable positive outcome (numbers, %, audit pass, cost saved, or zero recurrence).`],Example:`Answering "Tell me about a time you improved a process" by ending with the Result: "...which reduced batch changeover time from 45 minutes down to 22 minutes."`,keyPoint:`Always finish a STAR answer with a measurable Result—numbers and outcomes make your spoken English memorable and credible.`}],sections:[],quiz:[]}]})],v=_.map(t),y={id:`default-course-template`,code:`FSC-INT`,title:`International Food Safety & Quality Certification`,levelBadge:`International Certification`,accreditationStandard:`Codex Alimentarius CXC 1-1969 & ISO 22000 Standard`,duration:`Self-Paced Certification`,certificateFeeRs:1e3,passPercentage:60,distinctionPercentage:75,totalExamQuestions:40,description:`Professional Food Safety and Quality Management System Certification.`,modules:[{id:`mod-1`,moduleNumber:1,title:`Module 1: Core Food Safety Principles & Regulatory Compliance`,estimatedMinutes:60,overview:`Core principles, regulatory requirements, and operational standards for food safety management.`,internationalClauses:[`Codex Alimentarius CXC 1-1969`,`ISO 22000:2018`],keyPrinciples:[`Establish and maintain prerequisite programs (PRPs) and operational controls.`,`Conduct hazard analysis and monitor critical control limits with calibrated instruments.`,`Maintain verifiable documentation and traceability records for regulatory due diligence.`],criticalControlParameters:[{parameter:`Critical Control Limit Monitoring`,standardLimit:`100% compliance with validated time, temperature, and sanitation limits`,correctiveProtocol:`Isolate non-conforming product, restore process control, and document root cause.`}],practicalChecklist:[`Verify daily calibration and sanitation monitoring logs.`,`Confirm traceability and corrective action records are signed and archived.`]}],coreExamPool:[{q:`What is the primary objective of an accredited Food Safety Management System (FSMS)?`,options:[`To systematically identify, evaluate, and control food safety hazards across the food chain`,`To rely exclusively on end-product consumer feedback for hazard identification`,`To substitute prerequisite sanitation programs with quarterly visual inspections`,`To delegate regulatory compliance responsibility solely to third-party logistics providers`],correctIndex:0,explanation:`An FSMS ensures hazards are systematically identified, evaluated, and controlled to ensure food is safe at the time of consumption.`}]},b=[n,l,...a,...d,...p,...h,..._];function x(e){let t=b.find(t=>t.id===e)||y;return i(t)}var S=i(l),C=[o,{...u,customMcqs:S.map(e=>({id:e.id,question:e.question,options:e.options,correctIndex:e.correctIndex,explanation:e.explanation}))},...r,...f,...m,...g,...v];export{y as DEFAULT_COURSE_TEMPLATE,C as INITIAL_INTERNATIONAL_TRAININGS,b as INTERNATIONAL_TRAINING_COURSES,x as get40CourseExamQuestions};